function updateHints(){for(const k of ['len','xian','chm']){const el=document.getElementById('hint-'+k);if(!el)continue;const f=(OPT_INFO[k]||{})[CFG[k]||0]||(OPT_INFO[k]||{})[CFG[k]];if(!f){el.style.display='none';continue}const [ic,t,d,tg]=f();
 el.style.animation='none';void el.offsetWidth;el.style.animation='';el.innerHTML=`<div class="hic">${ic}</div><div style="min-width:0"><b>${t}</b><div class="hd">${d}</div><div class="htg">${tg.map(x=>`<span class="${x[1]||''}">${x[0]}</span>`).join('')}</div></div>`}}
function titleMode(){const x=!!CFG.xian,a=document.getElementById('titleSub'),b=document.getElementById('popW');if(a)a.textContent=x?'วันนี้ จะได้เกิดเป็นใครในโลกเทพเซียน?':'วันนี้ จะได้เกิดเป็นใครในยุทธภพ?';if(b)b.textContent=x?'โลกเทพเซียน':'ยุทธภพ';document.body.classList.toggle('xian',x)}

// ============ PIXEL ART ============

function drawAvatar(cv,seed,gender,demon){
 const c=cv.getContext('2d');if(!c)return;let s=seed;const rnd=()=>(s=(s*9301+49297)%233280)/233280;
 c.clearRect(0,0,16,16);const {skin,hair,robe}=avatarCols(seed,gender,demon);
 const P=(x,y,w,h,col)=>{c.fillStyle=col;c.fillRect(x,y,w,h)};
 P(4,3,8,7,skin);P(3,2,10,3,hair);P(3,4,2,4,hair);P(11,4,2,4,hair);
 if(gender==='หญิง'){P(3,7,2,5,hair);P(11,7,2,5,hair)}else{P(7,0,2,2,hair)}
 P(6,6,1,1,'#2a2838');P(9,6,1,1,'#2a2838');P(7,8,2,1,'#c0525e');
 P(3,10,10,6,robe);P(7,10,2,6,'#ffffff88');P(5,10,6,1,'#2a283855');
}

