function famKind(f){return f.heirType==='มาร'?'demon':f.heirType==='ธรรมะ'?'noble':f.heirType==='อธรรม'?'martial':f.clanObj?'martial':f.demon?'demon':f.orphan?'orphan':/ขุนนาง/.test(f.n)?'noble':/พ่อค้า/.test(f.n)?'merchant':/ยุทธ์|ทายาท/.test(f.n)?'martial':'common'}
function genName(f,g,sur){const k=famKind(f),gs=g==='หญิง'?NM.f:NM.m;if(k==='orphan'&&!sur)return ch(gs.orphan);
 const s=sur||(f.clanObj?f.clanObj.sur:0)||(k==='demon'?ch(NM.sur.demon):(k==='noble'||k==='martial')&&Math.random()<.5?ch(NM.sur.clan):ch(NM.sur.common));return s+' '+ch(gs[k==='orphan'?'common':k])}
function anyName(g){return genName(pickW(FAMILY.filter(f=>!f.demon&&!f.orphan)).v,g)}
