const whereTxt=()=>PLACE[S.focus]||'ระหว่างทาง';
const withTxt=()=>S.focus==='love'&&S.spouse?` พร้อมกับ${S.spouse}${S.kids?'และลูกๆ':''}`:'';
const oppG=()=>S.gender==='ชาย'?'หญิง':'ชาย';
const roll01=p=>Math.random()<Math.max(.03,Math.min(.97,p+statAdj()));
function loverAge(){const c=Math.max(0,S.cha||0),hi=Math.max(18,Math.min((S.age||18)+3,Math.round(60-c/5))),lo=Math.max(18,Math.round(hi-8-c/20));return R(lo,hi)}
function loverLife(a){const ri=realmIdx();let l=Math.max(R(55,85),a+R(25,45),ri>=2?Math.round(lifeMax()*R(55,85)/100):0);if(S.xian)l=Math.max(l,a+R(150,300));return l}
function mkLover(nm,t,o){const a=Math.max(18,(o&&o.age)||loverAge());return Object.assign({n:nm,t:t||'',p:ch(PERS_S),aff:72,age:a,life:loverLife(a),peer:false},o||{},{age:a})}
const isWed=()=>!!S.spouse&&!(S.sp&&S.sp.wed===false);
function marry(nm,how){albumSnap('แต่งงานกับ '+nm);S.spouse=nm;S.spouseP=null;S.cha+=5;log(`💍 ${how||'แต่งงานกับ'} <b>${nm}</b>`,'epic');setScene('wedding')}

function beggarGood(extra=0){if(!S.arc.master&&Math.random()<.35+extra){meetMaster('ที่แท้ขอทานชราคือยอดฝีมือปลอมตัว!')}else{log('ชายชรายิ้ม แล้วหายไปในฝูงชน','good');plant('beggarFed',{},5,15,.7)}}
function banditSpare(){choice('🗡️ หัวหน้าโจรคุกเข่า','คุณจัดการโจรป่าได้หมด หัวหน้าโจรคุกเข่าอ้อนวอน "ข้ามีแม่แก่ต้องเลี้ยง ไว้ชีวิตข้าเถิด!"',[{t:'ไว้ชีวิต',s:'กรรม + · ไม่รู้ว่าเขาจะกลับตัวไหม',f(){S.karma+=4;log('ปล่อยหัวหน้าโจรไป "ไปเริ่มต้นใหม่เสีย"','good');plant('banditSpared',{},4,12,.8)}},{t:'ปลิดชีพ',s:'กรรม −',f(){S.karma-=4;S.kills++;log('ปลิดชีพหัวหน้าโจร');plant('banditKilled',{},8,18,.35)}},{t:'ส่งตัวให้ทางการ',s:'ได้ค่าหัว',f(){S.money+=inc(300);S.fame+=5;log('ส่งตัวหัวหน้าโจรให้ทางการ ได้ค่าหัว 300 ตำลึง','good')}}])}
function tourney(){let w=0;for(let i=0;i<2;i++){if(fight('คู่ประลอง',200+S.age*20+i*300+realmIdx()*200))w++;else break}
 if(w===2){log('ชนะสองรอบแรก ผ่านเข้ารอบชิงชนะเลิศ!','good');duel('คู่ชิงชนะเลิศ',800+S.age*20+realmIdx()*200,ww=>{if(ww){S.fame+=120;S.money+=inc(2000);log('ชนะรอบชิง! ได้รับการยกย่องเป็นยอดฝีมือรุ่นใหม่','myth')}else log('พ่ายแพ้ในรอบชิงชนะเลิศ','bad')})}else log(`ชนะ ${w} รอบ ก่อนตกรอบ`,w?'good':'bad')}
function buyScroll(p,real){if(S.money<p){log('เงินไม่พอ พ่อค้าเดินจากไป');return}S.money-=p;if(Math.random()<real){const a=newArt(1);S.arts.push(a);log(`ได้ ${artHtml(a)}`,'good')}else{log('เปิดดู... เป็นตำราทำอาหาร โดนหลอก!','bad');plant('scam',{},3,12,.45)}}
