function milestone(){
 modal(`<h3>อายุ ${S.age} ปี</h3><p>เวลาหยุดนิ่งไปชั่วขณะ...<br>ตอนนี้ <b>${esc(S.name)}</b> กำลังคิดอะไรอยู่?</p><input class="ta" id="thIn" maxlength="60" placeholder="เขียนสั้นๆ หนึ่งประโยค"><div class="brow"><button class="gbtn" onclick="afterThink()">ข้าม</button><button class="gbtn" onclick="LS.set('murim_nothink',1);toast('ปิดคำถามแล้ว เปิดใหม่ได้ที่เมนู ☰');afterThink()">ไม่ต้องถามอีก</button><button class="pbtn" style="font-size:16px;padding:9px" onclick="saveThought()">บันทึก</button></div>`,'think');
}
function saveThought(){const v=$('thIn').value.trim();if(v){S.thoughts.push({a:S.age,t:v});addFeed('think',`💭 "${esc(v)}"`)}afterThink()}
