function drinkRound(n,foe){
 if(n>5){S.fame+=15;S.money+=inc(500);joy(6);log(`🍶 ไหที่หก ${foe}ฟุบหน้าลงโต๊ะ คุณยังนั่งตัวตรง ชนะการแข่งดื่ม! ได้เงินเดิมพัน 500 ตำลึง`,'epic');S.flags.drinkWin=1;return}
 const p=clamp(.92-n*.11+S.qi/500+S.maxHp/3000,.2,.95);
 choice(`🍶 แข่งดื่มกับ${foe} — ไหที่ ${n}/5`,`${n===1?`${foe}วางไหสุราลงตรงหน้า "ใครล้มก่อนจ่าย!"<br>`:''}หัวเริ่ม${n<3?'อุ่นๆ':n<5?'หมุน':'มองเห็นเป็นสองคน'} · โอกาสไหว ~${Math.round(p*100)}%`,[
  {t:'🍶 ดื่มต่อ',f(){if(Math.random()<p)drinkRound(n+1,foe);else{S.money=Math.max(0,S.money-300);S.fame-=3;S.hp-=8;log(`🍶 ไหที่ ${n} คุณร่วงลงใต้โต๊ะ ตื่นมาพบว่าถูกล้วงกระเป๋าไป 300 ตำลึง`,'bad')}}},
  {t:'🏳️ ยอมแพ้',skip:true,f(){S.money=Math.max(0,S.money-150);log(`🍶 ยอมแพ้ที่ไหที่ ${n} จ่ายค่าสุราไป 150 ตำลึง`)}}])}
function diceRes(bet,pick){const d=[R(1,6),R(1,6),R(1,6)],sm=d[0]+d[1]+d[2],hi=sm>=11;const win=pick==='win'||(pick!=='lose'&&(pick===1)===hi);
 if(win){S.money+=bet;log(`🎲 [${d.join('·')}] = ${sm} — ชนะ! ได้ ${fmtM(bet)} ตำลึง`,'good')}else{S.money-=bet;log(`🎲 [${d.join('·')}] = ${sm} — แพ้ เสีย ${fmtM(bet)} ตำลึง`,'bad')}}
function goRes(opp,me){const beat={ล้อม:'รุก',รุก:'หลอก',หลอก:'ล้อม'};const win=beat[me]===opp||(me===opp&&roll01(S.int/150));
 if(win){const a=newArt(1);S.arts.push(a);S.int+=4;log(`♟️ คุณเล่นแบบ${me}สวนทางที่ชายชราเล่นแบบ${opp}พอดี — ชนะ! ได้ ${artHtml(a)}`,'epic')}else{S.int+=2;log(`♟️ ชายชราเล่นแบบ${opp} คุณแพ้ราบคาบ แต่ได้เรียนรู้มาก`)}}
function poemRes(match){if(roll01(match?.7+S.int/500:.2+S.int/500)){S.fame+=20;S.cha+=5;joy(5);log(`📜 กรรมการผู้เฒ่าน้ำตาซึม บทกวีคุณ${match?'แตะใจคนคิดถึงบ้าน':'ไพเราะเกินคาด'} — ชนะเลิศ!`,'epic')}else{S.int+=2;log('📜 บทกวีคุณได้รับเสียงปรบมือพอประมาณ แต่ไม่ชนะ')}}

