const PET_LV=['ลูกอ่อน','วัยรุ่น','สัตว์อสูร','สัตว์ศักดิ์สิทธิ์','สัตว์เทพ'];
const petM=()=>S.pet&&S.pet.spirit?1+(S.pet.lv||0)*.06:1;
function petTick(){const p=S.pet;if(!p||!p.spirit||(p.lv||0)>=4)return;if(S.age-(p.lvAt||p.age)>=R(12,25)||(bagHas('core')&&Math.random()<.15&&bagUse('core'))){p.lv=(p.lv||0)+1;p.lvAt=S.age;log(`🐉 ${p.n}วิวัฒนาการเป็น<b>${PET_LV[p.lv]}</b>!${p.lv>=4?' ทั้งแคว้นสั่นสะเทือนด้วยเสียงคำราม':''}`,p.lv>=3?'myth':'epic');if(p.lv>=4){S.flags.petGod=1;keyAdd(`${p.n}กลายเป็นสัตว์เทพ`)}}}
