EVENTS.push(
 {w:2,cd:12,c:s=>s.xian&&realmIdx()>=2&&s.age>=16,f(){const auc=auctionEv();if(!auc)log('🔨 งานประมูลใหญ่เปิดขึ้นในเมืองเซียน แต่หินวิญญาณคุณไม่พอแม้แต่จะซื้อตั๋วเข้างาน')}},
 {w:2,cd:10,c:s=>s.xian&&s.age>=14,f(){const ep=total()*(.6+Math.random()*.5),yn=ch(['คุณชายตระกูลหลิว','ศิษย์สายตรงนิกายกระบี่หมื่นดาว','หลานชายผู้อาวุโสใหญ่']);choice('👋 คุณชายจอมเย่อหยิ่ง',`<b>${yn}</b> เหยียดหยามรากวิญญาณคุณต่อหน้าคนทั้งหอ "ขยะแบบเจ้าไม่ควรเหยียบที่นี่"`,[
  {t:'ตบหน้า!',s:'สู้กับองครักษ์',f(){if(fight(`องครักษ์ของ${yn}`,ep)){S.fame+=30;log(`เผียะ! ${yn}กระเด็นไปสามจั้ง ทั้งหอเงียบกริบ`,'epic');plant('slapRevenge',{n:yn},3,8,.6)}else{S.hp-=20;log('ถูกองครักษ์ซ้อมจนน่วม','bad')}}},
  {t:'อดทน จดจำหน้าไว้',f(){S.karma+=2;plant('slapRevenge',{n:yn,wait:1},10,20,.8);log(`คุณยิ้มบาง "อีกสิบปี เจ้าจะจำวันนี้ได้"`)}}])}},
 {w:1.5,cd:20,c:s=>s.xian&&realmIdx()>=3,f(){choice('⚔️ ศึกเผ่ามนุษย์กับเผ่าอสูร','ทัพเผ่าอสูรบุกข้ามกำแพงเมืองเซียน ทุกสำนักต้องส่งคน',[
  {t:'ออกรบแนวหน้า',f(){if(fight('ขุนพลอสูร',total()*(.9+Math.random()*.4))){S.fame+=50;bagAdd('core',3);log('สังหารขุนพลอสูรได้ ได้แก่นอสูรมาหลายลูก','epic')}else{S.hp-=40;log('ถูกล้อมจนต้องถอย','bad')}}},
  {t:'ตั้งค่ายกลป้องกันเมือง',s:'ใช้ปัญญา',f(){if(roll01(.3+S.int/300+(S.prof&&S.prof.t==='array'?.3:0))){S.fame+=40;S.karma+=5;log('ค่ายกลคุณกันทัพอสูรไว้ได้สามวันสามคืนจนกำลังเสริมมาถึง','epic')}else log('ค่ายกลแตก ต้องถอยไปตั้งหลัก','bad')}},
  {t:'หลบอยู่หลังแนว',skip:true,f(){S.fame-=10}}])}},
 {w:1.2,once:1,c:s=>s.xian&&realmIdx()>=3,f(){choice('🏛️ ซากเมืองเซียนโบราณ','ใต้ซากเมืองเซียนที่จมอยู่ในทะเลทราย มีวิญญาณเก่าแก่เฝ้ารออยู่ "เจ้าคือผู้สืบทอดที่ข้ารอมาแสนปีหรือ?"',[
  {t:'"ใช่"',s:'รับการทดสอบ',f(){if(roll01(.4+S.karma/300+S.int/500)){const a=newArt(4);S.arts.push(a);daoGain('วิญญาณโบราณถ่ายทอดความเข้าใจ');log(`ผ่านการทดสอบ! ได้รับมรดก ${artHtml(a)}`,'myth');keyAdd('ได้รับมรดกจากเมืองเซียนโบราณ')}else{S.hp-=40;log('"ไม่ใช่เจ้า" วิญญาณโยนคุณออกจากซากเมือง','bad')}}},
  {t:'"ข้าแค่หลงทางมา"',f(){bagAdd('gem',2);log('วิญญาณหัวเราะ แล้วมอบของมีค่าให้เป็นค่าเดินทาง')}}])}},
 {w:1.2,once:1,c:s=>s.xian&&s.age>=18,f(){choice('🩸 ถูกใส่ร้ายว่าเป็นผู้ฝึกตนมาร',`มีคนพบศพที่ถูกดูดลมปราณจนแห้ง ทุกคนชี้มาที่คุณ`,[
  {t:'พิสูจน์ความบริสุทธิ์ด้วยกระจกส่องวิญญาณ',f(){if(S.karma>=-10){S.fame+=20;log('กระจกส่องวิญญาณฉายแสงขาวบริสุทธิ์ ผู้ใส่ร้ายตัวจริงถูกจับได้','epic')}else{S.fame-=40;S.karma-=5;log('กระจกฉายแสงหม่น... ทั้งที่คุณไม่ได้ทำ แต่อดีตคุณไม่สะอาดพอ','bad')}}},
  {t:'ตามล่าฆาตกรตัวจริง',f(){if(fight('ผู้ฝึกตนมารตัวจริง',total()*(.9+Math.random()*.3))){S.fame+=35;log('ลากตัวฆาตกรตัวจริงมาประจาน','epic')}else{S.fame-=20;log('ฆาตกรหนีไปได้ ข้อครหายังติดตัวคุณ','bad')}}},
  {t:'หนีออกจากเมือง',f(){S.fame-=25;log('คุณหนี ทุกคนยิ่งมั่นใจว่าคุณผิด','bad')}}])}},
 {w:1.5,cd:6,c:s=>s.xian&&s.age>=14,f(){bagLoot();log(`🌿 ${ch(['เก็บของระหว่างท่องหุบเขาวิญญาณ','พบของตกอยู่ข้างซากผู้ฝึกตนนิรนาม','แลกของกับพ่อค้าเร่ในเมืองเซียน'])}`)}});
