function xianSky(){if(!isX())return;g.globalAlpha=.18;P(0,0,SW,40,S.xt?'#ffd860':'#b080ff');g.globalAlpha=1;
 const isl=(x,y,w)=>{P(x,y,w,3,'#7ab06a');P(x+2,y+3,w-4,3,'#8a7a6a');P(x+5,y+6,w-10,2,'#6a5a4a');P(x+w/2-1,y-5,2,5,'#c8183a');P(x+w/2-3,y-6,6,1,'#3a2a2a')};
 const o=(frame*.2)%SW;isl((20+o)%SW-10,8,18);isl((100+o*.6)%SW-10,14,14);
 const cx=(frame*1.5)%(SW+20)-10;P(cx,6,3,1,'#fff');P(cx+1,5,1,1,'#fff');P(cx-2,7,8,1,'#d8e0ff')}
function xPanel(){const c=S.cave,p=S.prof,ri=realmIdx(),rem=Math.floor(lifeMax()-S.age-1);
 return `<h4 style="margin-top:12px">☁️ เส้นทางเซียน${S.xt?' · 🌟 โลกเทพ':''}</h4>
 <div class="item"><b>🌱 ${S.root||rootOf(S.talent)}</b></div>
 <div class="item"><b>☯️ กฎแห่งเต๋า ${daoSum()} ขั้น</b>${S.dao&&Object.keys(S.dao).length?'<br>'+Object.entries(S.dao).map(([k,v])=>`${k} ${'●'.repeat(v)}${'○'.repeat(5-v)}`).join('<br>'):'<br><span class="tag2">ยังไม่หยั่งรู้กฎใดเลย</span>'}${ri>=4?`<br><span class="tag2">ระดับนี้ต้องการ ${(ri-3)*2} ขั้นจึงจะฝึกได้เต็มที่ ${daoM()<1?'— ⚠️ ติดคอขวด':'✅'}</span>`:''}</div>
 <div class="item"><b>🏔️ ${c?CAVE_N[c.lv]:'ยังไม่มีถ้ำบ่มเพาะ'}</b>${c?`<br><span class="tag2">ลมปราณ +${(.3*(c.lv+1)).toFixed(1)}/ปี · ฝึกได้ผล ×${caveM().toFixed(2)}</span>${c.lv<4?`<br><button class="sysb" style="margin-top:6px" ${S.money>=caveCost()?'':'disabled'} onclick="caveUp()">อัปเกรด (${stoneTxt(caveCost())})</button>`:''}`:'<br><span class="tag2">จะพบได้เมื่อถึงขั้นสร้างรากฐาน</span>'}</div>
 <div class="item"><b>🧘 ปิดด่านข้ามเวลา</b><br><span class="tag2">ข้ามเวลาหลายปีในครั้งเดียว ได้ลมปราณต่อเนื่อง แต่พลาดทุกเหตุการณ์ข้างนอก (อายุขัยเหลือ ~${rem} ปี)</span><div style="display:flex;gap:6px;margin-top:6px">${secOpts().map(n=>`<button class="sysb" ${rem>=n?'':'disabled'} onclick="seclude(${n})">${fmt(n)} ปี</button>`).join('')}</div></div>
 ${p&&p.t?`<div class="item"><b>${PROF[p.t].ic} ${PROF[p.t].n} ${PROF_LV[p.lv]}</b></div>`:''}
 ${S.pet&&S.pet.spirit?`<div class="item"><b>🐉 ${S.pet.n} — ${PET_LV[S.pet.lv||0]}</b><br><span class="tag2">ช่วยต่อสู้ ×${petM().toFixed(2)} · ป้อนแก่นอสูรเพื่อเร่งวิวัฒนาการ</span></div>`:''}`}
function xTick(){if(!S.xian)return false;if(rootFixTick()||caveTick()||profTick())return true;
 if(auto&&!xFast()&&realmIdx()>=3&&S.age>=60&&Math.random()<.12&&lifeMax()-S.age>15){seclude(R(1,3)*10);return true}return false}

