function xOn(){const b=document.getElementById('birth');if(b&&b.classList.contains('on'))return !!CFG.xian;return !!(S&&S.xian)}
function xFix(ids){if(!xOn())return;ids.forEach(id=>{const e=typeof id==='string'?document.getElementById(id):id;if(e&&e.innerHTML)e.innerHTML=xT(e.innerHTML)})}
function xT(t){if(!xOn()||typeof t!=='string')return t;for(const [a,b] of XDICT)if(t.includes(a))t=t.split(a).join(b);return t}
