const nmP=()=>{const p=(S.parents||[]).filter(x=>x.alive);return p.length?ch(p):null};
const nmSib=()=>{const p=(S.sibs||[]).filter(x=>x.alive&&x.born!==false);return p.length?ch(p):null};
const nmKid=()=>{const k=(S.children||[]).filter(c=>c.alive);return k.length?ch(k):null};
const nmPeer=()=>{const p=peers.filter(x=>x.alive&&x.age>=8);return p.length?ch(p):null};
