const XTHEME=[['jade','🍃','หยกเขียว','สะสมความสำเร็จ 15 อย่าง',()=>Object.keys(achGot).length>=15],['ember','🩸','โลหิตมาร','ได้ความสำเร็จระดับตำนาน 1 อย่าง',()=>ACH_ALL.some(a=>achGot[a.id]&&a.r>=4)],['gold','✨','ทองเซียน','ได้ความสำเร็จระดับเทพ 1 อย่าง',()=>ACH_ALL.some(a=>achGot[a.id]&&a.r>=5)]];
function openCosmetic(){modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>🎖️ ของตกแต่ง</h3><p class="tag2">ปลดล็อกธีมสีพิเศษจากความสำเร็จ</p>${THEMES.map(t=>{const x=XTHEME.find(y=>y[0]===t[0]);const ok=!x||x[4]();return `<div class="item" style="display:flex;justify-content:space-between;align-items:center;gap:6px"><div><b>${t[1]} ${t[2]}</b>${x?`<br><span class="tag2">${ok?'✅ ปลดล็อกแล้ว':'🔒 '+x[3]}</span>`:''}</div><button class="sysb" style="flex:0 0 auto" ${ok?'':'disabled'} onclick="theme='${t[0]}';LS.set('murim_theme',theme);applyTheme();openCosmetic()">${theme===t[0]?'ใช้อยู่':'ใช้'}</button></div>`}).join('')}`)}
// ---- 8. เทศกาลตามวันจริง ----
const FEST_REAL=[[1,15,2,20,'🧧','ตรุษจีน','ทั้งเมืองแขวนโคมแดง เด็กๆ ได้อั่งเปา'],[2,21,3,10,'🏮','เทศกาลโคมไฟ','โคมไฟนับหมื่นลอยเต็มฟ้า'],[4,1,4,15,'🌿','เชงเม้ง','ผู้คนกลับไปไหว้บรรพบุรุษ'],[5,25,6,25,'🐉','เทศกาลเรือมังกร','แข่งเรือมังกรและกินบ๊ะจ่าง'],[8,1,8,20,'🌌','คืนชีซี','คู่รักนัดพบกันใต้ทางช้างเผือก'],[9,5,10,10,'🥮','ไหว้พระจันทร์','ขนมไหว้พระจันทร์และโคมกระต่าย'],[11,1,11,30,'🪔','เทศกาลโคมลอยริมน้ำ','ผู้คนลอยโคมขอพรริมแม่น้ำ'],[12,15,12,31,'🍡','ตงจื้อ','ครอบครัวรวมตัวกินบัวลอยร้อนๆ']];
function curFest(){const d=new Date(),m=d.getMonth()+1,dd=d.getDate(),v=m*100+dd;for(const f of FEST_REAL){if(v>=f[0]*100+f[1]&&v<=f[2]*100+f[3])return{ic:f[4],n:f[5],d:f[6]}}return null}
function festTick(){const f=curFest();if(!f||S.age<3||(S.festN||0)>=3||(S.festY!=null&&S.age-S.festY<10)||Math.random()>.5)return;S.festY=S.age;S.festN=(S.festN||0)+1;joy(6);
 const g=R(1,3);let t='';if(g===1){const v=inc(R(100,400));S.money+=v;t=`ได้ของขวัญ ${fmtM(v)} ตำลึง`}else if(g===2){bagAdd(ch(['food','hp','herb']),1,1);t='ได้ของฝากใส่กระเป๋า'}else{S.cha+=3;t='เสน่ห์ +3'}
 log(`${f.ic} <b>${f.n}</b> (ตรงกับวันจริงของคุณ) ${f.d} · ${t}`,'good')}
function festSky(){const f=curFest();if(!f||!S)return;for(let i=0;i<4;i++){const x=(i*41+frame*.4)%SW,y=4+((i*13+Math.floor(frame/6))%14);P(x,y,3,4,'#ff5a3a');P(x+1,y+4,1,1,'#ffd040')}}
