const TUT=[['.box.top','📋 แถบสถานะ','อายุ ระดับพลัง พลังชีวิต และสถานะสั้นๆ แตะเพื่อดูรายละเอียดทั้งหมด'],['#sceneBox','🎨 ฉากชีวิต','ภาพพิกเซลเปลี่ยนตามสิ่งที่เกิดขึ้น ชุดและอาวุธเปลี่ยนตามตัวตนคุณ'],['#feed','📖 เรื่องราว','เหตุการณ์แต่ละปีจะค่อยๆ ขึ้นทีละบรรทัด แตะเพื่อให้ขึ้นทันที'],['#focus','🎯 โฟกัสประจำปี','เลือกว่าปีนี้จะทุ่มเทกับอะไร ฝึกยุทธ์ ลมปราณ หาเงิน หรือครอบครัว ผลจะต่างกัน'],['#pauseBtn','⏸ หยุด / เล่น','หยุดเวลาไว้ก่อนได้ทุกเมื่อ'],['#spdBtn','⏩ ความเร็ว','กดเพื่อเร่ง 1× 2× 4× 8× 16× หรือ ⚡A เร่งอัตโนมัติช่วงไม่มีอะไรเกิด'],['#bagBtn','🎒 กระเป๋า','ของที่เก็บได้ ใช้อัตโนมัติเมื่อจำเป็น ขายได้'],['#autoBtn','🤖 โหมดอัตโนมัติ','ให้ชีวิตดำเนินไปเอง ตัวเลือกจะถูกเลือกให้'],['#skipBtn','⏭ ข้ามข้อความ','ให้ข้อความที่เหลือของปีขึ้นทันที'],['#logBtn','📜 บันทึกชีวิต','ดูเหตุการณ์สำคัญย้อนหลังและอัลบั้มภาพ'],['#menuBtn','☰ เมนู','วิชา สำนัก ตลาด ครอบครัว แผนที่ ของตกแต่ง และการตั้งค่า']];
let tutI=-1,tutWasPaused=false;
function startTut(){closeM();tutI=0;tutWasPaused=paused;paused=true;let o=document.getElementById('tut');if(!o){o=document.createElement('div');o.id='tut';document.body.appendChild(o)}tutDraw()}
function tutDraw(){const o=document.getElementById('tut');if(tutI<0||tutI>=TUT.length){if(o)o.remove();tutI=-1;LS.set('murim_tut',1);paused=tutWasPaused;render&&S&&render();return}
 const [sel,t,d]=TUT[tutI],el=document.querySelector(sel);if(!el||!(el.offsetParent||(el.getClientRects().length&&getComputedStyle(el).visibility!=='hidden'&&(sel!=='#modal'||modalOpen)))){tutI++;return tutDraw()}
 const r=el.getBoundingClientRect(),vh=window.innerHeight,below=r.top<vh/2;
 o.innerHTML=`<div class="tut-hole" style="left:${r.left-4}px;top:${r.top-4}px;width:${r.width+8}px;height:${r.height+8}px"></div><div class="tut-tip" style="${below?`top:${Math.min(vh-170,r.bottom+12)}px`:`bottom:${Math.min(vh-170,vh-r.top+12)}px`}"><div class="tag2">${tutI+1}/${TUT.length}</div><b>${t}</b><div style="margin:4px 0 10px">${d}</div><div style="display:flex;gap:8px"><button class="gbtn" style="flex:1" onclick="tutI=-1;tutDraw()">ข้าม</button><button class="pbtn" style="flex:2" onclick="tutI++;tutDraw()">${tutI===TUT.length-1?'เริ่มเล่น!':'ถัดไป ▶'}</button></div></div>`}

