// ---------- 1) ตัวเลือกย่อไว้ก่อน + ชะตาตัดสินแทน ----------
const FATE_L=[0,5,10,20];
function fateSec(){return LS.get('murim_fate',0)}
function chMinDef(){return LS.get('murim_chmin',0)}
function choiceShow(){const c=choice._cur;if(!c)return;
 const fs=fateSec();
 modal(`<div class="chtop"><span class="tag2" id="chCd">${fs&&!auto?'⏳ ชะตาจะตัดสินใน '+fs+' วิ':''}</span><button class="minb" onclick="minChoice()">▾ ย่อไว้ก่อน</button></div><h3>${c.title}</h3><p>${c.text}</p>`+c.opts.map((o,i)=>`<button class="opt" data-i="${i}">${o.t}${o.s?`<small>${o.s}</small>`:''}</button>`).join('')+(auto?'<div class="tag2" style="text-align:center">🤖 กำลังตัดสินใจอัตโนมัติ...</div>':'')+
 `<div class="chfoot"><label><input type="checkbox" ${chMinDef()?'checked':''} onchange="LS.set('murim_chmin',this.checked?1:0)"> ให้ตัวเลือกขึ้นแบบย่อไว้ก่อน (เวลาจะหยุดรอจนกว่าจะเลือก)</label><button class="sysb" onclick="cycleFate()">⏳ ชะตาตัดสินแทน: ${fs?fs+' วิ':'ปิด'}</button></div>`,'choice');
 document.querySelectorAll('#modal .opt').forEach(b=>b.onclick=()=>choiceRun(+b.dataset.i));
 clearTimeout(choice._t);clearInterval(choice._cd);
 if(auto){const go=()=>{if(choice._cur&&modalOpen&&$('modal').dataset.k==='choice'){if(pendModal){choice._t=setTimeout(go,400);return}fateChoice(true)}};choice._t=setTimeout(go,(speed>=8||speed===0)?450:1300)}
 else if(fs){let left=fs;choice._cd=setInterval(()=>{if(!choice._cur||$('modal').dataset.k!=='choice'){clearInterval(choice._cd);return}if(pendModal||!modalOpen)return;left--;const e=$('chCd');if(e)e.textContent='⏳ ชะตาจะตัดสินใน '+left+' วิ';if(left<=0){clearInterval(choice._cd);fateChoice()}},1000)}
}
function choice(title,text,opts){
 if(choice._cur)fateChoice();
 choice._cur={title,text,opts,fac:S&&S.faction?S.faction.n:null};choice._min=false;
 if(chMinDef()&&!auto){choice._min=true;pendBar();return}
 choiceShow();
}
function choiceRun(i){const c=choice._cur;if(!c){if($('modal').dataset.k==='choice')closeM();return}
 if(c.fac&&S&&(!S.faction||S.faction.n!==c.fac)){clearTimeout(choice._t);clearInterval(choice._cd);choice._cur=null;choice._min=false;pendBar();if($('modal').dataset.k==='choice')closeM();log(`📜 เรื่อง「${String(c.title).replace(/<[^>]+>/g,'')}」ที่ค้างไว้จบลงเอง ตอนนี้คุณไม่ได้อยู่ใน${c.fac}แล้ว`);render();return}clearTimeout(choice._t);clearInterval(choice._cd);choice._cur=null;choice._min=false;pendBar();
 if($('modal').dataset.k==='choice')closeM();try{persNote(c.opts[i].t)}catch(e){}c.opts[i].f();render();checkDeath()}
function fateChoice(silent){const c=choice._cur;if(!c)return;const valid=c.opts.map((o,i)=>i).filter(i=>!c.opts[i].skip);const i=valid.length?ch(valid):0;
 if(!silent&&!auto)addFeed('ev',`🎲 ปล่อยให้ชะตาเลือก <b>${c.title.replace(/<[^>]+>/g,'')}</b>: ${c.opts[i].t.replace(/<[^>]+>/g,'')}`,'sum');
 choiceRun(i)}
function minChoice(){if(!choice._cur)return;clearInterval(choice._cd);choice._min=true;closeM();pendBar();toast('ย่อไว้แล้ว เวลาหยุดรอจนกว่าคุณจะเลือก')}
function openPend(){if(!choice._cur)return;if(modalOpen&&$('modal').dataset.k==='duel')return toast('จบการดวลก่อน');choice._min=false;pendBar();choiceShow()}
function cycleFate(){const v=FATE_L[(FATE_L.indexOf(fateSec())+1)%FATE_L.length];LS.set('murim_fate',v);choiceShow()}
function pendBar(){const b=$('pendBar');if(!b)return;const on=!!(choice._cur&&choice._min);b.style.display=on?'':'none';if(on)b.innerHTML=xT(`⏸ เวลาหยุดรอ มีเรื่องให้ตัดสินใจ: <b>${choice._cur.title.replace(/<[^>]+>/g,'')}</b> <span>แตะเพื่อเลือก</span>`)}

