// ---------- ตัวช่วย: เอฟเฟกต์แบบย่อ ----------
const FXN={k:'กรรม',i:'ปัญญา',c:'เสน่ห์',$:'เงิน',h:'พลังชีวิต',f:'ชื่อเสียง',p:'พลัง',q:'ลมปราณ',j:'ความสุข',l:'อายุขัย',m:'ผลงาน'};
function applyFx(s){if(!s)return;const re=/([a-z$])([+-]\d+(?:\.\d+)?)/g;let m;while((m=re.exec(s))){const k=m[1],v=+m[2];
 if(k==='k')S.karma+=v;else if(k==='i')S.int+=v;else if(k==='c')S.cha+=v;else if(k==='$')S.money=Math.max(0,S.money+(v>0?inc(v):v));else if(k==='h')S.hp=Math.min(S.maxHp,S.hp+v);
 else if(k==='f')S.fame=Math.max(0,S.fame+v);else if(k==='p')S.power+=v;else if(k==='q')S.qi+=v;else if(k==='j')joy(v);else if(k==='l')S.lifespan+=v;else if(k==='m')S.merit=(S.merit||0)+v}}
function fxDesc(s){if(!s)return'';const out=[];const re=/([a-z$])([+-]\d+(?:\.\d+)?)/g;let m;while((m=re.exec(s)))out.push(FXN[m[1]]+(+m[2]>0?'+':'')+(+m[2]));return out.join(' · ')}
// E: [หัวข้อ, เรื่อง, [[ตัวเลือก, เอฟเฟกต์, ผลลัพธ์], ...], เงื่อนไข?]
function runE(ev,tag){const [ti,tx,opts]=ev;choice((tag||'')+ti,typeof tx==='function'?tx():tx,opts.map(o=>({t:o[0],s:fxDesc(o[1]),f(){applyFx(o[1]);if(o[2])log(typeof o[2]==='function'?o[2]():o[2],/[-−]/.test(o[1]||'')&&!/\+/.test(o[1]||'')?'bad':'good');if(o[3])o[3]()}})))}
function mulb(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}

