function shadeC(c,a){try{let n=parseInt(c.slice(1),16),r=(n>>16)&255,g0=(n>>8)&255,b=n&255;const f=a<0?0:255,t=Math.abs(a);r=Math.round((f-r)*t+r);g0=Math.round((f-g0)*t+g0);b=Math.round((f-b)*t+b);return'#'+((1<<24)|(r<<16)|(g0<<8)|b).toString(16).slice(1)}catch(e){return c}}
function drawBeast(c,b,ox,oy,s,fr){s=s||1;fr=fr||0;const R0=(x,y,w,h,col)=>{c.fillStyle=col;c.fillRect(ox+x*s,oy+y*s,w*s,h*s)};
 const base=b.col,ec=b.ec,dk=shadeC(base,-.35),lt=shadeC(base,.25),eye=b.t>=5?ec:'#1a1a1a',bob=Math.round(Math.sin(fr*.15)*.6);
 if(b.f.glow){c.fillStyle=ec+'33';c.fillRect(ox,oy+2*s,32*s,22*s)}
 const k=b.k;
 if(k==='quad'||k==='qilin'){const y=8+bob;R0(8,y,14,7,base);R0(8,y+5,14,2,dk);R0(9,y-1,12,1,lt);
  R0(21,y-4,7,6,base);R0(26,y-1,3,2,dk);R0(24,y-3,1,1,eye);if(b.f.eye3)R0(23,y-5,1,1,ec);if(b.f.head2){R0(19,y-7,6,5,base);R0(21,y-6,1,1,eye)}
  R0(22,y-6,2,2,dk);R0(25,y-6,2,2,dk);const lg=fr%20<10?0:1;R0(9,y+7,2,4+lg,dk);R0(13,y+7,2,4-lg,dk);R0(17,y+7,2,4+lg,dk);R0(20,y+7,2,4-lg,dk);
  if(b.f.tail9){for(let t=0;t<5;t++)R0(3-t%2,y-3+t*2,6,1,t%2?ec:lt)}else{R0(4,y+1,5,2,base);R0(2,y-1,3,2,base)}
  if(b.f.horn){R0(22,y-8,1,3,ec);R0(26,y-8,1,3,ec)}if(b.f.spike)for(let t=0;t<5;t++)R0(10+t*2,y-2,1,2,ec);if(k==='qilin'){R0(10,y+1,10,1,ec);R0(21,y-5,6,1,ec)}
  if(b.f.wing){R0(11,y-6,6,5,lt);R0(10,y-7,4,2,ec)}}
 else if(k==='serp'||k==='drag'){for(let t=0;t<11;t++){const x=3+t*2.3,y=12+Math.round(Math.sin(t*.8+fr*.12)*3);R0(x,y,4,4,t%2?base:dk);if(k==='drag'&&t%3===0)R0(x,y-1,3,1,ec)}
  const hx=27,hy=10+Math.round(Math.sin(8.8+fr*.12)*3);R0(hx,hy,5,5,base);R0(hx+3,hy+1,1,1,eye);R0(hx+4,hy+3,2,1,'#c82a2a');
  if(k==='drag'){R0(hx,hy-3,1,3,ec);R0(hx+3,hy-3,1,3,ec);R0(hx+5,hy+2,3,1,lt);R0(8,17,2,3,dk);R0(18,17,2,3,dk)}if(b.f.wing){R0(12,4,7,5,lt);R0(11,3,4,2,ec)}if(b.f.head2)R0(hx-2,hy-5,4,4,base)}
 else if(k==='bird'){const fl=fr%16<8;const y=9+bob;R0(12,y,9,6,base);R0(13,y+5,7,1,dk);R0(20,y-3,5,5,base);R0(23,y-2,1,1,eye);R0(25,y-1,3,1,'#e0a030');
  R0(fl?6:8,fl?y-6:y+1,8,fl?6:3,lt);R0(fl?5:7,fl?y-7:y+1,4,2,ec);R0(7,y+3,5,2,dk);R0(4,y+4,4,1,ec);R0(15,y+6,1,3,'#c8a040');R0(18,y+6,1,3,'#c8a040');if(b.f.horn)R0(21,y-5,1,2,ec);if(b.f.tail9)for(let t=0;t<4;t++)R0(2,y+1+t*2,6,1,t%2?ec:lt)}
 else if(k==='bug'){const y=11+bob;for(let t=0;t<4;t++)R0(8+t*4,y,4,5,t%2?base:dk);R0(24,y,5,4,base);R0(27,y+1,1,1,eye);for(let t=0;t<4;t++){R0(9+t*4,y+5,1,3,dk);R0(10+t*4,y-2,1,2,dk)}R0(28,y-2,3,1,dk);R0(28,y+4,3,1,dk);
  if(b.sp==='แมงป่อง'){R0(4,y-4,2,5,base);R0(5,y-6,3,2,ec)}if(b.sp==='ผีเสื้อ'){R0(10,y-8,7,7,ec);R0(16,y-8,6,7,lt)}if(b.f.wing&&b.sp!=='ผีเสื้อ')R0(12,y-5,8,4,lt+'aa')}
 else if(k==='fish'){const y=10+bob;R0(8,y,16,7,base);R0(9,y+5,14,2,dk);R0(10,y-1,10,1,lt);R0(21,y+2,1,1,eye);R0(3,y+fr%10<5?0:1,5,7,ec);R0(14,y-3,4,3,ec);R0(13,y+7,3,2,ec)}
 else if(k==='ape'){const y=4+bob;R0(11,y+5,10,10,base);R0(12,y+13,8,2,dk);R0(12,y,8,6,base);R0(14,y+2,1,1,eye);R0(17,y+2,1,1,eye);R0(14,y+4,4,1,dk);R0(8,y+6,3,9,base);R0(21,y+6,3,9,base);R0(12,y+15,3,4,dk);R0(17,y+15,3,4,dk);if(b.f.eye3)R0(16,y+1,1,1,ec);if(b.f.horn){R0(12,y-2,1,2,ec);R0(19,y-2,1,2,ec)}}
 else if(k==='turt'){const y=10+bob;R0(8,y,16,6,base);R0(9,y-2,14,2,lt);for(let t=0;t<4;t++)R0(10+t*3,y+1,2,2,dk);R0(24,y+1,5,4,shadeC(base,.15));R0(27,y+2,1,1,eye);R0(9,y+6,3,3,dk);R0(19,y+6,3,3,dk);if(b.sp==='เต่ามังกร'||b.f.horn)R0(25,y-1,1,2,ec);if(b.f.spike)for(let t=0;t<5;t++)R0(10+t*3,y-3,1,1,ec)}
 if(b.f.big){c.strokeStyle=ec+'88';c.lineWidth=Math.max(1,s*.5);c.strokeRect(ox+1*s,oy+2*s,30*s,21*s)}}
function beastImg(b,px){try{const cv=document.createElement('canvas');cv.width=32*(px||3);cv.height=24*(px||3);const c=cv.getContext('2d');if(!c)return'';c.imageSmoothingEnabled=false;drawBeast(c,b,0,0,px||3,0);return cv.toDataURL()}catch(e){return''}}
const bImgTag=(b,w)=>{const u=beastImg(b,3);return u?`<img class="bimg" src="${u}" style="width:${w||96}px;height:${(w||96)*.75}px">`:''};
// ---- สมุดสัตว์ (สะสมข้ามชีวิต) ----
function bdexGet(){return LS.get('murim_bdex',{})}
function bdexAdd(b,how){const d=bdexGet();const was=!!d[b.i];d[b.i]=Math.max(d[b.i]||0,how==='tame'?3:how==='kill'?2:1);LS.set('murim_bdex',d);if(!was)toast('📖 บันทึกสัตว์ใหม่: '+b.n);return!was}
function openBestiary(w,page){w=w==null?(CFG.xian?1:0):w;page=page||0;const d=bdexGet(),L=beasts().filter(b=>b.w===w),seen=L.filter(b=>d[b.i]),per=24,pages=Math.ceil(L.length/per),slice=L.slice(page*per,page*per+per);
 const all=Object.keys(d).length;
 modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>📖 สมุดสัตว์${w?'วิญญาณ':'อสูร'}</h3><p class="tag2">พบแล้ว ${seen.length}/${L.length} ตัว · รวมทั้งสองโลก ${all}/${BEAST_N} (${Math.round(all/BEAST_N*100)}%) · ⚔️ ปราบ · 🪢 สยบ · 👀 เห็น</p>
 <div class="tabs"><button class="tabb ${w===0?'on':''}" onclick="openBestiary(0)">⚔️ สัตว์อสูรยุทธภพ</button><button class="tabb ${w===1?'on':''}" onclick="openBestiary(1)">☁️ สัตว์วิญญาณเซียน</button></div>
 <div class="bgrid">${slice.map(b=>d[b.i]?`<div class="bcard t${Math.min(5,Math.floor(b.t/2))}" onclick="beastInfo(${b.i})">${bImgTag(b,72)}<b>${b.n}</b><small>${btierN(b)} · ${['','👀','⚔️','🪢'][d[b.i]]}</small></div>`:`<div class="bcard unk"><div class="bq">?</div><b>???</b><small>${btierN(b)}</small></div>`).join('')}</div>
 <div class="brow" style="margin-top:8px"><button class="gbtn" ${page?'':'disabled'} onclick="openBestiary(${w},${page-1})">◀</button><span class="tag2" style="align-self:center">หน้า ${page+1}/${pages}</span><button class="gbtn" ${page<pages-1?'':'disabled'} onclick="openBestiary(${w},${page+1})">▶</button></div>`,'bdex')}
function beastInfo(i){const b=beasts()[i];modal(`<button class="xbtn" onclick="openBestiary(${b.w},${Math.floor(beasts().filter(x=>x.w===b.w).indexOf(b)/24)})">←</button><h3>${b.n}</h3><div style="text-align:center">${bImgTag(b,192)}</div>
 <ul class="speclist"><li>ระดับ: <b>${btierN(b)}</b></li><li>พันธุ์: ${b.sp} · ธาตุ${b.el} · ${b.ad}</li><li>นิสัย: ${b.tm} · ถิ่นอาศัย: ${b.hab}</li><li>พลังโดยประมาณ: ${fmt(b.ep)}</li><li>ของที่ได้: ${b.t<3?'หนังเกล็ดอสูร':b.t<6?'หนังเกล็ด · แก่นอสูร':'แก่นอสูร · หยกดิบ · แก่นอสูรโบราณ'}</li></ul>`,'bdex')}

// ---- เจอสัตว์ระหว่างการจำลอง ----
Object.assign(BAGIT,{hide:{n:'หนังเกล็ดอสูร',ic:'🦴',v:140},bcore:{n:'แก่นอสูรโบราณ',ic:'🔮',v:2400}});
MATS.push('hide');
Object.assign(RCP,{f7:{k:'forge',n:'เกราะเกล็ดอสูร',lv:2,m:{hide:4,ore:2},out:{eq:'t5'}},a7:{k:'alch',n:'ยาแก่นอสูร',lv:3,m:{core:2,herb:2},out:{bag:'bpill',q:1}},r5:{k:'arr',n:'ค่ายกลกักอสูร',lv:4,m:{bcore:1,jade:2},out:{buf:'fight',v:1.2,y:5}}});
function beastPick(near){const ri=realmIdx(),w=S.xian?1:0,L=beasts().filter(b=>b.w===w&&b.t<=Math.min(9,ri+(near?1:3)));const wt=L.map(b=>({w:1/(1+Math.abs(b.t-(ri+1))*1.5),b}));return pickW(wt).v.b}
function beastLoot(b){const got=[];const add=(k,n)=>{bagAdd(k,n,true);got.push(BAGIT[k].ic+BAGIT[k].n+'×'+n)};
 add('hide',R(1,2+Math.floor(b.t/3)));if(b.t>=3)add('core',R(1,1+Math.floor(b.t/3)));if(b.t>=6&&Math.random()<.5)add('jade',R(1,2));if(b.t>=7&&Math.random()<.35)add('bcore',1);return got.join(' · ')}
function tameOdds(b){const r=myPow()/(b.ep*1.2);return Math.max(.03,Math.min(.85,(.15+r*.35)*b.tmm*(1+S.cha/600)*(S.beast?(typeof bSlotFree==='function'&&bSlotFree()>0?.8:.5):1)*(b.t>realmIdx()+2?.3:1)))}
function beastFight(b){const my=myPow()*(.75+Math.random()*.5),en=b.ep*(.75+Math.random()*.5);const win=my>=en;const dmg=Math.round((win?R(4,14):R(18,40))*(1-gv('armor','red')-eqA('red')-bufA('red')));S.hp-=Math.max(1,dmg);return{win,dmg}}
function beastEncounter(b,where){b=b||beastPick();const img=bImgTag(b,120);const isNew=!bdexGet()[b.i];setScene('fight',{beast:b});if(sceneEvt)sceneEvt.t=Date.now()+20000;
 choice(`${isNew?'✨ ':''}🐾 พบ${btierN(b)}`,`${img?`<div style="text-align:center">${img}</div>`:''}<b>${b.n}</b> (${b.sp} ธาตุ${b.el} · นิสัย${b.tm})<br>${where||'โผล่ออกมาจาก'+b.hab+' ขวางทางคุณไว้'}<br><span class="tag2">พลังประมาณ ${fmt(b.ep)} · พลังคุณ ${fmt(Math.round(myPow()))}</span>`,[
  {t:'⚔️ ต่อสู้',s:`ชนะได้ของจากสัตว์ · โอกาส ~${Math.round(Math.min(.95,myPow()/(myPow()+b.ep))*100)}%`,f(){const r=beastFight(b);if(r.win){S.kills++;S.fame+=3+b.t*4;bdexAdd(b,'kill');log(`⚔️ ปราบ<b>${b.n}</b>ได้! (−${r.dmg} พลังชีวิต) ได้ ${beastLoot(b)}`,b.t>=6?'epic':'good',b.t>=6)}else{bdexAdd(b,'see');log(`🩸 ${b.n}แข็งแกร่งเกินคาด คุณบาดเจ็บหนักต้องถอยหนี (−${r.dmg} พลังชีวิต)`,'bad')}}},
  {t:'🪢 พยายามสยบมาเป็นสัตว์คู่ใจ',s:S.beast?`มีสัตว์คู่ใจอยู่แล้ว (${S.beast.nick}) — ${typeof bTameNote==='function'?bTameNote():'ถ้าสำเร็จจะปล่อยตัวเก่า'} · ~${Math.round(tameOdds(b)*100)}%`:`โอกาส ~${Math.round(tameOdds(b)*100)}%`,f(){if(Math.random()<tameOdds(b)){bdexAdd(b,'tame');if(S.beast){if(typeof bTeamKeep==='function'&&bTeamKeep(S.beast))log(`🏡 ${S.beast.nick} กลับไปอยู่บ้าน ตัวใหม่ติดตัวแทน`);else log(`ปล่อย${S.beast.nick}คืนสู่ป่า`)}S.beast={i:b.i,lv:1,xp:0,st:0,bond:40+R(0,20),nick:ch(['เสี่ยว','อา','ต้า'])+ch(['ไป๋','เฮย','หง','จิน','หลาน','ฮวา','เล่ย','อวิ๋น']),hum:0};
     log(`🪢 สยบ<b>${b.n}</b>สำเร็จ! ตั้งชื่อให้ว่า "${S.beast.nick}" — กลายเป็นสัตว์คู่ใจ`,'epic',true);sfx('rare')}else{const r=beastFight(b);bdexAdd(b,'see');log(`${b.n}ไม่ยอมสยบ หันมาจู่โจม (−${r.dmg} พลังชีวิต)`,'bad')}}},
  {t:'👀 แอบสังเกตแล้วจดบันทึก',s:'ปัญญา + · บันทึกลงสมุดสัตว์',f(){bdexAdd(b,'see');S.int+=2+Math.floor(b.t/2);log(`👀 แอบสังเกต${b.n}อยู่นาน จดลักษณะนิสัยและจุดอ่อนลงสมุด`)}},
  {t:'🏃 หนี',f(){if(Math.random()<.8){log('ถอยหนีมาได้อย่างปลอดภัย')}else{const d=R(5,15);S.hp-=d;log(`หนีไม่ทัน โดนกรงเล็บข่วนเป็นแผล (−${d})`,'bad')}}}])}
function beastTick(){if(S.age<8||(S.beastMode&&!S.beastMode.human))return false;const hot=['adv','mission'].includes(S.focus)||S.region;if(Math.random()<(hot?.2:.07)){beastEncounter();return true}return false}
// ---- 2) สัตว์คู่ใจ เติบโต วิวัฒนาการ แปลงกาย ----
const bOf=()=>S&&S.beast?beasts()[S.beast.i]:null;
function beastStageN(){const b=bOf(),st=S.beast.st;return st===0?b.n:st===1?b.n+'ตื่นรู้':(['เทพ','ราชา','จักรพรรดิ'][b.t%3])+b.sp+'สวรรค์'}
let beastM=()=>{if(!S||!S.beast)return 1;const b=bOf();return 1+.04+.03*S.beast.st+Math.min(.12,S.beast.lv*.004)+b.t*.006}
function beastCompTick(){if(!S.beast)return;const B=S.beast,b=bOf();B.xp+=1+(S.focus==='adv'?2:0)+(S.xian?1:0);while(B.xp>=B.lv*2&&B.lv<60){B.xp-=B.lv*2;B.lv++}
 if(B.st===0&&B.lv>=10){B.st=1;log(`🐾 ${B.nick} วิวัฒนาการเป็น <b>${beastStageN()}</b>! ร่างกายใหญ่ขึ้น ดวงตาเปล่งแสง`,'epic',true)}
 else if(B.st===1&&B.lv>=25&&b.t>=3){B.st=2;log(`🌟 ${B.nick} ผ่านทัณฑ์ฟ้าวิวัฒนาการสูงสุดเป็น <b>${beastStageN()}</b>!`,'myth',true)}
 if(B.st===2&&!B.hum&&(b.t>=5||['เจ้าเล่ห์','ภักดี'].includes(b.tm))&&Math.random()<.2){B.hum=1;B.hn=anyName(Math.random()<.5?'หญิง':'ชาย');log(`✨ ${B.nick} แปลงกายเป็นมนุษย์ได้แล้ว! ในร่างคนชื่อว่า <b>${B.hn}</b> ยังคงเรียกคุณว่าเจ้านายเหมือนเดิม`,'myth',true)}
 B.bond=Math.min(100,B.bond+1);if(Math.random()<.18)addFeed('ev',`🐾 ${B.nick} ${ch(['คาบปลามาฝาก','นอนขดข้างกองไฟ','ไล่ขโมยออกไปจากบ้าน','ช่วยคุณฝึกซ้อม','พาคุณไปเจอสมุนไพรหายาก'])}`,'sum');if(Math.random()<.06)bagAdd('herb',1,true)}
function openBeastComp(){const B=S.beast;if(!B){modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>🐾 สัตว์คู่ใจ</h3><p class="tag2">ยังไม่มี ออกท่องยุทธภพหรือลงดันเจี้ยนแล้วลองสยบสัตว์ที่เจอ</p><button class="gbtn" style="width:100%" onclick="openBestiary()">📖 สมุดสัตว์</button>`,'bcomp');return}
 const b=bOf();modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>🐾 ${B.nick}${B.hum?' ('+B.hn+')':''}</h3><div style="text-align:center">${bImgTag(b,160)}</div>
 <ul class="speclist"><li>ร่างปัจจุบัน: <b>${beastStageN()}</b></li><li>${btierN(b)} · ${b.sp} ธาตุ${b.el} · นิสัย${b.tm}</li><li>เลเวล ${B.lv} (ถัดไป ${B.xp}/${B.lv*2}) · ความผูกพัน ${B.bond}/100</li><li>ช่วยต่อสู้ ×${beastM().toFixed(2)}${B.hum?' · แปลงกายเป็นมนุษย์ได้':''}</li><li>วิวัฒนาการ: เลเวล 10 → ตื่นรู้ · เลเวล 25 → ร่างสูงสุด${b.t<3?' (สัตว์ระดับนี้ไปได้ถึงร่างตื่นรู้)':''}</li></ul>
 <div class="brow"><button class="gbtn" onclick="openBestiary()">📖 สมุดสัตว์</button><button class="gbtn" onclick="if(confirm2())0">🌿 ปล่อยคืนป่า</button></div>`,'bcomp')}
function confirm2(){modal(`<h3>ปล่อย ${S.beast.nick} คืนป่า?</h3><p>ปล่อยแล้วจะเรียกกลับไม่ได้</p><div class="brow"><button class="gbtn" onclick="openBeastComp()">ไม่ปล่อย</button><button class="pbtn" onclick="log('🌿 ปล่อย '+S.beast.nick+' คืนสู่ป่า มันหันกลับมามองครั้งสุดท้ายก่อนหายไป');S.beast=null;joy(-5);closeM();render()">ปล่อย</button></div>`,'bcomp')}
// ---- 4) คลื่นสัตว์อสูร ----
function tideTick(){if(S.age<12||(S.beastMode&&!S.beastMode.human))return false;if(S.tideY!=null&&S.age-S.tideY<15)return false;if(Math.random()>.06)return false;S.tideY=S.age;const W=S.xian?'คลื่นสัตว์วิญญาณคลุ้มคลั่ง':'คลื่นสัตว์อสูร';
 const L=[beastPick(),beastPick(),beastPick(true)];setScene('fight');
 choice(`🌊 ${W}!`,`ฝูงสัตว์นับพันจาก${L[0].hab}คลุ้มคลั่งบุกเข้าใส่เมือง นำโดย<b>${L[2].n}</b> (${btierN(L[2])})<br>เสียงกลองเตือนภัยดังไปทั่ว`,[
  {t:'⚔️ ออกรบแนวหน้า',s:'สู้ 3 ครั้ง · ชื่อเสียงและของมาก · เสี่ยงบาดเจ็บ',f(){let w=0,loot=[];for(const b of L){const r=beastFight(b);if(r.win){w++;loot.push(beastLoot(b));bdexAdd(b,'kill')}else bdexAdd(b,'see')}S.fame+=w*25;S.kills+=w;log(`🌊 ออกรบใน${W} ชนะ ${w}/3 ศึก${w?' · ได้ '+loot.join(' · '):''}${w===3?' ผู้คนยกย่องเป็นวีรบุรุษ':''}`,w>=2?'epic':'bad',w===3);if(w===3)S.karma+=5}},
  {t:'🛡️ ปกป้องชาวบ้านให้อพยพ',s:'กรรม + · สู้ 1 ครั้ง',f(){const r=beastFight(L[0]);S.karma+=8;S.fame+=10;log(r.win?`🛡️ คุ้มกันชาวบ้านหนีออกมาได้หลายร้อยคน ปราบ${L[0].n}ที่ไล่ตามมาได้`:`🛡️ คุ้มกันชาวบ้านหนีได้ แต่บาดเจ็บหนักจาก${L[0].n} (−${r.dmg})`,r.win?'good':'bad')}},
  {t:'🎯 ฉวยโอกาสล่าหัวหน้าฝูง',s:'ศึกเดียว เสี่ยงสูง รางวัลสูง',f(){const r=beastFight(L[2]);if(r.win){S.fame+=60;S.kills++;bdexAdd(L[2],'kill');log(`🎯 ฝ่ากลางฝูงไปสังหาร<b>${L[2].n}</b>ได้! ฝูงสัตว์แตกกระเจิง · ได้ ${beastLoot(L[2])} ${beastLoot(L[2])}`,'myth',true)}else{S.hp-=R(10,25);log(`🎯 ${L[2].n}แข็งแกร่งเกินไป คุณถูกเหวี่ยงกระเด็นบาดเจ็บสาหัส`,'bad')}}},
  {t:'🏃 อพยพหนีไปเมืองอื่น',s:'ปลอดภัย · เสียเงิน 20%',f(){S.money=Math.round(S.money*.8);joy(-4);log(`🏃 ทิ้งบ้านอพยพหนี${W} สูญทรัพย์สินไปไม่น้อย`)}}]);return true}

