const BL_SP=[['จิ้งจอก','quad','#e07030','ฉลาด เจ้าเล่ห์ อายุยืน'],['งูขาว','serp','#eeeeee','อดทน บำเพ็ญได้นาน'],['กระเรียน','bird','#f4f4f4','สง่างาม ใกล้ชิดเซียน'],['พยัคฆ์','quad','#d8902a','แข็งแกร่ง ดุดัน'],['เต่าดำ','turt','#2a3a3a','อายุยืนที่สุด ช้าแต่มั่นคง'],['ปลาคาร์ป','fish','#e88a3a','ฝันจะกระโดดข้ามประตูมังกร'],['วานร','ape','#8a6a4a','ซน ฉลาด เลียนแบบมนุษย์'],['หมาป่า','quad','#8a8a92','ภักดีต่อฝูง']];
const BFOCUS=[['hunt','🍖','ล่าเหยื่อ'],['moon','🌕','ดูดซับแสงจันทร์'],['roam','🗺️','ท่องป่า'],['hide','🌿','ซ่อนตัวพักฟื้น'],['human','🏘️','แอบดูมนุษย์']];
