function blMe(){const m=S.beastMode,sp=BL_SP.find(x=>x[0]===m.sp)||BL_SP[0];return{i:-1,w:S.xian?1:0,t:Math.min(9,m.st*2),n:m.sp,sp:m.sp,k:sp[1],col:sp[2],el:m.el,ec:(BEL.find(e=>e[0]===m.el)||BEL[0])[1],ad:'',tm:'',f:{wing:sp[1]==='bird',horn:m.st>=3,tail9:m.sp==='จิ้งจอก'&&m.st>=4,spike:false,eye3:false,head2:false,big:m.st>=4,glow:m.st>=2}}}
function goBeastLife(){modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>🐾 เกิดเป็นสัตว์</h3><p class="tag2">เริ่มจากลูกสัตว์ในป่า บำเพ็ญจนเปิดปัญญา กลายเป็นอสูร แล้วเลือกว่าจะแปลงกายเป็นมนุษย์หรือครองป่าเป็นราชาอสูร</p><p>ฟ้าจะลิขิตว่าคุณจะเกิดเป็นสัตว์อะไร ธาตุไหน และพรสวรรค์แบบใด เลือกเองไม่ได้</p><button class="pbtn" style="width:100%" onclick="closeM();beastBirth(R(0,BL_SP.length-1))">🎲 สุ่มเกิดเป็นสัตว์</button><p class="tag2" style="margin-top:6px">🏆 ชีวิตสัตว์อสูรขึ้นทำเนียบแยกของตัวเอง</p>`)}
function beastBirth(i){const sp=BL_SP[i],el=ch(BEL)[0],gn=GENDER[R(0,1)];crForce=null;
 const fam=Object.assign({},FAMILY[0],{n:'สัตว์ในป่าลึก',d:'เกิดในโพรงไม้กลางป่า ไม่มีใครรู้จัก',money:0,orphan:1,beast:1});
 roll={g:{v:gn,p:.5},f:{v:fam,p:1},t:{v:TALENT[R(1,3)],p:1},isOw:false,op:1,w:null,it:null,trs:{list:[],p:1},p:1,seed:R(1,99999),era:{v:ERAS[0],p:1},custom:false,look:null};
 roll.root=rootOf(roll.t.v);roll.name=ch(['เจ้า','อา','เสี่ยว'])+sp[0]+ch(['น้อย','ขาว','ดำ','ทอง','ไฟ','จันทร์']);roll.soul=null;roll.goals=[GOALS[0].id];roll.goal=GOALS[0].id;rerolls=0;startLife();
 S.beastMode={sp:sp[0],el,st:0,human:0};S.lifespan+=S.xian?400:180;S.focus='hunt';S.flags.lostParents=1;S.parents=[];S.sibs=[];
 log(`🐾 ${S.name} ลืมตาดูโลกเป็นลูก${sp[0]}ธาตุ${el} ในโพรงไม้กลางป่าลึก`,'epic',true);render()}
const BL_EV=[
 ['🪤 กับดักนายพราน','เดินไปเจอบ่วงลวดที่นายพรานซ่อนไว้ใต้ใบไม้',[['กัดบ่วงจนขาด','h-12 p+6','ฟันเกือบหัก แต่หลุดออกมาได้'],['ค่อยๆ ถอยออก','i+3','ดมกลิ่นเหล็กแล้วถอยห่าง จดจำกลิ่นมนุษย์ไว้']]],
 ['🌕 คืนจันทร์เต็มดวง','แสงจันทร์สาดลงมาบนลานหินกลางป่า พลังฟ้าดินเข้มข้นผิดปกติ',[['นั่งดูดซับทั้งคืน','q+3 h-4','ลมปราณไหลเวียนในร่าง ดวงตาเริ่มเปล่งแสง'],['ไล่ล่าสัตว์ที่ออกมาเล่นแสงจันทร์','p+10','ได้อาหารอิ่มท้อง']]],
 ['🐺 ฝูงคู่แข่ง','ฝูงสัตว์อีกกลุ่มรุกล้ำเข้ามาในอาณาเขต',[['สู้ปกป้องถิ่น','p+15 h-15 f+5','ไล่พวกมันออกไปได้ แต่แผลเต็มตัว'],['ยอมถอยไปหาถิ่นใหม่','j-3 i+2','ย้ายไปอยู่ลึกกว่าเดิม']]],
 ['🧙 นักพรตเฒ่า','นักพรตชราคนหนึ่งนั่งสมาธิใต้ต้นสน เขาหันมามองแล้วยิ้ม',[['เข้าไปใกล้','q+4 k+5','เขาลูบหัวแล้วสอนวิธีหายใจรับพลังฟ้าดิน'],['หนีไป','','มนุษย์น่ากลัว ไม่ไว้ใจใครทั้งนั้น']]],
 ['🍑 ผลไม้วิญญาณ','กลิ่นหอมประหลาดลอยมาจากหน้าผา มีผลไม้สีทองสุกอยู่ลูกเดียว',[['ปีนขึ้นไปกิน','q+5 l+20 h-8','ร่างกายร้อนผ่าว อายุขัยยืดยาวออก'],['ปล่อยไว้','k+3','สัตว์ใหญ่ตัวอื่นเฝ้าอยู่ ไม่คุ้มเสี่ยง']]],
 ['🏹 กองนักล่า','ผู้ฝึกตนกลุ่มหนึ่งเข้ามาล่าสัตว์อสูรเอาแก่น',[['ซ่อนตัวนิ่ง','i+3','รอจนพวกเขาผ่านไป'],['ล่อพวกเขาไปทางอื่น','p+8 h-10 f+8','วิ่งนำพวกเขาวนจนหลงป่า'],['จู่โจม','p+18 h-25 k-5','ทำร้ายมนุษย์ได้หลายคน ข่าวสัตว์อสูรดุร้ายแพร่ไปทั่ว']]],
 ['💕 คู่ครอง','พบสัตว์พันธุ์เดียวกันที่ถูกชะตา',[['อยู่ด้วยกัน','j+10','มีครอบครัวเล็กๆ ในป่า',()=>{S.kids=(S.kids||0)+R(1,3)}],['ใช้ชีวิตลำพังบำเพ็ญต่อ','q+2','หัวใจมุ่งสู่เต๋าเพียงอย่างเดียว']]],
 ['⛈️ ฟ้าผ่ากลางป่า','สายฟ้าฟาดลงต้นไม้ใกล้ๆ ไฟลุกลาม',[['หนีไฟ','h-5','รอดมาได้หวุดหวิด'],['ฝ่าเข้าไปดูดซับพลังอัสนี','q+4 h-20 p+10','ร่างกายไหม้เกรียมแต่พลังเพิ่มพูน']]],
 ['👶 เด็กมนุษย์หลงป่า','เด็กน้อยคนหนึ่งร้องไห้อยู่ใต้ต้นไม้',[['พากลับไปส่งชายป่า','k+12 j+5','ชาวบ้านเล่าลือถึงสัตว์ใจดีในป่า'],['ปล่อยไว้','k-3','ไม่ใช่เรื่องของเรา'],['เฝ้าจนพ่อแม่มาตามหา','k+8 i+2','แอบมองครอบครัวมนุษย์กอดกันอยู่นาน']]],
 ['🐍 สัตว์อสูรครองถิ่น','สัตว์อสูรตัวใหญ่ประกาศว่าป่านี้เป็นของมัน',[['ยอมเป็นลูกน้อง','p+5 j-5','ได้ส่วนแบ่งอาหารแต่ต้องรับใช้'],['ท้าสู้','p+25 h-30 f+15','สู้กันสามวันสามคืน'],['ย้ายป่า','i+2','ป่าใหม่เงียบสงบกว่า']]]];
function blAdvance(){const m=S.beastMode;const need=[[3,0,0],[12,6,0],[0,20,450],[0,45,1500]];if(m.st>=4)return;const [age,qi,pow]=need[m.st];
 if(S.age>=age&&S.qi>=qi&&total()>=pow){m.st++;log(`🌟 ${S.name} ก้าวสู่ขั้น <b>${BL_ST[m.st]}</b>!${m.st===2?' เริ่มเข้าใจภาษามนุษย์ และมีความคิดเป็นของตัวเอง':m.st===4?' ทัณฑ์ฟ้าผ่านพ้น พลังเทียบเท่ายอดฝีมือมนุษย์':''}`,'myth',true);S.maxHp+=20;S.hp=S.maxHp;
  if(m.st===4){const tryC=()=>{if(choice._cur||modalOpen)return setTimeout(tryC,600);choice('🌙 ทางแยกของอสูรพันปี',`พลังของ${esc(S.name)}มาถึงขีดที่แปลงกายได้แล้ว<br>จะทิ้งร่างสัตว์ไปใช้ชีวิตเป็นมนุษย์ หรือครองป่าเป็นราชาอสูร?`,[
   {t:'🧑 แปลงกายเป็นมนุษย์',s:'เล่นต่อในร่างคน พลังเดิมติดตัว · ⚠️ ต้องเลือกเอง ชะตาจะไม่เลือกให้ · ตอนสืบทอดยังเลือกให้ลูกเป็นร่างสัตว์ได้',noFate:1,f(){m.bName=S.name;m.human=1;const g0=S.gender;S.name=anyName(g0);S.family=Object.assign({},S.family,{n:'อสูรแปลงกาย'});S.focus='train';S.flags.transformed=1;log(`✨ ร่างสัตว์สลายเป็นแสง กลายเป็นมนุษย์รูปงามชื่อ <b>${S.name}</b> ก้าวเข้าสู่โลกมนุษย์`,'myth',true);setScene('aura');render()}},
   {t:'👑 ครองป่าเป็นราชาอสูร',s:'อยู่ในร่างสัตว์ต่อ ขยายอาณาเขต · แปลงกายทีหลังได้ที่ ☰',f(){m.king=1;S.fame+=200;log(`👑 ${S.name} ประกาศตนเป็นราชาอสูรแห่ง${ch(BHAB[S.xian?1:0])} สัตว์ทั้งป่าก้มหัวให้`,'myth',true)}}])};setTimeout(tryC,400)}}}
function beastYear(){yearSum();yearSnap();const m=S.beastMode,f=S.focus;const mul=S.talent.m*(S.xian?1.4:1);
 if(f==='hunt'){S.power+=Math.round(R(8,18)*mul*(1+m.st*.6));if(Math.random()<.25)S.hp-=R(4,12);joy(2)}else if(f==='moon'){S.qi+=+(R(6,14)/10*mul*(m.st>=1?1.5:.6)).toFixed(1)}else if(f==='roam'){S.int+=R(1,3);if(Math.random()<.35){const b=beastPick(true);bdexAdd(b,'see');addFeed('ev',`🐾 พบ${b.n}ระหว่างท่องป่า แอบมองแล้วจากมา`,'sum')}}else if(f==='hide'){S.hp=Math.min(S.maxHp,S.hp+25);joy(3)}else if(f==='human'){S.int+=R(2,5);S.cha+=1;if(Math.random()<.2){S.hp-=R(10,20);log('🏘️ ชาวบ้านเห็นเข้า ไล่ตีด้วยไม้และคบไฟ','bad')}}
 S.age++;ensureHeader();S.hp=Math.min(S.maxHp,S.hp+R(4,9));
 try{blYearEvent()}catch(e){console.error(e)}
 if(S.age%3===0&&Math.random()<.4&&m.st>=1)tideTick();
 blAdvance();render();checkDeath();saveGame()}

// ---------- 5) จำเหตุการณ์ข้ามชีวิต ----------
const evSeen=()=>LS.get('murim_evseen',{});
function evMark(k){const d=evSeen(),was=d[k]||0;d[k]=was+1;LS.set('murim_evseen',d);return was}
function evW(k,w){const n=evSeen()[k]||0;return w*(n?1/(1+n*.6):1.8)}
function newTag(k){if(!(evSeen()[k]))addFeed('ev','✨ เหตุการณ์ใหม่ที่ไม่เคยเจอมาก่อน','sum')}

