const PERS=[['kind','ใจดี','💗',/ช่วย|แบ่ง|ยอม|ดูแล|รับเลี้ยง|ปกป้อง|รักษา|อภัย|ไว้ชีวิต|บริจาค/],['ruth','เหี้ยมโหด','🩸',/ฆ่า|สังหาร|ปลิดชีพ|แก้แค้น|จู่โจม|บุก|ทำลาย|ทรมาน|ตัด/],['cun','เจ้าเล่ห์','🦊',/หลอก|แอบ|ขโมย|วางแผน|ลอบ|ต่อรอง|ฉวยโอกาส|เจรจา|สะกดรอย/],['calm','รักสงบ','🍃',/ปล่อย|หลบ|อดทน|สงบ|ไม่ยุ่ง|ถอย|ปฏิเสธ|พัก|ซ่อน/],['brave','กล้าหาญ','🔥',/ท้า|สู้|ต่อสู้|ประลอง|ดวล|เผชิญ|ออกรบ|ฝ่า/]];
function persNote(t){if(!S)return;S.pers=S.pers||{};const s=String(t).replace(/<[^>]+>/g,'');for(const [k,,,re] of PERS)if(re.test(s))S.pers[k]=(S.pers[k]||0)+1}
function persTop(){const p=S&&S.pers;if(!p)return null;let best=null,bv=0,sec=0;for(const [k] of PERS){const v=p[k]||0;if(v>bv){sec=bv;bv=v;best=k}else if(v>sec)sec=v}return bv>=6&&bv>=sec*1.3?PERS.find(x=>x[0]===best):null}
const PERS_EV={kind:[['💗 ชื่อเสียงคนใจบุญ','ผู้คนรู้กันทั่วว่าคุณใจดี ขอทานและเด็กกำพร้ามารอหน้าบ้านทุกเช้า',[['เปิดโรงทาน','$-300 k+15 f+15','ผู้คนขนานนามว่าพระโพธิสัตว์เดินดิน'],['ให้เท่าที่ไหว','$-60 k+5','ใจยังอยากช่วย แต่เงินมีจำกัด']]]],
 ruth:[['🩸 ชื่อเสียงคนเหี้ยม','ข่าวลือเรื่องความโหดเหี้ยมคุณทำให้แก๊งมาเฟียมาเสนองานสังหาร',[['รับงาน','$+1200 k-12 f+10','ชื่อคุณถูกกระซิบด้วยความหวาดกลัว'],['ไล่ไป','k+3','ยังไม่ได้ตกต่ำถึงขั้นนั้น']]]],
 cun:[['🦊 แผนการใหญ่','พ่อค้าโลภมากคนหนึ่งตกหลุมพรางคุณโดยไม่รู้ตัว',[['ต้มตุ๋นจนหมดตัว','$+1500 k-8','หัวเราะอยู่คนเดียวในห้อง'],['สอนบทเรียนแล้วคืนเงิน','k+6 i+5','เขากลับตัวเป็นคนดี']]]],
 calm:[['🍃 ความสงบ','จิตใจที่สงบทำให้ลมปราณไหลเวียนลื่นไหลกว่าคนทั่วไป',[['นั่งสมาธิใต้น้ำตก','q+4 h+20','บรรลุความสงบชั่วขณะ'],['ชวนคนอื่นมาฝึกด้วย','c+5 k+4','กลายเป็นอาจารย์สมาธิของหมู่บ้าน']]]],
 brave:[['🔥 วีรชน','ทุกครั้งที่มีภัย ผู้คนวิ่งมาหาคุณก่อน คราวนี้เสือสมิงบุกหมู่บ้าน',[['ออกไปสู้ทันที','p+20 f+25 h-15','ชาวบ้านแห่ร่างคุณไปรอบหมู่บ้าน'],['วางแผนดักจับ','i+5 f+15','จับเสือได้โดยไม่มีใครเจ็บ']]]]};
function persTick(){const p=persTop();if(!p)return false;if(S.persLab!==p[1]){S.persLab=p[1];log(`${p[2]} นิสัยคุณชัดเจนขึ้น ผู้คนต่างพูดว่าคุณเป็นคน<b>${p[1]}</b>`,'epic');return false}
 if(Math.random()<.07){runE(ch(PERS_EV[p[0]]));return true}return false}

