function stgKey(){return S.age<13?'child':S.age<20?'teen':S.age<50?'adult':'elder'}
function stgTick(){if(S.age<6||Math.random()>.2||(S.beastMode&&!S.beastMode.human))return false;const k=stgKey(),L=STG[k];const pool=L.map((e,i)=>({w:evW('stg_'+k+i,1),e,i}));const x=pickW(pool).v;newTag('stg_'+k+x.i);evMark('stg_'+k+x.i);runE(x.e);return true}

