const ACH_ALL=ACH.flatMap(c=>c[1]);
let achGot=LS.get('murim_ach',{});
function achCheck(atEnd){
 if(!S)return[];const got=[];
 ACH_ALL.forEach(a=>{if(achGot[a.id]||(a.end&&!atEnd))return;let ok=false;try{ok=a.c()}catch(e){}
  if(ok){achGot[a.id]={t:Date.now(),n:S.name};got.push(a);if(S.alive&&!atEnd){log(`🏆 สมุดตำนาน: <b class="t${a.r}">${a.n}</b>`,'epic');toast('🏆 '+a.n);setTimeout(()=>sfx('ach'),250)}}});
 if(got.length){LS.set('murim_ach',achGot);S.achLife=(S.achLife||[]).concat(got.map(a=>a.id))}
 return got;
}
function openBook(){
 const n=Object.keys(achGot).length,N=ACH_ALL.length,st=LS.get('murim_stats',{lives:0,goals:0,best:0});
 modal(`<button class="xbtn" onclick="${S?'closeM()':'closeM()'}">✕</button><h3>📖 สมุดตำนาน</h3>
 <p class="tag2">ปลดล็อก ${n}/${N} · เกิดมาแล้ว ${st.lives} ชาติ · ทำปณิธานสำเร็จ ${st.goals} ครั้ง · คะแนนสูงสุด ${fmt(st.best)}</p>
 <div class="hpbar" style="height:9px;margin-bottom:10px"><i style="width:${n/N*100}%;background:var(--pink)"></i></div>`+
 ACH.map(([cat,list])=>`<h4 style="margin:12px 0 6px">${cat} <span class="tag2">${list.filter(a=>achGot[a.id]).length}/${list.length}</span></h4>`+list.map(a=>{const g=achGot[a.id];
  return`<div class="item" style="${g?'':'opacity:.55'}"><div class="h"><b class="${g?'t'+a.r:''}">${g?'🏆 '+a.n:'🔒 ???'}</b><span class="t${a.r}" style="font-size:11px">${TIER_N[a.r]}</span></div><p>${a.d}${g?` · ${esc(g.n)}`:''}</p></div>`}).join('')).join(''),'book');
}

