function setScene(type,data){if(!S)return;sceneEvt={type,data,t:type==='death'?Infinity:Date.now()+Math.max(900,2800/Math.sqrt(speed||2))}}
let g,PS=3,fdt=1,lastTs=0,lastDraw=0;const P=(x,y,w,h,c)=>{g.fillStyle=c;const X=Math.round(x*PS),Y=Math.round(y*PS);g.fillRect(X/PS,Y/PS,Math.max(1,Math.round(w*PS))/PS,Math.max(1,Math.round(h*PS))/PS)};
const srand=k=>{const x=Math.sin(k*127.1+311.7)*43758.5453;return x-Math.floor(x)};
function avatarCols(seed,gender,demon){let s=seed;const rnd=()=>(s=(s*9301+49297)%233280)/233280;
 return{skin:['#ffd9b8','#f1c27d','#e0ac69','#c68642'][Math.floor(rnd()*4)],hair:demon?'#7a0f2a':['#2a2838','#4a3426','#6b4a2f','#1f2b4a'][Math.floor(rnd()*4)],robe:['#5b8def','#ff6b9a','#6fbf73','#e0a030','#8b4fd8'][Math.floor(rnd()*5)]}}
