function sceneType(){if(sceneEvt&&Date.now()<sceneEvt.t)return sceneEvt.type;sceneEvt=null;if(!S.alive)return'death';if(S.age<2)return'cradle';if(S.chronic&&S.hp<S.maxHp*.4)return'sick';return FOC_LOC[S.focus]||'home'}
function tickScene(){
 if(!S||!$('game').classList.contains('on'))return;
 const box=$('sceneBox');box.style.display=showScene?'block':'none';if(!showScene)return;
 {const now=performance.now();fdt=lastTs?Math.min(4,(now-lastTs)/150):1;lastTs=now;frame+=fdt}const t=sceneType();const ctx=$('scene').getContext('2d');if(!ctx)return;drawScene(ctx,t);
 const cap=xT(sceneCap(t));if(cap!==lastCap){lastCap=cap;$('scCap').textContent=cap}
}
(function loopScene(ts){if(!lastDraw||ts-lastDraw>=33){lastDraw=ts;try{tickScene()}catch(e){}}requestAnimationFrame(loopScene)})(0);
function toggleScene(){showScene=!showScene;LS.set('murim_scene',showScene);tickScene();openMenu()}

// ============ SAVE / LOAD ============
function saveGame(){if(!S||!S.alive)return;if(!S.slot)S.slot=1;const d={t:Date.now(),S:{...S,faction:S.faction?S.faction.n:null},peers:peers.map(p=>({...p,fac:p.fac?p.fac.n:null})),cfg:CFG,feed:$('feed').innerHTML,headerAge,v:VERSION};let ok=LS.set(slotKey(S.slot),d);if(!ok){d.feed='';ok=LS.set(slotKey(S.slot),d)}if(!ok&&Array.isArray(d.S.album)&&d.S.album.length>6){d.S.album=d.S.album.slice(-6);ok=LS.set(slotKey(S.slot),d);if(ok)S.album=d.S.album}if(!ok){if(!saveGame._warn){saveGame._warn=1;toast('⚠️ พื้นที่เก็บเซฟในเครื่องเต็ม เกมนี้ยังไม่ถูกบันทึก ลองลบช่องเซฟเก่าหรือภาพในอัลบั้ม');try{log('⚠️ บันทึกเกมไม่สำเร็จ: พื้นที่เก็บข้อมูลของเบราว์เซอร์เต็ม ลบช่องเซฟเก่าหรือภาพในอัลบั้มที่หน้าแรก แล้วเกมจะบันทึกต่อเอง','bad')}catch(e){}}}else saveGame._warn=0;try{cloudAuto()}catch(e){}}
function clearSave(){if(S&&S.slot)LS.del(slotKey(S.slot))}
function readSave(n=1){const ok=d=>d&&typeof d==='object'&&d.S&&typeof d.S==='object'&&d.S.name!=null&&Array.isArray(d.peers);const d=LS.get(slotKey(n),null);if(ok(d))return d;const b=LS.get(bakKey(n),null);return ok(b)&&b.S.alive!==false?b:null}
function loadGame(n=1){
 const d=readSave(n);if(!d)return;
 setWorld(!!(d.S&&d.S.xian));if(d.S&&d.S.xt)REALMS.forEach((r,i)=>{r.n=XGOD[i];r.p=XGP[i]});CFG.xian=d.S&&d.S.xian?1:0;
 const fac=n=>n?FACTIONS.find(f=>f.n===n)||null:null;
 S=Object.assign(baseState({}),d.S);S.slot=n;S.flags=S.flags||{};S.faction=fac(S.faction);peers=d.peers.map(p=>({...p,fac:fac(p.fac)}));Object.assign(CFG,d.cfg);
 choice._cur=null;choice._min=false;flushReveal();$('feed').innerHTML=d.feed;headerAge=d.headerAge;quiet=null;paused=false;auto=false;speed=1;acc=0;detailOpen=false;
 show('game');render();startTimer();$('feed').scrollTop=$('feed').scrollHeight;toast('▶ โหลดชีวิตเดิมแล้ว เล่นต่อได้เลย');
}
document.addEventListener('visibilitychange',()=>{if(document.hidden)saveGame()});

