const I18N={"d":{},"n":{}};
let LANG=LS.get('murim_lang','th');
const I18N_ORIG=new WeakMap();
const I18N_RUN=/[฀-๿](?:[฀-๿]|[ ](?=[฀-๿]))*/g;
function i18nRun(r){const D=I18N.d,N=I18N.n;if(D[r]!=null)return D[r];if(N[r]!=null)return N[r];
 const p=r.split(' ');if(p.length===1)return r;const out=[];let i=0;
 while(i<p.length){let done=false;for(let j=p.length;j>i;j--){const k=p.slice(i,j).join(' ');const v=D[k]!=null&&(j-i>1||k.length>=4)?D[k]:N[k];if(v!=null){out.push(v);i=j;done=true;break}}if(!done){out.push(p[i]);i++}}
 return out.join(' ')}
function tEN(t){if(typeof t!=='string'||!/[฀-๿]/.test(t))return t;return t.replace(I18N_RUN,i18nRun)}
function i18nNode(n){if(LANG!=='en')return;const v=n.nodeValue;if(!v||!/[฀-๿]/.test(v))return;const p=n.parentNode;if(p&&(p.nodeName==='SCRIPT'||p.nodeName==='STYLE'||p.nodeName==='TEXTAREA'))return;const nv=tEN(v);if(nv!==v){I18N_ORIG.set(n,[v,nv]);n.nodeValue=nv}}
function i18nAttrs(e){if(LANG!=='en'||!e.getAttribute)return;for(const a of ['placeholder','title']){const v=e.getAttribute(a);if(v&&/[฀-๿]/.test(v)){const nv=tEN(v);if(nv!==v){if(!e.hasAttribute('data-th-'+a))e.setAttribute('data-th-'+a,v);e.setAttribute(a,nv)}}}}
function i18nTree(root){if(LANG!=='en'||!root)return;if(root.nodeType===3){i18nNode(root);return}if(root.nodeType!==1)return;if(root.nodeName==='SCRIPT'||root.nodeName==='STYLE')return;
 const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT|NodeFilter.SHOW_ELEMENT);let n=root;do{if(n.nodeType===3)i18nNode(n);else i18nAttrs(n)}while((n=w.nextNode()))}
let i18nObs=null;
function i18nStart(){document.documentElement.lang=LANG;if(LANG==='en'){document.title=tEN(document.title);i18nTree(document.body);
 if(!i18nObs){i18nObs=new MutationObserver(ms=>{if(LANG!=='en')return;for(const m of ms){if(m.type==='characterData')i18nNode(m.target);else if(m.type==='attributes')i18nAttrs(m.target);else m.addedNodes.forEach(i18nTree)}});
  i18nObs.observe(document.body,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['placeholder','title']})}}
 const b=document.getElementById('langBtn');if(b)b.textContent=LANG==='en'?'🌐 TH':'🌐 EN'}
function setLang(l){if(l===LANG)return;LANG=l;LS.set('murim_lang',l);
 if(l==='th'){const w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT|NodeFilter.SHOW_ELEMENT);let n;while((n=w.nextNode())){if(n.nodeType===3){const o=I18N_ORIG.get(n);if(o&&n.nodeValue===o[1])n.nodeValue=o[0]}else for(const a of ['placeholder','title']){const v=n.getAttribute('data-th-'+a);if(v){n.setAttribute(a,v);n.removeAttribute('data-th-'+a)}}}document.title='1 ใน นวนิยาย — จำลองชีวิตยุทธภพและเทพเซียน'}
 i18nStart();try{if(S)render()}catch(e){}toast(l==='en'?'English (Beta) — translation is not complete yet':'ภาษา: ไทย')}
