function sqPickN(keys,n){const pool=keys.slice(),out=[];while(out.length<n&&pool.length){const tot=pool.reduce((a,k)=>a+sqW(k),0);let r=Math.random()*tot,i=0;for(;i<pool.length;i++){r-=sqW(pool[i]);if(r<=0)break}out.push(pool.splice(Math.min(i,pool.length-1),1)[0])}return out}
