function achTh(a){return a.r<=1?[1,4,10]:a.r===2?[1,3,6]:[1,2,4]}
function achCnt(a){const g=achGot[a.id];return g?(g.c||1):0}
function achStar(a){const c=achCnt(a);return achTh(a).filter(t=>c>=t).length}
function achStars(){return ACH_ALL.reduce((s,a)=>s+achStar(a),0)}
const BOOK_RK=[[0,'ผู้เริ่มจดบันทึก'],[30,'นักเล่าเรื่อง'],[70,'ผู้บันทึกพงศาวดาร'],[120,'ปราชญ์ผู้รู้แจ้ง'],[180,'ผู้จารึกตำนาน'],[250,'เทพแห่งตำนาน'],[330,'ผู้อยู่เหนือตำนาน']];
