 const lo=Math.max(500,Math.floor(S.age*.05)),hi=Math.min(100000,Math.max(lo+1,Math.floor(S.age*.5),kcap()-S.age-1));const yrs=Math.min(hi,R(lo,Math.max(lo,Math.min(hi,lo*8))));
