const RS_SUB=['ระดับต่ำ','ระดับกลาง','ระดับสูง','ใกล้เลื่อนขั้น','สมบูรณ์'],RS_PFX=['เทพ','ราชา','บรรพกาล','ราชัน','นิรันดร์'],RS_G=1.27,RS_MAX=44;
function rsG(){try{return S&&S.xian&&!S.xt?1.15:RS_G}catch(e){return RS_G}}
function rsPF(L){const pf=RS_PFX[Math.max(0,Math.min(RS_PFX.length-1,Math.floor(L/9)))]||'',n=REALMS[7].n||'';return n.startsWith(pf)?'มหา':pf}
function rsPN(L){return REALMS[7].n+' · ชั้น'+(RS_PFX[Math.max(0,Math.min(RS_PFX.length-1,Math.floor(L/9)))]||'')}
function postP(L){if(S&&S.pv2)return REALMS[7].p*(1+(rsG()-1)*(L+1));return REALMS[7].p*Math.pow(rsG(),L+1)}
function postRaw(){const top=REALMS[7].p,p=total();if(p<postP(0))return -1;if(S&&S.pv2)return Math.min(RS_MAX,Math.floor((p/top-1)/(rsG()-1)+1e-9)-1);return Math.min(RS_MAX,Math.floor(Math.log(p/top)/Math.log(rsG()))-1)}
function postLv(){if(!S||(S.beastMode&&!S.beastMode.human)||realmIdx()<7||S.pcap==null)return -1;return Math.min(postRaw(),S.pcap)}
function realmSub(){if(!S)return 0;const ri=realmIdx(),p=total();let lo,hi,blocked;
 if(ri<7){blocked=rawRealm()>ri;lo=REALMS[ri].p;hi=REALMS[ri+1].p}else{const L=postLv();blocked=postRaw()>L&&L<RS_MAX;lo=L<0?REALMS[7].p:postP(L);hi=L>=RS_MAX?lo*rsG():postP(L+1)}
 if(blocked)return 4;const f=(p-lo)/Math.max(1,hi-lo);return f<.3?0:f<.6?1:f<.88?2:3}
function realmLabel(){const ri=realmIdx(),L=postLv();const mx=L>=RS_MAX;return{base:L>=0?`${rsPN(L)} ★${L%9+1}`:REALMS[ri].n,sub:mx?'จุดสูงสุด':RS_SUB[realmSub()],si:mx?4:realmSub(),L,tier:L>=0?Math.floor(L/9):-1}}
function realmNext(){const ri=realmIdx();if(ri<7)return REALMS[ri+1].p;const L=postLv();return L>=RS_MAX?null:postP(L+1)}
