{const _otm=openTitleMenu;openTitleMenu=function(){const r=_otm.apply(this,arguments);try{const m=$('modal');const host=m&&(m.querySelector('.mgrid')||m.querySelector('#modalIn')||m);if(host){const b=document.createElement('button');b.className=host.classList.contains('mgrid')?'opt':'gbtn';if(!host.classList.contains('mgrid'))b.style.cssText='width:100%;margin-top:8px';b.onclick=openGuide;b.innerHTML='📘 คู่มือระบบ<small> ระบบสำคัญทั้งหมด</small>';host.appendChild(b)}}catch(e){}return r}}
{const st=document.createElement('style');st.textContent='.gdi .h{display:flex;justify-content:space-between;align-items:center;gap:8px}.gdgo{padding:4px 10px;min-width:0;font-size:12px;flex-shrink:0}';document.head.appendChild(st)}
try{Object.assign(I18N.d,{'คู่มือระบบสำคัญ':'Key systems guide','คู่มือระบบ':'Systems guide','เปิดดู':'Open','ระบบสำคัญทั้งหมด':'All key systems','อยากรู้จักระบบสำคัญไหม':'Want a tour of the key systems','ไว้ทีหลัง':'Later','เปิดคู่มือ':'Open guide'})}catch(e){}

{let tutQ=[];const _md2=modal;modal=function(html,k){try{if(tutI>=0&&!window._tutQ&&!['guide','guideask'].includes(k)){tutQ.push([html,k]);if(tutQ.length>4)tutQ.shift();return}}catch(e){}return _md2.apply(this,arguments)};
 const _td2=tutDraw;tutDraw=function(){const was=tutI>=0;const r=_td2.apply(this,arguments);try{if(was&&tutI<0&&tutQ.length){const q=tutQ.filter(x=>x[1]!=='choice');tutQ=[];const last=q[q.length-1];if(last)setTimeout(()=>{if(!modalOpen)_md2(last[0],last[1])},200)}}catch(e){}return r}}

