let acPrev=null;
function acSnap(){return{int:+S.int||0,cha:+S.cha||0,fame:+S.fame||0,money:+S.money||0,qi:+S.qi||0,pow:(()=>{try{return +total()||0}catch(e){return +S.power||0}})(),dis:S.ownSect?+S.ownSect.dis||0:0,kids:+S.kids||0,har:(S.harem||[]).length,age:+S.age||0}}
function acFlag(why){if(!S||S._tp)return;S._tp=why;S._tpv=2;try{console.warn('integrity')}catch(e){}}
let acObj=null;
function acCheck(){try{if(!S||!S.alive||S.custom)return;if(S._tp&&/^(cap-|save-jump)/.test(String(S._tp)))delete S._tp;if(S!==acObj){const kp=acPrev&&acObj&&acObj.name===S.name&&Math.abs((+S.age||0)-acPrev.age)<=2;acObj=S;if(!kp)acPrev=null}
 for(const k of ['int','cha','fame','money','qi','power','karma']){const v=S[k];if(typeof v==='number'){if(v!==v)S[k]=0;else if(v>1e30)S[k]=1e30;else if(v<-1e30)S[k]=-1e30}}
 try{if(S.ownSect&&+S.ownSect.dis>1e30)S.ownSect.dis=1e30}catch(e){}
 const c=acSnap();if(!isFinite(c.pow)||c.pow>1e30)c.pow=1e30;
 if(c.kids>1e9)return acFlag('cap-x');
 if(acPrev&&c.age-acPrev.age<=1){const d=(k)=>c[k]-acPrev[k];
  if(d('int')>800||d('cha')>800)return acSus('jump-stat');
  if(d('fame')>Math.max(30000,acPrev.fame*4,c.pow/5))return acSus('jump-fame');
  if(d('money')>Math.max(8e6*acW(),acPrev.money*20))return acSus('jump-money');
  if(d('pow')>Math.max(200000,acPrev.pow*6))return acSus('jump-pow');
  if(d('dis')>Math.max(5000,acPrev.dis*5))return acSus('jump-dis')}
 acPrev=c}catch(e){}}
setInterval(acCheck,700);
