let FU_SEL=[];
function fuseCan(a){return a&&(a.lv||0)>=1}
function fuseP(L){const m=(S.talent&&S.talent.m)||1,avg=L.reduce((s,a)=>s+(a.lv||0),0)/L.length,mr=Math.max(...L.map(a=>a.r||0));return Math.max(.05,Math.min(.85,.25+(S.int||0)/600+(m-1)*.1+avg*.08-(L.length-2)*.08-mr*.04+(artFx('mind')*.02)))}
function openFuse(){if(!S)return;const L=S.arts.map((a,i)=>({a,i})).filter(x=>x.a);const cd=(S.fuseY!=null&&S.age-S.fuseY<3);FU_SEL=FU_SEL.filter(i=>S.arts[i]&&fuseCan(S.arts[i]));
 const sel=FU_SEL.map(i=>S.arts[i]),p=sel.length>=2?fuseP(sel):0;
 modal(`<button class="xbtn" onclick="openArts()">✕</button><h3>🔮 รวมวิชา</h3><p class="tag2">เลือกวิชาที่ฝึกถึง<b>ระดับกลาง</b>ขึ้นไป 2–3 วิชา เพื่อหลอมรวมเป็นวิชาใหม่ในแบบคุณเอง · วิชาเดิมจะถูกหลอมหายไป พลังรวมไม่ลดลง และมีโอกาสได้ระดับสูงขึ้น · ล้มเหลวอาจโดนธาตุไฟเข้าแทรก · ทำได้ทุก 3 ปี</p>
 <div style="margin:6px 0 8px"><span class="tag2">✍️ ตั้งชื่อวิชาใหม่เอง (ไม่บังคับ · เว้นว่าง = ตั้งชื่อให้อัตโนมัติ)</span><input class="crin" id="fuName" maxlength="24" placeholder="เช่น กระบี่พิรุณพันสาย" value="${esc(window.FU_NAME||'')}" oninput="window.FU_NAME=this.value"></div>
 ${L.map(({a,i})=>{const ok=fuseCan(a),on=FU_SEL.includes(i);return`<button class="item fuit ${on?'on':''}" ${ok?'':'disabled'} onclick="fuseTog(${i})" style="width:100%;text-align:left;${ok?'':'opacity:.45'}"><div class="h"><b class="t${a.r}">${on?'✅ ':''}《${a.n}》</b><span class="tag2">${AMN[a.lv||0]}</span></div>${a.fx?`<p class="tag2">${(Array.isArray(a.fx)?a.fx:[a.fx]).map(k=>UA[k]?UA[k].ic+' '+UA[k].d:'').join(' · ')}</p>`:''}</button>`}).join('')}
 <button class="pbtn" style="width:100%;margin-top:8px" ${sel.length>=2&&!cd?'':'disabled'} onclick="fuseGo()">${cd?`รอให้ลมปราณสงบอีก ${3-(S.age-S.fuseY)} ปี`:sel.length>=2?`🔮 หลอมรวม ${sel.length} วิชา (โอกาสสำเร็จ ${Math.round(p*100)}%)`:'เลือกอย่างน้อย 2 วิชา'}</button>`,'fuse')}
function fuseTog(i){const k=FU_SEL.indexOf(i);if(k>=0)FU_SEL.splice(k,1);else if(FU_SEL.length<3)FU_SEL.push(i);openFuse()}
function fuseCore(n){let s=String(n||'').replace(/^วิชายุทธ์ชาติก่อน — /,'').replace(/^วิถี[^:]*: /,'');for(const p of ART_S.slice().sort((a,b)=>b.length-a.length))if(s.startsWith(p)){s=s.slice(p.length);break}return s.split('ผสาน')[0].split('·')[0]||s}
function fuseGo(){const idx=FU_SEL.slice().sort((a,b)=>b-a),L=idx.map(i=>S.arts[i]).filter(Boolean);if(L.length<2||(S.fuseY!=null&&S.age-S.fuseY<3))return;const p=fuseP(L);S.fuseY=S.age;FU_SEL=[];closeM();
 if(Math.random()<p){const tot=L.reduce((s,a)=>s+a.b*artM(a),0),mr=Math.max(...L.map(a=>a.r||0)),r=Math.min(4,mr+(Math.random()<.3?1:0)),fx=[...new Set(L.flatMap(a=>a.fx?(Array.isArray(a.fx)?a.fx:[a.fx]):[]))];
  const given=(S.name||'').split(' ').pop(),typ=(ART_S.find(t=>String(L[0].n).startsWith(t))||ch(ART_S));const cu=String(window.FU_NAME||'').replace(/[<>&"'`\\]/g,'').replace(/[《》\[\]]/g,'').replace(/\s+/g,' ').trim().slice(0,24);window.FU_NAME='';const nm=cu||`วิถี${given}: ${typ}${fuseCore(L[0].n)}ผสาน${fuseCore(L[1].n)}${L[2]?'·'+fuseCore(L[2].n):''}`;
  const kp0=Math.max(0,...L.map(x=>x.kp|0)),a={n:nm,tier:ART_TIER[r].n+' · วิชาของตัวเอง',cn:cu?1:0,b:Math.round(tot*1.05/(1+.5*kp0)+ART_TIER[r].b*.2),r,p:.0001,lv:0,own:1};try{if(kp0>0)a.kp=kp0;if(L.some(x=>x.kal))a.kal=1;const sk=L.find(x=>x.sk&&typeof ASK!=='undefined'&&ASK[x.sk]);if(sk)a.sk=sk.sk;if(a.kal&&kp0>=3)a.tier='♾️ วิชาแห่งกัลป์ · วิชาของตัวเอง'}catch(e){}try{a.src=L.flatMap(x=>x.src&&x.src.length?x.src:[String(x.n)]).slice(0,4)}catch(e){}if(fx.length)a.fx=fx.length===1?fx[0]:fx;
  idx.forEach(i=>S.arts.splice(i,1));Array.prototype.push.call(S.arts,a);S.flags.fused=(S.flags.fused||0)+1;setScene('aura');
  log(`🔮 หลอมรวม ${L.map(x=>'《'+x.n+'》').join(' + ')} สำเร็จ! ถือกำเนิดเป็นวิชาใหม่ที่มีเพียงคุณคนเดียวในใต้หล้า ${artHtml(a)}${r>mr?' ระดับสูงขึ้น!':''}`,'myth',true)}
 else{log(`💢 พยายามหลอมรวม ${L.map(x=>'《'+x.n+'》').join(' + ')} แต่ลมปราณของวิชาต่างสายปะทะกัน ล้มเหลว <span class="tag2">(โอกาส ${Math.round(p*100)}%)</span>`,'bad');if(Math.random()<.45)qiDev(false)}
 render()}
{const _oa=openArts;openArts=function(){const r=_oa.apply(this,arguments);try{const m=$('modal'),host=m&&(m.querySelector('#modalIn')||m);if(host&&S&&!(S.beastMode&&!S.beastMode.human)){const ua=S.arts.filter(a=>a&&a.fx);const box=document.createElement('div');box.innerHTML=`${ua.length?`<p class="tag2" style="margin-top:6px">วิชาพิเศษ: ${[...new Set(ua.flatMap(a=>Array.isArray(a.fx)?a.fx:[a.fx]))].map(k=>UA[k]?UA[k].ic+' '+UA[k].d:'').join(' · ')}</p>`:''}${S.arts.filter(Boolean).length>=2?`<button class="pbtn" style="width:100%;margin-top:8px" onclick="openFuse()">🔮 รวมวิชา สร้างวิชาของตัวเอง</button>`:''}`;host.appendChild(box)}}catch(e){}return r}}
