let EN_SKIP=null;
function enSkip(n){if(!EN_SKIP){EN_SKIP=new Set([...BOSS_M,...BOSS_X].map(b=>b.n).concat(SH_N,SH_M,REG_BETRAY))}return EN_SKIP.has(n)||/\s/.test(n)||(peers||[]).some(p=>p.name===n)}
function enKind(n){return S&&S.xian&&Math.random()<.5?'xian':/โจร|อันธพาล|นักเลง|คนเมา|ลูกสมุน/.test(n)?'bandit':/มาร|โลหิต|ลัทธิ/.test(n)?'demon':/นักฆ่า|มือสังหาร/.test(n)?'assassin':/ทหาร|แม่ทัพ|นายพล|องครักษ์/.test(n)?'soldier':'warrior'}
function enName(role){if(!S||typeof role!=='string'||enSkip(role)||EN_NOT.test(role))return role;const grp=EN_GROUP.test(role);if(!grp&&!EN_HUMAN.test(role))return role;
 S._enN=S._enN||{};const old=S._enN[role];if(old&&Math.random()<.4)return old;
 const fem=/ลูกชาย|พ่อ/.test(role)?false:/ลูกสาว|แม่|นาง/.test(role)?true:Math.random()<(/ศิษย์|สาวก|นักฆ่า|ทายาท/.test(role)?.3:grp?.05:.12),nm=`${ch(EN_SUR)} ${ch(fem?EN_GF:EN_GM)}`,nk=Math.random()<.55?`「${ch(EN_NK[enKind(role)])}」 `:'';
 const full=grp?`${role} นำโดย ${nk}${nm}`:`${role} ${nk}${nm}`;
 S._enN[role]=full;const ks=Object.keys(S._enN);if(ks.length>40)delete S._enN[ks[0]];return full}
