 if(S.age>2&&Math.random()<.55){
  const C=M.evC=M.evC||{};const okNew=BLX.filter(e=>(!e.sp||e.sp===m.sp)&&(!e.mx||(C[e.id]||0)<e.mx)&&(L[e.id]==null||S.age-L[e.id]>=(e.gap||6))&&(()=>{try{return e.c()}catch(x){return false}})());
  const okOld=BL_EV.filter(e=>(C[e[0]]||0)<(/คู่ครอง|เด็กมนุษย์/.test(e[0])?1:3)&&(L[e[0]]==null||S.age-L[e[0]]>=(/คู่ครอง|เด็กมนุษย์/.test(e[0])?18:9)));
  const pool=okNew.map(e=>({w:blEvW(e),v:['n',e]})).concat(okOld.map(e=>({w:.5,v:['o',e]})));
  if(pool.length){const [k,e]=pickW(pool).v.v;if(k==='n'){L[e.id]=S.age;C[e.id]=(C[e.id]||0)+1;e.f()}else{L[e[0]]=S.age;C[e[0]]=(C[e[0]]||0)+1;runE(e)}return}}
