 if(S){o.nm=String(S.name||'').slice(0,20);o.ag=S.age;o.al=S.alive?1:0;o.au=auto?1:0;o.pa=paused?1:0;o.sp=speed;o.w=S.beastMode&&!S.beastMode.human?'b':S.xt?'g':S.xian?'x':'m';o.yr=window._lastYr?Math.round((n-window._lastYr)/1000):-1;try{o.ri=REALMS[realmIdx()].n}catch(e){}}
