function gevTick(st){if(!S||!S.alive||!S.xian||!S.xt||S.beastMode)return;const g=gdInit();g.n=(g.n||0)+1;try{gdTick(st)}catch(e){console.error(e)}
 if(choice._cur||modalOpen||S.hp<=0)return;if(gdAsk())return;if(g.n-(g.at||-9)<2||Math.random()>.5)return;
 const e=gevPick();if(e)try{e.f()}catch(x){console.error(x)}}
function gevPick(){const g=gdInit(),L=GEV.filter(e=>(!e.c||e.c())&&!g.ev.includes(e.id));if(!L.length)return null;const e=pickW(L).v;g.at=g.n;g.ev.push(e.id);if(g.ev.length>6)g.ev.shift();return e}
const G_MORTAL=/เควสฉุกเฉิน|เควส: (ชิมอาหาร|ตบหน้าคุณชาย|คุ้มกันคาราวาน|ยอมแพ้ให้เด็กน้อย|ช่วยศิษย์ที่ถูกรังแก|เข้าพบผู้งามล่มเมือง|ปราบสัตว์อสูร|สมาธิใต้น้ำตก|งานประมูลใต้ดิน|ปริศนาในถ้ำโบราณ)|สำนักเปิดรับศิษย์|งานชุมนุมยุทธ์|กองคาราวาน|จดหมายจากบ้าน|ลัทธิมารเกณฑ์คน|ทุพภิกขภัย|ขอเข้าตำหนักใน/;
{const _ch122=choice;choice=function(title,text,opts){try{if(!choice._g&&S&&S.alive&&S.xian&&S.xt&&!choice._cur&&G_MORTAL.test(String(title))&&Math.random()<.65){const e=gevPick();if(e){choice._g=1;try{e.f()}finally{choice._g=0}if(choice._cur)return}}}catch(x){console.error(x);choice._g=0}return _ch122.apply(this,arguments)};Object.assign(choice,_ch122)}
function gdAsk(){const g=gdInit();if(g.lv>=9||choice._cur||modalOpen)return false;const c=GD_COST[g.lv+1];if(g.fp<c||g.ask===g.lv+1)return false;g.ask=g.lv+1;
 choice('🏯 พลังศรัทธาเพียงพอแล้ว',`ผู้ศรัทธา ${fmt(g.bel)} คนส่งพลังศรัทธาขึ้นมาถึง ${fmt(Math.floor(g.fp))} — พอจะขยายแดนเทพเป็น<b>${GD_LV[g.lv+1]}</b>แล้ว`,[{t:'🏗️ ขยายแดนเทพ',s:`ใช้ศรัทธา ${fmt(c)} · ฝ่าทัณฑ์ง่ายขึ้น พลังงอกเงยเอง`,f(){gdUp(1)}},{t:'⏳ เก็บศรัทธาไว้ก่อน',s:'เปิดได้ทีหลังที่ ☰ เมนู → 🏯 แดนเทพ',skip:true,f(){}}]);return true}
