{const _bt=bagTick;bagTick=function(){const r=_bt.apply(this,arguments);try{if(S&&S.alive&&bagHas('lpill')&&S.age>lifeMax()-(S.xt?60:S.xian?15:4)&&bagUse('lpill')){const m=BAGX.lpill.use();log(`🎒 💮 กลืนยาอายุวัฒนะ — ${m}`,'epic')}}catch(e){console.error(e)}return r}}
function crOutTxt(r){const o=r.out;try{if(o.bag)return`${rarName(o.bag)} ×${o.q} (ขั้นบน ×${o.q*2} · สุดยอด ×${o.q*3}) — ${bagDesc(o.bag)}`;
 if(o.eq){const e=EQI[o.eq];return e?`${e.ic} ${e.n} — ${e.d}`:o.eq}if(o.fx==='int')return`ปัญญา +${o.v} (ขึ้นกับขั้นที่ได้)`;if(o.fx==='qi')return`ลมปราณ +${o.v} ปี (ขึ้นกับขั้นที่ได้)`;if(o.fx==='life')return`อายุขัย +${o.v} ปี`;
 if(o.fx==='weapon')return'อาวุธที่ใช้อยู่ขึ้นหนึ่งขั้น (ถ้าสุดแล้วได้พลังยุทธ์แทน)';
 if(o.buf){const B={train:`ฝึกยุทธ์ ×${o.v}`,qi:`ฝึกลมปราณ ×${o.v}`,red:`เจ็บน้อยลง ${Math.round(o.v*100)}%`,fight:`ต่อสู้ ×${o.v}`}[o.buf]||r.n;return`${B} นาน ${o.y} ปี`}}catch(e){}return r.n}

