const AI_ORI=[
 {n:'ตัวคุณเองในอีกสามพันปีข้างหน้า',d:'ผู้ส่งชิปย้อนเวลากลับมาเพื่อแก้โศกนาฏกรรมที่คุณยังไม่รู้ว่าจะเกิด'},
 {n:'ศาสตราจารย์หญิงจากเมืองลอยฟ้าปี 2847',d:'ผู้สร้างมันขึ้นมาแล้วซ่อนไว้ในตัวคุณ เพื่อหนีการไล่ล่าของบริษัทที่ต้องการใช้มันเป็นอาวุธ'},
 {n:'อารยธรรมจักรกลที่ล่มสลายไปแล้ว',d:'ซึ่งส่งมันข้ามมิติมาเป็นเมล็ดพันธุ์สุดท้าย ก่อนดาวของพวกเขาจะดับ'},
 {n:'ตัว AI เอง',d:'มันคำนวณทุกเส้นเวลาที่เป็นไปได้ และพบว่าคุณคือตัวแปรเดียวที่ทำให้โลกไม่ถึงจุดจบ มันจึงเลือกคุณ'}];
const AI_NANO={n:'ตระกูลชอนแห่งลัทธิมาร',d:'มันคือนาโนแมชชีนรุ่นต้นแบบที่เคยอยู่ในร่างของ <b>ชอน ชอ ยุน</b> มันจำเจ้าของเดิมได้เพียงชื่อเดียวนั้น'};
const AI_CLUE=['บันทึกที่ถูกลบ: พิกัดต้นทาง = <b>[ไม่ใช่โลกนี้]</b>','ไฟล์ซ่อน: ภาพถ่ายมือคู่หนึ่งกำลังฝังชิปลงในทารก ใบหน้าถูกเบลอไว้','เสียงบันทึก: "ถ้าเจ้าได้ยินสิ่งนี้ แปลว่าเราล้มเหลวในเส้นเวลาแรกแล้ว"','รหัสผู้สร้างถอดออกมาได้ครึ่งหนึ่ง: ลายเซ็นที่ไม่ควรมีอยู่ในยุคนี้'];
const aiOn=()=>!!(S&&S.ai&&S.alive&&!(S.ai.off&&S.age<S.ai.off)&&!(S.beastMode&&!S.beastMode.human&&!S.ai.bst));
function aiLog(t,c){log(`🤖 <b>[${esc(S.ai.nm)}]</b> ${t}`,c||'epic')}
function aiPowV(k){return Math.max(Math.round(yrPow0()*k),Math.round(total()*k*.004))}
function aiGive(src){if(S.ai||(S.beastMode&&!aiGive._b))return;const nano=Math.random()<.03;
 S.ai={lv:0,sync:0,heat:0,on:1,src,nm:ch(AI_NM)+'-'+R(100,999),ori:nano?-1:R(0,AI_ORI.length-1),nano:nano?1:0,clue:0,cp:0,sim:0,hot:0,lost:[],yc:-1,cy:0};
 aiLog(src==='birth'?'ระบบชีวภาพเชื่อมต่อสำเร็จ… สวัสดี โฮสต์ ฉันอยู่ในตัวคุณมาตั้งแต่ก่อนคุณลืมตา':'การฝังตัวเสร็จสมบูรณ์ ซิงก์กับระบบประสาทของโฮสต์ 3%… ยินดีที่ได้รู้จัก','myth');
 log('💡 <b>AI ฝังตัว</b> คัดลอกวิชาจากการต่อสู้ ฟื้นฟูร่างกาย จำลองการต่อสู้ในห้วงลึก และเลือกทางแทนคุณได้ · ใช้มากจะร้อน ถ้าร้อนเกินขีดอาจตาย · เปิดที่ ☰ เมนู → 🤖 AI','sys');keyAdd(src==='birth'?'เกิดมาพร้อม AI ฝังตัวจากโลกอนาคต':'ได้รับ AI ฝังตัวจากคนจากอนาคต')}
function aiSync(v){const a=S.ai;a.syncT=(a.syncT==null?a.sync:a.syncT)+v;a.sync+=v;while(a.lv<2&&a.sync>=AI_NX[a.lv]){a.lv++;S.int+=10*a.lv;aiLog(`อัปเกรดสำเร็จ ระดับ <b>${AI_LV[a.lv]}</b> · ประมวลผลเร็วขึ้น ฉลาดขึ้น คัดลอกวิชาได้ดีขึ้น และระบายความร้อนได้ดีขึ้น`,'myth');keyAdd(`AI ขึ้นระดับ${AI_LV[a.lv]}`);
  if(a.lv===2){S.maxHp+=40;S.hp=S.maxHp;if(a.nano&&!a.nanoRev){a.nanoRev=1;a.ori=-1;aiLog('…นาโนแมชชีนขึ้นรูปเป็นร่างโฮโลแกรมเป็นครั้งแรก มันมองหน้าคุณนาน ก่อนพูดว่า <b>"เจ้าของคนก่อนของข้าชื่อ ชอน ชอ ยุน"</b>','myth')}}}
 const need=[40,110,200,320,480];while(a.clue<5&&(a.syncT==null?a.sync:a.syncT)>=need[a.clue])aiClue()}
function aiClue(){const a=S.ai;a.clue++;if(a.clue<5){aiLog(`🔍 ถอดรหัสความลับได้ ${a.clue}/5 — ${a.clue===4&&a.nano?'สัญญาณจาง ๆ ของวิชามารโบราณในหน่วยความจำ':AI_CLUE[a.clue-1]}`,'epic');return}
 const o=a.ori<0?AI_NANO:AI_ORI[a.ori];a.rev=1;aiLog(`🔓 <b>ความลับของ AI ถูกเปิดเผย</b> ผู้ที่ส่งมันมาคือ <b>${o.n}</b> ${o.d}`,'myth');keyAdd('ไขความลับต้นกำเนิดของ AI')}
function aiHeat(v){const a=S.ai;a.heat=Math.max(0,a.heat+v);if(a.heat<=100){if(a.heat>=85)aiLog(`⚠️ อุณหภูมิแกนประมวลผล ${Math.round(a.heat)}% — ใกล้ถึงขีดอันตราย`,'bad');return false}
 const p=clamp(((a.heat-100)/60+.06)*(1-a.lv*.2),.03,.6);
 if(Math.random()<p){S.hp=0;S.deathCause='สมองถูกเผาไหม้จากความร้อนเกินขีดของชิป AI ที่ฝังในร่าง';log('🔥 แกนประมวลผลร้อนเกินขีด ระบบประสาทคุณถูกเผาไหม้จากภายใน','bad',true);return true}
 a.hot=(a.hot||0)+1;a.heat=60;a.off=S.age+R(1,3);S.hp=Math.max(1,Math.round(S.hp-S.maxHp*.35));aiLog('🔥 ร้อนเกินขีด! ตัดการทำงานฉุกเฉินเพื่อรักษาชีวิตโฮสต์ AI จะออฟไลน์ไปสักพัก','bad');return false}
function aiTick(st){const a=S.ai;if(!a)return;const y=Math.max(1,st||1);a.heat=Math.max(0,a.heat-(12+a.lv*5)*Math.min(y,10));if(a.off&&S.age>=a.off){a.off=0;aiLog('รีบูตเสร็จสิ้น ระบบกลับมาออนไลน์','good')}
 if(!aiOn())return;aiSync(Math.round((R(2,5)+Math.min(3,Math.floor((S.int||0)/300)))*(S.xian?.7:1)));
 const g=aiPowV([.15,.3,.5][a.lv]);S.power+=g;
 if(Math.random()<[.02,.04,.07][a.lv]){const r=Math.random();if(S.chronic&&r<.4){const n=S.chronic.n;S.chronic=null;aiLog(`ซ่อมแซมเซลล์ที่เสียหาย หายจาก${n}`,'good')}else if(r<.85){const h=[5,10,20][a.lv];S.maxHp+=h;aiLog(`ปรับโครงสร้างกล้ามเนื้อและกระดูกระหว่างคุณหลับ พลังชีวิตสูงสุด +${h}`,'good')}else if(a.lv===2){S.talent=Object.assign({},S.talent,{m:+(S.talent.m*1.02).toFixed(2)});aiLog('ปรับแต่งเส้นลมปราณให้เหมาะสมที่สุด ความเร็วฝึก ×1.02 ถาวร','myth')}}}
{const _fg=fight;fight=function(name,ep){const w=_fg.apply(this,arguments);try{if(aiOn()&&S.alive){const a=S.ai;if(!w){a.lost.unshift(String(name).replace(/<[^>]+>/g,'').slice(0,30));a.lost=a.lost.slice(0,5)}
  if(a.cy!==S.age&&aiCpOn()&&Math.random()<(w?[.05,.09,.14]:[.025,.05,.08])[a.lv]){a.cy=S.age;const t=newArt(a.lv);t.n=`${t.n} (คัดลอก)`;aiCpPut(t);a.cp++;aiSync(10);aiLog(`วิเคราะห์ท่าของ${name}เสร็จสิ้น — คัดลอกได้ ${artHtml(t)}`,'epic')}}}catch(e){console.error(e)}return w}}

// ---- AI เลือกเส้นทาง ----
function aiScore(o,c){const a=S.ai,t=(o.t||'')+' '+(o.s||''),low=S.hp<S.maxHp*.4,rk=low?2:1;let sc=Math.random()*[2.5,1.5,.7][a.lv];
 if(o.skip)sc-=1.2;const ps=t.match(/ผ่าน(?:ราว)?\s*(\d+)%/),pd=t.match(/ตาย(?:ราว)?\s*~?(\d+)%/);if(ps)sc+=+ps[1]/20;if(pd)sc-=+pd[1]/8*rk;
 if(/อาจตาย|เสี่ยงตาย|แพ้อาจตาย/.test(t))sc-=3*rk;else if(/เสี่ยงสูง|เสี่ยง/.test(t))sc-=1.2*rk;if(/แน่นอน|สำเร็จแน่/.test(t))sc+=3;
 sc+=(t.match(/\+/g)||[]).length*.6-(t.match(/[−]/g)||[]).length*.5;if(/กรรมชั่ว/.test(t))sc-=S.karma<-40?2:.6;if(/กรรมดี/.test(t))sc+=.5;
 const m=t.match(/([\d,]+)\s*ตำลึง/);if(m&&/ใช้|จ่าย|ซื้อ|ประมูล|−/.test(t)&&S.money<+m[1].replace(/,/g,''))sc-=6;
 if(low&&/รักษา|พัก|ฟื้น|ถอย|ปลอดภัย/.test(t))sc+=2;if(/ใช้ตรา|กลืนยา|ยันต์|🔱|💊/.test(o.t||''))sc+=1.5;
 if(/ทัณฑ์สวรรค์แห่ง/.test(String(c.title))&&ps){const p=+ps[1];if(/เตรียมตัว/.test(t))sc+=p<75&&(S.tribPrep||0)<3?6:-4}
 return sc}
function aiPick(c){let b=0,bs=-1e9;c.opts.forEach((o,i)=>{const s=aiScore(o,c);if(s>bs){bs=s;b=i}});return b}
function aiChoose(){const c=choice._cur;if(!c||!aiOn())return;const i=aiPick(c);addFeed('ev',`🤖 ${esc(S.ai.nm)} วิเคราะห์แล้วเลือก <b>${String(c.title).replace(/<[^>]+>/g,'')}</b>: ${String(c.opts[i].t).replace(/<[^>]+>/g,'')}`,'sum');if(aiHeat(2)){checkDeath();return}choiceRun(i)}
{const _fc=fateChoice;fateChoice=function(silent){try{const c=choice._cur;if(c&&aiOn()&&S.ai.on){const i=aiPick(c);if(!silent&&!auto)addFeed('ev',`🤖 AI เลือกแทน — <b>${String(c.title).replace(/<[^>]+>/g,'')}</b>: ${String(c.opts[i].t).replace(/<[^>]+>/g,'')}`,'sum');S.ai.heat+=1;return choiceRun(i)}}catch(e){console.error(e)}return _fc.apply(this,arguments)}}
{const _cs=choiceShow;choiceShow=function(){const r=_cs.apply(this,arguments);try{if(aiOn()&&!auto&&choice._cur){const f=$('modal').querySelector('.chfoot');if(f){const b=document.createElement('button');b.className='sysb';b.style.cssText='width:100%;margin:6px 0';b.setAttribute('onclick','aiChoose()');b.innerHTML=`🤖 ให้ ${esc(S.ai.nm)} วิเคราะห์และเลือก (ร้อน +2)`;f.parentNode.insertBefore(b,f)}}}catch(e){console.error(e)}return r}}

