function qgNext(){if(QGM.i>=QGM.N)return qgFinish();QGM.ring={r:44,t0:performance.now(),dur:1700/QGM.d*(.9+Math.random()*.25)}}
const QG_TG=16;
function qgTap(){if(QGM.done||!QGM.ring||$('modal').dataset.k!=='qigame')return;const r=QGM.ring.r,w=1/Math.sqrt(QGM.d),dv=Math.abs(r-QG_TG);const g=dv<=2.2*w?2:dv<=5.5*w?1:0;qgMark(g)}
function qgMark(g){QGM.res.push(g);QGM.ring=null;QGM.i++;const tx=$('qgTx');if(tx)tx.innerHTML=g===2?'<b style="color:#f0c860">✨ เป๊ะ! สายปราณรวมเข้าศูนย์กลาง</b>':g===1?'<b style="color:#8fd18f">ดี ปราณไหลเข้าแต่ยังไม่นิ่ง</b>':'<b style="color:#ff6b6b">💢 พลาด สายปราณแตกกระจาย</b>';
 const sc=$('qgSc');if(sc)sc.textContent=QGM.res.map(x=>x===2?'🌟':x===1?'🔹':'💥').join('')+'▫️'.repeat(QGM.N-QGM.res.length);
 for(let k=0;k<(g?10:16);k++){const a=Math.random()*6.283;QGM.parts.push({x:48+Math.cos(a)*QG_TG,y:48+Math.sin(a)*QG_TG,vx:g?-Math.cos(a)*.6:Math.cos(a)*(1+Math.random()*1.5),vy:g?-Math.sin(a)*.6:Math.sin(a)*(1+Math.random()*1.5),l:g?20:30,c:g?QGM.col[0]:'#ff6b6b'})}
 try{sfx(g?'good':'bad')}catch(e){}setTimeout(qgNext,380)}
function qgFinish(){const s=QGM.res.reduce((a,x)=>a+(x===2?1:x===1?.6:0),0),perf=s/QGM.N,o=QGM.o,pF=clamp(o.p*(.45+1.1*perf),.03,.97);QGM.done=true;QGM.perf=perf;try{if(window._aqEv&&!auto){window._aqEv('mg');if(perf>=.6)window._aqEv('mgg');if(perf>=.9)window._aqEv('mgp')}}catch(e){}
 const tx=$('qgTx');if(o.noRoll){if(tx)tx.innerHTML=`รวมปราณได้ <b>${Math.round(perf*100)}%</b>`;setTimeout(()=>{if($('modal').dataset.k==='qigame')closeM();QGM.cb(null,perf,pF)},900);return}
 const ok=Math.random()<pF;QGM.end={ok,t:performance.now()};if(tx)tx.innerHTML=`รวมปราณได้ ${Math.round(perf*100)}% · โอกาส ${Math.round(o.p*100)}% → <b>${Math.round(pF*100)}%</b><br>${ok?'<b style="color:#f0c860">🌟 ปราณทั้งหมดหลอมเป็นหนึ่ง ทะลวงสำเร็จ!</b>':'<b style="color:#ff6b6b">💢 แกนปราณสั่นคลอน สายปราณแตกกระจายไปทั่ว…</b>'}`;
 if(!ok)for(let k=0;k<60;k++){const a=Math.random()*6.283,v=.8+Math.random()*2;QGM.parts.push({x:48,y:48,vx:Math.cos(a)*v,vy:Math.sin(a)*v,l:40,c:ch(['#ff6b6b',QGM.col[0],'#888'])})}
 const b=$('qgB');if(b){b.textContent='ต่อไป';b.onclick=()=>qgClose(ok,perf,pF);const sk=b.nextElementSibling;if(sk)sk.style.display='none'}setTimeout(()=>{if(!QGM.closed&&$('modal').dataset.k==='qigame')qgClose(ok,perf,pF)},2600)}
function qgClose(ok,perf,pF){if(QGM.closed)return;QGM.closed=1;if($('modal').dataset.k==='qigame')closeM();QGM.cb(ok,perf,pF)}
function qgSkip(){if(QGM.done)return;QGM.done=true;QGM.closed=1;closeM();const o=QGM.o;QGM.cb(o.noRoll?null:Math.random()<o.p,.5,o.p,1)}
function qgDraw(ts){const cv=$('qgC');if(!cv||$('modal').dataset.k!=='qigame'){if(!QGM.closed&&!QGM.done){QGM.done=true;QGM.closed=1;const o=QGM.o;QGM.cb(o.noRoll?null:Math.random()<o.p,.5,o.p,1)}return}
 const c=cv.getContext('2d'),t=performance.now(),P=(x,y,col,s=1)=>{c.fillStyle=col;c.fillRect(Math.round(x),Math.round(y),s,s)};c.fillStyle='#0d0a14';c.fillRect(0,0,96,96);
 for(let k=0;k<40;k++){const a=k*2.4+t*.0002,r=20+((k*37)%28);P(48+Math.cos(a)*r,48+Math.sin(a)*r,k%3?'#2a2236':'#3a3050')}
 const good=QGM.res.filter(x=>x).length,cr=4+good*1.3+(QGM.end&&QGM.end.ok?(t-QGM.end.t)/40:0);
 // สายปราณไหลเข้า
 if(!QGM.done)for(let k=0;k<3;k++){const a=Math.random()*6.283;QGM.parts.push({x:48+Math.cos(a)*46,y:48+Math.sin(a)*46,vx:-Math.cos(a+.5)*.9,vy:-Math.sin(a+.5)*.9,l:45,c:QGM.col[k%2?0:2],sw:1})}
 QGM.parts=QGM.parts.filter(p=>{p.x+=p.vx;p.y+=p.vy;if(p.sw){const dx=48-p.x,dy=48-p.y,dd=Math.hypot(dx,dy)||1;p.vx+=dx/dd*.05;p.vy+=dy/dd*.05;if(dd<cr)p.l=0}p.l--;if(p.l>0)P(p.x,p.y,p.c);return p.l>0});
 // วงเป้าหมาย
 for(let a=0;a<6.283;a+=.13)P(48+Math.cos(a)*QG_TG,48+Math.sin(a)*QG_TG,'#f0c860');
 // แกนกลาง
 for(let y=-cr;y<=cr;y++)for(let x=-cr;x<=cr;x++)if(x*x+y*y<=cr*cr)P(48+x,48+y,(x*x+y*y<cr*cr*.35)?QGM.col[1]:QGM.col[0]);
 // สายที่รวมแล้วโคจรรอบแกน
 for(let k=0;k<good;k++){const a=t*.004+k*6.283/Math.max(1,good);P(48+Math.cos(a)*(cr+4),48+Math.sin(a)*(cr+4),QGM.col[1],2)}
 // วงที่หดเข้า
 if(QGM.ring&&!QGM.done){const R0=QGM.ring,f=(t-R0.t0)/R0.dur;R0.r=44-f*40;if(R0.r<QG_TG-6*(1/Math.sqrt(QGM.d))){qgMark(0)}else{const near=Math.abs(R0.r-QG_TG)<=5.5/Math.sqrt(QGM.d);for(let a=0;a<6.283;a+=.09)P(48+Math.cos(a)*R0.r,48+Math.sin(a)*R0.r,near?'#ffffff':QGM.col[2])}}
 if(QGM.end&&QGM.end.ok){const k=Math.min(1,(t-QGM.end.t)/600);c.fillStyle=`rgba(255,250,220,${.5*(1-k)})`;c.fillRect(0,0,96,96)}
 requestAnimationFrame(qgDraw)}
function qgNote(perf,skip){return skip?'':perf>=.9?' · ☯️ รวมปราณได้สมบูรณ์แบบ':perf>=.6?' · ☯️ รวมปราณได้ดี':perf<.3?' · ☯️ รวมปราณพลาดหลายจังหวะ':''}
