{const _bt=btTick;btTick=function(){try{if(S&&S.alive&&!S.beastMode&&!S.xt&&qgOk()&&!(bagHas('brk')&&S.rcap!=null&&S.rcap+1<=5)){const raw=rawRealm();if(S.rcap!=null&&raw>S.rcap){const t=S.rcap+1;if(t>1&&REALMS[t]){const p=btChance(t),nm=REALMS[t].n;
  qiGame({title:`ทะลวงสู่${nm}`,sub:`ปราณในร่างล้นถึงขีด ต้องรวมให้เป็นหนึ่งที่ตันเถียนเพื่อฝ่าคอขวด`,p,diff:actDiff()*(1+t*.03)},(ok,perf,pF,skip)=>{if(!S||!S.alive)return;
   if(ok){S.rcap=t;log(`🌟 ทะลวงคอขวดสู่<b>${nm}</b>สำเร็จ${qgNote(perf,skip)} <span class="tag2">(โอกาส ${Math.round(pF*100)}%)</span>`,'epic',true);if(perf>=.99&&!skip)S.flags.qgPerfect=1;S.btFail=0}
   else{S.btFail=(S.btFail||0)+1;const d=Math.round(R(8,20)*t/2*(perf<.3&&!skip?1.4:1));S.hp-=d;if(!(tr('yinyang')||tr('allarts')))S.qi=Math.max(0,S.qi*.95);log(`💢 สายปราณแตกกระจาย ทะลวงสู่<b>${nm}</b>ไม่สำเร็จ${qgNote(perf,skip)} — พลังชีวิต −${d} <span class="tag2">(โอกาส ${Math.round(pF*100)}% · ครั้งหน้าง่ายขึ้น)</span>`,'bad');try{qiDev(false)}catch(e){}}
   try{render();checkDeath()}catch(e){}});return}}}}catch(e){console.error(e)}return _bt.apply(this,arguments)}}
