function paCanSee(){return S&&S.alive&&S.ch!=='short'&&!(S.beastMode&&!S.beastMode.human)&&$('game')&&$('game').classList.contains('on')}
function paNote(j){if(!j)return;PA.sum=j.pa||null;if(j.pw>0)paClaim();const p=j.pa;if(!p||p.phase!=='open'||PA.seen[p.sid]||!paCanSee())return;PA.seen[p.sid]=1;if(Date.now()-p.t0>4*60e3)return;paBanner(p)}
function paBanner(p){const old=$('paBan');if(old)old.remove();const d=document.createElement('div');d.id='paBan';d.innerHTML=`📢 <b>ประกาศทั่ว${S.xt?'เก้าชั้นฟ้า':S.xian?'โลกเซียน':'ยุทธภพ'}!</b><br>งานประมูลสมบัติล้ำค่าของผู้เล่นทั้งแผ่นดิน${p.ls&&p.ls>Date.now()+5000?'<b>จะเริ่มในอีกราว '+Math.max(1,Math.round((p.ls-Date.now())/1000))+' วิ</b>':'เริ่มแล้ว'} · ${p.left} ชิ้นที่หาที่ไหนไม่ได้<div class="pbar"><i id="paBanT"></i></div><div class="bt"><button onclick="paJoin()">🏛️ ไปร่วมประมูล</button><button class="n" onclick="paBanX()">ไม่ไป</button></div>`;document.body.appendChild(d);try{sfx('rare')}catch(e){}
 const t0=Date.now();PA.banT=setInterval(()=>{const f=1-(Date.now()-t0)/10000,e=$('paBanT');if(e)e.style.width=Math.max(0,f*100)+'%';if(f<=0)paBanX()},200)}
function paBanX(){clearInterval(PA.banT);const d=$('paBan');if(d)d.remove()}
function paJoin(){paBanX();if(!S||!S.alive)return;if(S.ch==='short')return toast('โหมดชีวิตสั้นเข้าร่วมประมูลไม่ได้');if(choice._cur)return toast('ตัดสินใจเรื่องที่ค้างอยู่ก่อน');openPAuc()}
