async function paVote(i){if(!PA.cur||!PA.cur.cur)return;try{const j=await api('pavote',{sid:PA.cur.cur.sid,l:i});toast(j.ok?'โหวตแล้ว ⭐':'โหวตไปแล้วในรอบนี้');paPoll(0)}catch(e){}}
