async function paClaim(){if(PA.claiming)return;PA.claiming=1;try{const j=await api('pa',{});if(j&&j.ok)paWins(j.wins)}catch(e){}finally{PA.claiming=0}}
function paWins(L){if(!L||!L.length||!S||!S.alive)return;S.paDone=S.paDone||[];for(const w of L){let o=null;try{o=JSON.parse(w)}catch(e){}if(!o)continue;const key=o.sid+':'+o.li;if(S.paDone.includes(key)){api('paclaim',{w}).catch(()=>{});continue}
  S.paDone.push(key);if(S.paDone.length>40)S.paDone.shift();const it=paItem(o.r,o.k),cost=o.u?Math.round(o.g):Math.round(o.g*({m:1e5,x:5e6,g:5e8}[ECO_W()]));
  if(S.money>=cost){S.money-=cost;(S.vault=S.vault||[]).push({pa:1,r:o.r,k:o.k,paid:cost,uid:Math.random().toString(36).slice(2,8)});log(`🏛️ ชนะการประมูลทั่ว${S.xt?'เก้าชั้นฟ้า':S.xian?'โลกเซียน':'ยุทธภพ'}! ได้ <b>${esc(it.n)}</b> ${rarTag(it.r)} ในราคา ${paGold(cost)} 🗝️ เก็บเข้าคลังสมบัติแล้ว (เปิดได้ที่ 🎒 กระเป๋า)`,'myth',true);keyAdd(`ชนะประมูลผู้เล่น ${it.n}`);S.flags.paWin=1}
  else{S.fame=Math.max(0,S.fame-40);log(`💸 ชนะประมูล <b>${esc(it.n)}</b> แต่เงินไม่พอจ่าย (${fmtM(cost)} ตำลึง) ถูกยึดสิทธิ์และเสียชื่อเสียง −40`,'bad',true)}
  api('paclaim',{w}).catch(()=>{})}try{render()}catch(e){}}
