{const _omPA=openMenu;openMenu=function(){const r=_omPA.apply(this,arguments);try{if(S&&S.ch!=='short'&&PA.sum&&PA.sum.phase==='open'){const gr=$('modal').querySelector('.mgrid');if(gr){const b=document.createElement('button');b.className='opt';b.style.cssText='background:linear-gradient(160deg,#4a3112,#2b1d0e);color:#ffe08a;border-color:#f0c860';b.setAttribute('onclick','paJoin()');b.innerHTML=`🏛️ ประมูลทั่วแผ่นดิน<small style="color:#f0c860">กำลังเปิด · เหลือ ${PA.sum.left} ชิ้น</small>`;gr.insertBefore(b,gr.firstChild)}}}catch(e){console.error(e)}return r}}
{const L=[{id:'pa_win',n:'เศรษฐีใต้หล้า',d:'ชนะการประมูลทั่วแผ่นดินกับผู้เล่นจริง',r:3,c:()=>!!S.flags.paWin}];const c=ACH.find(x=>x[0]==='ผู้ข้ามมิติ');if(c){c[1].push(...L);ACH_ALL.push(...L)}}

// ==== สมดุล v13.1: เควสระบบตามจังหวะผู้เล่น · บันไดถุงมิติ · วิชาเน้นคุณภาพ · ชื่อเสียงขึ้นลง · คอขวดใหญ่ · อายุขัยซ้อนลดลง · ลูกในโลกเซียนมีเพดาน ====
function artForce(a){window._artForce=1;try{S.arts.push(a)}finally{window._artForce=0}}
function artCap(){return Math.min(20,6+Math.floor((S.int||0)/60))}
function artMaster(L,a){const pool=L.filter(x=>x&&x.n&&!x.own),t=pool.length?ch(pool):null;if(!t){_nPush.call(L,a);return}const up=Math.max(1,Math.round((a.b||20)*.15));t.b=Math.round((t.b||0)+up);const full=L.length>=artCap();
 queueMicrotask(()=>{try{log(`📘 ${full?'ความจำเรื่องวิชาเต็มแล้ว ':''}ได้ตำรา《${esc(a.n)}》มาเทียบกับวิชาที่มี นำมาเสริม${artHtml(t)} พลังวิชา +${fmt(up)}${full?` <span class="tag2">(จำได้ ${artCap()} วิชาตามปัญญา · หลอมรวมเพื่อเปิดที่ว่าง)</span>`:''}`,'')}catch(e){}})}
