const TTL_WEAK=new Set(['วิญญาณเก่าในร่างใหม่','ผู้ที่ระบบดึงกลับจากความตาย','ผู้กลับมาจากความตาย','ผู้หวนคืนมาทวงแค้น']);
ttlMake=function(){let weak=null;for(const t of TTL_SP){let ok=false;try{ok=t[1]()}catch(e){}if(!ok)continue;if(!TTL_WEAK.has(t[2]))return t[2];if(!weak)weak=t[2]}
 if(weak){if(S.ttlWk==null)S.ttlWk=Math.random();if(S.ttlWk<.35)return weak}
 const c=ttlCat();S.ttlPk=S.ttlPk||{};if(S.ttlPk[c]==null)S.ttlPk[c]=R(0,TTL_MOD[c].length-1);return TTL_CORE[S.xian?'x':'m'][ttlPath()][ttlTier()]+TTL_MOD[c][S.ttlPk[c]]};
