function profFile(inp){const f=inp.files&&inp.files[0];inp.value='';if(!f)return;if(!/^image\//.test(f.type)){toast('เลือกไฟล์รูปภาพเท่านั้น');return}if(f.size>12e6){toast('ไฟล์ใหญ่เกินไป');return}
 const url=URL.createObjectURL(f),im=new Image();im.onload=()=>{try{const c=document.createElement('canvas');c.width=c.height=72;const x=c.getContext('2d'),s=Math.min(im.width,im.height);x.imageSmoothingQuality='high';x.drawImage(im,(im.width-s)/2,(im.height-s)/2,s,s,0,0,72,72);
  let q=.86,out=c.toDataURL('image/jpeg',q);while(out.length>11000&&q>.3){q-=.12;out=c.toDataURL('image/jpeg',q)}URL.revokeObjectURL(url);if(out.length>11000){toast('ย่อรูปไม่ได้ ลองรูปอื่น');return}
  const d=frGet();if(!d.snap&&S)try{d.snap=snapAvatar()}catch(e){}d.av=out;d.avUp=1;d.avSt='pend';frSet(d);profPush().then(()=>{profStat().then(()=>{if($('modal').dataset.k==='profile')openProfile()})});toast('📤 ส่งรูปให้ตรวจแล้ว');openProfile()}catch(e){toast('เปิดรูปไม่ได้')}};
 im.onerror=()=>{URL.revokeObjectURL(url);toast('เปิดรูปไม่ได้')};im.src=url}
