function birthSetup(){const b=$('birth');if(!b||b.dataset.v2)return;b.dataset.v2=1;const av=$('ava');if(av){av.style.display='none';av.insertAdjacentHTML('beforebegin','<div class="bstage" id="bStage"><canvas id="bAva" width="136" height="150"></canvas><div class="bcap" id="bCap"></div></div>')}
 const nm=$('nameOut');if(nm&&nm.parentNode){nm.parentNode.classList.add('bname');nm.parentNode.insertAdjacentHTML('beforeend','<div class="btags" id="bTags"></div>')}
 const h2=b.querySelector('h2');if(h2)h2.insertAdjacentHTML('afterend','<div class="bwld" id="bWld"></div>');const ob=$('oddsBox');if(ob)ob.insertAdjacentHTML('beforeend','<div class="ot" id="oddsT"></div>')}
