function fateApply(){const r=roll;if(!r)return;const N=1/(r.p*(r.era?r.era.p:1)),f=r.rare?r.rare.f:fateOf(N),F=FATE[f];
 const st=$('bStage');if(st)st.className='bstage sg'+f;
 const ob=$('oddsBox');if(ob){ob.className='box oddsbig fb'+f;ob.querySelectorAll('.fstar').forEach(e=>e.remove());const t=$('oddsT');if(t){t.className='ot';t.innerHTML=`${F[2]} <span class="fx${f}">ระดับชะตา: ${F[1]}</span>`}
  let d=$('oddsD');if(!d){ob.insertAdjacentHTML('beforeend','<div class="od" id="oddsD"></div><div class="fbar" id="oddsBar"></div>');d=$('oddsD')}d.textContent=F[3];const bar=$('oddsBar');if(bar){bar.className='fgrade fx'+f;bar.textContent=`⟪ ${FGRADE[f]} ⟫`}
  const n=$('oddsN');if(n)n.className='n px fx'+f;
  if(f>=10)for(let i=0;i<(f-8)*6;i++){const s=document.createElement('i');s.className='fstar';s.style.left=Math.random()*100+'%';s.style.top=Math.random()*100+'%';s.style.animationDelay=(Math.random()*1.8)+'s';ob.appendChild(s)}}
 const dl=(document.querySelectorAll('#birth .trait').length*220)+400;
 if(f>=6)setTimeout(()=>{const b=$('oddsBox');if(!b||b.style.visibility==='hidden'||roll!==r)return;const C=f>=10?['#ff4d4d','#ffd84d','#5dff7a','#4dd8ff','#b06bff','#ffffff']:f>=8?['#ff3a5a','#ff5ad8','#ffd040','#ffffff']:['#ffc030','#ff8a2a','#fff0a0'];for(let i=0;i<Math.min(70,(f-4)*9);i++){const e=document.createElement('i');e.className='bconf';e.style.left=Math.random()*100+'%';e.style.background=C[i%C.length];e.style.animationDelay=(Math.random()*.6)+'s';b.appendChild(e);setTimeout(()=>e.remove(),2500)}try{if(f>=8)sfx('ach')}catch(e){}},dl)}
{const _dr3=doRoll;doRoll=function(first){const r=_dr3.apply(this,arguments);try{document.querySelectorAll('#oddsBox .bconf').forEach(e=>e.remove());fateApply()}catch(e){console.error(e)}return r}}
{const _ol=oddsLine;oddsLine=function(){const t=_ol.apply(this,arguments);try{if(S&&!S.custom&&S.odds){const F=FATE[S.rareF!=null?S.rareF:fateOf(1/S.odds)];return t+` · ${F[2]} ชะตา${F[1].replace(/^ชะตา/,'')}`}}catch(e){}return t}}

// ============ v13.9 แจ้งเตือนเร็ว: ประมูล + ประกาศ ถึงทุกคนภายใน ~20 วิ (ไม่ต้องรอรอบ 45 วิ/2 นาที) ============
async function fastTick(){if(document.hidden||fastTick._f)return;fastTick._f=1;try{const j=await api('tick');
 try{const p=j.pa;PA.sum=p||PA.sum;if(p&&p.phase==='open'&&!PA.seen[p.sid]&&paCanSee()&&Date.now()-p.t0<4*60e3){PA.seen[p.sid]=1;paBanner(p)}}catch(e){}
 if(j.av&&j.av!==fastTick._av){fastTick._av=j.av;onlinePing()}else if(!j.av)fastTick._av='';try{if(j.nt&&typeof ntShow==='function')ntShow(j.nt)}catch(e){}}
 catch(e){}finally{fastTick._f=0}}
setTimeout(fastTick,6000);{let ftL=0;setInterval(()=>{const busy=!!(PA.sum&&PA.sum.phase==='open'),iv=busy?20000:(idleMs()>300000?180000:45000);if(Date.now()-ftL<iv-1000)return;ftL=Date.now();fastTick()},20000)}

