function blPathOffer(){const m=S.beastMode;if(m.path||m.pOff)return false;m.pOff=1;
 choice('🐾 เส้นทางของอสูร',`${esc(S.name)}เปิดปัญญาแล้ว สัตว์ตนหนึ่งจะเดินทางไหนต่อ?<br><span class="tag2">แต่ละเส้นทางมีเนื้อเรื่อง 6 บท และท่าทางฝึกเฉพาะทาง</span>`,Object.keys(BPATH).map(k=>({t:`${BPATH[k].ic} ${BPATH[k].n}`,s:BPATH[k].d,f(){m.path=k;m.pc=0;m.pcY=S.age;blFocusSync();S.focus=BPATH[k].fo[0];log(`${BPATH[k].ic} ${S.name} เลือกเส้นทาง <b>${BPATH[k].n}</b>`,'epic',true);keyAdd('เลือกเส้นทาง'+BPATH[k].n);render()}})));return true}
function blPathTick(){const m=S.beastMode;if(!m||m.human||choice._cur||modalOpen)return;
 if(!m.path){if(m.st>=2&&S.age>=6)blPathOffer();return}
 const L=BCH[m.path];if(!L||(m.pc||0)>=L.length)return;const c=L[m.pc||0];if(m.st<c.st)return;
 if(S.age-(m.pcY||0)<6+(m.pc||0)*3||Math.random()>.4)return;m.pc=(m.pc||0)+1;m.pcY=S.age;try{c.f()}catch(e){console.error(e)}}
function blPathYear(){const m=S.beastMode,f=S.focus,mul=S.talent.m*(S.xian?1.4:1),st=m.st||0;
 if(f==='patrol'){S.power+=Math.round(R(5,12)*mul*(1+st*.6));S.karma+=1;if(Math.random()<.2)S.hp-=R(3,10);S.fame+=1}
 else if(f==='devour'){S.power+=Math.round(R(14,28)*mul*(1+st*.7));S.karma-=2;if(Math.random()<.35)S.hp-=R(5,15);if(Math.random()<.5)S.kills=(S.kills||0)+1}
 else if(f==='pack'){m.pk=Math.min(20+st*40,(m.pk||0)+R(0,2));S.power+=Math.round((R(4,9)+(m.pk||0)*.6)*mul*(1+st*.4));S.fame+=1}
 else if(f==='bond'){S.int+=R(1,3);S.qi+=+(.5*mul).toFixed(1);S.power+=Math.round(R(6,14)*mul*(1+st*.5));joy(2)}
 else if(f==='seclude'){S.qi+=+(R(10,20)/10*mul*(st>=1?2:1)).toFixed(1);S.int+=1;S.hp=Math.min(S.maxHp,S.hp+10)}}
{const _by2=beastYear;beastYear=function(){const P0=S.power,Q0=S.qi,pm=(S.beastMode&&S.beastMode.pm)||1;try{blNames();blFocusSync();if(!focusOK(S.focus))S.focus='hunt';blPathYear()}catch(e){console.error(e)}
 const r=_by2.apply(this,arguments);try{if(S&&S.beastMode&&pm!==1){const dp=S.power-P0,dq=S.qi-Q0;if(dp>0)S.power+=Math.round(dp*(pm-1));if(dq>0)S.qi+=+(dq*(pm-1)*.5).toFixed(1)}if(S&&S.alive&&S.beastMode&&!S.beastMode.human)blPathTick()}catch(e){console.error(e)}return r}}
{const _af=autoFocus;autoFocus=function(){const r=_af.apply(this,arguments);try{const m=S.beastMode;if(m&&!m.human&&m.path&&S.hp>=S.maxHp*.4&&Math.random()<.45)S.focus=BPATH[m.path].fo[0]}catch(e){}return r}}
