function godMark(root){try{(root||document).querySelectorAll('.item,.lgf,.tchip,.shpick button,#achPop').forEach(e=>{if(e.classList.contains('frgod'))return;
 if(e.classList.contains('item')){const b=e.querySelector('.h b');if(!b||!(b.textContent||'').includes(GOD_T))return;e.classList.add('frgod');b.classList.add('tgod');const tl=e.querySelector('.h span.t6');if(tl)tl.textContent='✦ พระเจ้า ✦ ×'+ACH_W[6];return}
 const tx=e.textContent||'';if(tx.includes(GOD_T)&&tx.length<GOD_T.length+50){e.classList.add('frgod');e.querySelectorAll('.t6,b').forEach(x=>{if((x.textContent||'').includes(GOD_T))x.classList.add('tgod')})}})}catch(e){}}
{const _lg=log;log=function(t,...a){if(window._bbirth)return;if(typeof t==='string'&&t.includes(GOD_T))t=t.replace(/fr6/g,'fr6 frgod').replace(/class="t6"/g,'class="t6 tgod"').replace(/>\?\?\?</g,'>✦ พระเจ้า ✦<');return _lg.call(this,t,...a)}}
{let _gq=0;const mo=new MutationObserver(ms=>{if(_gq)return;for(const m of ms)for(const n of m.addedNodes){if(n.nodeType===1&&(n.textContent||'').includes(GOD_T)){_gq=1;requestAnimationFrame(()=>{_gq=0;godMark()});return}}});try{mo.observe(document.body,{childList:true,subtree:true})}catch(e){}}
