const I18N_HK=Object.keys(I18N.h).sort((a,b)=>b.length-a.length);
function i18nComp(tk){const Hh=I18N.h,Mm=I18N.m;for(const h of I18N_HK){if(tk.length>h.length&&tk.startsWith(h)){const r=tk.slice(h.length);if(Mm[r]!=null)return Mm[r]+' '+Hh[h];
  for(const h2 of I18N_HK){if(r.length>h2.length&&r.startsWith(h2)&&Mm[r.slice(h2.length)]!=null)return Mm[r.slice(h2.length)]+' '+Hh[h2]+' '+Hh[h]}}}return null}
{const _it=i18nTok;i18nTok=function(tk){const D=I18N.d;if(D[tk]!=null)return D[tk];const c=i18nComp(tk);if(c!=null)return c;if(I18N.m[tk]!=null)return I18N.m[tk];return _it(tk)}}

