// เฟสแอนิเมชันอิงเวลาจริง: วาดใหม่กี่ครั้งก็เล่นต่อเนื่อง ไม่กระตุกกลับจุดเริ่ม (สาเหตุที่ประกายกรอบไม่ขึ้นตอนสวมใส่)
function aPh(ms,off){return '-'+(((Date.now()+(off||0))%ms)/1000).toFixed(2)+'s'}
frWrap=function(inner,id,extra){const f=frOf(id);if(!f)return`<span class="frw fr-none"${extra?` style="${extra}"`:''}>${inner}</span>`;
 const P=/pulse/.test(f.ty)?3500:4000,sp=/sparkle/.test(f.ty);
 return`<span class="frw ${frCls(id)}" style="${frSty(id)};animation-delay:${aPh(P)}${extra?';'+extra:''}">${inner}${sp?`<i class="frsp s1" style="animation-delay:${aPh(2400)}"></i><i class="frsp s2" style="animation-delay:${aPh(2400,1600)}"></i><i class="frsp s3" style="animation-delay:${aPh(2400,800)}"></i>`:''}</span>`};
// ---- วิเคราะห์ฉายาเรียกขาน: ระดับความยาก + ฝ่าย ----
const TTL_AL={'ผู้สังหารมารสวรรค์':'g','ผู้ล้มราชันมารแห่งอเวจี':'g','พระโพธิสัตว์เดินดิน':'g','ลูกกำพร้าผู้ท้าฟ้า':'g','ขยะผู้พลิกชะตาฟ้า':'g','ผู้ยิ่งใหญ่ไร้วรยุทธ':'g','ปรมาจารย์ผู้ก่อตั้งสำนัก':'g','ผู้ย้อนเวลามาแก้ชะตา':'g','ผู้ที่ระบบดึงกลับจากความตาย':'g',
 'ยมทูตเดินดิน':'e','มารร้ายในร่างคน':'e','ผู้หวนคืนมาทวงแค้น':'e','ราชันแห่งตำหนักใน':'e'};
const TTL_PATHOF=(()=>{const m={};['m','x'].forEach(w=>Object.entries(TTL_CORE[w]).forEach(([p,L])=>L.forEach((c,i)=>{if(!m[c]||m[c].i<i)m[c]={p,i}})));return m})();
const TTL_MODOF=(()=>{const m={};Object.entries(TTL_MOD).forEach(([k,L])=>L.forEach(x=>{m[x]=k}));return m})();
function ttlInfo(t){t=String(t||'');if(!t)return null;if(typeof ACH_ALL!=='undefined'&&ACH_ALL.some(a=>a.n===t))return null;
 const sp=TTL_SP.find(x=>x[2]===t);if(sp)return{hard:true,tier:5,al:TTL_AL[t]||'n'};
 let best='';for(const c in TTL_PATHOF)if(t.startsWith(c)&&c.length>best.length)best=c;if(!best)return null;
 const P=TTL_PATHOF[best],mk=TTL_MODOF[t.slice(best.length)];if(!mk&&t.length>best.length)return null;
 let al=P.p==='ธรรมะ'?'g':P.p==='มาร'?'e':'n';if(mk==='good')al='g';else if(mk==='evil'||mk==='kills')al='e';
 return{hard:P.i>=3,tier:P.i,al}}
function ttlCls(t){const i=ttlInfo(t);if(!i||!i.hard)return'';return' tt tt-'+({g:'good',e:'evil',n:'neu'})[i.al]}
{const _tc2=tchipH;tchipH=function(t,r){if(String(t)===GOD_T)return _tc2.apply(this,arguments);r=Math.max(0,Math.min(6,+r||0));const tc=ttlCls(t);
 const ic=tc.includes('evil')?'<i class="tti">☠</i>':tc.includes('good')?'<i class="tti">✧</i>':tc.includes('neu')?'<i class="tti">◇</i>':'';
 return`<span class="tchip fr${r}${tc}" style="--ph:${aPh(3000)};--ph2:${aPh(4200,700)}">${ic}<span class="tcx">${esc(String(t).slice(0,40))}</span></span>`}}
// หน้าเลือกฉายา: ปุ่มใช้หน้าตาเดียวกับป้ายจริง + คำอธิบายสี
{const _osp=openShowPick;openShowPick=function(){const r=_osp.apply(this,arguments);try{const m=$('modal');m.querySelectorAll('.shpick button').forEach(b=>{const sp=b.querySelector('span');if(!sp)return;const t=sp.textContent,rr=(b.className.match(/fr(\d)/)||[])[1]||0;b.classList.add('shx');b.innerHTML=tchipH(t,rr)});
 const h=[...m.querySelectorAll('h4')].find(x=>/ฉายาที่เคยถูกเรียกขาน/.test(x.textContent));if(h&&!m.querySelector('#ttLegend'))h.insertAdjacentHTML('afterend',`<p id="ttLegend" class="tag2" style="margin:-2px 0 8px">ฉายาที่ได้ยาก (ระดับเทพขึ้นไป และฉายาพิเศษ) สีตามบทบาท: ${tchipH('จักรพรรดิกระบี่ทรงธรรม',4)} ฝ่ายธรรมะ · ${tchipH('จักรพรรดิมารโลหิต',4)} ฝ่ายมาร · ${tchipH('จักรพรรดิหมัดสายลม',4)} สายกลาง</p>`)}catch(e){}return r}}
try{Object.assign(I18N.d,{'ฉายาที่ได้ยาก':'Hard-earned titles','ระดับเทพขึ้นไป และฉายาพิเศษ':'God tier and above, plus special titles','สีตามบทบาท':'are colored by role','ฝ่ายธรรมะ':'Orthodox','ฝ่ายมาร':'Demonic','สายกลาง':'Neutral'})}catch(e){}
