function achThemeMark(){try{
 document.querySelectorAll('#modal .item:not([data-th])').forEach(e=>{e.dataset.th='-';const b=e.querySelector('.h b');if(!b)return;const n=(b.textContent||'').replace(/^[^฀-๿A-Za-z0-9]+/,'').trim();const th=achThemeOf(n);if(th){e.dataset.th=th.t;e.classList.add('th','th-'+th.t)}});
 document.querySelectorAll('.lgf:not([data-th])').forEach(e=>{e.dataset.th='-';const b=e.querySelector('b');const th=b&&achThemeOf(b.textContent);if(th){e.dataset.th=th.t;e.classList.add('th','th-'+th.t);e.style.setProperty('--ph',aPh(3000))}});
 const ap=$('achPop');if(ap){const n=ap.querySelector('.an');const th=n&&achThemeOf(n.textContent);const k=th?th.t:'-';if(ap.dataset.th!==k){[...ap.classList].filter(c=>/^th/.test(c)).forEach(c=>ap.classList.remove(c));ap.dataset.th=k;if(th)ap.classList.add('th','th-'+th.t)}}
}catch(e){}}
{let q=0;const mo=new MutationObserver(()=>{if(q)return;q=1;requestAnimationFrame(()=>{q=0;achThemeMark()})});try{mo.observe(document.body,{childList:true,subtree:true})}catch(e){}}
