const EST_TRAD={war:['⚔️ ตระกูลนักรบ','พลังยุทธ์จากลานฝึก ×2'],sch:['📜 ตระกูลบัณฑิต','ปัญญาจากหอคัมภีร์ ×2 · ทายาทฉลาด'],mer:['💰 ตระกูลพ่อค้า','รายได้ตระกูลทั้งหมด +40%'],vir:['🙏 ตระกูลคุณธรรม','กรรมดี ×2 · ชื่อเสียง +20%'],lov:['💞 ตระกูลรักใคร่','ความสุข ×1.5 · ลูกหลานมากขึ้น']};
function estInit(){if(!S.est)S.est={lv:0,b:{},prop:0,pr:0,tr:null,trY:-99,raid:0,ev:[]};return S.est}
