function estPropInc(){return Math.round((estInit().prop||0)*60*W15())}
function estInc(){const E=estInit(),W=W15();let m=estLv('farm')*120*W+estLv('mine')*90*W+estLv('inn')*110*W+estLv('pond')*50*W+estPropInc();m+=estLv('market')*Math.min(S.money*.004,800*W*estLv('market'));if(E.tr==='mer')m*=1.4;return Math.round(m)}
