 if(estLv('lib')){const v=estLv('lib')*(E.tr==='sch'?2:1);S.int+=v;if(Math.random()<.03*estLv('lib')){const a=newArt(Math.min(3,Math.floor(estLv('lib')/2)));S.arts.push(a);got.push('ได้ '+artHtml(a))}}
 if(estLv('alch')){S.qi=+(S.qi+.2*estLv('alch')).toFixed(1);if(Math.random()<.08*estLv('alch'))bagAdd(Math.random()<.3?'qi':'hp',1,true)}
 if(estLv('clinic'))S.hp=Math.min(S.maxHp,S.hp+Math.round(S.maxHp*.06*estLv('clinic')));
