function estBuyLand(){const E=estInit(),n=E.lv+1;if(n>5)return;const c=estLandCost(n);if(S.money<c)return toast('เงินไม่พอ');S.money-=c;E.lv=n;S.fame+=Math.round(20*n*({m:1,x:3,g:10}[ECO_W()]));log(`🏞️ ขยายเป็น <b>${estLandN(n)}</b> สร้างสิ่งปลูกสร้างได้ ${EST_SL[n]} หลัง`,'epic',n>=4);sfx('good');render();openHouse('est')}
