const TOWN_X=['เมฆาหยก','ภูผาเซียน','ธาราวิญญาณ','หงส์เพลิง','จันทร์เงิน','วายุหมื่นลี้','ดาราใส','บุปผาพันปี'],TOWN_G=['ดาวเหนือ','สุริยันทอง','รุ้งเก้าสี','ทะเลดารา','วังเมฆ','อรุณนิรันดร์','จักรวาลกลาง','กัลป์พฤกษ์'];
{const _tn=townName;townName=function(){if(S&&!S.region){const w=ECO_W();if(S.townW!==w){S.townW=w;S.town=w==='g'?'นครเทพ'+ch(TOWN_G):w==='x'?'เมืองเซียน'+ch(TOWN_X):null}if(w==='m'&&S.town&&S.town.startsWith('หมู่บ้าน')&&S.age>=16)S.town='เมือง'+S.town.slice(8)}return _tn.apply(this,arguments)}}
const TW={m:{bk:'🏦 โรงรับฝากเงิน',ar:'🥋 ลานประลองเมือง',gm:'🎲 บ่อนเต๋า',ft:'🔮 หมอดูตาบอด',tea:'🍵 โรงน้ำชา',gov:'🏛️ จวนเจ้าเมือง',fest:'🎪 เทศกาลเมือง'},x:{bk:'🏦 หอคลังวิญญาณ',ar:'🥋 ลานประลองเซียน',gm:'🎲 หอเสี่ยงโชคดารา',ft:'🔮 ผู้หยั่งชะตา',tea:'🍵 หอชาเมฆา',gov:'🏛️ หอเจ้าเมืองเซียน',fest:'🎪 งานชุมนุมเซียน'},g:{bk:'🏦 คลังเทวสภา',ar:'🥋 สังเวียนเทพ',gm:'🎲 วงล้อโชคชะตา',ft:'🔮 กระจกพันภพ',tea:'🍵 ศาลาน้ำอมฤต',gov:'🏛️ ตำหนักผู้ปกครองนคร',fest:'🎪 งานเฉลิมฉลองแดนเทพ'}};
