function twInit(){if(!S.tw)S.tw={bank:0,arY:-1,gmY:-1,gmN:0,ftY:-1,teaY:-1,gov:0,festY:-1};if(S.tw.w!==ECO_W()){S.tw.w=ECO_W();S.tw.gov=0}return S.tw}
function twMain(){const T=twInit(),W=W15(),fest=S.age%4===0;return`<h4 style="margin:12px 0 4px">🏙️ สถานที่อื่นในเมือง</h4><div class="mgrid">
 <button class="opt" onclick="openTown('bk')">${tw('bk')}<small>ฝากไว้ ${fmtM(T.bank)} · ดอก 2%/ปี</small></button>
 <button class="opt" onclick="openTown('ar')">${tw('ar')}<small>${T.arY===S.age?'ปีนี้ประลองแล้ว':'ชิงเงินรางวัล'}</small></button>
 <button class="opt" onclick="openTown('gm')">${tw('gm')}<small>${T.gmY===S.age?'เล่นได้อีก '+Math.max(0,3-T.gmN)+' ครั้ง':'ลองดวงปีละ 3 ครั้ง'}</small></button>
 <button class="opt" onclick="openTown('ft')">${tw('ft')}<small>${T.ftY===S.age?'ดูแล้วปีนี้':'ทำนายชะตา'}</small></button>
 <button class="opt" onclick="openTown('tea')">${tw('tea')}<small>${T.teaY===S.age?'นั่งแล้วปีนี้':'ข่าวลือ · พบผู้คน'}</small></button>
 <button class="opt" onclick="openTown('gov')">${tw('gov')}<small>${T.gov?GOV_T[T.gov-1]:'ซื้อยศกิตติมศักดิ์'}</small></button>
 <button class="opt" onclick="openTown('fest')" ${fest?'style="background:var(--tb4)"':''}>${tw('fest')}<small>${fest?(T.festY===S.age?'ร่วมแล้วปีนี้':'🎉 กำลังจัดอยู่!'):'จัดทุก 4 ปี (อีก '+(4-S.age%4)+' ปี)'}</small></button></div>`}
function twPage(p){const T=twInit(),W=W15(),tn=townName(),back=`<button class="gbtn" onclick="openTown()">← ${tn}</button>`,ri=Math.max(0,realmIdx());
 if(p==='bk'){const cap=Math.round(2e5*W*(1+ri)),pi=Math.round(Math.min(T.bank*.02,cap*.02));return back+`<h4 style="margin:10px 0 4px">${tw('bk')}</h4><p>เงินฝาก <b>${fmtM(T.bank)}</b> ตำลึง · ดอกเบี้ย 2%/ปี (ได้ราว ${fmtM(pi)}/ปี) · รับฝากสูงสุด ${fmtM(cap)} · เงินฝากไม่ถูกโจรปล้นและไม่ถูกใช้จ่ายอัตโนมัติ</p>
  <div class="mgrid">${[.1,.5,1].map(f=>`<button class="opt" onclick="twBank(${f})">ฝาก ${f*100}%<small>${fmtM(Math.round(Math.min(S.money*f,Math.max(0,cap-T.bank))))}</small></button>`).join('')}${[.5,1].map(f=>`<button class="opt" onclick="twBank(-${f})">ถอน ${f*100}%<small>${fmtM(Math.round(T.bank*f))}</small></button>`).join('')}</div>`}
 if(p==='ar'){const done=T.arY===S.age;return back+`<h4 style="margin:10px 0 4px">${tw('ar')}</h4><p class="tag2">ปีละ 1 ครั้ง · แพ้เสียพลังชีวิต · ชนะได้เงินและชื่อเสียง</p>`+[[.85,'🟢 รุ่นทั่วไป',1],[1.1,'🟡 รุ่นยอดฝีมือ',3],[1.4,'🔴 รุ่นจ้าวสังเวียน',8]].map(([k,n,m],i)=>`<div class="item"><div class="h"><b>${n}</b><button class="sysb" onclick="twArena(${i})" ${done?'disabled style="opacity:.45"':''}>ลงสนาม</button></div><p class="tag2">คู่ต่อสู้แข็งแรงราว ${Math.round(k*100)}% ของคุณ · รางวัล ${fmtM(twArPrize(m))} ตำลึง</p></div>`).join('')}
 if(p==='gm'){const n=T.gmY===S.age?T.gmN:0;return back+`<h4 style="margin:10px 0 4px">${tw('gm')}</h4><p class="tag2">ทอยเต๋า 3 ลูก · สูง (11–18) หรือ ต่ำ (3–10) · ตองชนะ ×10 · ปีละ 3 ครั้ง (เหลือ ${3-n})</p><div class="mgrid">`+[100,1000,10000].map(b=>Math.round(b*W)).map(b=>`<button class="opt" onclick="twDice(${b},1)" ${n>=3||S.money<b?'disabled style="opacity:.45"':''}>⬆️ แทงสูง<small>${fmtM(b)}</small></button><button class="opt" onclick="twDice(${b},0)" ${n>=3||S.money<b?'disabled style="opacity:.45"':''}>⬇️ แทงต่ำ<small>${fmtM(b)}</small></button>`).join('')+'</div>'}
 if(p==='ft'){const c=Math.round(300*W);return back+`<h4 style="margin:10px 0 4px">${tw('ft')}</h4><p>ค่าดู ${fmtM(c)} ตำลึง · ปีละครั้ง · ได้ยินคำทำนายเรื่องอนาคต และได้พรเล็กๆ</p><button class="sysb" onclick="twFort()" ${T.ftY===S.age||S.money<c?'disabled style="opacity:.45"':''}>🔮 ขอดูดวง</button>`}
 if(p==='tea'){const c=Math.round(80*W);return back+`<h4 style="margin:10px 0 4px">${tw('tea')}</h4><p>ค่าน้ำชา ${fmtM(c)} ตำลึง · ปีละครั้ง · ฟังข่าวลือ ฝึกเสน่ห์ อาจได้พบคนที่ถูกชะตา</p><button class="sysb" onclick="twTea()" ${T.teaY===S.age||S.money<c?'disabled style="opacity:.45"':''}>🍵 นั่งจิบชา</button>`}
 if(p==='gov'){return back+`<h4 style="margin:10px 0 4px">${tw('gov')}</h4><p class="tag2">ซื้อยศกิตติมศักดิ์ของเมือง · ได้ชื่อเสียงทันที และเบี้ยหวัดทุกปี</p>`+GOV_T.map((n,i)=>{const c=twGovC(i);return`<div class="item ${T.gov>i?'pin':''}"><div class="h"><b>${n}</b>${T.gov>i?'<span class="tag2">✅ ได้แล้ว</span>':T.gov===i?`<button class="sysb" onclick="twGov()" ${S.money>=c?'':'disabled style="opacity:.45"'}>${fmtM(c)}</button>`:'<span class="tag2">🔒</span>'}</div><p class="tag2">เบี้ยหวัด ${fmt(twGovInc(i+1))}/ปี · ชื่อเสียง +${fmt(twGovFame(i))}</p></div>`}).join('')}
 if(p==='fest'){const on=S.age%4===0,done=T.festY===S.age;return back+`<h4 style="margin:10px 0 4px">${tw('fest')}</h4>${on?`<p>เทศกาลกำลังคึกคัก! เลือกร่วมกิจกรรมได้ 1 อย่าง</p><div class="mgrid">${[['eat','🍡 ตระเวนชิมอาหาร','ความสุข +12'],['lan','🏮 ปล่อยโคมกับคนรัก','ความรัก + · ความสุข +'],['cmp','🏹 แข่งยิงธนูชิงรางวัล','ลุ้นรางวัลใหญ่'],['don','🙏 บริจาคงานบุญ','กรรมดี + ชื่อเสียง +']].map(([k,n,d])=>`<button class="opt" onclick="twFest('${k}')" ${done?'disabled style="opacity:.45"':''}>${n}<small>${d}</small></button>`).join('')}</div>`:`<p class="tag2">เทศกาลจัดทุก 4 ปี ครั้งหน้าอีก ${4-S.age%4} ปี</p>`}`}
 return null}
const twArPrize=m=>Math.round(250*W15()*m*(1+Math.max(0,realmIdx())*.6));
const twGovC=i=>Math.round([3000,15000,60000,250000,1000000][i]*W15());
const twGovInc=lv=>lv?Math.round([0,150,600,2000,6000,15000][lv]*W15()):0;
const twGovFame=i=>Math.round([30,80,200,500,1200][i]*({m:1,x:3,g:10}[ECO_W()]));
{const _ot2=openTown;openTown=function(p){p=p||'main';if(S&&['bk','ar','gm','ft','tea','gov','fest'].includes(p)){twInit();openTown._p=p;const h=twPage(p);modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>🏘️ ${townName()}</h3><p class="tag2">💰 ${fmtM(S.money)} ตำลึง</p>${h}`,'town');return}
 const r=_ot2.apply(this,arguments);try{if(p==='main'){const m=$('modal');m.insertAdjacentHTML('beforeend',twMain())}}catch(e){console.error(e)}return r}}
function twBank(f){const T=twInit(),cap=Math.round(2e5*W15()*(1+Math.max(0,realmIdx())));if(f>0){const v=Math.round(Math.min(S.money*f,Math.max(0,cap-T.bank)));if(v<=0)return toast(T.bank>=cap?'ฝากเต็มวงเงินแล้ว':'ไม่มีเงินให้ฝาก');S.money-=v;T.bank+=v;toast('ฝาก '+fmtM(v))}else{const v=Math.round(T.bank*-f);if(v<=0)return;T.bank-=v;S.money+=v;toast('ถอน '+fmtM(v))}sfx('click');render();openTown('bk')}
function twArena(i){const T=twInit();if(T.arY===S.age)return;if(choice._cur)return toast('ตัดสินใจเรื่องที่ค้างอยู่ก่อน');T.arY=S.age;const k=[.85,1.1,1.4][i],m=[1,3,8][i],foe=ch(S.xt?['เทพนักรบนิรนาม','จ้าวสังเวียนดารา','เทพอสูรผู้ท้าชิง']:S.xian?['เซียนกระบี่พเนจร','ศิษย์เอกนิกายใหญ่','ผู้ฝึกตนสายมาร']:['นักมวยร่างยักษ์','จอมดาบพเนจร','ศิษย์สำนักใหญ่','หญิงสาวถือแส้']);closeM();window._dsSkipN=foe;
 duel(foe,Math.round(total()*k*(.92+Math.random()*.16)),w=>{if(w){T.arW=(T.arW||0)+1;const g=twArPrize(m);S.money+=g;S.fame+=Math.round(m*8*({m:1,x:3,g:10}[ECO_W()]));log(`🥋 ชนะ${foe}ที่${tw('ar')} — รางวัล ${fmtM(g)} ตำลึง`,i>=2?'epic':'good')}else{const d=Math.round(S.maxHp*[.08,.15,.25][i]);S.hp-=d;log(`🥋 แพ้${foe}ที่${tw('ar')} — พลังชีวิต −${d}`,'bad')}render()})}
function twDice(b,hi){const T=twInit();if(T.gmY!==S.age){T.gmY=S.age;T.gmN=0}if(T.gmN>=3||S.money<b)return;T.gmN++;S.money-=b;const d=[R(1,6),R(1,6),R(1,6)],s=d[0]+d[1]+d[2],trip=d[0]===d[1]&&d[1]===d[2];let msg;
 if(trip){S.money+=b*10;msg=`🎉 ตอง ${d.join('-')}! ได้ ${fmtM(b*10)}`;joy(6)}else if((s>=11)===!!hi){S.money+=b*2;msg=`✅ ${d.join('-')} = ${s} ชนะ! ได้ ${fmt(b*2)}`;joy(2)}else{msg=`❌ ${d.join('-')} = ${s} เสีย ${fmtM(b)}`;joy(-2)}
 log(`🎲 ${tw('gm')}: ${msg}`,trip?'epic':'');toast(msg);sfx('click');render();openTown('gm')}
const FORT=[['ชะตาปีหน้าสดใส ดวงดาวส่องทางให้','luck'],['ระวังคนใกล้ตัวที่ยิ้มให้ แต่ใจไม่ตรง','warn'],['เงินทองจะไหลมาจากทิศตะวันออก','money'],['คู่ครองของเจ้าอยู่ไม่ไกล หากตั้งใจมองหา','love'],['พลังในกายยังซ่อนอยู่ อีกไม่นานจะแตกหน่อ','pow'],['อายุขัยของเจ้ายืนยาวกว่าที่คิด','life'],['ปีนี้อย่าเพิ่งลงมือเรื่องใหญ่ รอฟ้าเปิดก่อน','calm']];
function twFort(){const T=twInit(),c=Math.round(300*W15());if(T.ftY===S.age||S.money<c)return;T.ftY=S.age;S.money-=c;const [t,k]=ch(FORT);let ex='';
 if(k==='luck'){joy(5);ex='ความสุข +5'}else if(k==='money'){const g=Math.round(c*R(2,5));S.money+=g;ex=`เดินออกจากร้านเจอถุงเงินตก +${fmtM(g)}`}else if(k==='love'){S.cha+=3;ex='เสน่ห์ +3'}else if(k==='pow'){const g=pctPow(.03);S.power+=g;ex=`พลังยุทธ์ +${fmt(g)}`}else if(k==='life'){const v=S.xt?2000:S.xian?20:3;if(S.xt)S.glExtra=(S.glExtra||0)+v;else lsAdd(v);ex=`อายุขัย +${fmt(v)} ปี`}else if(k==='warn'){S.int+=2;ex='ระวังตัวมากขึ้น ปัญญา +2'}else{S.qi=+(S.qi+.5).toFixed(1);ex='จิตสงบ ลมปราณ +0.5 ปี'}
 log(`🔮 ${tw('ft')}ทำนาย: "${t}" — ${ex}`,'good');sfx('good');render();openTown('ft')}
function twTea(){const T=twInit(),c=Math.round(80*W15());if(T.teaY===S.age||S.money<c)return;T.teaY=S.age;S.money-=c;S.cha+=2;const x=Math.random();
 if(x<.3&&S.age>=18){closeM();log('🍵 ระหว่างจิบชา มีคนเดินมาขอนั่งร่วมโต๊ะ…');setTimeout(()=>{try{haremOffer(true)}catch(e){}},50);return}
 if(x<.55){S.dgHint=1;log('🍵 ได้ยินพ่อค้าคุยกันเรื่องดันเจี้ยนแห่งใหม่ (เสน่ห์ +2)','good')}else if(x<.75){const g=Math.round(c*R(3,8));S.money+=g;log(`🍵 พ่อค้าชวนลงทุนเล็กๆ ได้กำไร ${fmtM(g)} (เสน่ห์ +2)`,'good')}else{S.int+=3;log('🍵 ถกเรื่องยุทธ์กับผู้เฒ่าข้างโต๊ะจนเข้าใจอะไรมากขึ้น ปัญญา +3 · เสน่ห์ +2','good')}
 sfx('good');render();openTown('tea')}
function twGov(){const T=twInit(),i=T.gov,c=twGovC(i);if(i>=5||S.money<c)return;S.money-=c;T.gov=i+1;S.fame+=twGovFame(i);log(`🏛️ ได้รับยศ <b>${GOV_T[i]}</b> แห่ง${townName()} — เบี้ยหวัด ${fmt(twGovInc(T.gov))}/ปี`,'epic',i>=3);sfx('good');render();openTown('gov')}
function twFest(k){const T=twInit();if(T.festY===S.age||S.age%4)return;T.festY=S.age;const W=W15();
 if(k==='eat'){joy(12);log('🍡 ตระเวนชิมอาหารในเทศกาลจนพุงกาง ความสุข +12','good')}
 else if(k==='lan'){joy(8);if(S.sp)S.sp.aff=Math.min(100,(S.sp.aff||60)+10);(S.harem||[]).forEach(g=>g.aff=Math.min(100,(g.aff||65)+5));log(`🏮 ปล่อยโคมลอยฟ้า${S.sp?'กับ'+S.sp.n:'คนเดียวใต้แสงจันทร์'} — ความสุข +8${S.sp?' · ความรัก +10':''}`,'good')}
 else if(k==='cmp'){const p=.25+Math.min(.5,(S.power>0?Math.log10(total()+1)/20:0)+(S.int||0)/1000);if(Math.random()<p){const g=Math.round(2000*W*(1+Math.max(0,realmIdx())*.5));S.money+=g;S.fame+=Math.round(30*({m:1,x:3,g:10}[ECO_W()]));log(`🏹 ชนะการแข่งยิงธนูของเทศกาล! รางวัล ${fmtM(g)} ตำลึง`,'epic')}else{joy(2);log('🏹 ยิงพลาดไปนิดเดียว ได้รางวัลปลอบใจเป็นขนมหนึ่งห่อ')}}
 else{const c=Math.round(Math.min(S.money*.05,5000*W));S.money-=c;S.karma+=8;S.fame+=Math.round(15*({m:1,x:3,g:10}[ECO_W()]));log(`🙏 บริจาคงานบุญ ${fmtM(c)} ตำลึง — กรรมดี +8`,'good')}
 sfx('good');render();openTown('fest')}
function twTick(){if(!S||!S.alive||!S.tw)return;const T=S.tw;if(T.w&&T.w!==ECO_W()){S.money+=T.bank;T.bank=0}const ri=Math.max(0,realmIdx()),cap=Math.round(2e5*W15()*(1+ri));if(T.bank>0)T.bank=Math.round(T.bank+Math.min(T.bank*.02,cap*.02));if(T.gov)S.money+=twGovInc(T.gov)}

