function paElig(L){if(!L||!L.w)return'';const w=ECO_W(),ri=Math.max(0,realmIdx());if(L.w!==w)return'ชิ้นนี้สำหรับคนใน'+PA_WN[L.w];if(L.nb&&ri>2)return'ชิ้นมือใหม่ สำหรับคนที่ยังอยู่ขั้นต้น';if(!L.nb&&L.r<=1&&ri>=5)return'ของระดับต่ำ เก็บไว้ให้มือใหม่';return''}
function paLTag(L){if(!L||!L.w)return'';return`<span class="paWt ${L.nb?'nb':''}">${L.nb?'🌱 มือใหม่':PA_WI[L.w]+' '+PA_WN[L.w]}</span>`}
{const _pr=paRender;paRender=function(j){const r=_pr.apply(this,arguments);try{if($('modal').dataset.k!=='pauc')return r;const c=j&&j.cur;if(!c||c.phase!=='open')return r;const L=c.lots[c.li],why=paElig(L);const nbW=!(j.bid&&j.bid.hi)&&c.nb>0;if(nbW)PA.end=Math.min(c.end||c.nb,c.nb);
 const lot=$('paLot');if(lot&&!lot.querySelector('.paWt')){const nm=lot.querySelector('.nm');if(nm)nm.insertAdjacentHTML('beforebegin',paLTag(L))}
 let ew=$('paEl');if(!ew){const m=$('paMsg');if(m){m.insertAdjacentHTML('beforebegin','<div id="paEl" class="tag2" style="margin-top:4px"></div>');ew=$('paEl')}}
 if(ew)ew.innerHTML=(why?`🚫 <b>${why}</b> ดูและแชทได้ แต่เสนอราคาไม่ได้`:(L.w?`✅ คุณประมูลชิ้นนี้ได้`:''))+(nbW?'<br>⏩ ไม่มีใครเสนอราคา ราคาจะลดลงทุก 5 วิ (ต่ำสุด 40%) จนครบ 30 วิแล้วข้ามไปชิ้นถัดไป':'');
 document.querySelectorAll('#modal .paB button').forEach(b=>{if(/paBid/.test(b.getAttribute('onclick')||''))b.disabled=!!why});const inp=$('paIn');if(inp)inp.disabled=!!why;
 const up=$('paUp');if(up){let k=0;c.lots.forEach((x,i)=>{if(x.sold||i===c.li)return;const el=up.children[k++];if(el&&!el.querySelector('.paWt'))el.insertAdjacentHTML('afterbegin',paLTag(x)+'<br>')})}}catch(e){console.error(e)}return r}}
