function realmTxt(){try{const B=S.beastMode;if(B&&!B.human){const L=B.sp==='มังกร'?BL_STD:BL_ST;return `${B.sp||'สัตว์อสูร'} · ${(L&&L[B.st])||('ขั้น '+((B.st|0)+1))}`}const L=realmLabel();return L.base+(L.sub?' · '+L.sub:'')}catch(e){return REALMS[realmIdx()].n}}
function worldTxt(){return S.xt?'✨ แดนเทพ':S.xian?'☁️ โลกเซียน':'⚔️ ยุทธภพ'}
function birthInfo(){const B=S.beastMode,o=S.odds>0?1/S.odds:0;let fi=0;try{fi=S.rareF!=null?S.rareF:fateOf(o)}catch(e){}
 const g=S.goal&&typeof goalOf==='function'?goalOf(S.goal):null;
 return{fam:S.family?S.family.n:'',famD:String((S.family&&S.family.d)||'').replace(/<[^>]+>/g,'').slice(0,90),tal:S.talent?S.talent.n:'',talM:S.talent?+S.talent.m||0:0,g:S.gender||'',
  odds:S.custom?'✍️ ลิขิตเอง':S.rareN?(S.rareN>1.5?'1 ใน '+fmt(Math.round(S.rareN)):'ธรรมดา'):(o?'1 ใน '+fmt(Math.round(o)):''),oc:fi,cu:S.custom?1:0,
  traits:(S.traits||[]).map(trOf).filter(Boolean).map(t=>(t.bad?'⚠️ ':'')+t.n).slice(0,10),
  ow:S.ow&&S.world?('🌌 วิญญาณจาก'+S.world.n+(S.soul?' — '+S.soul.n:'')):'',
  mode:S.ch==='short'?'⏳ ชีวิตสั้น':B?'🐾 สัตว์อสูร':S.xt?'✨ แดนเทพ':S.xian?'☁️ โลกเซียน':'⚔️ ยุทธภพ',
  beast:B?{sp:String(B.sp||''),bl:(BBLOOD[B.bl]||{}).n||'',el:String(B.el||''),hab:String(B.hab||'')}:null,
  goal:g?{n:g.n,d:String(typeof g.d==='function'?g.d():g.d||'').replace(/<[^>]+>/g,'').slice(0,90),done:S.goalDone?1:0,p:String(S.goalDone?'สำเร็จแล้ว':(g.p?g.p():'')).replace(/<[^>]+>/g,'').slice(0,60)}:null,
  gen:S.gen||1,par:(S.heirParents||[]).map(p=>(p.role||'')+' '+p.n).slice(0,3),sys:S.sys?{n:sysName(),since:S.sys.since}:null}}
function histInfo(){return{key:(S.key||[]).map(k=>String(k).replace(/<[^>]+>/g,'')).slice(-30),ach:(S.achLife||[]).map(id=>ACH_ALL.find(a=>a.id===id)).filter(Boolean).slice(-20).map(a=>[a.n,a.r]),lin:(S.lineage||[]).slice(-6).map(p=>p.n+(p.e?'「'+p.e+'」':''))}}
function relInfo(){const kids=(S.children||[]).filter(c=>c.alive!==false);const R=[];
 if(S.spouse)R.push('💍 คู่ชีวิต: '+(S.sp?S.sp.n+' (ความรัก '+Math.round(S.sp.aff||0)+')':S.spouse));
 if(S.harem&&S.harem.length)R.push('🏯 ตำหนักใน '+S.harem.length+' คน: '+S.harem.slice(0,6).map(g=>g.n).join(', ')+(S.harem.length>6?' …':''));
 if(kids.length||S.kids)R.push('👶 บุตร '+Math.max(kids.length,S.kids||0)+' คน'+(kids.length?': '+kids.slice(0,6).map(c=>c.n).join(', '):''));
 if(S.grand)R.push('👪 หลาน '+S.grand+' คน');
 if(S.arc&&S.arc.master&&S.arc.master.n)R.push('🧓 อาจารย์: '+S.arc.master.n+(S.arc.master.alive===false?' (ล่วงลับ)':''));
 if(S.disc&&S.disc.n)R.push('🧑‍🎓 ศิษย์: '+S.disc.n);
 if(S.beast)R.push('🐾 สัตว์คู่ใจ: '+S.beast.nick+' Lv.'+S.beast.lv);
 if(S.nem)R.push('😈 คู่แค้น: '+S.nem.n+(S.nem.peace?' (คืนดีแล้ว)':S.nem.alive?' · ชนะ '+S.nem.w+' แพ้ '+S.nem.l:' (ปิดฉากแล้ว)'));
 if(S.arc&&S.arc.rival!=null&&peers[S.arc.rival])R.push('⚔️ คู่ปรับ: '+peers[S.arc.rival].name);
 if(S.allies&&S.allies.length)R.push('🤝 พันธมิตร '+S.allies.length+' คน');
 return R}
function orgInfo(){const R=[];
 if(S.faction)R.push('🏯 '+S.faction.n+' · '+rankName());else R.push('🚶 จอมยุทธ์พเนจร');
 if(S.ownSect)R.push('🏯 เจ้าสำนัก '+S.ownSect.n+' · ศิษย์ '+(S.ownSect.dis||0));
 try{if(S.est&&(S.est.lv||S.est.prop))R.push('🏞️ '+estLandN(S.est.lv)+' · '+estPrN(S.est.pr||0))}catch(e){}
 if(S.sys)R.push('🟦 '+sysName()+' Lv.'+S.sys.lv);
 try{if(S.tw&&S.tw.gov)R.push('🏛️ ยศ '+GOV_T[S.tw.gov-1])}catch(e){}
 return R}
