{const _ls=liveSnap;liveSnap=function(){const o=_ls.apply(this,arguments);try{Object.assign(o,{rl:realmTxt(),wd:worldTxt(),birth:birthInfo(),hist:histInfo(),rel:relInfo(),org:orgInfo(),q2:questList().filter(q=>Q_REAL(q.k)).map(q=>q.ic+' '+q.n+' — '+String(q.p).replace(/<[^>]+>/g,'')).slice(0,12),r:realmTxt()})}catch(e){console.error(e)}return o}}
