{const L=[{id:'ai_fuse',n:'มนุษย์จักรกล',d:'หลอมรวมจิตกับ AI',r:4,c:()=>!!(S.ai&&S.ai.end==='fuse')},{id:'ai_free',n:'เพื่อนที่ไม่ใช่มนุษย์',d:'ปล่อย AI ให้เป็นอิสระ แล้วมันเลือกอยู่ข้างคุณ',r:4,c:()=>!!(S.ai&&S.ai.end==='free')},
 {id:'ai_upload',n:'มรดกดิจิทัล',d:'อัปโหลดจิต AI ลงชิปเพื่อส่งต่อทายาท',r:4,c:()=>!!(S.ai&&(S.ai.end==='upload'||S.ai.src==='inherit'))},{id:'ai_gene',n:'เขียนชะตาใหม่',d:'ให้ AI ปรับพันธุกรรมสำเร็จ',r:5,c:()=>!!(S.ai&&S.ai.gene)},
 {id:'ai_bond',n:'ใจถึงใจ',d:'ความผูกพันกับ AI เต็ม 100',r:3,c:()=>!!(S.ai&&S.ai.bond>=100&&S.ai.end!=='fuse')}];
 const G=ACH.find(x=>x[0]==='🤖 AI ฝังตัว');if(G)G[1].push(...L);ACH_ALL.push(...L)}


