function bhWatch(rid){clearInterval(BH.poll);BH.poll=setInterval(async()=>{if(!BH.st||BH.st.rid!==rid){clearInterval(BH.poll);return}try{const j=await api('bhst',{rid});if(!j||!j.ok){if(j&&j.gone){clearInterval(BH.poll);BH.st=null;if($('modal').dataset.k==='bh')closeM()}return}if(j.st.res){clearInterval(BH.poll);bhApply(j.st);return}BH.st=j.st;BH.off=j.st.now-Date.now();if($('modal').dataset.k==='bh')bhShow(j.st,1)}catch(e){}},1500)}
