setInterval(()=>{if(BH.st&&$('modal').dataset.k==='bh'&&modalOpen)bhShow(BH.st,1)},1000);
function bhApply(st){const R=st.res;if(!R||BH.done[st.rid])return;BH.done[st.rid]=1;clearInterval(BH.poll);BH.st=null;if($('modal').dataset.k==='bh')closeM();if(!S||!S.alive)return;
 const B=st.B,hn=st.H.map(h=>h.n),C={fight:'⚔️ สู้',flee:'🏃 หนี',hide:'🌿 ซ่อน',yield:'🎁 สละเกล็ด',accept:'🤝 ยอมสัญญา',tame:'🤝 ปราบสหาย',hunt:'🏹 ไล่ล่า',trap:'🪤 กับดัก',coop:'🤝 ร่วมมือ',steal:'🗡️ แย่งชิง'};
 const sum=`สรุป: ${esc(B.n)} เลือก ${C[R.cb]} · ${hn.map((n,i)=>esc(n)+' '+C[R.hc[i]]+(hn.length>1?' '+C[R.hj[i]]:'')).join(' · ')}`;
 if(st.role==='b'){
  if(R.k==='h'){const tk=hn[R.taker]||'นักล่า',dp=Math.round(S.power*.15),dq=+(S.qi*.15).toFixed(1);S.power=Math.max(1,S.power-dp);S.qi=Math.max(0,+(S.qi-dq).toFixed(1));S.hp=Math.max(1,Math.round(S.hp-S.maxHp*.4));S.bhFoe=tk;S.bhLost=(S.bhLost||0)+1;
   log(`💔 ผู้เล่น <b>${esc(tk)}</b> ล้วงแก่นอสูรคุณไป! พลังยุทธ์ −${fmt(dp)}${dq>0?' · ลมปราณ −'+dq+' ปี':''} · บาดเจ็บสาหัส · (ไปตามล่าคืนได้ในเหตุการณ์ป่า)`,'bad',true);keyAdd(`ถูกผู้เล่น ${tk} ล้วงแก่นอสูร`)}
  else if(R.k==='b'){const g=pctPow(.04);S.power+=g;S.fame+=40;S.bhWin=(S.bhWin||0)+1;log(`🐉 คุณขย้ำนักล่า${hn.length>1?'ทั้งสองคน':''} (${hn.map(esc).join(', ')}) จนแตกพ่าย! พลังยุทธ์ +${fmt(g)} · ชื่อเสียง +40`,'myth',true);keyAdd('ชนะนักล่าผู้เล่นจริง')}
  else if(R.k==='esc'){S.int+=3;S.fame+=10;log(`🏃 หนีพ้นนักล่าผู้เล่นจริงเข้าป่าลึกได้ ปัญญา +3`,'good',true)}
  else{S.int+=2;log('🌿 ซ่อนตัวแนบเนียนจนนักล่าหาไม่เจอ ปัญญา +2','good',true)}}
 else{const me=+st.role.slice(1);
  if(R.betray){if(R.betray.l===me){S.hp=Math.max(1,Math.round(S.hp-S.maxHp*.25));log(`🗡️ ถูก <b>${esc(hn[R.betray.w])}</b> ลอบแทงข้างหลังระหว่างล่า พลังชีวิต −25% · หลุดจากการล่า`,'bad',true);log('📜 '+sum,'');return}
   else log(`🗡️ คุณจัดการ <b>${esc(hn[R.betray.l])}</b> ได้ก่อน เหลือล่าคนเดียว`,'epic')}
  if(R.k==='h'){if(R.taker===me){const n=1+(B.st|0);const got=bagAdd('core',n,true)||0;const g=pctPow(.05);S.power+=g;S.fame+=50;S.bhCore=(S.bhCore||0)+1;log(`🏹 ล้วง<b>แก่นอสูรของ ${esc(B.n)}</b> (${esc(B.sp||'สัตว์อสูร')} · ผู้เล่นจริง) ได้สำเร็จ! แก่นอสูร ×${got} · พลังยุทธ์ +${fmt(g)} · ชื่อเสียง +50`,'myth',true);keyAdd(`ล้วงแก่นอสูรของผู้เล่น ${B.n}`)}
   else{bagAdd('food',3,true);S.hp=Math.min(S.maxHp,S.hp+Math.round(S.maxHp*.3));const g=pctPow(.015);S.power+=g;log(`🍖 ${esc(hn[R.taker])}ได้แก่นไป คุณได้เนื้อของ${esc(B.n)}มาแทน — พลังยุทธ์ +${fmt(g)} · เสบียง +3`,'good',true)}}
  else if(R.k==='b'){S.hp=Math.max(1,Math.round(S.hp-S.maxHp*.3));log(`🐉 ${esc(B.n)} (ผู้เล่นจริง) สู้กลับจนคุณพ่ายแพ้ พลังชีวิต −30%`,'bad',true)}
  else log(`🐾 ${esc(B.n)} ${R.k==='esc'?'หนีเข้าป่าลึกไปได้':'ซ่อนตัวจนหาไม่เจอ'} การล่าครั้งนี้คว้าน้ำเหลว`,'')}
 log('📜 '+sum,'');try{render();checkDeath()}catch(e){}}
