// ===================== v15.7 สีฉายาตามความยาก + อนิเมชั่น =====================
const TTL_SPR={imm:6,trash:6,ow:6,bossX:5,regress:5,asc:5,crip:5,orphan:5,sect:5,kills300:5,rich:5,saint:5,fiend:5,kids:5,harem:5,bossM:4,ndsys:4,revive:4,slowmax:4};
const TTL_MB={power:0,qi:.5,int:.5,cha:.5,fame:.5,good:.5,evil:.5,money:.6,kills:.6,love:.6,elder:1,hermit:1};
const TTL_XC=(()=>{const s=new Set();Object.values(TTL_CORE.x).forEach(L=>L.forEach(c=>s.add(c)));return s})();
const TTL_VALID=(()=>{const st=new Set();['m','x'].forEach(w=>Object.values(TTL_CORE[w]).forEach(L=>L.forEach(c=>Object.values(TTL_MOD).forEach(M=>M.forEach(m=>st.add(c+m))))));TTL_SP.forEach(x=>st.add(x[2]));return st})();
function ttlRar(t){t=String(t||'');const sp=TTL_SP.find(x=>x[2]===t);if(sp)return TTL_SPR[sp[0]]!=null?TTL_SPR[sp[0]]:4;
 let best='';for(const c in TTL_PATHOF)if(t.startsWith(c)&&c.length>best.length)best=c;if(!best)return 0;const P=TTL_PATHOF[best],mk=TTL_MODOF[t.slice(best.length)];
 const xb=TTL_XC.has(best)&&!Object.values(TTL_CORE.m).some(L=>L.includes(best))?1:0;return Math.max(0,Math.min(5,Math.floor(P.i+xb+(TTL_MB[mk]||0))))}
ttlTierOf=function(t){return ttlRar(t)};
