{const _qk=qKeys;qKeys=function(){if(!bsB())return _qk.apply(this,arguments);const s=S.sys,L=BSQ[s.t]||['bq_pow','bq_hunt','bq_qi'];return[...new Set(L.concat(['bq_pow','bq_qi']))].filter(k=>(!QOK[k]||QOK[k]())&&!s.quests.some(q=>q.k===k))}}
