// เวลาในเกมเดินเร็ว: ขยายเส้นตายทุกเควสระบบ ×1.8 (อย่างน้อย +2 ปี)
{const _mq2=mkQuest;mkQuest=function(k){const q=_mq2.apply(this,arguments);try{if(q&&typeof q.g==='number'&&q.g>3&&!/^bq_/.test(k)){const ng=Math.max(2,Math.round(q.g*.7)),o=fmt(q.g);if(q.n.indexOf(o)>=0){q.n=q.n.replace(o,fmt(ng));q.g=ng}}}catch(e){}try{if(q&&q.dl!=null){const y=Math.max(1,q.dl-S.age);q.dl=S.age+Math.max(y+2,Math.ceil(y*1.8))}}catch(e){}return q}}
// สัตว์อสูร: ล่าเหยื่อ/ท่องป่า/ชื่อเสียง นับจากทิศทางที่เลือกด้วย
{const _byq=beastYear;beastYear=function(){const f=S&&S.focus;const r=_byq.apply(this,arguments);try{if(S&&S.alive&&bsB()){
 if(f==='hunt'||Math.random()<.15)S.bKill=(S.bKill||0)+1;
 if(f==='roam'){S.bSeen=(S.bSeen||0)+1+(Math.random()<.3?1:0);S.fame+=1+bqSt()}
 if(f==='hide'&&Math.random()<.3)S.bSeen=(S.bSeen||0)+1}}catch(e){}return r}}

// ===================== v15.3 สัตว์อสูรปลายทาง: ขั้นย่อย · ขึ้นสวรรค์ · ศาลเจ้า · อาณาจักร · ศึกปลายเกม =====================
const bmOK=()=>!!(S&&S.alive&&S.beastMode&&!S.beastMode.human);
const bFree=()=>!(choice._cur||modalOpen);
function bLs(a){const m=S.beastMode;S.lifespan+=a;S._lsEx=(S._lsEx||0)+a;if(m)m.lsB=(m.lsB||0)+a}
{const _lm=lifeMax0;lifeMax0=function(){const r=_lm.apply(this,arguments);try{const m=S&&S.beastMode;if(m&&!m.human&&m.lsB)return Math.min(r+m.lsB,S.lifespan+40)}catch(e){}return r}}
function bPct(p){const m=S.beastMode,k=(m.st||0)+'|'+(m.pst||0)+'|'+(m.heaven?'h'+(m.hs||0):'');if(!m._pp||m._pp.k!==k)m._pp={k,a:0};const room=Math.max(0,.3-m._pp.a),full=Math.min(p,room),eff=full+(p-full)*.1*Math.min(1,.6/Math.max(.3,m._pp.a));m._pp.a+=p;return Math.round(total()*eff)}
const bPm=()=>(S.xian?1.4:1)*((S.talent&&S.talent.m)||1);
// ---------- 1) ขั้นย่อยหลังปฐมสัตว์เทพ ชั้น 1–9 ----------
const BPS_N=9,bpsNeed=n=>Math.round(220000*Math.pow(1.45,n)*(S.xian?1.4:1)),bpsQi=n=>200+n*45;
function bpsTry(){const m=S.beastMode,n=(m.pst||0)+1;if(n>BPS_N||m.heaven)return;if(total()<bpsNeed(n)||S.qi<bpsQi(n)||Math.random()>.25)return;
 if((m.pstCd||0)>S.age)return;const w=Math.random()<Math.min(.85,.35+(total()/bpsNeed(n)-1)*.6+Math.min(.15,S.qi/bpsQi(n)*.03));
 if(w){m.pst=n;const add=300+n*120;bLs(add);S.maxHp+=40;S.hp=S.maxHp;S.fame+=80*n;
  log(`⚡ ฝ่าทัณฑ์ฟ้าชั้นที่ ${n} สำเร็จ — <b>${BL_ST[7]} ชั้น ${n}</b> · อายุขัย +${add} ปี${n===BPS_N?' · ฟ้าดินเริ่มเปิดประตูสวรรค์ให้คุณ...':''}`,'myth',true);S.key.push(`${S.age} ปี — ${BL_ST[7]} ชั้น ${n}`);setScene('aura')}
 else{m.pstCd=S.age+R(8,15);S.hp=Math.max(1,Math.round(S.hp*.6));S.power=Math.round(S.power*.98);log(`💢 ทัณฑ์ฟ้าชั้นที่ ${n} ซัดคุณกระเด็น พลังชีวิตลดลง พลัง −2% · ต้องพักฟื้นราว ${m.pstCd-S.age} ปี`,'bad')}}
// ---------- 2) ทัณฑ์ปฐมกาล → ขึ้นสวรรค์เป็นสัตว์เทพประจำทิศ ----------
const BDIR={ไฟ:['ทิศใต้','🐦 หงส์แดง'],โลหิต:['ทิศใต้','🐦 หงส์แดง'],ไม้:['ทิศตะวันออก','🐉 มังกรเขียว'],ลม:['ทิศตะวันออก','🐉 มังกรเขียว'],อัสนี:['ทิศตะวันออก','🐉 มังกรเขียว'],
 โลหะ:['ทิศตะวันตก','🐅 พยัคฆ์ขาว'],แสง:['ทิศตะวันตก','🐅 พยัคฆ์ขาว'],น้ำแข็ง:['ทิศตะวันตก','🐅 พยัคฆ์ขาว'],น้ำ:['ทิศเหนือ','🐢 เต่าดำ'],เงา:['ทิศเหนือ','🐢 เต่าดำ'],พิษ:['ทิศเหนือ','🐢 เต่าดำ'],ดิน:['ศูนย์กลาง','🦄 กิเลนเหลือง']};
