const bhNeed=i=>Math.round(bpsNeed(BPS_N)*Math.pow(2,i+1));
function bAscOffer(){const m=S.beastMode;if(m.heaven||(m.pst||0)<BPS_N||!bFree()||(m.ascCd||0)>S.age)return false;const D=BDIR[m.el]||BDIR['ดิน'];setScene('aura');
 choice('⚡ ทัณฑ์ปฐมกาล',`ฟ้าเปิดออกเป็นวงกว้างนับพันลี้ สายฟ้าเก้าสีม้วนตัวอยู่เหนือหัว นี่คือ<b>ทัณฑ์ปฐมกาล</b> ที่ไม่มีสัตว์ตนใดผ่านมาได้นับหมื่นปี<br>ถ้าผ่าน คุณจะขึ้นสวรรค์เป็น <b>${D[1]} สัตว์เทพประจำ${D[0]}</b><br><span class="tag2">ต้องชนะติดกัน 3 ระลอก · ล้มเหลวจะบาดเจ็บหนักและต้องรออีก 30–50 ปี</span>`,[
  {t:'⚡ รับทัณฑ์',s:'เดิมพันทุกสิ่ง',f(){let ok=true;for(let i=1;i<=3&&ok;i++){ok=Math.random()<.78;log(`⚡ ${['สายฟ้าปฐมกาลระลอกแรก','สายฟ้าปฐมกาลระลอกสอง','สายฟ้าปฐมกาลระลอกสุดท้าย'][i-1]} — ${ok?'ต้านไว้ได้!':'ร่างแตกร้าว...'}`,ok?'epic':'bad')}
   if(ok)bAscend();else{m.ascCd=S.age+R(30,50);S.hp=Math.max(1,Math.round(S.hp*.3));S.power=Math.round(S.power*.88);log('💥 ทัณฑ์ปฐมกาลบดขยี้ร่างคุณจนเกือบสลาย พลัง −12% · ต้องรออีกหลายสิบปีถึงจะลองใหม่ได้','bad',true)}}},
  {t:'🌲 ยังไม่พร้อม',s:'รอสะสมพลังก่อน',skip:true,f(){m.ascCd=S.age+R(10,20);log('คุณก้มหัวให้ฟ้า แล้วถอยกลับเข้าป่า ไว้วันหน้าค่อยรับทัณฑ์')}}]);return true}
function bAscend(){const m=S.beastMode,D=BDIR[m.el]||BDIR['ดิน'];m.heaven=1;m.hs=0;m.hsCd=S.age+R(20,40);m.dir=D[0];m.god=D[1];
 const add=3000;bLs(add);S.maxHp+=300;S.hp=S.maxHp;S.fame+=5000;S.power+=bPct(.3);S.flags.bHeaven=1;
 log(`🌈 <b>ผ่านทัณฑ์ปฐมกาล!</b> ประตูสวรรค์เปิดออก คุณขึ้นสวรรค์เป็น <b>${D[1]} สัตว์เทพประจำ${D[0]}</b> · อายุขัย +${add} ปี · พลัง +30%`,'myth',true);S.key.push(`${S.age} ปี — ขึ้นสวรรค์เป็น${D[1].slice(3)} สัตว์เทพประจำ${D[0]}`);keyAdd('ขึ้นสวรรค์เป็นสัตว์เทพประจำทิศ');setScene('aura')}
