 const sh=m.shr,evil=S.karma<0;const capF=3000*(m.st-3)*(m.heaven?4+(m.hs||0):1);sh.f=Math.max(0,Math.round(sh.f+Math.max(0,capF-sh.f)*(evil?.012:.025)+R(0,6)));
 const fp=Math.round(Math.sqrt(sh.f)*(2+m.st)*bPm());S.power+=fp;if(evil)S.karma-=sh.f>500?1:0;else S.karma+=sh.f>500?1:0;if(Math.random()<.3)S.fame+=Math.round(Math.sqrt(sh.f));
