 const C=[[1.5,L(st.pow,1e8)],[1.2,L(st.fame,1e5)],[bm?0:1,L(st.money,1e9)],[1,L(st.int,5000)],[.8,L(st.cha,5000)],[.8,L(D.kc,50)],[1,L(e.age,bm?20000:10000)],[.7,L(st.kills,2000)],[1.2,L(D.an,20)],[.5,L(Math.abs(+st.karma||0),1000)],[.6,Math.min(1,Math.max(0,(+st.joy||0)/100))]];
