function goalInfo(){if(!S||!S.alive)return null;const P=(ic,l,c,n,h)=>({ic,l,c:+c||0,n:+n||0,h});
 const m=S.beastMode;
 if(m&&!m.human){
  if(m.st<4){const nd=[[3,0,0],[12,6,0],[0,20,450],[0,45,1500]][m.st];const L=[];if(nd[0])L.push(P('⏳','อายุ',S.age,nd[0],''));if(nd[1])L.push(P('🌀','ลมปราณ',S.qi,nd[1],'🌕 ดูดซับแสงจันทร์'));if(nd[2])L.push(P('⚔️','พลังรวม',total(),nd[2],'🍖 ล่าเหยื่อ'));return{t:`สู่ ${BL_ST[m.st+1]}`,L}}
  if(m.st<7){if(!(m.king||m.pdone))return{t:`สู่ ${BL_ST[m.st+1]}`,note:'ต้องเลือก 👑 ครองป่าเป็นราชาอสูร หรือเดินเส้นทางอสูรให้จบก่อน ถึงจะเลื่อนขั้นต่อได้',L:[]};
   const u=BL_UP[m.st-4];return{t:`สู่ ${BL_ST[m.st+1]}`,L:[P('⏳','อายุ',S.age,u[0],''),P('🌀','ลมปราณ',S.qi,u[1],'🌕 ดูดซับแสงจันทร์'),P('⚔️','พลังรวม',total(),u[2],'🍖 ล่าเหยื่อ')]}}
  if(!m.heaven){const n=(m.pst||0)+1;if(n<=BPS_N)return{t:`ฝ่าทัณฑ์ฟ้าชั้นที่ ${n}`,note:(m.pstCd||0)>S.age?`กำลังพักฟื้นอีก ${m.pstCd-S.age} ปี`:'ค่าครบแล้วจะลุ้นฝ่าทัณฑ์ทุกปี (ยิ่งพลังเกินเกณฑ์ยิ่งผ่านง่าย)',L:[P('🌀','ลมปราณ',S.qi,bpsQi(n),'🌕 ดูดซับแสงจันทร์'),P('⚔️','พลังรวม',total(),bpsNeed(n),'🍖 ล่าเหยื่อ')]};
   return{t:'ทัณฑ์ปฐมกาล → ขึ้นสวรรค์',note:(m.ascCd||0)>S.age?`รออีก ${m.ascCd-S.age} ปี ถึงจะรับทัณฑ์ได้อีกครั้ง`:'ฟ้าจะเปิดให้รับทัณฑ์เร็วๆ นี้ ต้องรอด 3 ระลอก',L:[]}}
  const i=(m.hs||0)+1;if(i<BH_ST.length)return{t:`สู่ ${BH_ST[i]}`,note:(m.hsCd||0)>S.age?`สวรรค์จะทดสอบอีกครั้งในอีก ${m.hsCd-S.age} ปี`:'',L:[P('⚔️','พลังรวม',total(),bhNeed(i),'🍖 ล่าเหยื่อ · ⛩️ ศาลเจ้า')]};
  return{t:'ถึงจุดสูงสุดแล้ว',note:'คุณคือบรรพสัตว์ฟ้าดิน ขยายเผ่า ศาลเจ้า และสืบสายเลือดต่อได้',L:[]}}
 const ri=realmIdx(),raw=typeof rawRealm==='function'?rawRealm():ri;
 if(raw>ri)return{t:`สู่ ${REALMS[ri+1]?REALMS[ri+1].n:'ขั้นถัดไป'}`,note:S.age<16?'⚡ พลังถึงแล้ว แต่ยังเด็กเกินไป ต้องรอโตก่อนถึงจะทะลวงขั้นได้':'⚡ พลังถึงแล้ว รอโอกาสทะลวง/ฝ่าทัณฑ์สวรรค์ (เกิดขึ้นเองในไม่ช้า)',L:[]};
 if(ri<REALMS.length-1)return{t:`สู่ ${REALMS[ri+1].n}`,L:[P('⚔️','พลังรวม',total(),REALMS[ri+1].p,S.age<6?'ฝึกตอนเด็ก':'🗡️ ฝึกยุทธ์ · 🌀 ลมปราณ')]};
 const L0=typeof postLv==='function'?postLv():-1;if(L0>=0&&L0<RS_MAX){const pr=postRaw();if(pr>L0)return{t:`สู่ขั้น ${L0+2} หลังขั้นสูงสุด`,note:'⚡ พลังถึงแล้ว รอฝ่าทัณฑ์สวรรค์',L:[]};return{t:`สู่ขั้น ${L0+2} หลังขั้นสูงสุด`,L:[P('⚔️','พลังรวม',total(),postP(L0+1),'🗡️ ฝึกยุทธ์')]}}
 if(!S.xian)return{t:'เหาะสู่โลกเทพเซียน',note:'ถึงขั้นสูงสุดของยุทธภพแล้ว รอโอกาสเหาะขึ้นโลกเซียน',L:[]};
 return{t:'ฝึกต่อไป',note:'ถึงขั้นสูงสุดแล้ว ล่าความสำเร็จ ฉายา และทำเนียบ',L:[]}}
