function adviceList(){const A=[],en=LANG==='en';if(!S||!S.alive)return A;const g=goalInfo();
 if(g){const miss=g.L.filter(x=>x.c<x.n);if(miss.length)miss.forEach(x=>A.push(`🎯 ${esc(g.t)}: ${x.l}ยังขาดอีก <b>${fmt(Math.ceil(x.n-x.c))}</b>${x.h?` → ลอง <b>${x.h}</b>`:''}`));else if(g.note)A.push(`🎯 ${esc(g.t)}: ${g.note}`)}
 if(S.hp<S.maxHp*.35)A.push(`❤️ พลังชีวิตเหลือน้อย (${fmtH(S.hp)}/${fmtH(S.maxHp)}) → ${S.beastMode&&!S.beastMode.human?'🌿 ซ่อนตัวพักฟื้น':'🍵 พักผ่อน หรือกินยา'}`);
 if(S.sys&&S.sys.quests&&S.sys.quests.length){S.sys.quests.forEach(q=>{const left=q.dl-S.age;if(left<=3)A.push(`🟦 เควสระบบ "<b>${esc(q.n)}</b>" เหลือ ${Math.max(0,left)} ปี (${fmt(Math.floor(qProg(q)))}/${fmt(q.g)})${QHINT[q.k]?` → ทิศทางแนะนำ <b>${(([...(S.beastMode&&!S.beastMode.human?BFOCUS:FOCUS)].find(f=>f[0]===QHINT[q.k])||[])[2])||QHINT[q.k]}</b>`:''}`)})}
 if((S.happy==null?60:S.happy)<25)A.push('😞 ความสุขต่ำ → พักผ่อน อยู่กับครอบครัว หรือไปเทศกาลเมือง');
 if(!S.beastMode&&S.age>=18&&!S.spouse&&!S.sp)A.push('💕 ยังไม่มีคู่ครอง → เลือก 🌸 ครอบครัว หรือคุยกับคนรู้จักในหน้าผู้คน');
 if(S.beastMode&&!S.beastMode.human&&S.age>=4&&!(blM().mate&&blM().mate.alive))A.push('💞 ยังไม่มีคู่ → 🗺️ ท่องป่าบ่อยๆ จะได้เจอคู่ · มีลูกไว้สืบสายเลือดตอนตาย');
 if(S.bag&&S.bag.it){const n=Object.values(S.bag.it).reduce((a,b)=>a+b,0);if(n>=8)A.push(`🎒 มีของในกระเป๋า ${n} ชิ้น → เปิดดูว่ามีของใช้ได้ไหม`)}
 const lm=typeof lifeMax==='function'?lifeMax():S.lifespan;if(lm-S.age<=10&&lm-S.age>=0)A.push(`⏳ อายุขัยเหลือราว ${Math.round(lm-S.age)} ปี → เตรียมทายาท หรือหายาอายุวัฒนะ`);
 if(!A.length)A.push('✨ ตอนนี้ไม่มีอะไรเร่งด่วน เลือกทิศทางตามเป้าหมาย แล้วปล่อยให้ชีวิตดำเนินไป');return A.slice(0,8)}
function openAdvice(){if(!S||!S.alive)return toast('ต้องอยู่ระหว่างเล่นชีวิตก่อน');modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>💡 ทำอะไรดี?</h3>${adviceList().map(x=>`<div class="adv1">${x}</div>`).join('')}<p class="tag2" style="margin-top:8px">แตะกล่อง 🎯 ด้านบนปุ่มทิศทางเพื่อย่อ/ขยาย · อ่านทุกระบบได้ที่ 📘 คู่มือ</p><button class="gbtn" style="width:100%" onclick="openGuide()">📘 เปิดคู่มือ</button>`,'advice')}
