function mqEnd(k,beast){const W=typeof W15==='function'?W15():1;const O={
 fight:()=>{const w=fight('ผู้เฝ้า',total()*(.85+Math.random()*.4));if(w){const g=pctPow(.05);S.power+=g;S.fame+=fameR(12);beast?0:bagLoot(2);return[`⚔️ ชนะ! พลัง +${fmt(g)}`,'epic']}S.hp=Math.max(1,Math.round(S.hp-S.maxHp*.3));return['💥 พ่ายแพ้ บาดเจ็บหนัก','bad']},
 sneak:()=>{if(roll01(.5)){if(beast){S.qi=+(S.qi+R(2,5)).toFixed(1);return['🤫 สำเร็จ! ลมปราณเพิ่ม','good']}S.money+=Math.round(R(200,900)*W);S.karma-=3;return['🦊 สำเร็จ! ได้ของมีค่า · กรรม −3','good']}S.hp=Math.max(1,Math.round(S.hp-S.maxHp*.2));return['😖 ถูกจับได้ ต้องหนีสุดชีวิต','bad']},
 calm:()=>{S.qi=+(S.qi+1).toFixed(1);joy(3);return['🍃 ปลอดภัย ได้ลมปราณเล็กน้อย','good']},
 greed:()=>{if(Math.random()<.4){S.money+=Math.round(R(1000,3000)*W);return['💰 กวาดได้หมดเกลี้ยง!','epic']}S.hp=Math.max(1,Math.round(S.hp-S.maxHp*.4));return['💥 กับดักทำงาน บาดเจ็บสาหัส','bad']},
 smart:()=>{S.int+=R(5,12);if(roll01(.55)){const g=pctPow(.03);S.power+=g;return[`🧠 สำเร็จอย่างแนบเนียน ปัญญาเพิ่ม · พลัง +${fmt(g)}`,'epic']}return['🧠 ได้ความรู้ แต่ไม่ได้ของ','good']},
 pill:()=>{if(Math.random()<.7){const g=pctPow(.04);S.power+=g;return[`💊 ยาวิเศษจริง! พลัง +${fmt(g)}`,'epic']}S.hp=Math.max(1,Math.round(S.hp*.7));return['🤢 ยาปลอม ท้องเสียไปสามวัน','bad']},
 sell:()=>{S.money+=Math.round(R(400,1200)*W);return['💰 ขายต่อได้กำไรงาม','good']},
 good:()=>{S.karma+=8;S.fame+=fameR(10);futAdd('kind','เรื่องที่คุณช่วยไว้');return['☯️ ทำสิ่งที่ถูกต้อง · กรรมดี +8','good']},
 dark:()=>{S.karma-=8;const g=pctPow(.04);S.power+=g;futAdd('foe','เรื่องที่คุณทำไว้');return[`🩸 ได้พลังมืด +${fmt(g)} · กรรม −8`,'epic']},
 love:()=>{joy(10);S.cha+=5;if(!S.spouse&&!S.beastMode){try{const nm=anyName(S.gender==='ชาย'?'หญิง':'ชาย');S.spouse=nm;S.sp=mkLover(nm,'บุตรีขุนนาง',{wed:true,aff:70});return[`💕 แต่งงานกับ ${nm} บุตรีขุนนาง`,'epic']}catch(e){}}return['💕 ได้ความรักและความสุข','good']}};
 const r=(O[k]||O.calm)();log(r[0],r[1])}
function mqRun(q,beast,step,br){try{if(step===0){const [d,o]=q.s[0];choice(q.t,d,o.map(([t,b])=>({t,f(){setTimeout(()=>mqRun(q,beast,1,b),350)}})));return}
 const [d,o]=q.s[1][br];choice(q.t,d,o.map(([t,k])=>({t,f(){mqEnd(k,beast)}})))}catch(e){console.error(e)}}
function mqTick(){if(!S||!S.alive||choice._cur||modalOpen||S.age<14)return;const beast=S.beastMode&&!S.beastMode.human;if(Math.random()>(beast?.05:.04))return;
 S.mqL=S.mqL||{};const P=(beast?MQ_B:MQ_H).filter(q=>S.age-(S.mqL[q.t]??-99)>=25);if(!P.length)return;const q=ch(P);S.mqL[q.t]=S.age;mqRun(q,beast,0)}
