{const _omS=openMenu;openMenu=function(){const r=_omS.apply(this,arguments);try{const m=$('modal'),gs=[...m.querySelectorAll('.mcat15 .mgrid')],g=gs[gs.length-1]||m.querySelector('.mgrid');if(g&&!g.querySelector('[data-csum]'))g.insertAdjacentHTML('afterbegin',`<button class="opt" data-csum="1" onclick="toggleChSum()">📜 สรุปก่อนตัวเลือก<small>${CS_ON()?'เปิดอยู่':'ปิดอยู่'}</small></button>`)}catch(e){}return r}}
