const PL_FIX=['ฟ้าผ่าลงตรงหน้าคุณโดยไม่มีเมฆ เหมือนโลกกำลังเตือน','คนแปลกหน้าพูดประโยคเดียวกับในนิยายเป๊ะ ทั้งที่คุณเปลี่ยนเรื่องไปแล้ว','ของที่คุณแย่งมาจากตัวเอกหายไปเองตอนกลางคืน','คุณลืมเนื้อเรื่องบางตอนไปเฉยๆ ราวกับมีคนลบความจำ','ตัวเอกได้โอกาสใหม่มาแทนที่ทันที แข็งแกร่งกว่าเดิม','คุณป่วยหนักกะทันหันในวันที่ควรจะเป็นวันสำคัญของตัวเอก','ทุกคนในเมืองมองคุณเหมือน "ตัวประกอบ" เป็นเวลาหนึ่งเดือน','ฝันเห็นตัวอักษรนิยายลอยรอบตัว มีบรรทัดหนึ่งเขียนชื่อคุณแล้วถูกขีดฆ่า'];
function plNew(){const T=tmFix(),P=T.plot;if(!P.prot)P.prot={n:anyName(Math.random()<.5?'ชาย':'หญิง'),alive:1,rel:0,luck:1};while(P.notes.length<3){const k=ch(PL_K),p={pl:ch(PL_PLACE),it:ch(PL_ITEM)};P.notes.push({k:k[0],kn:k[1],txt:k[2](p),pl:p.pl,it:p.it,y:S.age+R(2,14),done:0})}}
function plTick(){const T=tmFix(),P=T.plot;if(!P.on)return;if(!P.prot&&S.age>=10){plNew();log(`📖 ความทรงจำบางอย่างผุดขึ้น… <b>คุณเคยอ่านนิยายเรื่องนี้!</b> ตัวเอกชื่อ <b>${esc(P.prot.n)}</b> และคุณจำเหตุการณ์ข้างหน้าได้บางส่วน ดูได้ที่ ☰ → 🌌 ผู้ข้ามมิติ`,'myth',true);return}
 if(!P.prot)return;if(P.notes.length<3)plNew();const n=P.notes.find(x=>!x.done&&S.age>=x.y);
 if(n&&!choice._cur&&!modalOpen){n.done=1;P.notes=P.notes.filter(x=>!x.done);const pr=P.prot;
  choice(`📖 ${n.kn} — ตามบทนิยาย`,`${n.txt}<br><span class="tag2">ตัวเอก: ${esc(pr.n)}${pr.alive?'':' (ตายไปแล้ว)'} · ความสัมพันธ์ ${pr.rel}</span>`,[
   {t:'🏃 ชิงตัดหน้าตัวเอก',s:'ได้ของดี แต่บทจะเพี้ยน',f(){const g=pctPow(.06);S.power+=g;S.fame+=fameR(15);P.fix+=2;P.chg++;pr.luck=Math.max(.3,pr.luck-.15);pr.rel-=10;log(`🏃 คุณไปถึง${esc(n.pl)}ก่อนตัวเอก! ได้<b>${esc(n.it)}</b> — พลัง +${fmt(g)} · บทนิยายเพี้ยนไป`,'myth')}},
   {t:'🤝 ช่วยตัวเอกให้สำเร็จ',s:'เป็นเพื่อนตัวเอก',f(){pr.rel+=15;pr.luck+=.1;S.karma+=4;S.int+=3;log(`🤝 คุณแอบช่วยให้ ${esc(pr.n)} ได้สิ่งที่ควรได้ เขาจดจำบุญคุณนี้`,'good')}},
   {t:'🗡️ ขัดขวางตัวเอก',s:'บทเพี้ยนหนัก',f(){P.fix+=3;P.chg++;pr.rel-=25;pr.luck=Math.max(.2,pr.luck-.25);S.karma-=5;log(`🗡️ คุณทำให้ ${esc(pr.n)} พลาดโอกาสนี้ไป… โลกดูเหมือนจะไม่พอใจ`,'bad')}},
   {t:'👀 ปล่อยไปตามบท',skip:true,f(){S.int+=1;log('👀 ทุกอย่างเกิดขึ้นตามนิยายเป๊ะ คุณยืนดูอยู่ห่างๆ')}}]);return}
 if(P.fix>=6&&Math.random()<.15&&!choice._cur){P.fix-=4;S.hp=Math.max(1,Math.round(S.hp-S.maxHp*.15));log(`🌀 <b>แรงแก้บท</b>: ${ch(PL_FIX)}`,'bad')}
 if(P.prot.alive&&P.prot.rel>=40&&Math.random()<.05){const g=pctPow(.02);S.power+=g;log(`🤝 ${esc(P.prot.n)} ตัวเอกแห่งนิยาย ส่งของมาให้เพื่อนเก่า พลัง +${fmt(g)}`,'good')}
 if(P.prot.alive&&P.prot.rel<=-40&&Math.random()<.06&&!choice._cur){choice('⚔️ ตัวเอกมาเยือน',`${esc(P.prot.n)} ตัวเอกของนิยายจำได้ว่าคุณขัดขวางเขามาตลอด วันนี้เขามาพร้อม "รัศมีตัวเอก"`,[
  {t:'⚔️ สู้กับตัวเอก',f(){const w=fight(P.prot.n,total()*(.9+P.prot.luck*.4));if(w){P.prot.alive=0;P.fix+=5;S.fame+=fameR(40);const g=pctPow(.08);S.power+=g;log(`💀 คุณฆ่าตัวเอกของนิยาย! พลัง +${fmt(g)} · โลกสั่นสะเทือน บทนิยายพังทลาย`,'myth',true);keyAdd('สังหารตัวเอกของนิยาย')}else{S.hp=Math.max(1,Math.round(S.hp-S.maxHp*.4));log('💥 รัศมีตัวเอกแรงเกินไป คุณแพ้ยับเยิน','bad')}}},
  {t:'🙇 ขอคืนดี',f(){P.prot.rel+=20;S.karma+=3;log('🙇 คุณสารภาพทุกอย่าง ตัวเอกนิ่งไปนานก่อนยอมให้อภัย','good')}}])}}
// ---------- 2) ร้านค้าข้ามมิติ ----------
const TS_SELL=[['herb','🌿 สมุนไพรวิญญาณ',600],['core','🔶 แก่นอสูร',1500],['gem','💎 ของมีค่า/หยกโบราณ',2200],['fruit','🍑 ผลไม้อายุวัฒนะ',6000],['egg','🥚 ไข่สัตว์วิญญาณ',5000],['map','🗺️ แผนที่มิติลับ',1800],['mirror','🪞 กระจกเงาใส (ขายให้ขุนนาง)',700]];
const TS_BUY=[['noodle','🍜 บะหมี่กึ่งสำเร็จรูป',120,'ความสุข +6 · ฟื้นเลือด 10%',()=>{joy(6);S.hp=Math.min(S.maxHp,S.hp+Math.round(S.maxHp*.1))}],['pain','💊 ยาแก้ปวด',200,'ฟื้นเลือด 35%',()=>{S.hp=Math.min(S.maxHp,S.hp+Math.round(S.maxHp*.35))}],['anti','💉 ยาปฏิชีวนะ',450,'หายจากโรคเรื้อรัง',()=>{S.chronic=null;S.hp=Math.min(S.maxHp,S.hp+20)}],['chem','📗 ตำราเคมี ม.ปลาย',380,'ปัญญา +12',()=>{S.int+=12}],['phys','📘 ตำราฟิสิกส์',420,'ปัญญา +10 · ฝึกยุทธ์เข้าใจหลักแรง',()=>{S.int+=10;S.power+=pctPow(.01)}],['choco','🍫 ช็อกโกแลต',150,'ความรักคู่ครอง +10',()=>{if(S.sp)S.sp.aff=Math.min(100,(S.sp.aff||60)+10);joy(4)}],['torch','🔦 ไฟฉาย',260,'ชื่อเสียง +เทพแห่งแสง',()=>{S.fame+=fameR(8)}],['coffee','☕ กาแฟกระป๋อง',90,'ลมปราณ +1 ปี (นั่งสมาธิไม่หลับ)',()=>{S.qi=+(S.qi+1).toFixed(1)}],['shoe','👟 รองเท้าผ้าใบ',520,'พลัง + (วิ่งเร็วขึ้น)',()=>{S.power+=pctPow(.02)}],['vit','🧴 วิตามินรวม',300,'อายุขัย +2 ปี',()=>{S.lifespan+=2}],['manga','📚 การ์ตูนกำลังภายใน',160,'ความสุข +10 · ไอเดียท่าใหม่',()=>{joy(10);S.int+=3}],['bank','🔋 พาวเวอร์แบงก์',340,'ชาร์จมือถือเต็ม',()=>{if(S.phone)S.phone.bat=100;joy(2)}],['lighter','🔥 ไฟแช็ก',80,'ชาวบ้านคิดว่าคุณใช้เวทไฟ',()=>{S.fame+=fameR(4);S.cha+=1}],['perf','🌸 น้ำหอมแบรนด์เนม',600,'เสน่ห์ +8',()=>{S.cha+=8}],['camp','⛺ เต็นท์กันน้ำ',450,'ท่องยุทธภพปลอดภัยขึ้น',()=>{S.hp=Math.min(S.maxHp,S.hp+30);joy(3)}],['knife','🔪 มีดพับสวิส',380,'พลัง +เล็กน้อย',()=>{S.power+=pctPow(.015)}],['seed','🌽 เมล็ดพันธุ์ข้าวโพด',220,'ปลูกขายได้เงินทุกปี',()=>{const T=tmFix();T.biz.corn=T.biz.corn||{lv:1}}],['sugar','🍬 ขนมหวาน',70,'ความสุข +4',()=>{joy(4)}],['band','🩹 พลาสเตอร์ยา',60,'ฟื้นเลือด 8%',()=>{S.hp=Math.min(S.maxHp,S.hp+Math.round(S.maxHp*.08))}],['mirror','🪞 กระจกเงาใส',260,'เก็บเข้ากระเป๋า · ขายให้ขุนนางได้ในแท็บขาย',()=>{bagAdd('mirror',1)}]];
function tsPx(){const T=tmFix();if(T.pxY!==S.age){T.pxY=S.age;T.px={};TS_SELL.forEach(x=>T.px[x[0]]=+(.5+Math.random()*1.6).toFixed(2));TS_BUY.forEach(x=>T.px[x[0]]=+(.7+Math.random()*.8).toFixed(2))}return T.px}
function tsSell(id,q){if(!tmOn())return;const x=TS_SELL.find(y=>y[0]===id),px=tsPx();if(!x||!bagHas(id))return toast('ไม่มีของชิ้นนี้');const have=(S.bag&&S.bag.it&&S.bag.it[id])||1;
 if(q==='ask'){const s=prompt('ขายกี่ชิ้น? (มี '+have+')',String(Math.min(10,have)));if(s==null)return;q=parseInt(s,10);if(!(q>0))return toast('ใส่จำนวนเป็นตัวเลข')}
 let n=q==null?1:q==='max'?have:Math.floor(+q||1);n=Math.max(1,Math.min(n,have));const u=Math.round(x[2]*px[id]*tmW());let k=0;for(;k<n&&bagHas(id);k++)bagUse(id);S.money+=u*k;toast(k>1?`ขาย ${x[1]} ×${k} ได้ ${fmtM(u*k)}`:`ขาย ${x[1]} ได้ ${fmtM(u)}`);tmHome(Math.min(5,1+Math.floor(k/10)));openTM('shop')}
function tsBuy(id,q){if(!tmOn())return;const x=TS_BUY.find(y=>y[0]===id),px=tsPx();const c=Math.round(x[2]*px[id]*tmW());if(!x||!(c>0))return;
 if(q==='ask'){const v=prompt('ซื้อกี่ชิ้น? (สูงสุด 200)','10');if(v==null)return;q=parseInt(v,10);if(!(q>0))return toast('ใส่จำนวนเป็นตัวเลข')}
 const aff=Math.floor(S.money/c);if(aff<1)return toast('เงินไม่พอ');let n=q==null?1:q==='max'?aff:Math.floor(+q||1);n=Math.max(1,Math.min(n,200,aff));
 if(id==='mirror'){if(!S.bag)bagInit();if(!S.bag.sp){const fr=S.bag.cap-bagCount();if(fr<=0)return toast('กระเป๋าเต็ม ขายของก่อน');n=Math.min(n,fr)}}
 S.money-=c*n;for(let i=0;i<n;i++)x[4]();log(`🛒 ซื้อ <b>${x[1]}</b>${n>1?' ×'+n:''} จากโลกเดิม — ${x[3]}`,'good');if(n>1)toast(`ซื้อ ${x[1]} ×${n} รวม ${fmtM(c*n)}`);tmHome(Math.min(5,1+Math.floor(n/10)));openTM('shop')}
