function invOk(x){const T=tmFix();return!T.inv.includes(x[0])&&S.int>=x[2]&&(!x[4]||x[4].every(p=>T.inv.includes(p)))}
function invDo(id){if(!tmOn())return;const T=tmFix(),x=INV.find(y=>y[0]===id);if(!x||!invOk(x))return toast('ยังประดิษฐ์ไม่ได้');const c=Math.round(x[3]*tmW());if(S.money<c)return toast(`ต้องใช้เงิน ${fmtM(c)}`);S.money-=c;T.inv.push(id);T.dist+=Math.round(x[2]/30);tmHome(2);
 log(`💡 คุณประดิษฐ์ <b>${x[1]}</b> สำเร็จ! ผู้คนในยุคนี้ตะลึง ${{'$':'ได้รายได้ทุกปี','i':'ปัญญาเพิ่มทุกปี','f':'ชื่อเสียงเพิ่มทุกปี','p':'พลังเพิ่ม','k':'กรรมดีทุกปี','q':'ลมปราณเพิ่มทุกปี'}[x[5]]} · มิติบิดเบี้ยว +${Math.round(x[2]/30)}`,'myth',true);S.key.push(`${S.age} ปี — ประดิษฐ์${x[1].slice(3)}`);
 if(x[5]==='p')S.power+=pctPow(x[6]*2);try{const L=LS.get('murim_tminv',[])||[];if(!L.includes(id)){L.push(id);LS.set('murim_tminv',L)}}catch(e){}openTM('inv')}
