function tmHome(v){const T=tmFix();T.home.p+=v;while(T.home.st<HOME_ST.length&&T.home.p>=HOME_NEED[T.home.st]){T.home.st++;log(`🏠 ทางกลับบ้าน: ค้นพบ <b>${HOME_ST[T.home.st-1]}</b> (${T.home.st}/${HOME_ST.length})`,'myth',true)}}
