 const tabs=[['plot','📖 บทนิยาย'],['shop','🛒 ร้านข้ามมิติ'],['inv','💡 ประดิษฐ์'],['biz','🍵 ธุรกิจ'],['home','🏠 ทางกลับบ้าน']].map(([k,t])=>`<button class="cxtab ${k===tab?'on':''}" onclick="openTM('${k}')">${t}</button>`).join('');
 let b='';
