 // เส้นทางลำตัว: หางซ้าย → หัวขวา (คลื่นวิ่ง)
 const N=34,pts=[];for(let i=0;i<=N;i++){const u=i/N,x=.5+u*20*L+(1-L)*6,y=12.5+bob+Math.sin(u*7.2-ft)*3.2*(0.55+u*.45)-u*2.2,r=u<.08?.55:u<.25?.6+u*4.2:u>.9?2.1-(u-.9)*3:1.65+Math.sin(u*3.14)*.65;pts.push({x,y,r,u})}
 // ขาเกาะลม 4 ขา (หลัง 2 หน้า 2)
 const leg=(u,ph)=>{const p=pts[Math.round(u*N)],sw=Math.sin(ft*1.3+ph)*1.1;const lx=p.x+.3,ly=p.y+p.r*.6;R(lx,ly,1,1.6,dk);R(lx+sw*.5,ly+1.4,1,1.2,base);R(lx-.4+sw*.5,ly+2.5,.6,.6,horn);R(lx+.3+sw*.5,ly+2.6,.6,.6,horn);R(lx+1+sw*.5,ly+2.4,.6,.6,horn)};
 leg(.34,0);leg(.42,1.6);
