 leg(.74,2.4);leg(.82,4);
 // ปลายหางพู่เปลวไฟ
 {const p=pts[0];for(let j=0;j<5;j++){const fl=Math.sin(ft*2.2+j)*.7;R(p.x-1.2-j*.35,p.y-1.5+j*.7+fl*.4,1.4,.7,j%2?ec:shadeC(ec,.3),.9)}}
 // หัว
 const hp=pts[N],hx=hp.x-.5,hy=hp.y-2.6,jaw=Math.max(0,Math.sin(fr*.09))*.9;
