 // เขากวางแตกกิ่ง
 R(hx+1.2,hy-2.2,.6,2.2,horn);R(hx+.4,hy-3.6,.6,1.6,horn);R(hx+.4,hy-3.6,-.9+1.5,.5,horn);if(!young){R(hx-.6,hy-4.4,.6,1.2,horn);R(hx+1.6,hy-3.2,1,.5,hornD);R(hx-.2,hy-2.6,.8,.5,hornD);if(t>=4){R(hx-1.4,hy-5,.6,1,horn);R(hx+.9,hy-4.6,.6,1,horn)}}
