 for(let w=0;w<2;w++)for(let j=0;j<12;j++){const x=hx+6.4-j*.85,y=hy+1.2+w*.7+Math.sin(j*.7-ft*1.6+w)*.9+j*.22-(w?0:.4);R(x,y,.55,.45,w?shadeC(horn,-.1):horn,1-j*.06)}
 // ไข่มุกเพลิง
 {const px=hx+9.2,py=hy-1.2+Math.sin(fr*.2)*1;const gr=c.createRadialGradient(ox+(px+.8)*s,oy+(py+.8)*s,0,ox+(px+.8)*s,oy+(py+.8)*s,3.2*s);gr.addColorStop(0,'#ffffffcc');gr.addColorStop(.35,ec+'aa');gr.addColorStop(1,ec+'00');c.fillStyle=gr;c.fillRect(ox+(px-2.4)*s,oy+(py-2.4)*s,6.4*s,6.4*s);R(px,py,1.6,1.6,'#fff4d0');R(px+.3,py+.3,.5,.5,'#ffffff');for(let j=0;j<3;j++){const a=ft*1.5+j*2.1;R(px+.6+Math.cos(a)*1.9,py+.6+Math.sin(a)*1.9,.45,.45,ec)}}
