const BK_KID={quad:'ลูก',bird:'ลูกนก',fish:'ลูกปลา',serp:'ลูกงู',turt:'ลูกเต่า',ape:'ลูกลิง',bug:'ตัวอ่อน',frog:'ลูกอ๊อด'};
BNEW.forEach(n=>{const [nm,k,col,d,sx,ic,prey,home,part,call]=n;if(BL_SP.some(x=>x[0]===nm))return;BL_SP.push([nm,k,col,d]);BSPX[nm]=sx;try{CX_BSI[nm]=ic}catch(e){}
 const mv=BX_MV[k]||BX_MV.quad;BX[nm]={prey,home,part,move:mv[0],rest:mv[1],call,kid:(BK_KID[k]==='ลูก'?'ลูก'+nm:BK_KID[k]||'ลูก'+nm),mateF:nm+'สาว'+ch(['ตาอำพัน','ขนเงิน','ลายงาม','แสงจันทร์']),mateM:nm+'หนุ่ม'+ch(['ร่างกำยำ','ตาคม','ลายเพลิง','สง่างาม'])}});
