function fqRw(){const st=S.beastMode.st|0;return{p:.02+st*.004,q:+(1+st*.6).toFixed(1),f:Math.round(20*(1+st)),k:R(1,4)}}
function fqNew(){const L=FQ_T.filter(t=>!t.c||t.c());const t=pickW(L.map(x=>({w:x.w,v:x}))).v.v;const g=FQ_GIVER(),q=Object.assign({id:'f'+Math.random().toString(36).slice(2,7),k:t.k,g:g[0],gi:g[1],left:4},t.mk());q.rw=fqRw();return q}
