{const _lmI=lifeMax0;lifeMax0=function(){const r1=_lmI.apply(this,arguments);try{const L=S&&S.lsI;if(!L||(S.beastMode&&!S.beastMode.human))return r1;S.lifespan-=L;let r0;try{r0=_lmI.apply(this,arguments)}finally{S.lifespan+=L}return Math.max(r1,r0+L)}catch(e){return r1}}}
