function kcap(){return 1e6*(1+((S&&S.kalpa&&S.kalpa.n)|0))}
function kOf(){if(!S.kalpa)S.kalpa={n:0,st:0,role:null,ev:0,pend:0};return S.kalpa}
// ---------- ฉากอนิเมชั่นเต็มจอ ----------
function kfx(kind,title,sub,col,ms){try{const d=document.createElement('div');d.className='kfx kfx-'+kind;d.style.setProperty('--c',col||'#c0a0ff');
 d.innerHTML=`<canvas></canvas><div class="kfxt"><div class="kfxs">${sub0(kind)}</div><div class="kfxh">${title}</div><div class="kfxb">${sub||''}</div><small>แตะเพื่อไปต่อ</small></div>`;document.body.appendChild(d);
 const cv=d.querySelector('canvas'),c=cv.getContext('2d');let W=cv.width=innerWidth,H=cv.height=innerHeight;const N=Math.min(260,Math.round(W*H/2500)),P=[];
 for(let i=0;i<N;i++){const a=Math.random()*6.283,r=Math.random()*Math.hypot(W,H)*.6;P.push({a,r,s:.4+Math.random()*1.8,v:.002+Math.random()*.01,h:Math.random()})}
 const t0=performance.now(),col2=col||'#c0a0ff';let alive=1;
 const fr=t=>{if(!alive)return;const k=(t-t0)/1000;c.fillStyle=kind==='fail'?'rgba(20,0,4,.25)':'rgba(4,2,16,.22)';c.fillRect(0,0,W,H);const cx=W/2,cy=H/2;
  for(const p of P){if(kind==='gate'){p.r*=k<1.6?.985:1.06;p.a+=p.v*(k<1.6?3:1)}else if(kind==='win'){p.r+=(k<.4?-2:4)*p.s;p.a+=p.v}else if(kind==='fail'){p.r+=3*p.s;p.a-=p.v*.5}else{p.a+=p.v*2;p.r+=Math.sin(k*2+p.h*6)*.6}
   if(p.r>Math.hypot(W,H)*.75)p.r=Math.random()*40;if(p.r<2)p.r=Math.hypot(W,H)*.6*Math.random();
   const x=cx+Math.cos(p.a)*p.r,y=cy+Math.sin(p.a)*p.r*.62;c.fillStyle=p.h<.33?'#ffffff':p.h<.66?col2:(kind==='fail'?'#ff3040':'#ffd070');c.globalAlpha=.55+.45*Math.sin(k*4+p.h*9);c.fillRect(x,y,p.s*1.6,p.s*1.6)}
  c.globalAlpha=1;const rr=kind==='gate'?Math.max(4,90-k*55)+(k>1.6?(k-1.6)*600:0):kind==='win'?k*260:kind==='fail'?40+Math.sin(k*20)*8:60+Math.sin(k*3)*10;
  const g=c.createRadialGradient(cx,cy,0,cx,cy,Math.max(5,rr));g.addColorStop(0,kind==='fail'?'#ff6070':'#ffffff');g.addColorStop(.35,col2);g.addColorStop(1,'transparent');c.globalAlpha=kind==='win'?Math.max(0,1-k/3):.85;c.fillStyle=g;c.beginPath();c.arc(cx,cy,Math.max(5,rr),0,6.283);c.fill();c.globalAlpha=1;
  if(kind!=='fail'){c.strokeStyle=col2;c.lineWidth=2;for(let i=0;i<3;i++){c.globalAlpha=.35;c.beginPath();c.ellipse(cx,cy,(60+i*45)*(1+Math.sin(k*1.5+i)*.08),(22+i*16),k*.6+i,0,6.283);c.stroke()}c.globalAlpha=1}
  requestAnimationFrame(fr)};requestAnimationFrame(fr);
 let done=null;const close=()=>{if(!alive)return;alive=0;d.classList.add('out');setTimeout(()=>{try{d.remove()}catch(e){}if(done)done()},400)};d.onclick=close;setTimeout(close,ms||4200);try{sfx(kind==='fail'?'bad':'realm')}catch(e){}return{then:f=>{done=f}}}catch(e){return{then:f=>f&&f()}}}
