const ARQ={w3:['⚔️ ชนะ 3 ครั้ง',3],man2:['🥋 สู้เองจนจบ 2 ครั้ง',2],adv:['🌀 ชนะด้วยธาตุข่มทาง',1],rv:['😤 ล้างแค้นสำเร็จ',1],cb3:['🔥 ทำคอมโบ ×3 ในการดวล',1],any5:['🎫 ลงสนาม 5 ครั้ง',5]};
function arDay(){const k=new Date(Date.now()+7*3600e3).toISOString().slice(0,10);let D=LS.get('murim_arq',null);if(!D||D.k!==k){const ids=Object.keys(ARQ).sort(()=>Math.random()-.5).slice(0,3);D={k,q:ids.map(id=>({id,p:0,done:0})),all:0};LS.set('murim_arq',D)}return D}
function arQAdd(ev){const D=arDay();let got=0;D.q.forEach(q=>{if(q.done)return;const need=ARQ[q.id][1];let inc=0;if(q.id==='w3'&&ev.w)inc=1;if(q.id==='man2'&&!ev.au)inc=1;if(q.id==='adv'&&ev.w&&ev.ad>0)inc=1;if(q.id==='rv'&&ev.w&&ev.rv)inc=1;if(q.id==='cb3'&&ev.best>=3)inc=1;if(q.id==='any5')inc=1;
 if(inc){q.p=Math.min(need,q.p+inc);if(q.p>=need){q.done=1;got+=8;toast('📋 ภารกิจลานสำเร็จ: '+ARQ[q.id][0]+' · 🪙8')}}});
 if(!D.all&&D.q.every(q=>q.done)){D.all=1;got+=15;toast('🏆 ภารกิจลานครบทั้งหมด! 🪙+15')}if(got)arCAdd(got);LS.set('murim_arq',D);return got}
function arQHtml(){const D=arDay();return`<div class="arq"><b>📋 ภารกิจวันนี้</b>${D.q.map(q=>{const [t,n]=ARQ[q.id];return`<div class="${q.done?'ok':''}"><span>${q.done?'✅':'⬜'} ${t}</span><small>${q.p}/${n} · 🪙8</small></div>`}).join('')}<small class="tag2">${D.all?'✅ ครบแล้ว พรุ่งนี้มีภารกิจใหม่':'ทำครบทั้ง 3 ได้โบนัส 🪙15 · รีเซ็ตเที่ยงคืน'}</small></div>`}
