 const rare=()=>{if(left.length){const id=Math.random()<.15&&left.includes('f_box3')?'f_box3':ch(left.filter(x=>x!=='f_box3').length?left.filter(x=>x!=='f_box3'):left);d.own.push(id);frSet(d);try{profPush()}catch(e){}return{t:5,ic:'🖼️',n:frOf(id).n,s:'กรอบเฉพาะหีบ!'}}arCAdd(80);return{t:4,ic:'🪙',n:'เหรียญลาน 80',s:'มีกรอบหีบครบแล้ว รับเหรียญแทน'}};
