openVault=function(){const V=S.vault||[];
 modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>🗝️ คลังสมบัติ</h3><p class="tag2">ของที่ประมูลมา (ทั้งโรงประมูลและประมูลทั่วยุทธภพ) เก็บไว้ที่นี่ · กดใช้เมื่อพร้อม · ขายคืนได้ครึ่งราคา · ของจากโรงประมูลที่ยังไม่ใช้ อาจโดนคนที่แพ้ประมูลตามมาชิง</p>
 ${V.length?V.map((v,i)=>{const it=vItem(v);if(!it)return'';const d=v.pa?paEff(it).d:ecoDesc(it);return`<div class="item"><div class="h"><b>${esc(it.n)} ${rarTag(it.r)}${v.pa?' <span class="tag2">🏛️</span>':''}</b><span><button class="sysb" onclick="vaultUse(${i})">ใช้</button> <button class="sysb" onclick="vaultSell(${i})">ขาย ${fmtM(Math.round((v.paid||0)*.5))}</button></span></div><p class="tag2">${d}</p></div>`}).join(''):'<p class="tag2">ยังว่างเปล่า</p>'}
 ${(S.hunts||[]).length?`<p class="tag2" style="color:#ff6b6b">⚠️ มีคนกำลังตามล่าคุณ ${S.hunts.length} ราย</p>`:''}`,'vault')};
