const PX_TH={};function pxThumb(type,w,seed){const k=type+w+seed;if(PX_TH[k])return PX_TH[k];try{const cv=document.createElement('canvas');cv.width=PXW;cv.height=PXH;pxScene(cv.getContext('2d'),type,w,seed,-1);return PX_TH[k]=cv.toDataURL()}catch(e){return''}}
// วาดตัวละครผู้เล่น (ใช้สไปรต์เดียวกับฉากหลัก)
function pxMe(c,x,y,flip){try{const g0=g,ps0=PS;g=c;PS=3;c.save();c.setTransform(3,0,0,3,0,0);if(flip){c.translate(x*2,0);c.scale(-1,1)}person(x,y,meLook());c.restore();g=g0;PS=ps0}catch(e){c.fillStyle='#e8e0d0';c.fillRect(x-2,y-14,5,14);c.fillStyle='#2a2030';c.fillRect(x-2,y-16,5,3)}}
// ธาตุของวิชา → สี
function pxEl(n){n=String(n||'');return /เพลิง|ไฟ|แดด|ตะวัน|อัคคี|หงส์/.test(n)?['#ff6a20','#ffd070']:/น้ำแข็ง|หิมะ|เยือก|เกล็ด/.test(n)?['#6ad8ff','#e8fbff']:/อัสนี|สายฟ้า|ฟ้าผ่า|ฟ้าร้อง/.test(n)?['#ffe040','#ffffff']:/มาร|โลหิต|เลือด|ทมิฬ|พิษ/.test(n)?['#c01848','#ff80a0']:/กระบี่|ดาบ|คม/.test(n)?['#9ad0ff','#ffffff']:/ลม|พายุ|เมฆ/.test(n)?['#8af0c0','#f0fff8']:/จันทร์|ดารา|ดาว|ราตรี/.test(n)?['#b08aff','#f0e8ff']:/น้ำ|คลื่น|สมุทร/.test(n)?['#3a9aff','#c8e8ff']:['#ffc840','#fff4c0']}
