const FAME_T=[[0,'🌱','ไร้นาม'],[100,'🏘️','คนในหมู่บ้านรู้จัก'],[1500,'🏯','ดังทั่วเมือง'],[15000,'⚔️','ลือลั่นยุทธภพ'],[200000,'🌏','ทั่วแผ่นดินรู้จัก'],[1e6,'☁️','เลื่องลือถึงโลกเซียน'],[1e8,'✨','ชื่อจารึกบนฟ้า'],[1e10,'🌌','ตำนานเหนือกาลเวลา']];
function fameTier(v){v=v==null?(S?S.fame:0):v;let t=FAME_T[0];for(const x of FAME_T)if(v>=x[0])t=x;return t}
function fameTierH(){const t=fameTier();return`<span style="font-size:11px;line-height:1.25;display:block" title="${fmt(S.fame)}">${t[1]} ${t[2]}</span><small style="display:block;font-size:10px;opacity:.65">${fmt(S.fame)}</small>`}
const fameCap=()=>S&&S.xt?1e10:S&&S.xian?1e8:1e6;
// ส่วนที่เกินเพดาน: ยิ่งมากยิ่งได้น้อยลง (ไม่ลดของเดิม)
function fameSoft(){if(!S)return;const f=+S.fame||0,p=S._fq;if(p==null||!isFinite(p)){S._fq=f;return}const d=f-p;if(d>0){const cap=fameCap();if(f>cap){const under=Math.max(0,cap-p),over=d-under,base=Math.max(cap,p);S.fame=Math.round(p+under+over*cap/(base+over)*.5)}}S._fq=S.fame}
{const _rFm=render;render=function(){try{fameSoft()}catch(e){}return _rFm.apply(this,arguments)}}
{const _pyFm=passYear;passYear=function(){try{fameSoft()}catch(e){}const r=_pyFm.apply(this,arguments);try{fameSoft()}catch(e){}return r}}

