function arLessonAct(a){const L=window._arL;if(!L)return;const st=L.steps[L.i],ok=arLessonOk(st.e);if(ok.includes(a)){L.en=Math.max(5,L.en-100/L.steps.length);try{sfx(a==='sec'?'rare':'hit')}catch(e){}arLessonDraw({ok:1,t:AR_CT[st.e].why})}
 else{L.wrong++;try{sfx('bad')}catch(e){}const bad={atk:'บุกตรงๆ ตอนนี้จะเสียเปรียบ',def:'ตั้งรับตอนนี้เสียจังหวะเปล่า',dodge:'หลบตอนนี้ไม่ได้อะไร',ctr:'รอสวนตอนนี้ไม่ได้ผล',sec:'เก็บวิชาลับไว้ใช้ตอนศัตรูตั้งการ์ดดีกว่า'}[a];arLessonDraw({ok:0,t:bad+' · '+AR_CT[st.e].why})}}
