 function onWin(nm){if(!hu())return;const t=tid();
  if(t==='devour'){const g=pctPow(.008);S.power+=g;S.karma-=1;S.o=S.o||{};S.o.dv=(S.o.dv||0)+1;if(S.o.dv%5===1)addFeed('ev',`🩸 กลืนพลังของ${esc(nm||'ศัตรู')} — พลังยุทธ์ +${fmt(g)} · กรรม −1`,'sum');if(Math.random()<.03){const d=Math.round(S.maxHp*.2);S.hp=Math.max(1,S.hp-d);S.karma-=5;log(`🩸 พลังที่กลืนมาย้อนกลับ คุณคลั่งไปครึ่งคืน (พลังชีวิต −${d} · กรรม −5)`,'bad')}}
  if(t==='mirror'){S.o=S.o||{};S.o.mr=(S.o.mr||0)+1;const need=cmb()==='prison+mirror'?2:3;if(S.o.mr>=need){S.o.mr=0;const a=newArt(0);const r=Math.min(2,ART_TIER.indexOf(ART_TIER.find(x=>x.n===a.tier))||0);if((a.r||0)>2){a.r=2;a.tier=ART_TIER[2].n;a.b=Math.min(a.b,ART_TIER[2].b*1.2|0)}a.n=a.n||'วิชาที่ลอกมา';a.mir=1;if(S.arts.some(x=>x.n===a.n))return;artLearned(a,`👁️ เนตรลอกเลียนจดจำท่าของ${esc(nm||'ศัตรู')}ได้หมด — ได้${artHtml(a)}`)}}}
 {const _f=fight;fight=function(n,ep){const w=_f.call(this,n,ep*epM());try{if(w&&!window._duW)onWin(n)}catch(e){}return w}}
