// ---------- จุดตรวจเซฟ: บันทึกค่าหลักพร้อมลายเซ็นทุกครั้งที่เกมเซฟเอง · โหลดแล้วค่ากระโดดเกินจริง/ลายเซ็นไม่ตรง → ชีวิตนั้นไม่ขึ้นทำเนียบ ----------
const SV_K=['power','qi','int','cha','fame','money','karma','maxHp','lifespan','luck','kids'];
function svVec(o){const v=SV_K.map(k=>Math.round(+o[k]||0));v.push(Math.round(+o.age||0));v.push(o.gd?Math.round(+o.gd.bel||0):0);return v}
function svHash(v,o){const s=v.join('|')+'|'+String(o.name||'')+'|'+String(o._lid||'')+'|'+[109,117,114,49,110,52,110,48,118,51,108].map(c=>String.fromCharCode(c^3)).join('')+v.length;let h1=0xdeadbeef^s.length,h2=0x41c6ce57^s.length;for(let i=0;i<s.length;i++){const ch=s.charCodeAt(i);h1=Math.imul(h1^ch,2654435761);h2=Math.imul(h2^ch,1597334677)}h1=Math.imul(h1^(h1>>>16),2246822507)^Math.imul(h2^(h2>>>13),3266489909);h2=Math.imul(h2^(h2>>>16),2246822507)^Math.imul(h1^(h1>>>13),3266489909);return(4294967296*(2097151&h2)+(h1>>>0)).toString(36)}
function svCheck(o){try{const c=o&&o._sg;if(!c||typeof c!=='object')return'';if(!Array.isArray(c.v)||c.v.length!==SV_K.length+2||svHash(c.v,o)!==c.h)return'save-sig';const v=c.v,n=svVec(o),dA=n[11]-v[11];if(dA<0||dA>3)return'';const f=dA>0;
  const over=(i,mul,add)=>n[i]>Math.abs(v[i])*mul+add;
  if(over(0,f?20:3,f?1e6:5e4)||over(1,f?5:2,f?500:50)||n[2]>v[2]+(f?3000:300)||n[3]>v[3]+(f?3000:300)||over(4,f?20:3,f?1e5:5000)||over(5,f?100:5,f?1e9:1e7)||n[6]>v[6]+(f?600:100)||over(7,f?10:2,f?5000:500)||over(8,f?10:2,f?5000:3000)||over(12,f?20:3,f?1e6:1e5))return'save-jump';return''}catch(e){return''}}
{const _lsS=LS.set;LS.set=function(k,v){try{if(v&&typeof v==='object'&&v.S&&typeof v.S==='object'&&v.cfg===CFG&&v.v===VERSION&&S&&v.S.name===S.name){const vec=svVec(v.S);v.S._sg={v:vec,h:svHash(vec,v.S)}}}catch(e){}return _lsS.apply(this,arguments)}}
{const _lgS=loadGame;loadGame=function(n){let bad='';try{const d=readSave(n==null?1:n);if(d&&d.S)bad=svCheck(d.S)}catch(e){}const r=_lgS.apply(this,arguments);try{if(bad&&S&&S.alive&&!S.custom){try{acSus(bad)}catch(e){}}}catch(e){}return r}}

// ---------- ส่งชีวิตขึ้นทำเนียบไม่สำเร็จ (เน็ตหลุด/เซิร์ฟเวอร์ขัดข้อง) → เก็บไว้แล้วส่งใหม่เองภายหลัง ----------
function lifeQAdd(P){const q=(LS.get('murim_lifeq',[])||[]).filter(x=>x&&x.lid!==P.lid);q.push(Object.assign({},P,{_q:Date.now()}));while(q.length>3)q.shift();LS.set('murim_lifeq',q);
 try{const end=$('end');if(end&&!$('lifeQN')){const b=document.createElement('div');b.id='lifeQN';b.className='box';b.style.cssText='border-color:#e8a23a;padding:8px 10px;margin:8px 0';b.innerHTML='<b>⏳ ส่งชีวิตนี้ขึ้นทำเนียบยังไม่สำเร็จ</b><p class="tag2">เซิร์ฟเวอร์ไม่ตอบในตอนนี้ เกมเก็บไว้แล้ว และจะส่งให้เองอัตโนมัติเมื่อเชื่อมต่อได้ (ไม่ต้องเล่นใหม่)</p>';end.insertBefore(b,end.firstChild)}}catch(e){}}
async function lifeQFlush(){if(lifeQFlush._b||typeof onlineOK==='undefined'||!onlineOK)return;const q=LS.get('murim_lifeq',[])||[];if(!q.length)return;lifeQFlush._b=1;
 try{const left=[];for(const P of q){if(Date.now()-(P._q||0)>14*86400e3)continue;try{const B=Object.assign({},P);delete B._q;const r=await api('life',B);if(!r||!r.ok)left.push(P);else if(!r.skip){try{toast('🏆 ส่งชีวิต '+(P.n||'')+' ขึ้นทำเนียบแล้ว')}catch(e){}}}catch(e){left.push(P)}}LS.set('murim_lifeq',left)}finally{lifeQFlush._b=0}}
setTimeout(()=>{try{lifeQFlush()}catch(e){}},8000);setInterval(()=>{try{lifeQFlush()}catch(e){}},120000);

