{const SEC=[['rec','📚 บันทึกและความรู้','Records & guides',/openBook|openGraves|openNovels|openCodex|openBestiary|openStats|openGuide|openUpdate/],
  ['acc','👤 บัญชีและเซฟ','Account & saves',/openProfile|openSaveCode|frmenu2/],
  ['set','⚙️ ตั้งค่า','Settings',/toggleLang|cycleTheme|openSound|cycleFs|openGfx|openUiZ|dockToggle/],
  ['con','💬 ติดต่อและสนับสนุน','Contact & support',/openSupport|openReport|openFeedback/],
  ['adm','🛠️ แอดมิน','Admin',/openAdmTools/]];
 const _otS=openTitleMenu;openTitleMenu=function(){const r=_otS.apply(this,arguments);try{const m=$('modal'),gr=m&&m.querySelector('.tmgrid');if(!gr||m.querySelector('.tmsec'))return r;
  const btns=[...gr.querySelectorAll(':scope > button')];
  // ปุ่มเต็มแถวที่ซ้ำกับในตาราง: ภาษา (langopt) · คู่มือระบบ → เอาออก · โปรไฟล์ → ย้ายเข้าตาราง
  m.querySelectorAll(':scope > button.langopt').forEach(b=>b.remove());
  [...m.querySelectorAll(':scope > button.gbtn')].forEach(b=>{if(b.onclick===openGuide||/คู่มือระบบ/.test(b.textContent))b.remove()});
  const pf=m.querySelector(':scope > button.frmenu2');if(pf){const nb=document.createElement('button');nb.className='cb frmenu2';nb.innerHTML='<i>👤</i>'+(LANG==='en'?'Profile & frames':'โปรไฟล์และกรอบ');nb.onclick=()=>openProfile();pf.remove();btns.unshift(nb)}
  const key=b=>(b.getAttribute('onclick')||'')+' '+b.className,box={},left=[];
  btns.forEach(b=>{const s=SEC.find(x=>x[3].test(key(b)));if(s)(box[s[0]]=box[s[0]]||[]).push(b);else left.push(b)});
  // คู่มือกับอัปเดตไว้ท้ายหมวดบันทึก · ภาษาไว้ท้ายหมวดตั้งค่า
  const wt=b=>/openGuide|openUpdate|toggleLang/.test(key(b))?1:0;['rec','set'].forEach(k=>box[k]&&box[k].sort((a,b)=>wt(a)-wt(b)));
  if(left.length)(box.set=box.set||[]).push(...left);
  const host=document.createElement('div');host.className='tmsecs';
  SEC.forEach(s=>{const L=box[s[0]];if(!L||!L.length)return;const d=document.createElement('div');d.className='tmsec';d.innerHTML=`<div class="tmh">${LANG==='en'?s[2]:s[1]}</div>`;const g=document.createElement('div');g.className='tmgrid';L.forEach(b=>g.appendChild(b));d.appendChild(g);host.appendChild(d)});
  gr.replaceWith(host)}catch(e){console.error(e)}return r}}


