  yr(W){if(W.k===1){const ok=chance(Math.min(.8,.3+S.fame/20000+(S.cha||0)/500));W.s+=ok?1:-1;say(ok?'🪑 เทพหลายองค์ประกาศสนับสนุนคุณ':'🪑 ฝ่ายตรงข้ามซื้อตัวผู้สนับสนุนคุณไป',ok?'good':'bad')}else if(W.k===2){if(chance(.5+(S.int||0)/4000)){W.c++;say('🔎 คุณพบร่องรอยของเทพจักรพรรดิ','good',{int:10})}}return false},
