 window.orphUp=function(){const O=S.orph,up=Math.round(3000*MU()*O.lv);if((S.money||0)<up)return toast('เงินไม่พอ');S.money-=up;O.lv++;toast('ขยายบ้านเด็กกำพร้าแล้ว');orphView()};
 function rw0(o){if(o.karma)S.karma+=o.karma;if(o.fame)S.fame+=o.fame;if(o.mon)S.money=Math.max(0,(S.money||0)+o.mon)}
