{const LT={'ผู้ไต่ลานทองคำ':[3,2],'เพชรแห่งลานเงา':[4,3],'จ้าวลานประลอง':[5,4],'ปรมาจารย์ผู้ไร้เงา':[5,5],'ราชันหมื่นเงา':[6,6],'เทพยุทธ์แห่งยุค':[6,7]};const isLeg=t=>/^ตำนานลานซีซั่น \d+$/.test(t);
 // อนิเมชั่นฉายาลีกใช้ระดับเดียวกับฉายาแลกในลาน
 try{const _t=tchipH;tchipH=function(t,r){const k=String(t||'').trim();if(LT[k]||isLeg(k)){const fx=isLeg(k)?7:LT[k][1];try{return tchipH0(k,r,fx)}catch(e){}}return _t.apply(this,arguments)};
  window.tchipH0=(k,r,fx)=>{const map={2:'ผู้ไม่เคยถอย',3:'ตำนานแห่งลาน',4:'ราชันเงาอสูร',5:'เทพสงครามแห่งลาน',6:'ผู้ยืนหนึ่งเหนือพันศึก',7:'จักรพรรดิแห่งเงา'},ref=map[fx]||map[2];const h=_t.call(this,ref,r);return h.split(ref).join(esc(k))}}catch(e){}
 // ส่วน "ฉายาลีก" ในร้านลาน
 const _sh=arShopHtml;arShopHtml=function(){let h=_sh.apply(this,arguments);try{const o=arOwn(),L=o.tt.filter(t=>LT[t]||isLeg(t));const sec=`<h5>🏅 ฉายาลีก <small>ได้เมื่อจบซีซั่นในลีกทองขึ้นไป · ตำนานลาน = 10 อันดับแรก</small></h5>${L.length?`<div class="arshop">${L.map(t=>{const r=isLeg(t)?6:LT[t][0];return`<div class="item arsi"><div class="arttl">${tchipH(t,r)}</div><button class="sysb" onclick="setShowTtl('${esc(t)}',${r},'ar');openOnline('arena')">โชว์ฉายานี้</button></div>`}).join('')}</div>`:`<p class="tag2">ยังไม่มี ${Object.keys(LT).map((t,i)=>`${AR_LG[i+2][0]} ${AR_LG[i+2][1]}: 「${t}」`).join(' · ')} · 🏯 ตำนานลาน: 「ตำนานลานซีซั่น ?」</p>`}`;const i=h.indexOf('<h5>🏷️ ฉายาลาน');h=i>=0?h.slice(0,i)+sec+h.slice(i):h+sec}catch(e){}return h}}



// ===================== สวิตช์เปิดยุคปัจจุบันให้ทุกคน (false = เฉพาะแอดมิน) =====================
var MW_PUBLIC=false;
function mwAllowed(){return MW_PUBLIC||!!admK()}
function mwTag(){return admK()&&!MW_PUBLIC?'(ทดสอบแอดมิน)':''}
// ===================== ยุคปัจจุบัน องก์ 1 — ยอดฝีมือหลงยุค (ทดสอบ: เฉพาะโหมดแอดมิน) =====================
// ค่าใหม่: S.mw = {y ปีในยุคนี้, sec ความลับรั่ว 0-100, fame ชื่อเสียงออนไลน์, adapt ความคุ้นเคยยุคใหม่ 0-100, qi ปราณ, lin ความผูกพันกับหลิน, past ข้อมูลจริงจากชีวิตก่อน}
const MW_Y0=2026,MW_GATE=50000;
const mwOn=()=>!!(S&&S.mw);
const mwTxt=h=>String(h||'').replace(/<[^>]+>/g,'').replace(/\s+/g,' ').trim();
function mwPast(){const P={n:S.name,age:S.age,ri:realmIdx(),realm:'',xian:!!S.xian,xt:!!S.xt};try{P.realm=REALMS[P.ri].n}catch(e){}
 try{const w=gearOf('weapon');P.wpn=w?w.n:null}catch(e){}
 try{const a=(S.arts||[]).slice().sort((x,y)=>(y.b||0)-(x.b||0))[0];P.art=a?mwTxt(a.n):null}catch(e){}
 if(!P.wpn)P.wpn=P.art&&/กระบี่|ดาบ/.test(P.art)?'กระบี่ที่ใช้ร่าย'+P.art:'กระบี่ประจำตัว';
 if(S.ownSect){P.sect=S.ownSect.n;P.sectUp=(S.ownSect.lv||1)>=3||(S.ownSect.dis||0)>=60;P.founder=1}
 else if(S.faction){P.sect=S.faction.n;P.sectUp=(S.rank||0)>=4}
 else if(S._mwFac){P.sect=S._mwFac;P.sectUp=true}
 const sp=String(S.name||'').split(' ');P.sur=sp.length>1?sp[0]:null;
 const mom=(S.parents||[]).find(p=>p.role==='แม่');P.mom=mom?mom.n:null;
 const kl=(S.children||S.kids||[]).filter(k=>k&&k.alive!==false),kid=kl.find(k=>k.g==='หญิง')||kl[0];P.kid=kid&&kid.n?kid.n:null;P.kidG=kid&&kid.g||null;
 const rv=(typeof peers!=='undefined'?peers:[]).find(p=>p.rel==='rival');P.foe=S.revenge&&S.revenge.n?S.revenge.n:rv?rv.name:null;
 P.fam=S.family&&S.family.n||'';
 try{P.keys=(S.key||[]).slice(-6).map(mwTxt).filter(x=>x.length>6).slice(-3)}catch(e){P.keys=[]}
 let h=0;for(const c of String(S.name))h=(h*31+c.charCodeAt(0))%997;P.yr=1260+h%280;
 return P}
// ---------- เข้าสู่ยุคปัจจุบัน ----------
function mwEnter(how){if(!S||!S.alive||S.mw)return;if(!mwAllowed()){toast('ยุคปัจจุบันยังไม่เปิด');return}
 const P=mwPast();P.how=how||'rift';P.pow0=Math.round(total());
 S.mw={y:0,sec:0,fame:0,adapt:4,qi:Math.max(1,Math.round((S.qi||0)*.01*10)/10),lin:0,linMet:0,past:P,seen:{},q:[],fl:{},end:S.age+R(55,80),clk:0};
 S.power=Math.max(5,Math.round((S.power||0)*.01));S.qi=S.mw.qi;S.xian=false;S.xt=0;CFG.xian=0;try{setWorld(false)}catch(e){}
 S.faction=null;S.ownSect=null;S.custom=true;S.mwTest=1;S.focus='mwjob';S.wev2=null;S.wPend=null;
 try{peers=[]}catch(e){}if(choice._cur){choice._cur=null}if(modalOpen)closeM();
 log(`🌀 <b>คุณก้าวผ่านรอยแยก…</b> แสงสีขาวกลืนทุกอย่าง เสียงสุดท้ายที่ได้ยินจากยุคของคุณคือเสียงลมบน${P.xian?'ยอดเขาเซียน':'ยอดเขา'}`,'myth',true);
 render();mwQ(['e1','e2']);saveGame()}
// ---------- ค่า และผลลัพธ์ ----------
const mwCl=(v,a,b)=>Math.max(a,Math.min(b,v));
function mwFx(o){const M=S.mw;if(!M)return'';const out=[];
 if(o.sec){M.sec=mwCl(M.sec+o.sec,0,100);out.push(`🤫 ความลับรั่ว ${o.sec>0?'+':''}${o.sec}`)}
 if(o.fame){M.fame=Math.max(0,Math.round(M.fame+o.fame));out.push(`📈 ผู้ติดตาม ${o.fame>0?'+':''}${fmt(o.fame)}`)}
 if(o.adapt){M.adapt=mwCl(M.adapt+o.adapt,0,100);out.push(`🏙️ ความคุ้นเคย ${o.adapt>0?'+':''}${o.adapt}`)}
 if(o.qi){M.qi=Math.max(0,+(M.qi+o.qi).toFixed(1));S.qi=M.qi;out.push(`🌀 ปราณ ${o.qi>0?'+':''}${o.qi}`)}
 if(o.lin){M.lin=mwCl(M.lin+o.lin,0,100);out.push(`🧒 หลิน ${o.lin>0?'+':''}${o.lin}`)}
 if(o.mon){S.money=Math.max(0,(S.money||0)+o.mon);out.push(`💵 ${o.mon>0?'+':''}${fmt(o.mon)} บาท`)}
 if(o.joy)joy(o.joy);
 return out.length?` <span class="tag2">(${out.join(' · ')})</span>`:''}
function mwSay(t,cls,o,big){log(t+(o?mwFx(o):''),cls||'',big)}
// คิวเหตุการณ์ (หลายเรื่องในปีเดียว เล่นต่อกันทีละเรื่อง)
function mwQ(ids){const M=S.mw;if(!M)return;ids.forEach(id=>{if(!M.seen[id]&&!M.q.includes(id))M.q.push(id)});mwRun()}
let _mwRun=0;function mwRun(){if(_mwRun)return;_mwRun=1;const me=S;const go=()=>{if(S!==me||!S||!S.alive||!S.mw){_mwRun=0;return}if(choice._cur||(modalOpen&&/choice|duel|mwask/.test($('modal').dataset.k||'')))return setTimeout(go,700);const M=S.mw;const id=M.q.shift();if(!id){_mwRun=0;return}const E=MW_EV[id];if(!E||M.seen[id])return go();M.seen[id]=M.y+1;
  try{setScene('mw')}catch(e){}try{E.go(M,M.past)}catch(e){console.error(e)}setTimeout(go,600)};setTimeout(go,250)}
