const MW_FILL={nat:['🍜 ร้านก๋วยเตี๋ยวหน้าปากซอยขึ้นราคาอีกห้าบาท คุณยังกินเหมือนเดิม','🌧️ ฝนตกหนักตอนเลิกงาน คุณยืนรอใต้กันสาดร้านสะดวกซื้อกับคนแปลกหน้า','🚌 รถเมล์สายประจำเปลี่ยนเป็นรถไฟฟ้า ค่ารถขึ้นแต่ถึงเร็วขึ้นครึ่งชั่วโมง','📱 แม่ส่งสติกเกอร์สวัสดีตอนเช้ามาในไลน์ครอบครัวทุกวันไม่เคยขาด','🐈 แมวส้มประจำซอยเริ่มมานอนหน้าห้องคุณทุกคืน','💡 บิลค่าไฟเดือนเมษาทำให้คุณต้องคิดใหม่เรื่องเปิดแอร์ทั้งคืน','🛵 พี่วินหน้าซอยจำได้แล้วว่าคุณลงตรงไหน ไม่ต้องบอก','🎆 คืนข้ามปี คุณดูพลุจากดาดฟ้าตึกกับคนในซอย','🍉 ป้าขายผลไม้แถมแตงโมให้ชิ้นหนึ่ง เพราะคุณซื้อประจำ','🏸 เด็กในซอยชวนตีแบดตอนเย็น คุณเล่นจนฟ้ามืด'],lo:['🥫 คุณพยายามฟันกระป๋องน้ำอัดลมด้วยฝ่ามือเพราะเปิดไม่เป็น น้ำหวานพุ่งเต็มเพดาน','🚇 คุณยืนท้ารถไฟฟ้าที่ไม่ยอมหยุดให้ จนพนักงานต้องมาพาออกไปจากชานชาลา','🧊 ตู้เย็นคือถ้ำน้ำแข็งพกพา คุณนั่งสมาธิหน้าตู้เย็นทั้งบ่าย','🎤 รถแห่หาเสียงผ่านหน้าบ้าน คุณนึกว่าเป็นกองทัพขุนนางบุกเมือง','🔥 คุณจุดไฟในห้องเช่าเพื่อต้มน้ำชา สัญญาณกันไฟร้องลั่นตึก','📺 คุณดูละครจีนกำลังภายในแล้วตะโกนว่า "ท่านั้นผิด!" ใส่จอทั้งเรื่อง'],
 mid:['🌧️ ฝนตกหนัก คุณยืนใต้กันสาดร้านสะดวกซื้อกับคนแปลกหน้าที่ยื่นร่มให้','🚌 คุณเริ่มจำสายรถเมล์ได้ครบทุกสายที่ผ่านซอย','💡 คุณเรียนรู้ว่าบิลค่าไฟคือศัตรูที่น่ากลัวกว่ายอดฝีมือคนไหน','🏸 เด็กในซอยขอให้คุณสอนตีแบดมินตัน ลูกขนไก่ไม่เคยตกพื้นเลยทั้งชั่วโมง'],
 hi:['🌙 คืนที่ไฟดับทั้งซอย ดาวบนฟ้ากรุงเทพฯ น้อยกว่าที่บ้านเกิดหลายพันดวง','📷 คุณเจอรูปถ่ายขาวดำเก่าในร้านของมือสอง คนในรูปไม่มีใครที่คุณรู้จักอีกแล้ว','🕯️ วันเกิดคุณในยุคนี้ไม่มีใครรู้ คุณซื้อขนมเค้กชิ้นเล็กๆ มากินคนเดียว','🎐 เสียงกระดิ่งลมจากร้านข้างบ้าน คล้ายเสียงกระดิ่งหน้าสำนักในวันที่ฝนตก']};
function mwYear(){const M=S.mw;yearSum&&0;S.age++;M.y++;ensureHeader();const f=S.focus,lt=M.linMet;
 if(f==='mwjob'){mwJobYear(M)}
 else if(f==='mwqi'){const q=M.fl.temple?R(10,20)/10:R(1,3)/10;mwFx({qi:q});S.power+=Math.round(q*20);addFeed('ev',`🧘 นั่งสมาธิ${M.fl.temple?'ที่วัดบนดอย':'บนดาดฟ้า'} · ปราณ +${q}`,'sum')}
 else if(f==='mwnet'){const g=Math.round((4000+M.fame*.06)*(M.fl.ch==='tale'?.5:1)*(.7+Math.random()*.6)),sec=M.fl.ch==='tale'?R(0,2):R(4,9);mwFx({fame:g,sec,mon:Math.round(g*.4)});addFeed('ev',`📱 ทำคอนเทนต์ทั้งปี · ผู้ติดตาม +${fmt(g)} · ความลับรั่ว +${sec}`,'sum')}
 else if(f==='mwlearn'){if(M.native){const g=R(2,5);S.int+=g;try{const l=M.L;if(l)l.sk=Math.min(100,(l.sk||0)+R(1,3))}catch(e){}addFeed('ev',`📚 ลงคอร์ส/อ่านหนังสือหลังเลิกงาน · ปัญญา +${g}`,'sum')}else{const a=R(6,10);mwFx({adapt:a});S.int+=R(2,5);addFeed('ev',`📚 เรียนรู้ยุคใหม่ · ความคุ้นเคย +${a}`,'sum')}}
 else if(f==='mwlow'){const d=R(5,9);mwFx({sec:-d,joy:3});S.hp=Math.min(S.maxHp,S.hp+20);addFeed('ev',`🍵 ใช้ชีวิตเงียบๆ ไม่มีใครสนใจคุณ · ความลับรั่ว −${d}`,'sum')}
 else if(f==='mwlin'&&lt){mwFx({lin:R(6,10),adapt:3});addFeed('ev','🧒 ใช้เวลากับหลิน — '+ch(['ช่วยเขาทำการบ้านเลข ที่คุณเองก็ไม่เข้าใจ','กินหมูกระทะด้วยกันครั้งแรก','ฟังเขาบ่นเรื่องสอบเข้ามหาลัย','ไปดูหนังโรงด้วยกัน คุณสะดุ้งทุกครั้งที่เสียงดัง']),'sum')}
 // ผลค้างจากปีก่อน
 if(M.fl.plaque&&M.y>=M.fl.plaque+1){M.fl.plaque=0;addFeed('ev',`🏛️ ป้ายในตู้กระจกเปลี่ยนแล้ว: <b>"อาวุธของ${esc(M.past.n)} ราว ค.ศ. ${M.past.yr}"</b> มีคนมาถ่ายรูปป้ายนี้มากขึ้นทุกวัน`,'sum');mwFx({sec:4})}
 if(M.fl.famW&&M.y>=M.fl.famW){M.fl.famW=0;log('🕯️ หญิงชราที่ตลาดนัดจากไปอย่างสงบ ในงานศพมีคนมาไม่ถึงสิบคน คุณเป็นคนเดียวที่รู้ว่าเธอเป็นใคร','bad',true);joy(-12)}
 // ความลับรั่วถึงขีด
 if(M.sec>=60&&!M.seen.e12&&!M.q.includes('e12')&&M.y>=4)mwQ(['e12']);
 // เหตุการณ์ตามแผน
 const pl=MW_PLAN.find(x=>x[0]===M.y);if(pl){const L=pl[1].filter(id=>!(id==='e10'&&M.adapt<30));mwQ(L);if(pl[1].includes('e10')&&M.adapt<30)M.fl.e10late=1}
 if(M.fl.e10late&&M.adapt>=30&&!M.seen.e10){M.fl.e10late=0;mwQ(['e10'])}
 // เรื่องเล็กๆ ตามความคุ้นเคย (มุกช็อกวัฒนธรรมหมดได้)
 if(!M.q.length&&Math.random()<.65){const b=M.native?'nat':M.adapt<35?'lo':M.adapt<70?'mid':'hi',used=M.fu=M.fu||[];const L=MW_FILL[b].filter((x,i)=>!used.includes(b+i));if(L.length){const t=ch(L);used.push(b+MW_FILL[b].indexOf(t));addFeed('ev',t,'sum')}}
 // นาฬิกาเซิร์ฟเวอร์
 if(M.q.length)mwRun(); M.clk=(M.clk||0)+1;if(M.clk>=1)mwClock(M.clk).then(j=>{if(j&&j.ok&&S&&S.mw)S.mw.clk=0}).catch(()=>{});
 S.hp=Math.min(S.maxHp,S.hp+R(3,8));render();checkDeath();saveGame()}
let _mwCk=0;
async function mwClock(n){if(typeof onlineOK==='undefined'||!onlineOK)return null;if(n&&Date.now()-_mwCk<20000)return null;if(n)_mwCk=Date.now();return api('mwclk',{n:Math.min(5,n|0)})}
