{const _pyW=passYear;passYear=function(){if(mwOn()){try{mwYear()}catch(e){console.error(e);S.age++;saveGame()}return}return _pyW.apply(this,arguments)}}
{const _lmW=lifeMax;lifeMax=function(){if(mwOn())return S.mw.end;return _lmW.apply(this,arguments)}}
{const _foW=focusOK;focusOK=function(k){if(mwOn()){if(k==='mwlin')return!!S.mw.linMet;return MW_FOC.some(f=>f[0]===k)}if(/^mw/.test(String(k)))return false;return _foW.apply(this,arguments)}}
{const _afW=autoFocus;autoFocus=function(){if(mwOn()){const M=S.mw;S.focus=M.sec>=50?'mwlow':M.adapt<30?'mwlearn':M.linMet&&M.lin<40?'mwlin':ch(['mwjob','mwjob','mwqi','mwnet','mwlearn']);return}return _afW.apply(this,arguments)}}
{const _rnW=render;render=function(){const r=_rnW.apply(this,arguments);try{if(!mwOn()){const h=$('mwHud');if(h)h.remove();const gb=$('goalBox');if(gb&&gb.style.display==='none')gb.style.display='';return r}const M=S.mw,fe=$('focus');
 if(fe){fe.innerHTML=MW_FOC.map(f=>`<button class="fc ${S.focus===f[0]?'on':''}" ${focusOK(f[0])?'':'disabled'} onclick="setFocus('${f[0]}')">${f[1]} ${f[2]}</button>`).join('');
  let h=$('mwHud');if(!h){h=document.createElement('div');h.id='mwHud';fe.parentNode.insertBefore(h,fe)}
  const bar=(ic,n,v,col,max)=>`<div class="mwh1"><span>${ic} ${n}</span><b>${max?Math.round(v):fmt(v)}${max?'/'+max:''}</b>${max?`<i style="width:${Math.min(100,v/max*100)}%;background:${col}"></i>`:''}</div>`;
  h.innerHTML=`<div class="mwhT">🏙️ กรุงเทพฯ · ค.ศ. ${MW_Y0+M.y} · ปีที่ ${M.y} ในยุคนี้ <span class="tag2">${mwTag()}</span></div><div class="mwhG">${bar('🤫','ความลับรั่ว',M.sec,M.sec>=60?'#ff4a5a':'#e8a23a',100)}${bar('🏙️','ความคุ้นเคย',M.adapt,'#4ab0ff',100)}${bar('📈','ผู้ติดตาม',M.fame)}${bar('🌀','ปราณ',M.qi)}${M.linMet?bar('🧒','หลิน',M.lin,'#6ad08a',100):''}</div>`}
 const gb=$('goalBox');if(gb)gb.style.display='none'; const gr=$('gRealm');if(gr)gr.textContent=`ยอดฝีมือหลงยุค · อดีต${M.past.realm||''}`}catch(e){console.error(e)}return r}}
{const _dsW=drawScene;let off=null;drawScene=function(ctx,type){if(!mwOn()||type==='death')return _dsW.apply(this,arguments);try{if(!off){off=document.createElement('canvas');off.width=480;off.height=270}const o=off.getContext('2d');mwDraw(o,frame*1.4);const W=ctx.canvas.width,H=ctx.canvas.height,sh=Math.round(270*H/(W*270/480));ctx.setTransform(1,0,0,1,0,0);ctx.imageSmoothingEnabled=false;ctx.drawImage(off,0,Math.round((270-sh)*.6),480,sh,0,0,W,H)}catch(e){return _dsW.apply(this,arguments)}}}
{const _scW=sceneCap;sceneCap=function(t){if(mwOn()&&t!=='death'){const f=MW_FOC.find(x=>x[0]===S.focus);return`🏙️ กรุงเทพฯ ${MW_Y0+S.mw.y} · กำลัง: ${f?f[2]:'ใช้ชีวิต'}`}return _scW.apply(this,arguments)}}
