{const _chW=choice;choice=function(title,text,opts){if(mwAllowed()&&/รอยแยกสู่อนาคต/.test(String(title||''))&&Array.isArray(opts)&&opts[0]&&!S.mw){opts=opts.slice();opts[0]={t:'👣 ก้าวเข้าไปในรอยแยก'+(admK()&&!MW_PUBLIC?' (แอดมิน: เข้ายุคปัจจุบัน)':' · สู่ยุคปัจจุบัน'),s:'เก็บวิชาไว้ แต่พลังจะเหลือเพียงเล็กน้อย',f(){setTimeout(()=>mwEnter('rift'),300)}}}return _chW.call(this,title,text,opts)};Object.keys(_chW).forEach(k=>{try{choice[k]=_chW[k]}catch(e){}});
 try{Object.defineProperty(choice,'_cur',{get(){return _chW._cur},set(v){_chW._cur=v},configurable:true});Object.defineProperty(choice,'_min',{get(){return _chW._min},set(v){_chW._min=v},configurable:true})}catch(e){}}
// ทางเข้า 2: เมนูในเกม (แอดมิน) — พาตัวละครที่กำลังเล่นข้ามยุค
{const _omW=openMenu;openMenu=function(){const r=_omW.apply(this,arguments);try{if(!mwAllowed()||!S||!S.alive)return r;const gd=$('modal').querySelector('.mgrid');if(gd&&!gd.querySelector('.mwadmB'))gd.insertAdjacentHTML('afterbegin',S.mw?`<button class="opt mwadmB" onclick="mwInfo()">🏙️ ยุคปัจจุบัน<small>ดูสถานะองก์แรก</small></button>`:`<button class="opt mwadmB" onclick="mwAsk()">🌀 หลงยุคสู่ปี ${MW_Y0}<small>${admK()&&!MW_PUBLIC?'แอดมิน · ทดสอบยุคปัจจุบัน':'ยุคปัจจุบัน · เบต้า'}</small></button>`)}catch(e){}return r}}
function mwAsk(){modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>🌀 หลงยุคสู่ปี ${MW_Y0}</h3><p><b>${esc(S.name)}</b> จะข้ามไปยุคปัจจุบัน พร้อมความทรงจำและวิชาทั้งหมด แต่พลังเหลือราว 1 ใน 100 เพราะปราณเบาบาง</p><p class="tag2">${mwTag()} · ชีวิตนี้จะไม่ขึ้นทำเนียบ · ย้อนกลับไม่ได้</p><div class="brow"><button class="gbtn" onclick="closeM()">ยกเลิก</button><button class="pbtn" onclick="closeM();mwEnter('menu')">ข้ามยุค</button></div>`,'mwask')}
function mwInfo(){const M=S.mw,P=M.past,done=Object.keys(M.seen).length;modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>🏙️ ยอดฝีมือหลงยุค · องก์แรก</h3><p>ปีที่ ${M.y} ในยุคนี้ · เหตุการณ์หลักที่ผ่านมา ${done}/15${M.act1!=null?' · จบองก์แรกแล้ว':''}</p><p class="tag2">อดีต: ${esc(P.n)} · ${esc(P.realm||'')} ${P.sect?'· '+esc(P.sect):''} ${P.foe?'· ศัตรู '+esc(P.foe):''}</p><button class="pbtn" style="width:100%" onclick="closeM()">ปิด</button>`,'mwinfo')}
// ทางเข้า 3: ปุ่ม "ยุคปัจจุบัน" หน้าแรก (แอดมิน) — เริ่มเป็นยอดฝีมือหลงยุคจากชีวิตล่าสุดที่จบไป
{const _otW=openMWTeaser;openMWTeaser=function(src){if(!mwAllowed()||src==='rift'||src==='end')return _otW.apply(this,arguments);const L=(LS.get('murim_legacy',[])||[])[0];
 modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>🏙️ ยุคปัจจุบัน <span class="tag2">${mwTag()}</span></h3><p>${admK()&&!MW_PUBLIC?'ผู้เล่นทั่วไปยังเห็นหน้าตัวอย่าง "เร็วๆ นี้" เหมือนเดิม':'ข้ามยุคไปใช้ชีวิตในโลกปัจจุบัน ระบบนี้ยังเป็นเบต้า เจอบั๊กแจ้งได้ที่ ☰ → 🐞 แจ้งบั๊ก'}</p>
 <div class="mgrid"><button class="opt" onclick="mwNewLost()">🌀 ยอดฝีมือหลงยุค<small>${L?`ใช้ชีวิตล่าสุด: ${esc(L.n)} (${L.a} ปี)`:'สร้างยอดฝีมือขึ้นมาใหม่'}</small></button><button class="opt" onclick="_mwTeaser()">🎬 ดูหน้าตัวอย่าง<small>แบบที่ผู้เล่นทั่วไปเห็น</small></button></div><p class="tag2">หรือระหว่างเล่น: ☰ เมนู → 🌀 หลงยุคสู่ปี ${MW_Y0} เพื่อพาตัวละครที่เล่นอยู่ข้ามยุค (ใช้ประวัติจริงทั้งหมด)</p>`,'mwadm')}
 window._mwTeaser=()=>_otW('title')}
function mwNewLost(){const L=(LS.get('murim_legacy',[])||[])[window._mwLI|0];window._mwLI=0;closeM();try{CFG.xian=L&&L.ri>=0&&false?1:0;goBirth();doRoll(true);startLife()}catch(e){console.error(e);return}
 setTimeout(()=>{try{if(choice._cur)choice._cur=null;if(modalOpen)closeM();if(L){S.name=L.n;if(L.fac){const f=(typeof FACTIONS!=='undefined'?FACTIONS:[]).find(x=>x.n===L.fac||x.n0===L.fac);if(f){S.faction=f;S.rank=4}}if(L.art){const a=newArt(Math.max(0,Math.min(3,(L.art.r|0)-1)));a.n=L.art.n;S.arts.push(a)}}
  S.age=L?Math.max(30,Math.min(90,L.a||45)):45;S.power=Math.max(S.power,R(30000,80000));S.qi=Math.max(S.qi,200);S.int+=60;
  if(!S.parents||!S.parents.length)try{mkFamily()}catch(e){}if(L&&L.fac&&!S.faction)S._mwFac=L.fac;keyAdd('ยอดฝีมืออันดับต้นแห่งยุค');mwEnter('new')}catch(e){console.error(e)}},700)}
