const mwCC=()=>MW_CC[(S&&S.mw&&S.mw.cc)||'th']||MW_CC.th;
const _mwKeys={};
function mwLoc(x){if(typeof x!=='string'||!x||!mwOn())return x;const C=mwCC();if(!C.m&&C.lin==='หลิน')return x;
 const P=S.mw.past||{},nm=[S.name,P.n,P.mom,P.foe,P.kid,P.sect,P.sur,P.fam,P.art,P.wpn,P.realm].filter(v=>v&&String(v).length>=2).map(String).sort((a,b)=>b.length-a.length),ms=[];
 nm.forEach(v=>{if(x.includes(v)){x=x.split(v).join('\u0001'+ms.length+'\u0002');ms.push(v)}});
 if(C.m){const K=_mwKeys[S.mw.cc]||(_mwKeys[S.mw.cc]=Object.keys(C.m).sort((a,b)=>b.length-a.length));for(const k of K)if(x.includes(k))x=x.split(k).join(C.m[k])}
 x=x.replace(/([+−\-]?)([\d,]+) บาท/g,(a,sg,n)=>{const v=+n.replace(/,/g,'')*C.rate;return sg+fmt(v>=100?Math.round(v):Math.round(v*100)/100)+' '+C.cur});
 if(C.cur!=='บาท')x=x.replace(/บาท/g,C.cur);
 if(C.city!=='กรุงเทพฯ')x=x.split('กรุงเทพฯ').join(C.city);
 if(C.lin!=='หลิน')x=x.split('หลิน').join(C.lin);
 return x.replace(/\u0001(\d+)\u0002/g,(a,i)=>ms[+i])}
// แปลข้อความทุกจุดที่เหตุการณ์ยุคปัจจุบันส่งออก
{const _lgC=log;log=function(t,...r){return _lgC.call(this,mwLoc(t),...r)}}
{const _afC=addFeed;addFeed=function(k,t,...r){return _afC.call(this,k,mwLoc(t),...r)}}
{const _chC=choice;choice=function(title,text,opts){if(mwOn()&&mwCC().m||mwOn()&&mwCC().lin!=='หลิน'){title=mwLoc(title);text=mwLoc(text);if(Array.isArray(opts))opts=opts.map(o=>o?Object.assign({},o,{t:mwLoc(o.t),s:mwLoc(o.s)}):o)}return _chC.call(this,title,text,opts)};for(const k of Object.keys(_chC))try{choice[k]=_chC[k]}catch(e){}}
// เลือกประเทศตอนข้ามยุค (ทางรอยแยก = สุ่ม)
{const _meC=mwEnter;mwEnter=function(how,cc){const r=_meC.apply(this,arguments);try{if(S.mw&&!S.mw.cc){const k=cc||window._mwCC;S.mw.cc=MW_CC[k]?k:ch(Object.keys(MW_CC));window._mwCC=null;const C=mwCC();addFeed('ev',`${C.f} คุณตื่นขึ้นในประเทศ<b>${C.n}</b> — เมือง${C.city} ปี ${MW_Y0}`,'sum');render();saveGame()}}catch(e){console.error(e)}return r}}
function mwPickCC(nx){window._mwNx=nx;modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>🌍 จะตื่นขึ้นที่ไหน</h3><div class="mgrid">${Object.entries(MW_CC).map(([k,C])=>`<button class="opt" onclick="window._mwCC='${k}';closeM();setTimeout(window._mwNx,150)">${C.f} ${C.n}<small>${C.city}</small></button>`).join('')}<button class="opt" onclick="window._mwCC=null;closeM();setTimeout(window._mwNx,150)">🎲 สุ่ม<small>ให้รอยแยกเลือก</small></button></div>`,'mwcc')}
// ปุ่มข้ามยุคในเมนู และหน้าแรก → เลือกประเทศก่อน
mwAsk=function(){modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>🌀 หลงยุคสู่ปี ${MW_Y0}</h3><p><b>${esc(S.name)}</b> จะข้ามไปยุคปัจจุบัน พร้อมความทรงจำและวิชาทั้งหมด แต่พลังเหลือราว 1 ใน 100 เพราะปราณเบาบาง</p><p class="tag2">${mwTag()} · ชีวิตนี้จะไม่ขึ้นทำเนียบ · ย้อนกลับไม่ได้</p><div class="brow"><button class="gbtn" onclick="closeM()">ยกเลิก</button><button class="pbtn" onclick="closeM();setTimeout(()=>mwPickCC(()=>mwEnter('menu',window._mwCC)),150)">ข้ามยุค</button></div>`,'mwask')};
{const _nlC=mwNewLost;mwNewLost=function(){if(window._mwPicked){window._mwPicked=0;const k=window._mwCC;_nlC.apply(this,arguments);window._mwCC=k;return}closeM();setTimeout(()=>mwPickCC(()=>{window._mwPicked=1;mwNewLost()}),150)}}
// HUD / ป้ายฉาก ตามประเทศ
{const _rnC=render;render=function(){const r=_rnC.apply(this,arguments);try{if(mwOn()){const C=mwCC(),t=document.querySelector('#mwHud .mwhT');if(t&&C.city!=='กรุงเทพฯ')t.innerHTML=t.innerHTML.replace('🏙️ กรุงเทพฯ',`${C.f} ${C.city}`);else if(t)t.innerHTML=t.innerHTML.replace('🏙️ กรุงเทพฯ',`${C.f} กรุงเทพฯ`);
 const fe=$('focus');if(fe&&C.lin!=='หลิน'){const b=fe.querySelector('[onclick*="mwlin"]');if(b)b.innerHTML=`🧒 อยู่กับ${C.lin}`}const hb=[...document.querySelectorAll('#mwHud .mwh1 span')].find(x=>/หลิน/.test(x.textContent));if(hb&&C.lin!=='หลิน')hb.textContent=`🧒 ${C.lin}`}}catch(e){}return r}}
{const _scC=sceneCap;sceneCap=function(t){const r=_scC.apply(this,arguments);return mwOn()?mwLoc(r):r}}
// ฉาก: แลนด์มาร์ก + โทนสีของแต่ละเมือง
function mwSkin(c,t){const cc=S.mw.cc;if(!cc||cc==='th')return;const C=mwCC();c.save();c.setTransform(3,0,0,3,0,0);c.beginPath();c.rect(0,0,160,47);c.clip();c.translate(52,13);
 const F=(x,y,w,h,col,a)=>{c.globalAlpha=a==null?1:a;c.fillStyle=col;c.fillRect(x,y,w,h)};const dk='#2c2266',lt='#ffe08a',bl=(t|0)%40<28;
 if(cc==='us'){F(26,30,12,20,dk);F(28,22,8,10,dk);F(30,16,4,8,dk);F(31.5,6,1,10,dk);F(26,30,.6,20,'#6a5ad0');F(28,22,.6,10,'#6a5ad0');F(30,16,.6,8,'#6a5ad0');for(let y=24;y<46;y+=3)for(let x=27;x<37;x+=2.5)if(srand(x*7+y)>.45)F(x,y,1,1,lt,.8);if(bl)F(31.5,5,1,1,'#ff3050')}
 else if(cc==='jp'){const o='#ff5a2a';for(let y=8;y<46;y+=1){const w=1+(y-8)*.42;F(30-w/2,y,w,1,(y%3===0)?'#ffffff':o,.92)}F(26,22,8,2.4,o);F(24,33,12,2.6,o);if(bl)F(29.5,6,1,2,'#ff3050')}
 else if(cc==='kr'){c.globalAlpha=1;c.fillStyle='#120a2a';c.beginPath();c.ellipse(32,52,28,12,0,0,7);c.fill();F(31,14,2,30,'#d8d8f0');F(28,14,8,4,'#d8d8f0');F(28.5,15,7,1,'#a060ff');F(31.6,6,.8,8,'#d8d8f0');if(bl)F(31.5,5,1,1,'#ff3050')}
 else if(cc==='cn'){const p='#ff4aa8';F(31,6,1,40,'#c8c0e0');c.fillStyle=p;c.globalAlpha=.95;c.beginPath();c.arc(31.5,34,5.5,0,7);c.fill();c.beginPath();c.arc(31.5,21,3.8,0,7);c.fill();c.beginPath();c.arc(31.5,12,1.8,0,7);c.fill();F(26,38,1.2,8,'#c8c0e0');F(36,38,1.2,8,'#c8c0e0')}
 else if(cc==='tw'){for(let k=0;k<8;k++){const y=44-k*4;F(28,y-4,8,4,dk);F(27,y-4,10,1,dk);F(29,y-3,6,.6,'#30e0a0',.9);F(27,y-1,10,.5,'#7af0c8',.5)}F(30,8,4,4,dk);F(31.5,2,1,6,dk);if(bl)F(31.5,1.5,1,1,'#ff3050')}
 c.restore();c.save();c.globalCompositeOperation='overlay';c.globalAlpha=.22;c.fillStyle=C.col;c.fillRect(0,0,480,270);c.restore()}
