const mwJobOf=M=>M.job&&MW_JOBS[M.job.id];
const mwJP=(J,M,lv)=>(J.p[M.cc||'th']||J.p.th)[lv==null?M.job.lv:lv];
const mwLocal=(v,M)=>{const C=MW_CC[M.cc||'th']||MW_CC.th;return fmt(Math.round(v))+' '+C.cur}; // แสดงเงินท้องถิ่นตรงๆ (ไม่ผ่านการแปลง)
const mwToB=(v,M)=>Math.round(v/((MW_CC[M.cc||'th']||MW_CC.th).rate));   // ท้องถิ่น → บาท (หน่วยเงินภายในเกม)
function mwJobReq(J,M){const r=J.req||{};if(r.adapt&&M.adapt<r.adapt)return`ต้องมีความคุ้นเคยยุคใหม่ ${r.adapt}+ (ตอนนี้ ${Math.round(M.adapt)})`;if(r.edu&&!M.fl.edu)return'ต้องมีวุฒิการศึกษา (สอบเทียบให้ผ่านก่อน)';return''}
// ---------- หน้าหางาน ----------
function openJobs(){const M=S.mw;if(!M)return;const cur=M.job&&M.job.id;
 const cards=Object.entries(MW_JOBS).map(([id,J])=>{const P=J.p[M.cc||'th']||J.p.th,why=mwJobReq(J,M),me=cur===id;
  return `<div class="jobC${me?' on':''}"><div class="jobH">${J.ic} <b>${esc(P[0][0])}</b>${me?' <span class="tag2">· งานปัจจุบัน</span>':''}</div><div class="jobP">${J.fight?'ค่าตัวต่อไฟต์':'รายได้ต่อเดือน'} <b>${mwLocal(P[0][1],M)}</b> → สูงสุด <b>${mwLocal(P[2][1],M)}</b> (${esc(P[2][0])})</div><div class="tag2">${esc(J.d)}</div>${why?`<div class="jobX">🔒 ${why}</div>`:me?'':`<button class="gbtn jobA" onclick="mwApply('${id}')">สมัครงาน</button>`}</div>`}).join('');
 modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>💼 ประกาศรับสมัครงาน · ${mwCC().f} ${mwCC().city}</h3><p class="tag2">ค่าแรงขั้นต่ำที่นี่ราว ${mwLocal(MW_MIN[M.cc||'th'],M)}/เดือน · เปลี่ยนงานแล้วตำแหน่งเริ่มใหม่</p><div class="jobL">${cards}</div>`,'jobs')}
function mwApply(id){const M=S.mw,J=MW_JOBS[id];if(!J||mwJobReq(J,M))return;closeM();
 const ok=Math.random()<(id==='office'?.65:.9);if(!ok){mwSay(`📄 คุณไปสัมภาษณ์งาน${esc(mwJP(J,M,0)[0])} กรรมการถามว่า "ประสบการณ์ทำงานล่าสุดคือที่ไหนครับ" คุณตอบว่า "${esc(M.past.sect||'ยุทธภพ')}" — ไม่ผ่าน`,'',{adapt:2});return}
 M.job={id,lv:0,y:0,perf:50};S.focus='mwjob';mwSay(`${J.ic} <b>ได้งานแล้ว:</b> ${esc(mwJP(J,M)[0])} · ${J.fight?'ค่าตัวไฟต์ละ':'เงินเดือน'} ${mwLocal(mwJP(J,M)[1],M)}`,'good',{joy:5});render();saveGame()}
// ---------- ทำงานทั้งปี ----------
function mwJobYear(M){const C=MW_CC[M.cc||'th']||MW_CC.th,J=mwJobOf(M);
 if(!J){const loc=MW_MIN[M.cc||'th']*12*(.6+Math.random()*.25)*(M.fl.agency?2:1),b=mwToB(loc,M);mwFx({mon:b,adapt:2});addFeed('ev',`💼 ${M.fl.agency?'ทำงานให้หน่วยลับ':'รับจ้างรายวันทั่วไป (ยังไม่มีงานประจำ)'} · ทั้งปีได้ราว ${mwLocal(loc,M)} <span class="tag2">— ดูงานประจำได้ที่ปุ่ม 💼 หางาน</span>`,'sum');return}
 const jb=M.job,[title,pay]=mwJP(J,M);let loc=0,note='';
 if(J.fight){const n=R(2,4);let w=0;for(let i=0;i<n;i++)if(Math.random()<.72+jb.perf/500)w++;loc=pay*w+pay*.5*(n-w);note=`${n} ไฟต์ ชนะ ${w}`;M.fame+=J.fx.fame*w;jb.perf=mwCl(jb.perf+(w*2-n)*6,0,100);if(n-w>0)S.hp=Math.max(10,S.hp-12*(n-w))}
 else{loc=pay*12*(.9+jb.perf/500);const bo=J.bonus&&J.bonus[M.cc||'th'];if(bo){loc+=pay*bo;note=`รวมโบนัส ${bo} เดือน`}jb.perf=mwCl(jb.perf+R(-6,10),0,100)}
 const fx=Object.assign({},J.fx);delete fx.fame;if(fx.hp){S.hp=Math.max(10,S.hp+fx.hp);delete fx.hp}if(!J.fight&&J.fx.fame)M.fame+=J.fx.fame;
 mwFx(Object.assign(fx,{mon:mwToB(loc,M)}));jb.y++;
 addFeed('ev',`${J.ic} ${esc(title)} ทั้งปี${note?' ('+note+')':''} · รายได้รวม ${mwLocal(loc,M)} · ผลงาน ${Math.round(jb.perf)}/100`,'sum');
 if(jb.lv<2&&jb.y>=J.up[jb.lv]&&jb.perf>=(jb.lv?75:55)&&Math.random()<.6){jb.lv++;jb.y=0;const P=mwJP(J,M);log(`📈 <b>ได้เลื่อนตำแหน่ง!</b> ${J.ic} ${esc(P[0])} · ${J.fight?'ค่าตัวไฟต์ละ':'เงินเดือน'} ${mwLocal(P[1],M)}`,'epic',true);keyAdd('เลื่อนเป็น'+mwTxt(P[0]))}
 else if(jb.perf<15&&Math.random()<.5){log(`📉 ${esc(title)} — ผลงานแย่ติดต่อกันจน${J.fight?'ไม่มีรายการไหนเรียกไปชก':'ถูกเลิกจ้าง'}`,'bad',true);M.job=null;return}
 if(Math.random()<.45)mwJobEv(M,J)}
function mwJobEv(M,J){const L=(MW_JEV[M.job.id]||[]).filter(e=>!(M.jev||{})[e.id]||M.y-M.jev[e.id]>=6);if(!L.length)return;const e=ch(L);(M.jev=M.jev||{})[e.id]=M.y;const me=S;
 setTimeout(()=>{const go=()=>{if(S!==me||!S||!S.alive||!S.mw||!S.mw.job)return;if(choice._cur)return setTimeout(go,700);try{e.go(S.mw,mwJP(J,S.mw)[0],J)}catch(x){console.error(x)}};go()},1300)}
const jp_=(M,d)=>{if(M.job)M.job.perf=mwCl(M.job.perf+d,0,100)};
const jPay=(M,mon)=>mwToB(mwJP(MW_JOBS[M.job.id],M)[1]*mon,M); // เงินเท่ากับกี่เดือนของเงินเดือน → บาท
// ---------- เหตุการณ์ของแต่ละอาชีพ (งานจริง) ----------
