function openAssets(){const M=S.mw;if(!M)return;const C=mwCO(M),A=mwAst(M),c=mwYearCost(M),mL=v=>mwLocal(v,M),my=(S.money||0)*mwCC().rate;
 const row=(ic,t,sub,btn)=>`<div class="jobC"><div class="jobH">${ic} <b>${t}</b></div><div class="tag2">${sub}</div>${btn||''}</div>`,B=(f,t,dis)=>`<button class="gbtn jobA" ${dis?'disabled style="opacity:.5"':''} onclick="${f}">${t}</button>`;
 const hp=C.home[1];
 modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>🏠 บ้านและทรัพย์สิน · ${mwCC().f} ${mwCC().city}</h3>
 <p class="tag2">เงินที่มี <b>${mL(my)}</b> · ค่าครองชีพต่อเดือน <b>${mL(c.mon)}</b>${A.mort?` + ผ่อนบ้านปีละ ${mL(A.mort)} (เหลือ ${A.mortY} ปี)`:''} · เงินออมเกษียณ ${mL((A.save||0)*mwCC().rate)}</p><div class="jobL">
 ${row('🏚️',`ที่อยู่: ${A.h===2?esc(C.home[0])+' (ของตัวเอง)':A.h===1?esc(C.rent0):esc(C.room0)}`,`ห้องถูก ${mL(C.room)}/เดือน · ${esc(C.rent0)} ${mL(C.rent1)}/เดือน (สบายขึ้น ทุกปีมีความสุขเพิ่ม)`,A.h===0?B('mwAs(\'rent1\')','ย้ายไปห้องดีกว่า'):A.h===1?B('mwAs(\'rent0\')','ย้ายกลับห้องถูก'):'')}
 ${A.h<2?row('🏠',`ซื้อ${esc(C.home[0])}`,`ราคา ${mL(hp)} · จ่ายสด หรือดาวน์ 20% (${mL(hp*.2)}) แล้วผ่อน 25 ปี ปีละ ${mL(hp*.8*1.45/25)}`,B('mwAs(\'cash\')','จ่ายสด',my<hp)+B('mwAs(\'mort\')','ดาวน์+ผ่อน',my<hp*.2||A.mort)):''}
 ${row('🛵',esc(C.bike[0]),`${mL(C.bike[1])} · ไรเดอร์ที่มีรถเองได้ค่ารอบเต็ม (ไม่มีรถถูกหักค่าเช่ารถ 20%)`,A.bike?'<div class="tag2">✅ มีแล้ว</div>':B('mwAs(\'bike\')','ซื้อ',my<C.bike[1]))}
 ${row('🚗',esc(C.car[0]),`${mL(C.car[1])} · เดินทางสะดวก ความคุ้นเคยยุคใหม่และความสุขเพิ่มทุกปี`,A.car?'<div class="tag2">✅ มีแล้ว</div>':B('mwAs(\'car\')','ซื้อ',my<C.car[1]))}
 ${row('🩺',esc(C.ins[0]),`${mL(C.ins[1])}/เดือน · ป่วยหรือบาดเจ็บหนัก ค่ารักษาลดลงมาก${M.cc==='us'?' (อเมริกาไม่มีประกัน ค่ารักษาแพงมาก)':''}`,A.ins?B('mwAs(\'insX\')','ยกเลิก'):B('mwAs(\'ins\')','ทำประกัน'))}
 ${row('🐷','เงินออมเกษียณ',`ฝากไว้แตะไม่ได้จนอายุ 60 ได้ดอกปีละ 3% แล้วค่อยๆ ถอนมาใช้ตอนแก่`,B('mwAs(\'save\')',`ฝาก ${mL(Math.round(my*.2))}`,my<100))}
 </div>`,'assets')}
function mwAs(k){const M=S.mw,C=mwCO(M),A=mwAst(M),r=mwCC().rate,pay=v=>{const b=mwToB(v,M);if((S.money||0)<b){toast('เงินไม่พอ');return false}S.money-=b;return true};
 if(k==='rent1'){A.h=1;mwSay(`📦 ย้ายเข้า${esc(C.rent0)} มีห้องน้ำในตัวและหน้าต่างที่เห็นฟ้า`,'good',{joy:5})}
 else if(k==='rent0'){A.h=0;mwSay(`📦 ย้ายกลับ${esc(C.room0)} ประหยัดขึ้นเดือนละ ${mwLocal(C.rent1-C.room,M)}`,'',null)}
 else if(k==='cash'){if(!pay(C.home[1]))return;A.h=2;mwSay(`🔑 คุณซื้อ<b>${esc(C.home[0])}</b>ด้วยเงินสด บ้านหลังแรกที่เป็นของคุณจริงๆ ในยุคนี้`,'myth',{joy:15},true);keyAdd('ซื้อบ้านในยุคปัจจุบัน')}
 else if(k==='mort'){if(!pay(C.home[1]*.2))return;A.h=2;A.mort=Math.round(C.home[1]*.8*1.45/25);A.mortY=25;mwSay(`🏦 ธนาคารอนุมัติสินเชื่อบ้าน 25 ปี คุณอยู่มาแล้วเจ็ดร้อยปี แต่เพิ่งเคยเป็นหนี้ธนาคารครั้งแรก`,'good',{joy:8},true);keyAdd('ผ่อนบ้านในยุคปัจจุบัน')}
 else if(k==='bike'){if(!pay(C.bike[1]))return;A.bike=1;mwSay(`🛵 ได้${esc(C.bike[0])}มาแล้ว คุณขับช้ากว่าวิ่งเองหลายเท่า แต่ไม่มีใครถ่ายคลิป`,'good',{adapt:3})}
 else if(k==='car'){if(!pay(C.car[1]))return;A.car=1;mwSay(`🚗 ได้${esc(C.car[0])}มาแล้ว สอบใบขับขี่ผ่านครั้งที่สาม ครูฝึกบอกว่าคุณ "เบรกเร็วเกินมนุษย์"`,'good',{adapt:5,joy:6})}
 else if(k==='ins'){A.ins=1;mwSay(`🩺 ทำ${esc(C.ins[0])}แล้ว`,'',null)}
 else if(k==='insX'){A.ins=0;mwSay('🩺 ยกเลิกประกันแล้ว ประหยัดได้ แต่ถ้าป่วยต้องจ่ายเองทั้งหมด','',null)}
 else if(k==='save'){const b=Math.round((S.money||0)*.2);S.money-=b;A.save=(A.save||0)+b;mwSay(`🐷 ฝากเงินออมเกษียณ ${mwLocal(b*r,M)}`,'',null)}
 render();saveGame();openAssets()}
