// ---------- ภาพ: ฉากเปลี่ยนตามงาน/สิ่งที่ทำ + ฤดู ----------
function mwSkin2(c,t){const M=S.mw;if(!M)return;const F=(x,y,w,h,col,a)=>{c.globalAlpha=a==null?1:a;c.fillStyle=col;c.fillRect(x,y,w,h)};c.save();c.setTransform(3,0,0,3,0,0);
 const j=M.job&&M.job.id,f=S.focus,bl=(t|0)%30<18;
 if(j==='rider'&&f==='mwjob'){const x=((t*2.2)%200)-30;F(x,70,7,2.5,'#2ad080');F(x+1,67,4,3,'#20a060');F(x+1,72,2,2,'#111');F(x+5,72,2,2,'#111');F(x+2,65,2,2,'#ffd8a0');F(x+5,66,3,3,'#ff7a20')}
 if(j==='build'){F(118,20,1.5,46,'#ffb020');F(100,20,30,1.5,'#ffb020');F(104,21,.6,(t%40)/2+4,'#ccc');F(102,30+(t%40)/2,4,3,'#888')}
 if(j==='guard'){F(132,60,10,8,'#3a4a6a');F(133,61,8,3,bl?'#ffe080':'#806020')}
 if(j==='office'){for(let i=0;i<14;i++)F(60+(i%7)*4,38+Math.floor(i/7)*4,2,2,'#bfe8ff',.9)}
 if(j==='stunt'){c.globalAlpha=.18;c.fillStyle='#fff8d0';c.beginPath();c.moveTo(150,10);c.lineTo(110,70);c.lineTo(135,70);c.fill()}
 if(j==='fight'){F(96,40,26,2,'#ff3040',bl?.9:.4);F(96,40,1,10,'#ff3040');F(121,40,1,10,'#ff3040')}
 if(j==='heal'||j==='coach'){F(140,50,14,5,j==='heal'?'#2ad080':'#ff6040');F(141,51,12,1,'#fff',.6)}
 if(f==='mwqi'){c.globalCompositeOperation='lighter';for(let i=0;i<10;i++){const a=t*.05+i*.63;F(28+Math.cos(a)*9,50+Math.sin(a)*5-(i%3),1,1,'#8ff0ff',.7)}c.globalCompositeOperation='source-over'}
 const sea=(MW_Y0+M.y)%4;if(sea===1){for(let i=0;i<30;i++)F((i*41+t*1.5)%160,(i*23+t*2.4)%90,.5,2,'#9ab8ff',.45)}else if(sea===3&&['jp','kr','cn','us'].includes(M.cc)){for(let i=0;i<24;i++)F((i*37+t*.3)%160,(i*19+t*.6)%90,1,1,'#fff',.7)}
 if(M.fl.public){F(0,0,160,1.5,'#ff3050',.7)}
 c.restore()}
{const _mdF=mwDraw;mwDraw=function(c,t){const r=_mdF.apply(this,arguments);try{if(mwOn())mwSkin2(c,t)}catch(e){}return r}}
// ---------- หน้าจบ: ไม่ใช้ฉายา/ยุคแบบยุทธภพ ----------
function mwTitle(M){if(M.fl.public)return'ตำนานที่โลกรู้จัก';if(M.native)return'ทายาทคนหลงยุค';if(M.fl.sect==='elder')return'บรรพบุรุษผู้กลับมา';if(mwQi(M)>=5)return'ยอดฝีมือคืนชีพ';if((M.kids||[]).length)return'พ่อแม่ต่างยุค';if(M.jbest)return'ยอดฝีมือหลงยุค · '+mwTxt(M.jbest).split(' ')[0];return'ยอดฝีมือหลงยุค'}
{const _egT=endGame;endGame=function(){const r=_egT.apply(this,arguments);try{if(S&&S.mw){const E=$('end'),M=S.mw;if(E){const tw=document.createTreeWalker(E,NodeFilter.SHOW_TEXT);let n;while(n=tw.nextNode()){if(n.parentNode.closest&&n.parentNode.closest('.mwSum'))continue;const v=n.nodeValue;let w=v.replace(/「[^」]*」/,'「'+mwTitle(M)+'」').replace(/ยุคยุทธภพ\S*|ยุทธภพปกติ|ยุคที่[^·]*ไร้เทียมทาน/g,`${mwCC().f} ${mwCC().city} ค.ศ. ${MW_Y0+M.y}`).replace(/สามัญชนในยุทธภพ/g,mwTitle(M));if(w!==v)n.nodeValue=w}}}}catch(e){console.error(e)}return r}}


