{const _jyW=mwJobYear;mwJobYear=function(M){const m0=S.money||0;const r=_jyW.apply(this,arguments);try{if(M.job){const d=(S.money||0)-m0;let cut=0,why='';if(M.fl.robo&&M.job.id==='rider'){cut=.25;why='หุ่นยนต์ส่งอาหารแย่งงาน'}if(M.fl.aiOff&&M.job.id==='office'){cut=.15;why='AI ทำงานแทนบางส่วน'}if(cut&&d>0){S.money-=Math.round(d*cut);addFeed('ev',`📉 รายได้ลดลง ${Math.round(cut*100)}% — ${why}`,'sum')}if(M.fl.aiOff&&M.job.id==='office'&&Math.random()<.08){M.job=null;log('📦 บริษัทเลิกจ้างคุณ AI ทำงานในตำแหน่งนี้แทนแล้ว','bad',true)}}}catch(e){}return r}}
{const _myW=mwYear;mwYear=function(){const r=_myW.apply(this,arguments);try{const M=S&&S.alive&&S.mw;if(M&&M.fl.heat&&mwQi(M)<3)S.hp=Math.max(10,S.hp-4)}catch(e){}return r}}
