 if(M.bf)R.push(['🤝',M.bf.n,M.bf.d?'จากไปแล้ว':M.bf.k?'เพื่อนสนิท · รู้ความลับ':'เพื่อนสนิท']);if(M.fl.pa)R.push(['🍜',mwLoc('ป้าแดง'),M.seen&&M.rs&&M.rs.pa2!=null?'จากไปแล้ว':'ร้านประจำ']);if(M.fl.som)R.push(['👮',mwLoc('จ่าสมชาย'),M.rs&&M.rs.som2!=null?'จากไปแล้ว':M.fl.somF?'เพื่อนฟังตำนาน':'คนรู้จัก']);if(M.par)R.push(['🕯️',M.par.n,'พ่อ/แม่ (คนหลงยุค)']);if(M.fl.sectN)R.push(['🏯',M.fl.sectN,M.fl.sect==='elder'?'คุณคือปรมาจารย์':'สำนักคุณในอดีต']);(Array.isArray(M.fr)?M.fr:[]).forEach(n=>R.push(['🔗',n,'คนจากยุทธภพอีกคน']));R.push(['🥋','ศิษย์ในยุคนี้',`${M.dis||0} คน`]);
