function mwSkin3(c,t){const M=S.mw;if(!hwOn(M))return;c.save();c.setTransform(3,0,0,3,0,0);const cx=100,cy=31,R0=10+Math.sin(t*.05)*1.2;c.globalCompositeOperation='lighter';
 for(let i=0;i<3;i++){c.globalAlpha=.25-.06*i;c.strokeStyle=['#c050ff','#7a40ff','#ff40c0'][i];c.lineWidth=1.4;c.beginPath();c.ellipse(cx,cy,R0+i*2.5,R0*.55+i*1.4,Math.sin(t*.02)*.2,0,7);c.stroke()}
 const g=c.createRadialGradient(cx,cy,0,cx,cy,R0);g.addColorStop(0,'rgba(255,220,255,.55)');g.addColorStop(.5,'rgba(150,60,255,.35)');g.addColorStop(1,'rgba(80,0,160,0)');c.fillStyle=g;c.globalAlpha=1;c.beginPath();c.ellipse(cx,cy,R0,R0*.55,0,0,7);c.fill();
 for(let i=0;i<8;i++){const a=t*.04+i*.8;c.fillStyle='#e0b0ff';c.globalAlpha=.6;c.fillRect(cx+Math.cos(a)*(R0+4),cy+Math.sin(a)*(R0*.55+3),.8,.8)}c.restore()}
{const _mdHW=mwDraw;mwDraw=function(c,t){const r=_mdHW.apply(this,arguments);try{if(mwOn())mwSkin3(c,t)}catch(e){}return r}}
