 const od=tw(),base=TALENT.filter(x=>!x.id).map(x=>`<b>${x.n}</b> ×${x.m} (${od(x)})`).join(' · '),sp=TALENT.filter(x=>x.id).map(x=>`<b>${x.n}</b> ×${x.m} — ${x.d}`).join('<br>');
