// ---------------------------------------------------------------- เครื่องยนต์รายปี
function saOK(){return S&&S.alive&&!(S.beastMode&&!S.beastMode.human)&&!(typeof mwOn==='function'&&mwOn())&&S.ch!=='short'}
function saTick(){if(!saOK())return;const A=S.sarc;
 if(A){const D=SA_ARCS.find(a=>a.id===A.id);if(!D){S.sarc=null;return}
  if(S.age===A.at-1&&!(A.h||{})[A.ch]){A.h=A.h||{};A.h[A.ch]=1;const h=(D.hint||[])[A.ch];if(h)log(h.replace(/\{(\w+)\}/g,(m,k)=>A.nm[k]||''),'',false)}
  if(S.age>=A.at){if(choice._cur||modalOpen){A.at=S.age+1;return}try{D.ch[A.ch](A)}catch(e){console.error(e);S.sarc=null}}return}
 if((S.arcN||0)>=3||S.age<(S.arcCd||0)||S.age<14||choice._cur||modalOpen||S._saY===S.age)return;S._saY=S.age;if(Math.random()>.12)return;
 const B=LS.get('murim_arcbook',{})||{},done=(S.arcDone||[]).map(x=>x.id);const pool=SA_ARCS.filter(a=>!done.includes(a.id)&&a.c());if(!pool.length)return;
 pool.sort((x,y)=>Object.keys(B[x.id]||{}).length-Object.keys(B[y.id]||{}).length+(Math.random()-.5)*2);const D=pool[0];
 const N={id:D.id,ch:0,at:S.age,v:{},nm:{},h:{}};D.init(N);S.sarc=N;log(`📖 <b>ภาคใหม่เริ่มต้น: ${D.ic} ${D.n}</b>`,'myth',true);try{D.ch[0](N)}catch(e){console.error(e);S.sarc=null}}
{const _pyA=passYear;passYear=function(){const r=_pyA.apply(this,arguments);try{if(S&&S.alive){setTimeout(()=>{try{saTick()}catch(e){console.error(e)}},60);setTimeout(()=>{try{if(S&&S.alive&&!S.sarc)saTick()}catch(e){}},2600)}}catch(e){}return r}}
// ตายกลางภาค → ลูกสานต่อ
{const _ihA=inherit;inherit=function(ci){const P=S,pa=P&&P.sarc?JSON.parse(JSON.stringify(P.arc)):null;const r=_ihA.apply(this,arguments);try{if(pa&&S!==P){const D=SA_ARCS.find(a=>a.id===pa.id);pa.at=Math.max(S.age+3,16);pa.v.heir=1;pa.h={};S.sarc=pa;setTimeout(()=>{try{log(`📖 ภาค「${D.n}」ของบรรพบุรุษยังไม่จบ บทที่ ${pa.ch+1} รอคุณอยู่`,'myth',true)}catch(e){}},500)}}catch(e){}return r}}
