function bcFeed(k){const B=S.beast;if(!B)return;if(S.bcFeedY!==S.age){S.bcFeedY=S.age;S.bcFeedN=0}if((S.bcFeedN||0)>=3)return toast('ปีนี้ป้อนครบ 3 ครั้งแล้ว');if(!bagHas(k)||!bagUse(k))return toast('ไม่มีแก่นอสูร');
 S.bcFeedN=(S.bcFeedN||0)+1;const xp=k==='bcore'?Math.max(10,B.lv*2):Math.max(3,Math.round(B.lv*.7));B.xp+=xp;B.bond=Math.min(100,B.bond+(k==='bcore'?8:3));const lv0=B.lv;while(B.xp>=B.lv*2&&B.lv<60){B.xp-=B.lv*2;B.lv++}
 try{const st0=B.st;beastCompTick();B.xp=Math.max(0,B.xp-1);B.bond=Math.max(0,B.bond-1)}catch(e){}
 log(`🐾 ${esc(B.nick)} กลืน${k==='bcore'?'แก่นอสูรโบราณ':'แก่นอสูร'}ลงไป ดวงตาเปล่งแสง EXP +${xp}${B.lv>lv0?` · เลเวล ${lv0} → <b>${B.lv}</b>`:''} · ความผูกพัน +${k==='bcore'?8:3}`,'epic');render();openBeastComp()}
{const _obc=openBeastComp;openBeastComp=function(){const r=_obc.apply(this,arguments);try{if(S&&S.beast){const m=$('modal'),br=m.querySelector('.brow');const n=S.bcFeedY===S.age?(S.bcFeedN||0):0;const c1=bagHas('core'),c2=bagHas('bcore');
 if(br&&!m.querySelector('.bcFeed'))br.insertAdjacentHTML('beforebegin',`<div class="bcFeed sysq" style="background:none;border:1px solid var(--line)">🍖 <b>ป้อนแก่นอสูร</b> <span class="tag2">(ปีนี้ ${n}/3)</span><br><span class="tag2">แก่นอสูร: EXP ≈ เลเวล×0.7 · แก่นอสูรโบราณ: EXP ≈ เลเวล×2 และผูกพัน +8</span><div class="brow" style="margin-top:6px"><button class="gbtn" ${c1&&n<3?'':'disabled'} onclick="bcFeed('core')">🔶 แก่นอสูร</button><button class="gbtn" ${c2&&n<3?'':'disabled'} onclick="bcFeed('bcore')">🔮 แก่นโบราณ</button></div></div>`)}}catch(e){console.error(e)}return r}}

