 const main=S.arts[idx[0]],food=idx.slice(1).map(i=>S.arts[i]).filter(Boolean);if(!main||!food.length)return;
 let xp=food.reduce((s,a)=>s+(a.b||0)*(typeof artM==='function'?artM(a):1)*(a.sect?.6:.4),0);main.fxp=(main.fxp||0)+Math.round(xp);const ups=[];
 const need=()=>Math.round((main.b||20)*(.6+.3*((main.lv|0)+(main.star|0))));
 while(main.fxp>=need()){main.fxp-=need();if((main.lv|0)<3){main.lv=(main.lv|0)+1;ups.push(AMN[main.lv])}else if((main.star|0)<5){main.star=(main.star|0)+1;ups.push('★'+main.star)}else{main.fxp=0;break}}
