function keepAdd(id){if(!KEEP[id])return;S.keep=S.keep||[];if(S.keep.includes(id))return;S.keep.push(id);const K=KEEP[id];log(`🎐 ได้ของคู่ชีวิต <b>${K[0]} ${K[1]}</b> — ${K[2]} (สวมได้ที่ ☰ → 🎐 ของคู่ชีวิต)`,'epic');if(!S.keepEq)S.keepEq=[];if(S.keepEq.length<2)S.keepEq.push(id)}
{const _seK=saEnd;saEnd=function(A,k){try{const m=KEEP_ARC[A.id];if(m&&m[k])setTimeout(()=>{try{keepAdd(m[k])}catch(e){}},200)}catch(e){}return _seK.apply(this,arguments)}}
{const _em=eqM;eqM=function(k){let m=_em.apply(this,arguments);try{if(k==='fight'&&S){m*=bwM();(S.keepEq||[]).forEach(id=>{const f=KEEP[id]&&KEEP[id][3];if(f&&f.fight)m*=1+f.fight})}}catch(e){}return m}}
function keepYear(){if(!S||!S.alive)return;(S.keepEq||[]).forEach(id=>{const f=KEEP[id]&&KEEP[id][3];if(!f)return;if(f.int)S.int+=f.int;if(f.joy)joy(f.joy);if(f.heal)S.hp=Math.min(S.maxHp,S.hp+Math.round(S.maxHp*f.heal));if(f.karma)S.karma+=f.karma;if(f.qi)S.qi+=f.qi;if(f.fame)S.fame+=f.fame;if(f.life&&Math.random()<f.life)sxLife(1)});
 const B=S.bw;if(B){if(['train','drill','adv','hunt','mission'].includes(S.focus))B.bond=Math.min(150,(B.bond|0)+1);bwCheck()}}
function bwCheck(){const B=S.bw;if(!B)return;while(B.st<3&&B.bond>=BW_NEED[B.st+1]){B.st++;S.power+=pctPow(.04);log(`⚔️ <b>${esc(B.n)}</b> ตื่นขั้นเป็น <b>${BW_ST[B.st]}</b>! ${BW_SK[B.st]} · พลังยุทธ์ +4%`,'myth',true);keyAdd(`อาวุธคู่ชีวิต ${B.n} ตื่นเป็น${BW_ST[B.st]}`)}}
{const _fgB=fight;fight=function(n,ep){const w=_fgB.apply(this,arguments);try{if(w&&S&&S.bw){S.bw.bond=Math.min(150,(S.bw.bond|0)+1);S.bw.kills=(S.bw.kills|0)+1;bwCheck()}}catch(e){}return w}}
{const _pyK=passYear;passYear=function(){const r=_pyK.apply(this,arguments);try{keepYear()}catch(e){}return r}}
