// ===================== v17.6 ตำนานบรรพกาล (หน้าตำนาน 12 หน้า) + ภาคใหม่: บรรพกาล 3 โลก · สัตว์อสูร · คู่ปรับ · ครอบครัว · นรก · ชีวิตสั้น · ชาติก่อน =====================
const LORE=[
 ['ศิลาแผ่นแรก','ก่อนจะมีฟ้า ก่อนจะมีดิน มีผู้ยืนอยู่ในความว่างเปล่าเก้าตน พวกเขาไม่มีชื่อ เพราะยังไม่มีใครให้เรียก'],
 ['ศิลาแผ่นที่สอง','ผู้ไร้นามทั้งเก้าแบ่งความว่างเปล่าออกเป็นสามชั้น ชั้นล่างให้มนุษย์ ชั้นกลางให้ผู้บำเพ็ญ ชั้นบนเก็บไว้ให้ตัวเอง นั่นคือยุทธภพ โลกเซียน และแดนเทพ'],
 ['ศิลาแผ่นที่สาม','พวกเขาถูกเรียกว่า "บรรพกาลเทพ" โดยสิ่งมีชีวิตแรกที่ลืมตาขึ้นมาเห็นพวกเขา และสิ่งมีชีวิตนั้นคือบรรพบุรุษของมนุษย์ทุกคน'],
 ['ม้วนไหมผนึก','บรรพกาลเทพองค์ที่เจ็ดรักมนุษย์มากเกินไป นางแอบมอบ "ราก" ให้มนุษย์บำเพ็ญได้ รากวิญญาณทุกเส้นในโลกนี้คือเศษเสี้ยวของนาง'],
 ['ม้วนไหมผนึกที่สอง','บรรพกาลเทพที่เหลือโกรธ พวกเขากลัวว่าสักวันมนุษย์จะขึ้นมาถึงชั้นบน จึงสร้างทัณฑ์สวรรค์ขึ้นมาเป็นประตูกั้น'],
 ['ม้วนไหมผนึกที่สาม','องค์ที่เจ็ดถูกผนึกไว้ใต้โลกเซียน ร่างของนางกลายเป็นภูเขาที่ผู้บำเพ็ญทั้งหลายนั่งสมาธิอยู่บนนั้นโดยไม่รู้ตัว'],
 ['ความทรงจำดวงดาว','แต่การสร้างทัณฑ์มีราคา ทุกครั้งที่ทัณฑ์ผ่าลง พลังของบรรพกาลเทพจะลดลงเล็กน้อย พวกเขาไม่รู้ว่ามนุษย์จะฝ่าทัณฑ์บ่อยขนาดนี้'],
 ['ความทรงจำดวงดาวที่สอง','หนึ่งกัลป์ผ่านไป บรรพกาลเทพอ่อนแรงจนต้องหลับใหล พวกเขาสร้าง "ผู้ล่าเทพ" ไว้เฝ้าแดนเทพ ให้ลงทัณฑ์ทุกคนที่ขึ้นมาถึง'],
 ['ความทรงจำดวงดาวที่สาม','ผู้ล่าเทพไม่ได้รู้จักความแตกต่างระหว่างผู้บุกรุกกับเทพ มันจึงฆ่าทุกองค์ รวมถึงผู้สร้างมันในการตื่นครั้งถัดมา'],
 ['หยดน้ำตาบรรพกาล','เหลือเพียงองค์ที่เจ็ดที่ถูกผนึก จึงรอดจากผู้ล่าเทพ นางรอคนที่ฝ่าได้ทั้งสามโลก เพื่อตัดสินว่าบรรพกาลควรกลับมาหรือไม่'],
 ['หยดน้ำตาบรรพกาลที่สอง','"ถ้ามนุษย์ผู้นั้นขึ้นมาถึงด้วยความโลภ จงผนึกข้าตลอดไป ถ้าขึ้นมาด้วยความเมตตา จงปลุกข้า ถ้าขึ้นมาด้วยความกล้า… จงแทนที่ข้า"'],
 ['หน้าสุดท้าย','หน้านี้ว่างเปล่า มีเพียงคำเดียวที่เขียนด้วยลายมือของคนที่อ่านทุกหน้ามาจนถึงตรงนี้: ชื่อคุณ']];
function loreGot(){return LS.get('murim_lore',{})||{}}
function loreAdd(i,why){const L=loreGot();if(L[i])return false;L[i]=1;LS.set('murim_lore',L);const n=Object.keys(L).length;log(`📜 พบ<b>${LORE[i][0]}</b>แห่งตำนานบรรพกาล${why?' — '+why:''} <span class="tag2">(${n}/12 · ☰ → 📜 ตำนานบรรพกาล)</span>`,'myth',true);return true}
function loreNext(range){const L=loreGot();const r=range.filter(i=>!L[i]);return r.length?r[0]:null}
function loreYear(){if(!S||!S.alive||(S.beastMode&&!S.beastMode.human)||(typeof mwOn==='function'&&mwOn()))return;if(S.loreY===S.age)return;S.loreY=S.age;
 const rg=S.xt?[6,7,8,9,10]:S.xian?[3,4,5]:[0,1,2];const i=loreNext(rg);if(i==null)return;const p=['adv','roam','hunt','study','read','qi'].includes(S.focus)?.035:.015;if(Math.random()<p)loreAdd(i,S.xt?'ความทรงจำลอยมาจากซากดาวที่ดับแล้ว':S.xian?'ซ่อนอยู่ในถ้ำใต้ภูเขาที่ปราณหนาแน่นผิดปกติ':'สลักอยู่บนศิลาเก่าในป่าลึก')}
{const _pyL=passYear;passYear=function(){const r=_pyL.apply(this,arguments);try{loreYear()}catch(e){}return r}}
function openLore(){const L=loreGot(),n=Object.keys(L).length;modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>📜 ตำนานบรรพกาล</h3><p class="tag2">หน้าตำนานกระจายอยู่ทั้งสามโลก (เก็บข้ามทุกชีวิต) · ยุทธภพ 3 หน้า · โลกเซียน 3 หน้า · แดนเทพ 5 หน้า · หน้าสุดท้ายต้องจบภาคบรรพกาล · พบแล้ว <b>${n}/12</b> · ออกท่องเที่ยว ศึกษา นั่งสมาธิ เจอบ่อยขึ้น และภาคบรรพกาลจะให้หน้าตำนาน</p>
 ${LORE.map((p,i)=>L[i]?`<details class="item"><summary><b>📜 ${p[0]}</b></summary><p style="line-height:1.7">${p[1]}</p></details>`:`<div class="item" style="opacity:.45"><b>🔒 ???</b> <span class="tag2">${i<3?'ยุทธภพ':i<6?'โลกเซียน':i<11?'แดนเทพ':'จบภาคบรรพกาลเทพ'}</span></div>`).join('')}`,'lore')}
{const _omL=openMenu;openMenu=function(){const r=_omL.apply(this,arguments);try{if(S&&!(typeof mwOn==='function'&&mwOn())){const g=document.querySelector('#modal .mgrid');if(g&&!g.querySelector('.loreOpt'))g.insertAdjacentHTML('beforeend',`<button class="opt loreOpt" onclick="openLore()">📜 ตำนานบรรพกาล<small>${Object.keys(loreGot()).length}/12 หน้า</small></button>`)}}catch(e){}return r}}
