function sqP(){return SQP[(S.sys&&S.sys.t)]||SQP._}
function sqAf(){const s=S.sys;if(s.af==null)s.af=50;return s.af}
function sqMood(){const a=sqAf();return a<30?0:a<70?1:2}
const SQ_MN=['เย็นชา','ปกติ','สนิทใจ'],SQ_MC=['#8aa0c0','#c0c0d0','#ff9ad0'];
function sqAfAdd(d,why){const s=S.sys;const a0=sqAf();s.af=clamp(a0+d,0,100);if(s.af>=100&&!s.afMax){s.afMax=1;s.pts=(s.pts||0)+2;s.sp+=100;sysLog(`💞 <b>${sqP()[0]}เปิดใจกับคุณเต็มที่</b> "ข้าเลือกโฮสต์ไม่ผิดจริงๆ" · แต้มอิสระ +2 · SP +100`,'up')}
 if(Math.floor(a0/30)!==Math.floor(s.af/30)&&why!==0)sysLog(`ความสัมพันธ์กับเจ้าระบบ: <b style="color:${SQ_MC[sqMood()]}">${SQ_MN[sqMood()]}</b> (${s.af}/100)`)}
function sqM(){const s=S.sys,a=sqAf();let m=a>=80?1.2:a>=60?1.1:a<=20?.8:a<=35?.9:1;if(s.qcBad&&S.age<s.qcBad)m*=.85;return m}
function sqSay(ok){try{const P=sqP(),L=ok?P[2]:P[3];sysLog(`💬 <i>${L[sqMood()]}</i> — ${P[0]}`)}catch(e){}}
{const _pqA=pushQuest;pushQuest=function(q){try{if(S.sys&&q){const m=sqM();q.rw=Math.round(q.rw*m);q.sp=Math.round(q.sp*m)}}catch(e){}return _pqA.apply(this,arguments)}}
{const _qfA=qFail;qFail=function(){const r=_qfA.apply(this,arguments);try{sqAfAdd(-6);if(Math.random()<.5)sqSay(false)}catch(e){}return r}}
