{const _ob=openArcBook;openArcBook=function(){const r=_ob.apply(this,arguments);try{const m=$('modal'),h=m.querySelector('h3');const on=storyOn();if(h&&!m.querySelector('.stbar'))h.insertAdjacentHTML('afterend',`<div class="stbar"><div class="brow"><button class="${on?'pbtn':'gbtn'}" onclick="storySet(1)">📖 เล่นเนื้อเรื่อง</button><button class="${on?'gbtn':'pbtn'}" onclick="storySet(0)">🚫 เล่นปกติ</button></div><p class="tag2" style="margin:4px 0">${on?'ภาคเรื่องราวจะเกิดขึ้นระหว่างชีวิต':'ปิดอยู่ ไม่มีภาคเรื่องราวใหม่ ภาคที่ค้างจะหยุดไว้จนกว่าจะเปิด'} · ตั้งครั้งเดียวใช้ทุกชีวิต</p>${S?`<button class="sysb" style="width:100%;margin-bottom:6px" onclick="openStoryRecap()">📜 สรุปเนื้อเรื่องชีวิตนี้ (${(S.arcDone||[]).length+(S.sarc?1:0)} ภาค)</button>`:''}</div>`)}catch(e){}return r}}
