function stTabFix(tabsSel,onTab,clickFn){const m=$('modal'),tabs=m.querySelector('.tabs');if(!tabs)return null;if(!tabs.querySelector('.sttab')){const b=document.createElement('button');b.className='tabb sttab';b.textContent='📖 เนื้อเรื่อง';b.onclick=clickFn;tabs.appendChild(b)}if(onTab){tabs.querySelectorAll('.tabb').forEach(x=>x.classList.toggle('on',x.classList.contains('sttab')))}return tabs}
