{const _olv=openLifeView;openLifeView=async function(lid,tab){const st=tab==='story';const r=await _olv.call(this,lid,st?'sum':tab);try{if($('modal').dataset.k!=='lifeview')return r;const tabs=stTabFix(0,st,()=>openLifeView(lid,'story'));if(st&&tabs){let d=null;try{const j=await api('lifeview&l='+encodeURIComponent(lid));d=j&&j.d}catch(e){}stReplaceBody(tabs,storyHtml(d&&d.sa,0))}}catch(e){console.error(e)}return r}}
{const _osp=openSpectate;openSpectate=async function(k,tab){const prev=openSpectate._tab;tab=tab||prev||'sum';const st=tab==='story';if(st!==(prev==='story'))openSpectate._sig=null;let cap=null;const _apiS=api;api=async function(a){const j=await _apiS.apply(this,arguments);try{if(String(a).indexOf('liveget')===0)cap=j}catch(e){}return j};let r;try{r=await _osp.call(this,k,st?'sum':tab)}finally{if(api!==_apiS)api=_apiS}try{openSpectate._tab=tab;if($('modal').dataset.k!=='spec')return r;const tabs=stTabFix(0,st,()=>openSpectate(k,'story'));if(st&&tabs&&!$('modal').querySelector('.stbody')){let s=cap&&cap.s;if(!s){try{const j=await _apiS('liveget&t='+encodeURIComponent(k));s=j&&j.s}catch(e){}}if(openSpectate._tab==='story'&&$('modal').dataset.k==='spec'&&!$('modal').querySelector('.stbody'))stReplaceBody(tabs,storyHtml(s&&s.sa,0))}}catch(e){console.error(e)}return r}}
