// ===================== v17.2 ลึกขึ้น: ผลกรรมย้อนกลับ · ชีวิตในสำนัก · คนสนิท · การลงทุน =====================
function dpOK(){return S&&S.alive&&!(S.beastMode&&!S.beastMode.human)&&!(typeof mwOn==='function'&&mwOn())&&S.age>=8}
function dpCD(k,y){S.dpc=S.dpc||{};if(S.dpc[k]!=null&&S.age-S.dpc[k]<y)return false;return true}
function dpSet(k){S.dpc=S.dpc||{};S.dpc[k]=S.age}
function dpFoe(m){return Math.round(total()*m*(.92+Math.random()*.16))}
// ---------- 1) ผลกรรมย้อนกลับ: ตัวเลือกในเหตุการณ์จะกลับมาในอีกหลายปี ----------
const CB_KIND=/ช่วย|ไว้ชีวิต|ปล่อย(?!ทิ้ง)|รับเลี้ยง|แบ่ง|ให้เงิน|ให้อาหาร|รักษา|ปกป้อง|คุ้มครอง|ไถ่|เมตตา|ให้อภัย|ให้ที่พัก|บริจาค/,CB_CRUEL=/ฆ่า|สังหาร|ทิ้ง|หักหลัง|ขโมย|ปล้น|หลอก|ทรยศ|รีดไถ|เหยียบ|ใส่ร้าย|ทำลาย|เผา|ข่มขู่|ชิง/;
function cbSkipTitle(t){return /🟦|🟪|📖|🏆|♾️|⚡|💞|🎲|🤖|ระบบ|ทัณฑ์|ภารกิจสายเรื่อง|ติ๊ง|เลือกเควส/.test(t)}
{const _crCB=choiceRun;choiceRun=function(i){let c=null;try{c=choice._cur}catch(e){}const r=_crCB.apply(this,arguments);
 try{if(c&&S&&S.alive&&dpOK()&&c.opts&&c.opts[i]){const t=saPlain(c.title),p=saPlain(c.opts[i].t);if(!cbSkipTitle(t)&&!cbSkipTitle(p)){const k=CB_CRUEL.test(p)?'cruel':CB_KIND.test(p)?'kind':null;if(k&&Math.random()<.45){S.cbs=S.cbs||[];if(S.cbs.length>=6)S.cbs.shift();S.cbs.push({k,t:t.slice(0,40),p:p.slice(0,50),a:S.age,at:S.age+R(4,14),nm:anyName(Math.random()<.5?'ชาย':'หญิง')})}}}}catch(e){}return r}}
function cbTick(){if(!S.cbs||!S.cbs.length||!dpCD('cb',3)||choice._cur)return false;const i=S.cbs.findIndex(x=>S.age>=x.at);if(i<0)return false;if(Math.random()>.5)return false;const x=S.cbs.splice(i,1)[0];dpSet('cb');const yrs=S.age-x.a,ago=`${yrs} ปีก่อน ตอน「${esc(x.t)}」คุณเลือก「${esc(x.p)}」`;
 if(x.k==='kind'){const opts=[{t:'🎁 รับน้ำใจไว้',s:'ได้ของตอบแทน',f(){const r=Math.random();if(r<.35){const a=newArt(Math.min(4,1+Math.floor(realmIdx()/2)));S.arts.push(a);log(`🎁 ${esc(x.nm)}มอบคัมภีร์ประจำตระกูล ${artHtml(a)} ให้เป็นการตอบแทน`,'epic',true)}else if(r<.7){const g=Math.round(sxBiz()*R(2,5)/4);S.money+=g;log(`🎁 ${esc(x.nm)}มอบทรัพย์ ${S.xian?stoneTxt(g):fmtM(g)+' ตำลึง'} "หนี้บุญคุณครั้งนั้น ข้าไม่เคยลืม"`,'epic')}else{S.hp=S.maxHp;S.maxHp+=20;joy(10);log(`🎁 ${esc(x.nm)}เป็นหมอเทวดาแล้ว รักษาแผลเก่าทั้งหมดให้คุณ · พลังชีวิตสูงสุด +20`,'epic')}keyAdd(`${esc(x.nm)}กลับมาตอบแทนบุญคุณ`)}},
  {t:'🙏 ไม่รับ ขอให้เป็นสหายกัน',s:'กรรมดี + · ได้คนสนิทใหม่',f(){S.karma+=8;S.fame+=20;S.dpF=S.dpF||[];S.dpF.push({n:x.nm,rel:70,from:'ผู้ติดหนี้บุญคุณ',a:S.age});log(`🤝 ${esc(x.nm)}ขอสาบานเป็นพี่น้องกับคุณ ดูได้ที่ ☰ → 👥 คนสนิท`,'good',true)}}];
  choice('🌸 บุญคุณที่กลับมา',`มีคนมาขอพบ <b>${esc(x.nm)}</b> คุกเข่าคำนับ<br><span class="tag2">${ago}</span><br>"ท่านจำข้าไม่ได้หรือ ข้าคือคนที่ท่านช่วยไว้ในวันนั้น"`,opts);return true}
 const foe=x.nm,ep=dpFoe(1.05);choice('🩸 กรรมตามทัน',`ชายสวมงอบดักรอคุณกลางทาง <b>${esc(foe)}</b> ถอดงอบออก ใบหน้ามีรอยแผลยาว<br><span class="tag2">${ago}</span><br>"ข้ารอวันนี้มา ${yrs} ปี"`,[
  {t:'⚔️ สู้',s:'ดวลจริง · ศัตรูแกร่งพอๆ กับคุณ',f(){duel(foe,ep,w=>{if(w){S.fame+=40;S.kills=(S.kills||0)+1;log(`⚔️ ${esc(foe)}ล้มลง "ข้า…ไม่น่ากลับมาเลย" กรรมเก่าจบลงที่นี่`,'epic',true);keyAdd(`ปิดฉากความแค้นกับ${esc(foe)}`)}else{S.hp=Math.max(1,Math.round(S.hp-S.maxHp*.35));const g=Math.round(S.money*.15);S.money-=g;log(`🩸 แพ้ให้${esc(foe)} เขาเอาทรัพย์ไป ${S.xian?stoneTxt(g):fmt(g)} แล้วจากไปพร้อมเสียงหัวเราะ`,'bad',true)}})}},
  {t:'🙇 ขอโทษและชดใช้',s:'เสียเงิน · กรรมดี +',f(){const g=Math.round(Math.max(sxBiz()*.5,S.money*.1));S.money=Math.max(0,S.money-g);S.karma+=10;log(`🙇 คุณคุกเข่าขอโทษและชดใช้ ${S.xian?stoneTxt(g):fmt(g)} — ${esc(foe)}เงียบไปนาน แล้วเดินจากไป "จำไว้ว่าเคยทำอะไรไว้"`,'')}},
  {t:'🏃 หนี',s:'50% · ไม่สำเร็จบาดเจ็บ',skip:true,f(){if(Math.random()<.5)log('🏃 คุณหายเข้าไปในฝูงชนทัน แต่รู้ดีว่าเขาจะกลับมาอีก');else{S.hp=Math.max(1,Math.round(S.hp-S.maxHp*.25));log(`🩸 หนีไม่พ้น โดน${esc(foe)}ฟันกลางหลัง`,'bad')}S.cbs.push(Object.assign({},x,{at:S.age+R(5,10)}))}}]);return true}
// ---------- 2) ชีวิตในสำนัก: ศิษย์พี่คู่แข่ง · อาจารย์มีความผูกพัน · ชิงตำแหน่งเจ้าสำนัก ----------
function svTop(){try{return RANKS[S.faction.t].length-1}catch(e){return 4}}
function svRival(){const f=S.faction;if(!f)return null;const fn=f.n0||f.n;if(!S.srv||S.srv.f!==fn){S.srv={n:anyName(Math.random()<.6?'ชาย':'หญิง'),f:fn,rel:-10,st:'rival',pw:1+Math.random()*.15}}return S.srv}
function svRelAdd(d){const r=S.srv;if(!r)return;r.rel=clamp(r.rel+d,-100,100);if(r.st==='rival'&&r.rel>=60){r.st='friend';log(`🤝 ศิษย์พี่ <b>${esc(r.n)}</b> ยื่นมือมาหาคุณ "ข้าแพ้ใจเจ้าแล้ว จากนี้ไปเราเป็นพี่น้องกัน"`,'epic',true);keyAdd(`คู่แข่ง${esc(r.n)}กลายเป็นพี่น้องร่วมสาบาน`)}else if(r.st==='rival'&&r.rel<=-60){r.st='foe';log(`😠 ศิษย์พี่ <b>${esc(r.n)}</b> ประกาศว่าคุณคือศัตรูตลอดชีวิต สักวันต้องมีคนตาย`,'bad',true)}}
function smAf(d){const m=S.smaster;if(!m)return;if(m.af==null)m.af=50;m.af=clamp(m.af+d,0,100);if(m.af>=85&&!m.secret){m.secret=1;const a=newArt(Math.min(4,(m.ri>=6?3:m.ri>=4?2:1)+1));S.arts.push(a);log(`👴 อาจารย์ ${esc(m.n)} เรียกคุณไปหลังเขากลางดึก "นี่คือวิชาที่ข้าไม่เคยสอนใคร" ได้ ${artHtml(a)} · คุณคือ<b>ศิษย์รัก</b>`,'myth',true);keyAdd(`ได้รับวิชาลับจากอาจารย์${esc(m.n)}`)}else if(m.af<=10){log(`👴 อาจารย์ ${esc(m.n)} ตัดความเป็นศิษย์อาจารย์กับคุณ "ข้าไม่มีศิษย์อย่างเจ้า"`,'bad',true);S.smaster=null}}
function svTick(){if(!S.faction||!dpOK()||S.age<12||choice._cur)return false;const r=svRival();r.pw=Math.max(.85,Math.min(1.3,r.pw+(Math.random()-.5)*.04));
 // ชิงตำแหน่งเจ้าสำนัก
 const top=svTop();if(S.rank===top-1&&S.age>=28&&!S.flags.svHead&&Math.random()<.25){S.flags.svHead=1;svHead();return true}
 if(!dpCD('sv',3)||Math.random()>.22)return false;dpSet('sv');const ev=[];ev.push('spar','spar');if(r.st!=='friend')ev.push('frame');ev.push('duo');if(S.smaster)ev.push('errand','errand');if(r.st==='foe'&&!r.done)ev.push('death');const k=ch(ev);
 if(k==='spar'){choice('🥋 ประลองประจำปีของสำนัก',`ศิษย์ทั้งสำนักมุงดู คู่คุณปีนี้คือศิษย์พี่ <b>${esc(r.n)}</b>${r.st==='friend'?' เขายิ้มให้คุณก่อนขึ้นเวที':r.st==='foe'?' — แววตาเขาอยากฆ่าคุณ':' — คู่แข่งตลอดกาลคุณ'}`,[
  {t:'⚔️ สู้เต็มที่',s:'ดวลจริง',f(){duel(r.n,dpFoe(r.pw),w=>{if(w){S.merit=(S.merit||0)+25;S.fame+=15;svRelAdd(r.st==='foe'?-5:6);smAf(5);log(`🥋 ชนะศิษย์พี่${esc(r.n)}กลางลานประลอง · ผลงาน +25 · ${r.st==='rival'?'เขากัดฟันแต่ก็ยอมรับในฝีมือ':''}`,'good')}else{S.merit=Math.max(0,(S.merit||0)-10);svRelAdd(-3);log(`🥋 แพ้ศิษย์พี่${esc(r.n)} · ผลงาน −10`,'bad')}})}},
  {t:'🤝 ออมมือให้เขา',s:'ผลงานเล็กน้อย · ความสัมพันธ์ +',f(){S.merit=(S.merit||0)+5;svRelAdd(14);smAf(-3);log(`🤝 คุณแกล้งพลาดท่าตอนท้าย ${esc(r.n)}มองคุณอยู่นาน — เขารู้`,'')}}]);return true}
 if(k==='frame'){choice('📜 ถูกใส่ร้าย',`คัมภีร์ในหอตำราหายไป และมีคนเห็น "คุณ" เข้าไปเมื่อคืน ทุกสายตาหันมา ส่วนศิษย์พี่ <b>${esc(r.n)}</b> ยืนกอดอกอยู่มุมห้อง`,[
  {t:'🔍 สืบหาความจริง',s:`ปัญญาช่วย (${Math.round(Math.min(.85,.35+S.int/400)*100)}%)`,f(){if(Math.random()<Math.min(.85,.35+S.int/400)){S.merit=(S.merit||0)+30;S.fame+=20;svRelAdd(-25);smAf(6);log(`🔍 คุณพบรอยเท้าและเศษผ้าที่โยงไปถึง${esc(r.n)} เขาถูกลงโทษกักบริเวณ · ผลงาน +30`,'epic')}else{S.merit=Math.max(0,(S.merit||0)-30);S.fame=Math.max(0,S.fame-20);log('🔍 หาหลักฐานไม่ได้ คุณถูกลงโทษขัดพื้นลานสำนักสามเดือน · ผลงาน −30','bad')}}},
  {t:'🧘 อดทน ยอมรับโทษ',s:'ผลงาน − · กรรมดี +',f(){S.merit=Math.max(0,(S.merit||0)-15);S.karma+=6;smAf(4);log('🧘 คุณยอมรับโทษโดยไม่เถียง อาจารย์มองคุณด้วยแววตาแปลกๆ','')}},
  {t:'⚔️ ท้าดวลกลางลาน',s:'ชนะ = พ้นผิด · แพ้ = โทษหนัก',f(){duel(r.n,dpFoe(r.pw*1.05),w=>{if(w){svRelAdd(-15);S.merit=(S.merit||0)+15;log(`⚔️ คุณชนะ ${esc(r.n)}ยอมสารภาพต่อหน้าทุกคน`,'epic')}else{S.merit=Math.max(0,(S.merit||0)-40);svRelAdd(-10);log('⚔️ แพ้ และถูกมองว่าเป็นคนผิดจริง · ผลงาน −40','bad')}})}}]);return true}
 if(k==='duo'){choice('🗺️ ภารกิจคู่',`เจ้าสำนักส่งคุณกับ <b>${esc(r.n)}</b> ไปปราบโจรที่ชายแดน ภารกิจสำเร็จ แต่ตอนรายงานผล…`,[
  {t:'🤝 แบ่งความดีความชอบเท่ากัน',s:'ความสัมพันธ์ ++',f(){S.merit=(S.merit||0)+15;svRelAdd(16);log(`🤝 ${esc(r.n)}ตบไหล่คุณ "ครั้งหน้าไปด้วยกันอีก"`,'good')}},
  {t:'🦊 รายงานว่าเป็นฝีมือคุณคนเดียว',s:'ผลงาน +++ · ความสัมพันธ์ −−',f(){S.merit=(S.merit||0)+40;svRelAdd(-22);S.karma-=4;log(`🦊 คุณได้หน้าไปคนเดียว ${esc(r.n)}ไม่พูดอะไร แต่จำไว้`,'')}},
  {t:'🙇 ยกความดีให้เขา',s:'ความสัมพันธ์ +++ · อาจารย์ชอบ',f(){S.merit=(S.merit||0)+5;svRelAdd(25);smAf(6);S.karma+=4;log(`🙇 ${esc(r.n)}อึ้งไปนาน นี่คือครั้งแรกที่เขามองคุณแบบนั้น`,'good')}}]);return true}
 if(k==='errand'){const m=S.smaster;if(m.af==null)m.af=50;choice(`👴 คำขอของอาจารย์ ${esc(m.n)}`,`อาจารย์ (นิสัย${esc(m.mood||'')}) เรียกคุณไป "ข้ามีสหายเก่าป่วยหนักอยู่ไกลถึงพันลี้ เอายานี้ไปส่งให้ที การฝึกของเจ้าต้องหยุดไปพักหนึ่ง"<br><span class="tag2">ความผูกพันกับอาจารย์ ${m.af}/100 · ถึง 85 ได้วิชาลับ · ต่ำกว่า 10 ถูกตัดศิษย์</span>`,[
  {t:'🏃 รับไปส่งทันที',s:'ผูกพัน +12 · เสียเวลาฝึก',f(){smAf(12);S.power=Math.max(1,S.power-Math.round(pctPow(.01)));S.karma+=4;log(`🏃 คุณเดินทางพันลี้ไปส่งยาทันเวลา สหายเก่าของอาจารย์ฝากคำขอบคุณกลับมา`,'good')}},
  {t:'🙅 ขอฝึกต่อ ให้คนอื่นไปแทน',s:'ผูกพัน −8',skip:true,f(){smAf(-8);log('🙅 อาจารย์พยักหน้าเงียบๆ แต่ไม่พูดกับคุณหลายวัน')}}]);return true}
 if(k==='death'){r.done=1;choice('🌑 ศึกชี้เป็นชี้ตาย',`ศิษย์พี่ <b>${esc(r.n)}</b> ส่งจดหมายท้าดวลถึงตายที่ผาหลังสำนัก "ระหว่างเรา ต้องเหลือคนเดียว"`,[
  {t:'⚔️ ไปตามนัด',s:'ดวลจริง · ศัตรูแกร่งกว่าปกติ',f(){duel(r.n,dpFoe(r.pw*1.12),w=>{if(w){S.fame+=60;S.kills=(S.kills||0)+1;S.srv.st='dead';log(`🌑 ${esc(r.n)}ล้มลงที่ปลายผา คำสุดท้ายของเขาคือ "ข้าแค่อยากให้อาจารย์มองข้าบ้าง"`,'myth',true);keyAdd(`ปิดฉากศิษย์พี่คู่แค้น${esc(r.n)}`)}else{S.hp=Math.max(1,Math.round(S.maxHp*.15));S.merit=Math.max(0,(S.merit||0)-50);log(`🌑 คุณแพ้และถูกโยนลงผา รอดมาได้อย่างปาฏิหาริย์ ${esc(r.n)}ได้หน้าไปทั้งสำนัก`,'bad',true)}})}},
  {t:'📜 รายงานเจ้าสำนัก',s:'ปลอดภัย · ถูกมองว่าขลาด',skip:true,f(){S.fame=Math.max(0,S.fame-15);svRelAdd(-10);r.done=0;log('📜 เจ้าสำนักสั่งห้ามดวลถึงตาย แต่ความแค้นยังไม่จบ','')}}]);return true}
 return false}
function svHead(){const r=S.srv,m=S.smaster,top=svTop(),nm=RANKS[S.faction.t][top];const sc=()=>Math.min(.9,.25+Math.min(.25,S.fame/8000)+(m?((m.af||50)-50)/250:0)+(r&&r.st==='friend'?.15:r&&r.st==='foe'?-.1:0)+Math.min(.15,(S.merit||0)/2000));
 choice(`🏯 ศึกชิงตำแหน่ง${nm}`,`${nm}คนเก่าประกาศวางมือ ผู้อาวุโสต้องเลือกผู้สืบทอด คุณคือหนึ่งในผู้ท้าชิง${r&&r.st!=='dead'?` คู่แข่งหลักคือศิษย์พี่ <b>${esc(r.n)}</b>${r.st==='friend'?' (ซึ่งประกาศสนับสนุนคุณ)':r.st==='foe'?' (ที่กำลังหาเสียงโจมตีคุณ)':''}`:''}<br><span class="tag2">โอกาสได้รับเลือกตอนนี้ราว ${Math.round(sc()*100)}% · ชื่อเสียง อาจารย์ ผลงาน และคู่แข่งมีผล</span>`,[
  {t:'🗳️ หาเสียงกับผู้อาวุโส',s:'ใช้เงินเลี้ยงรับรอง · โอกาส +15%',f(){const c=Math.round(sxBiz()*1.5);S.money=Math.max(0,S.money-c);svHeadRes(sc()+.15,`ใช้ไป ${S.xian?stoneTxt(c):fmt(c)} ในการหาเสียง`)}},
  {t:'⚔️ เสนอให้ตัดสินด้วยการประลอง',s:'ชนะ = ได้ตำแหน่งแน่นอน',f(){if(!r||r.st==='dead'||r.st==='friend'){duel('ผู้อาวุโสผู้ท้าชิง',dpFoe(1.1),w=>svHeadRes(w?1:0,w?'ชนะการประลองต่อหน้าทั้งสำนัก':'แพ้การประลอง'));return}duel(r.n,dpFoe(r.pw*1.08),w=>svHeadRes(w?1:0,w?`ชนะ${esc(r.n)}ต่อหน้าทั้งสำนัก`:`แพ้${esc(r.n)}`))}},
  {t:'🙏 ถอนตัว',s:'ชื่อเสียงคนถ่อมตน',skip:true,f(){S.fame+=20;S.karma+=5;log(`🙏 คุณถอนตัวจากการชิงตำแหน่ง${nm}`,'')}}])}
function svHeadRes(p,why){const top=svTop(),nm=RANKS[S.faction.t][top];if(Math.random()<p){S.rank=top;S.merit=Math.max(S.merit||0,MERIT[Math.min(MERIT.length-1,top)]||0);S.fame+=150;S.promoReady=false;log(`🏯 <b>ได้รับเลือกเป็น${nm}แห่ง${esc(S.faction.n)}!</b> — ${why}`,'myth',true);keyAdd(`ขึ้นเป็น${nm}แห่ง${S.faction.n}`);try{setScene('aura')}catch(e){}}else{S.fame=Math.max(0,S.fame-20);log(`🏯 ผู้อาวุโสเลือกคนอื่นเป็น${nm} — ${why}`,'bad',true);S.flags.svHead=0;S.dpc=S.dpc||{};S.dpc.svh=S.age}}
// ---------- 3) คนสนิท: พี่น้อง · สหาย · อาจารย์ · คู่แข่ง ----------
function ppList(){const L=[];(S.sibs||[]).filter(s=>s.alive&&s.born).forEach((s,i)=>L.push({k:'sib',i,o:s,n:s.n,role:s.role,rel:s.rel==null?50:s.rel,note:(s.fac?s.fac.n:'')+(s.married?' · แต่งงานแล้ว':'')}));
 (S.dpF||[]).forEach((f,i)=>L.push({k:'fr',i,o:f,n:f.n,role:f.from||'สหาย',rel:f.rel}));if(S.smaster)L.push({k:'ms',o:S.smaster,n:S.smaster.n,role:'อาจารย์',rel:S.smaster.af==null?50:S.smaster.af});if(S.srv&&S.srv.st!=='dead'&&S.faction)L.push({k:'rv',o:S.srv,n:S.srv.n,role:{rival:'ศิษย์พี่คู่แข่ง',friend:'ศิษย์พี่ร่วมสาบาน',foe:'ศิษย์พี่คู่แค้น'}[S.srv.st],rel:S.srv.rel});return L}
function ppRel(x,d){if(x.k==='sib')x.o.rel=clamp((x.o.rel==null?50:x.o.rel)+d,0,100);else if(x.k==='fr')x.o.rel=clamp(x.o.rel+d,0,100);else if(x.k==='ms')smAf(d);else if(x.k==='rv')svRelAdd(d)}
function openPeople(){if(!S)return;const L=ppList();S.ppv=S.ppv||{};
 modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>👥 คนสนิท</h3><p class="tag2">เยี่ยมได้ปีละครั้งต่อคน (สนิทขึ้น ความสุข +) · ขอความช่วยเหลือได้ 5 ปีครั้ง ยิ่งสนิทยิ่งช่วยมาก · ให้ของขวัญใช้เงิน</p>${L.length?L.map((x,j)=>{const key=x.k+(x.i!=null?x.i:''),vis=S.ppv[key]===S.age,ask=S.ppv[key+'a']!=null&&S.age-S.ppv[key+'a']<5;return`<div class="item"><b>${esc(x.n)}</b> <span class="tag2">${esc(x.role)}${x.note?' · '+esc(x.note):''}</span><div class="hpbar" style="height:6px;margin:4px 0"><i style="width:${Math.max(0,x.rel)}%;background:${x.rel>=60?'#ff9ad0':x.rel>=30?'#c0c0d0':'#8aa0c0'}"></i></div><div class="brow"><button class="sysb" ${vis?'disabled':''} onclick="ppDo(${j},'v')">🍵 เยี่ยม</button><button class="sysb" ${ask?'disabled':''} onclick="ppDo(${j},'a')">🙏 ขอช่วย</button><button class="sysb" onclick="ppDo(${j},'g')">🎁 ของขวัญ</button></div></div>`}).join(''):'<p class="tag2">ยังไม่มีคนสนิท พี่น้อง สหายที่ติดหนี้บุญคุณ อาจารย์ และศิษย์พี่ในสำนักจะมาอยู่ที่นี่</p>'}`,'people')}
function ppDo(j,a){const x=ppList()[j];if(!x)return;const key=x.k+(x.i!=null?x.i:'');S.ppv=S.ppv||{};
 if(a==='v'){if(S.ppv[key]===S.age)return;S.ppv[key]=S.age;ppRel(x,x.k==='rv'&&x.o.st==='foe'?2:7);joy(4);log(`🍵 ไปเยี่ยม${esc(x.n)} (${esc(x.role)}) นั่งคุยกันจนค่ำ`,'good')}
 else if(a==='g'){const c=Math.round(sxBiz()*.3);if(S.money<c)return toast('เงินไม่พอ ('+(S.xian?stoneTxt(c):fmt(c))+')');S.money-=c;ppRel(x,12);log(`🎁 มอบของขวัญให้${esc(x.n)} (${S.xian?stoneTxt(c):fmt(c)})`,'good')}
 else{if(S.ppv[key+'a']!=null&&S.age-S.ppv[key+'a']<5)return;S.ppv[key+'a']=S.age;const rel=x.rel;if(rel<30||(x.k==='rv'&&x.o.st==='foe')){ppRel(x,-5);log(`🙅 ${esc(x.n)}ปฏิเสธ "เราไม่ได้สนิทกันขนาดนั้น"`,'bad')}else{const m=rel/100;const r=Math.random();if(x.k==='ms'||(x.k==='sib'&&x.o.fac&&r<.4)){const g=pctPow(.015*m+.005);S.power+=g;log(`🙏 ${esc(x.n)}ชี้แนะเคล็ดวิชาให้ · พลังยุทธ์ +${fmt(g)}`,'good')}else if(r<.6){const g=Math.round(sxBiz()*m);S.money+=g;log(`🙏 ${esc(x.n)}ช่วยเหลือเงิน ${S.xian?stoneTxt(g):fmt(g)}`,'good')}else{S.hp=S.maxHp;joy(8);log(`🙏 ${esc(x.n)}ดูแลคุณจนหายดี · พลังชีวิตเต็ม`,'good')}ppRel(x,-3)}}
 render();openPeople()}
function sibTroub(){const L=(S.sibs||[]).filter(s=>s.alive&&s.born&&s.age>=16);if(!L.length||!dpCD('sib',6)||Math.random()>.12)return false;dpSet('sib');const s=ch(L),c=Math.round(sxBiz()*.8);
 choice(`👪 ${esc(s.role)}เดือดร้อน`,`${esc(s.role)} <b>${esc(s.n)}</b> มาหาคุณกลางดึก ตัวสั่น "ข้าติดหนี้พนันกับแก๊งมืด พวกมันจะตัดมือข้า"`,[
  {t:'💰 ชดใช้หนี้ให้',s:`${S.xian?stoneTxt(c):fmt(c)} · สนิท ++`,f(){S.money=Math.max(0,S.money-c);s.rel=clamp((s.rel||50)+20,0,100);log(`💰 คุณจ่ายหนี้ให้${esc(s.n)} เขาร้องไห้สัญญาว่าจะไม่เล่นอีก`,'good')}},
  {t:'⚔️ ไปจัดการแก๊งมืด',s:'ดวล · ชนะได้ชื่อเสียง',f(){duel('หัวหน้าแก๊งมืด',dpFoe(.85),w=>{if(w){S.fame+=30;s.rel=clamp((s.rel||50)+25,0,100);log(`⚔️ แก๊งมืดถูกกวาดล้าง ${esc(s.n)}มองคุณเหมือนฮีโร่`,'epic')}else{S.hp=Math.max(1,Math.round(S.hp-S.maxHp*.2));log('⚔️ พลาดท่า ต้องหนีกลับมาพร้อมแผล','bad')}})}},
  {t:'😤 ปล่อยให้รับผิดชอบเอง',s:'สนิท −− ',skip:true,f(){s.rel=clamp((s.rel||50)-25,0,100);log(`😤 คุณปิดประตูใส่ ${esc(s.n)}หายไปหลายปี`,'bad')}}]);return true}
// ---------- 4) การลงทุน: ที่ใช้เงินช่วงหลังเกม ----------
function ivOf(){if(!S.iv)S.iv={sh:0,gd:0,gdY:-1,don:0};return S.iv}
function ivCost(k){const b=sxBiz();return Math.round(k==='sh'?b*4*Math.pow(1.35,ivOf().sh):k==='gd'?b*1.2:b*2*Math.pow(1.25,ivOf().don))}
function ivFight(){const v=S&&S.iv;return v&&v.gd&&S.age<=v.gdY?1.08:1}
{const _emI=eqM;eqM=function(k){let m=_emI.apply(this,arguments);try{if(k==='fight')m*=ivFight()}catch(e){}return m}}
function openInvest(){if(!S)return;const v=ivOf(),M=x=>S.xian?stoneTxt(x):fmtM(x)+' ตำลึง';
 modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>💰 การลงทุนและบารมี</h3><p class="tag2">ทางใช้เงินช่วงหลังเกม ราคาปรับตามโลกและขั้นพลัง · เงินที่มี ${M(S.money)}</p>
 <div class="item"><b>🏙️ หุ้นหัวเมือง</b> <span class="tag2">ถือ ${v.sh} ส่วน</span><p class="tag2">ปันผลทุกปี ส่วนละ ~5% ของราคาซื้อเฉลี่ย · บางปีเมืองมีเหตุร้าย ปันผลหาย · ส่วนต่อไปแพงขึ้น 35%</p><button class="sysb" onclick="ivBuy('sh')">ซื้อ 1 ส่วน · ${M(ivCost('sh'))}</button></div>
 <div class="item"><b>🛡️ จ้างผู้คุ้มกัน</b> <span class="tag2">${v.gd&&S.age<=v.gdY?'จ้างอยู่ถึงอายุ '+v.gdY:'ยังไม่ได้จ้าง'}</span><p class="tag2">พลังต่อสู้ ×1.08 ตลอดสัญญา 5 ปี</p><button class="sysb" onclick="ivBuy('gd')">จ้าง 5 ปี · ${M(ivCost('gd'))}</button></div>
 <div class="item"><b>🏛️ สร้างศาลาและโรงทาน</b> <span class="tag2">สร้างแล้ว ${v.don} แห่ง</span><p class="tag2">กรรมดี +25 · ชื่อเสียง +120 ทันที และชื่อเสียงเพิ่มทุกปี · แห่งต่อไปแพงขึ้น 25%</p><button class="sysb" onclick="ivBuy('don')">สร้าง · ${M(ivCost('don'))}</button></div>${S.srv&&S.srv.st==='foe'?`<div class="item"><b>📜 ตั้งค่าหัวศัตรู</b><p class="tag2">ศิษย์พี่คู่แค้น ${esc(S.srv.n)} อ่อนกำลังลง (พลัง −10%)</p><button class="sysb" onclick="ivBuy('bty')">ตั้งค่าหัว · ${M(ivCost('gd'))}</button></div>`:''}`,'invest')}
function ivBuy(k){const v=ivOf(),c=k==='bty'?ivCost('gd'):ivCost(k);if(S.money<c)return toast('เงินไม่พอ');S.money-=c;
 if(k==='sh'){v.sh++;v.paid=(v.paid||0)+c;log(`🏙️ ซื้อหุ้นหัวเมืองเพิ่ม 1 ส่วน (รวม ${v.sh})`,'good')}else if(k==='gd'){v.gd=1;v.gdY=S.age+5;log('🛡️ จ้างผู้คุ้มกันฝีมือดี 5 ปี','good')}else if(k==='don'){v.don++;S.karma+=25;S.fame+=120;log(`🏛️ สร้างศาลาและโรงทานแห่งที่ ${v.don} ชาวบ้านจารึกชื่อคุณไว้`,'epic')}else{S.srv.pw=Math.max(.8,S.srv.pw*.9);log(`📜 ประกาศค่าหัว${esc(S.srv.n)} เขาต้องหลบซ่อนจนอ่อนกำลัง`,'')}render();openInvest()}
