 const c=k=>its.filter(d=>k==='done'?d.classList.contains('fixed'):d.dataset.k===k&&!d.classList.contains('fixed')).length;let bar=$('bugFb');if(!bar){bar=document.createElement('div');bar.id='bugFb';bar.className='tabs';el.before(bar)}
