function pxAtkN(c,kind,a,col,sc,sp,cx,cy,tx,ty){const e=Math.min(1,a*1.25),r=Math.random,my=cy-8;
 if(kind==='earth'){if(a<.42){const q=a/.42;for(let i=0;i<5;i++){const ang=i*1.256+q*6,R0=8+i,x=cx+Math.cos(ang)*R0,y=my-q*10+Math.sin(ang)*R0*.5,s=2+(i%3);c.fillStyle=col[0];c.fillRect(Math.round(x),Math.round(y),s,s);c.fillStyle=col[1];c.fillRect(Math.round(x),Math.round(y),1,1)}if(r()<.4)sp(cx+(r()-.5)*16,cy+1,(r()-.5)*.4,-.3,14,'#8a6a4a',1)}
  else{const q=Math.min(1,(a-.42)/.3),n=4+Math.min(5,sc);for(let i=0;i<n;i++){const x=tx-n*3+i*6+((i*7)%3),H=Math.round((10+sc*2.4+((i*13)%7))*q*(i%2?.75:1));for(let y=0;y<H;y++){const w=Math.max(1,Math.round((H-y)/H*4));c.fillStyle=y<2?col[1]:(y%4?col[0]:'#8a6036');c.fillRect(x-w,ty+2-y,w*2,1)}c.fillStyle=col[1];c.fillRect(x-1,ty+2-H,1,1)}
   if(q>=1&&r()<.8)for(let i=0;i<3;i++)sp(tx+(r()-.5)*40,ty+2,(r()-.5)*1.6,-r()*1.8,22,r()<.5?col[0]:'#8a6a4a',1+(r()<.3?1:0))}return}
 if(kind==='poison'){const n=3+Math.min(3,Math.floor(sc/2));for(let i=0;i<n;i++){const p=e-i*.09;if(p<=0)continue;const pp=Math.min(1,p),x=cx+10+(tx-cx-10)*pp,y=my-Math.sin(pp*3.14)*(14+i*3)+i*2;c.globalAlpha=.9;pxDisc(c,Math.round(x),Math.round(y),2+(i%2),col[0]);c.fillStyle=col[1];c.fillRect(Math.round(x)-1,Math.round(y)-1,1,1);c.globalAlpha=1;if(r()<.6)sp(x,y,(r()-.5)*.3,.2+r()*.3,16,i%2?col[1]:col[0],1)}
  if(a>.6){const q=(a-.6)/.4;for(let i=0;i<6;i++){const ang=i*1.05+q*2,R0=4+q*(10+sc*1.5);c.globalAlpha=(1-q*.6)*.5;pxDisc(c,Math.round(tx+Math.cos(ang)*R0*.8),Math.round(ty-6+Math.sin(ang)*R0*.4),Math.round(3+q*4),i%2?col[0]:'#3a7a20')}c.globalAlpha=1;if(r()<.7)sp(tx+(r()-.5)*24,ty-14,(r()-.5)*.2,.3+r()*.4,26,col[0],1)}return}
 if(kind==='light'){const W=Math.round((2+sc*.8)*Math.min(1,a*3)),top=-4;c.globalAlpha=.35;c.fillStyle=col[0];c.fillRect(tx-W*2,top,W*4,ty+6-top);c.globalAlpha=.85;c.fillStyle=col[0];c.fillRect(tx-W,top,W*2,ty+6-top);c.globalAlpha=1;c.fillStyle='#ffffff';c.fillRect(tx-Math.max(1,W>>1),top,Math.max(1,W),ty+6-top);
  if(a>.35){const q=Math.min(1,(a-.35)/.4),L=Math.round((8+sc*3)*q);c.fillStyle='#ffffff';c.fillRect(tx-L,ty-6,L*2,1);c.fillRect(tx,ty-6-L,1,L*2);c.fillStyle=col[0];c.fillRect(tx-L+2,ty-5,L*2-4,1)}
  for(let i=0;i<2;i++)sp(tx+(r()-.5)*W*4,ty+2,(r()-.5)*.2,-.6-r(),26,r()<.5?'#ffffff':col[0],1);return}
 if(kind==='wood'){const n=3+Math.min(4,Math.floor(sc/2)),q=Math.min(1,e*1.1);for(let i=0;i<n;i++){const bx=tx-14+i*(28/(n-1||1)),H=Math.round((14+sc*2+(i%2)*6)*q);let px=bx,py=ty+3;for(let y=0;y<H;y++){const x=Math.round(bx+Math.sin(y*.35+i*2)*3*(y/H+.2));c.fillStyle=y%5===0?col[1]:col[0];c.fillRect(x,ty+3-y,2,1);if(y%6===3){c.fillStyle='#2a7a30';c.fillRect(x+(i%2?2:-2),ty+3-y,2,1)}px=x;py=ty+3-y}
   if(q>=1){c.fillStyle='#ff9ac0';c.fillRect(px-1,py-1,3,3);c.fillStyle='#fff';c.fillRect(px,py,1,1)}}
  if(q>=1&&r()<.7)sp(tx+(r()-.5)*30,ty-20-r()*10,(r()-.5)*.6,.2+r()*.3,40,r()<.5?'#ff9ac0':col[1],1);return}}
{const _pa=pxAtk;pxAtk=function(c,kind){if(kind==='earth'||kind==='poison'||kind==='light'||kind==='wood')return pxAtkN.apply(this,arguments);return _pa.apply(this,arguments)}}

// ---------- 2) ชั้นแสงเรือง (light buffer) ทับทุกภาพพิกเซล ----------
const GLW={on:+LS.get('murim_glow',1)!==0,M:new Map(),last:0,iv:50,cost:0,sm:null,sm2:null};
const GLW_SEL='#scene,#endScene,.pxbox canvas,.rlv canvas,#specScn,#brCv';
function glwSet(v){GLW.on=!!v;LS.set('murim_glow',v?1:0);if(!v)GLW.M.forEach(o=>{try{o.ov.remove()}catch(e){}}),GLW.M.clear();toast(v?'✨ เปิดแสงเรือง':'แสงเรืองปิดแล้ว (ประหยัดเครื่อง)')}
function glwOne(cv){let o=GLW.M.get(cv);if(!o){if(cv.dataset.glwBad)return;const ov=document.createElement('canvas');ov.className='glwov';ov.width=128;ov.height=72;cv.after(ov);o={ov,ctx:ov.getContext('2d')};GLW.M.set(cv,o)}
 const ov=o.ov;if(ov.previousSibling!==cv){try{cv.after(ov)}catch(e){}}
 const w=cv.offsetWidth,h=cv.offsetHeight;if(!w||!h||cv.offsetParent===null){ov.style.display='none';return}const r=cv.getBoundingClientRect();if(r.bottom<0||r.top>innerHeight){ov.style.display='none';return}
 ov.style.display='';ov.style.left=cv.offsetLeft+'px';ov.style.top=cv.offsetTop+'px';ov.style.width=w+'px';ov.style.height=h+'px';
 const sw=72,sh=Math.max(8,Math.round(sw*cv.height/cv.width));if(!GLW.sm){GLW.sm=document.createElement('canvas');GLW.sm2=document.createElement('canvas')}const s=GLW.sm,s2=GLW.sm2;if(s.width!==sw||s.height!==sh){s.width=sw;s.height=sh;s2.width=sw>>2;s2.height=Math.max(2,sh>>2)}
 const x=s.getContext('2d',{willReadFrequently:true});x.imageSmoothingEnabled=true;x.clearRect(0,0,sw,sh);x.drawImage(cv,0,0,sw,sh);let d;try{d=x.getImageData(0,0,sw,sh)}catch(e){cv.dataset.glwBad=1;ov.remove();GLW.M.delete(cv);return}
 const p=d.data;let sum=0;for(let i=0;i<p.length;i+=4)sum+=Math.max(p[i],p[i+1],p[i+2]);const mean=sum/(p.length/4),thr=Math.max(176,Math.min(246,mean+78));
 for(let i=0;i<p.length;i+=4){const m=Math.max(p[i],p[i+1],p[i+2]),mn=Math.min(p[i],p[i+1],p[i+2]),sat=m?(m-mn)/m:0,t=thr-sat*40;if(m<t||p[i+3]<10){p[i+3]=0;continue}const k=(m-t)/(255-t+1);p[i+3]=Math.min(255,Math.round(255*Math.min(1,k*1.6)))}
 x.putImageData(d,0,0);const c2=s2.getContext('2d');c2.imageSmoothingEnabled=true;c2.clearRect(0,0,s2.width,s2.height);c2.drawImage(s,0,0,s2.width,s2.height);
 const g=o.ctx;g.imageSmoothingEnabled=true;g.clearRect(0,0,128,72);ov.height=Math.round(128*h/w)||72;g.globalAlpha=mean>150?.45:.7;g.drawImage(s,0,0,128,ov.height);g.globalAlpha=mean>150?.55:.85;g.drawImage(s2,0,0,128,ov.height)}
function glwTick(now){requestAnimationFrame(glwTick);if(!GLW.on||document.hidden||now-GLW.last<GLW.iv)return;GLW.last=now;const t0=performance.now();
 try{const L=[...document.querySelectorAll(GLW_SEL)];GLW.M.forEach((o,cv)=>{if(!cv.isConnected){try{o.ov.remove()}catch(e){}GLW.M.delete(cv)}});let n=0;for(const cv of L){if(n>=4)break;if(cv.offsetParent===null)continue;glwOne(cv);n++}}catch(e){}
 const dt=performance.now()-t0;GLW.cost=GLW.cost*.9+dt*.1;GLW.iv=GLW.cost>9?120:GLW.cost>5?80:50}
requestAnimationFrame(glwTick);
