  if(P[5]==='duel'){duel(c.ev==='duel'?'ทายาทตระกูลใหญ่':c.ev==='tide'?'ราชาอสูรผู้นำกระแส':c.ev==='cult'?'ผู้นำลัทธิมาร':c.ev==='assassin'?'มือสังหารยามวิกาล':c.ev==='bandit'?'หัวหน้ากองโจรภูผาดำ':'ผู้พิทักษ์ถ้ำต้องสาป',Math.round(total()*(P[6]-(fs?.35:0)+(rv?.15:0)-easy)),w=>{if(w){S.fame+=40;if(c.ev==='cave'){const a=newArt(Math.min(4,2+Math.floor(realmIdx()/3)));Array.prototype.push.call(S.arts,a);log(`🗝️ ในถ้ำมี ${artHtml(a)}`,'epic')}save(fs?P[4]:'คุณสู้แทนเขาจนชนะ')}else{S.hp=Math.max(1,Math.round(S.hp-S.maxHp*.35));if(!c.rt){c.rt=1;c.ea=S.age+1;delete G.seen['f'+c.ev];log(`🩸 คุณแพ้ แต่${nm}ยังไม่ตาย เขาบาดเจ็บสาหัส ปีหน้ายังมีโอกาสช่วยอีกครั้ง`,'bad',true)}else lose()}learn()});return}
  let p=0;if(P[5]==='int')p=Math.min(.9,P[6]+S.int/500);else if(P[5]==='karma')p=Math.min(.9,.25+Math.max(0,S.karma)/(P[6]*8));else if(P[5]==='money'){const cst=Math.round(sxBiz()*P[6]);if(S.money>=cst){S.money-=cst;p=.85}else p=.15}else if(P[5]==='herb')p=G.herb?1:.15;
