function qmLog(){const rows=LOGF.slice(0,7).map(x=>({ic:'',t:x[1],r:'›',f:()=>openLifeLog(x[0])}));rows.push({sep:1},{ic:'⤒',t:'เลื่อนไปข้อความแรก',f:()=>{const f=$('feed');if(f)f.scrollTo({top:0,behavior:'smooth'})}},{ic:'⤓',t:'เลื่อนไปล่าสุด',f:()=>{const f=$('feed');if(f)f.scrollTo({top:f.scrollHeight,behavior:'smooth'})}});
 return{ic:'📜',t:'บันทึกชีวิต',sub:`${(S.key||[]).length} เหตุการณ์`,rows}}
