const QM_MN=[['openFamily','👪','ครอบครัว'],['openArts','📚','วิชา'],['openPeople','👥','ผู้คน'],['openHouse','🏠','ตระกูล'],['openFaction','🏯','สำนัก'],['openMarket','🏪','ตลาด'],['openEquip','⚔️','ชุดสวมใส่'],['openDungeons','🏰','ดันเจี้ยน'],['openMap','🗺️','แผนที่'],['openCraft','🔨','งานช่าง'],['openRegress','🔁','วงจรย้อนกาล']];
QM_MN.forEach(([fn])=>{try{const o=window[fn];if(typeof o!=='function')return;window[fn]=function(){try{if(S&&S.alive){const c=LS.get('murim_qmc',{})||{};c[fn]=(c[fn]||0)+1;LS.set('murim_qmc',c)}}catch(e){}return o.apply(this,arguments)}}catch(e){}});
function qmMenu(){const c=LS.get('murim_qmc',{})||{};const L=QM_MN.filter(([fn])=>typeof window[fn]==='function'&&(fn!=='openRegress'||(S.ch==='regress'))).sort((a,b)=>(c[b[0]]||0)-(c[a[0]]||0)).slice(0,4);
 return{ic:'☰',t:'ทางลัด',sub:'หน้าที่ใช้บ่อย',rows:[...L.map(([fn,ic,t])=>({ic,t,r:'›',f:()=>window[fn]()})),{sep:1},{ic:'💾',t:'เซฟตอนนี้',f:()=>{saveGame();toast('💾 บันทึกแล้ว')}},{ic:'📤',t:'แชร์ชีวิตเข้าแชท',f:()=>{try{shareLife()}catch(e){openOnline('chat')}}},{ic:'☰',t:'เปิดเมนูเต็ม',r:'›',f:openMenu}]}}
// ---------- แถบปี ----------
function qmYear(){const ri=realmIdx(),nx=REALMS[ri+1],tot=total();let pr='';try{if(nx&&nx.p)pr=Math.min(100,Math.round(tot/nx.p*100))+'%'}catch(e){}
 const left=Math.max(0,Math.round(lifeMax()-S.age));const rows=[{info:`🎂 อายุ <b>${S.age}</b> ปี · ${esc(($('ymon')||{}).textContent||'')}`},{info:`⏳ อายุขัยเหลือราว <b>${fmt(left)}</b> ปี`},
 {info:`⚔️ ${esc(realmLabel?realmLabel().base:REALMS[ri].n)}${nx?` · ไป${esc(nx.n)} <b>${pr}</b>`:''}`}];
 try{if(typeof brkPend==='function'&&brkPend())rows.push({ic:'⚡',t:'ติดคอขวด ทะลวงขั้นตอนนี้',f:brkGo})}catch(e){}
 if(S.chronic)rows.push({info:`🤒 ป่วย: ${esc(S.chronic.n)}`});return{ic:'📅',t:'ปีนี้',sub:paused?'หยุดอยู่':'กำลังเล่น',rows}}
