  dawn:{b:['#3c3b62','#4a4570','#544a76','#403e66'],edge:'#f4ab8c',glass:'#d496a8',lit:.16,water:'#6c6c9c',wl:'#ffc8a8',gnd:'#262640',far:.55},
  day:{b:['#6d7d9c','#7f8fae','#5e6e8e','#8a98b4'],edge:'#e4f0fa',glass:'#b4d6f0',lit:0,water:'#3a7cbc',wl:'#a8dcf6',gnd:'#3a4658',far:.45},
  dusk:{b:['#30264a','#3c2c52','#463258','#2a2244'],edge:'#ffa070',glass:'#f4986e',lit:.24,water:'#8a4a70',wl:'#ffbc84',gnd:'#1c1630',far:.55},
