{const _rnI=render;render=function(){const r=_rnI.apply(this,arguments);try{if(imOn()){const M=S.mw,h=$('mwHud');if(h&&!h.querySelector('.imAge')){const t=h.querySelector('.mwhT');if(t)t.insertAdjacentHTML('afterend',`<div class="imAge">⏳ อายุจริง <b>${fmt(imTA(M))}</b> ปี · ร่าง ${S.age} ปี · ${(M.id||0)>0?'🪪 มีบัตร':'🚫 ไม่มีตัวตนในระบบ'}${M.imm.org>=2?' · 👁️ มีคนตามล่า':''}</div>`)}const gr=$('gRealm');if(gr&&!/ผู้อยู่ยง/.test(gr.textContent))gr.textContent='ผู้อยู่ยงข้ามศตวรรษ · '+gr.textContent}}catch(e){}return r}}
