{const _nlI=mwNewLost;mwNewLost=function(){try{const i=window._mwLI|0;if(i>=0){const L=(LS.get('murim_legacy',[])||[])[i];if(L&&L.a>=200)window._mwTApend=L.a}}catch(e){}return _nlI.apply(this,arguments)}}
(()=>{const st=document.createElement('style');st.textContent=`.imAge{font-size:12px;margin:-2px 0 6px;color:#ffe2a8}`;document.head.appendChild(st)})();


// ===================== แก้: ลูกเกิดใหม่ไม่เพิ่มในหน้าครอบครัว (ตัวนับลูกเคยถูกลดตอนลูกตาย) · ทะลวงขั้นโลกเทพค้าง =====================
{const _sfF=syncFamily;syncFamily=function(){try{if(S&&!(S.beastMode&&!S.beastMode.human)){const n=(S.children||[]).length;if(!S._kFix){S._kFix=1;if((S.kids||0)<n){S.kids=n;S._kSeen=n;S._kLen=n}}}}catch(e){}return _sfF.apply(this,arguments)}}
// ทะลวงขั้นโลกเทพ: ถ้าพลังถึงแล้ว ให้ทัณฑ์ขึ้นทุกปีเมื่อว่าง · คิวที่ค้างหลังโหลดเซฟถูกปลุกใหม่ · ปุ่มทะลวงขึ้นเสมอ
function brkSafe(){try{if(!S||!S.alive||!S.xt||(S.beastMode&&!S.beastMode.human))return;const p=brkPend();if(!p){S._tribQ=null;return}
 if(S.tribNext!=null&&(!isFinite(S.tribNext)||S.tribNext>S.age+2))S.tribNext=S.age+1;
 if(choice._cur||modalOpen||document.querySelector('.kfx'))return;if(S.tribNext!=null&&S.age<S.tribNext)return;if(S._brkY===S.age)return;S._brkY=S.age;S._tribQ=null;godTrib(p[0],p[1])}catch(e){console.error(e)}}
{const _pyS=passYear;passYear=function(){const r=_pyS.apply(this,arguments);setTimeout(brkSafe,260);return r}}
setInterval(()=>{try{if(S&&S.alive&&S._tribQ&&!window._tribPoll&&!choice._cur&&!modalOpen)brkSafe()}catch(e){}},2500);
{const _rnS=render;render=function(){const r=_rnS.apply(this,arguments);try{if(S&&S.alive&&S.xt&&!$('brkPill')&&!$('ascPill')){const g=$('gRealm');const p=brkPend();if(g&&p)g.insertAdjacentHTML('afterend','<button id="brkPill" class="ascpill" style="margin:4px 0;border-color:#ffd060;background:linear-gradient(180deg,#5a3a10,#2a1808)" onclick="brkGo()">⚡ ทะลวงสู่'+esc(tribName(p[0],p[1]))+'</button>')}else{const b=$('brkPill');if(b&&!$('ascPill')&&!brkPend())b.remove()}}catch(e){}return r}}


// ===================== งานช่าง v2: อาวุธหลอมเข้าคลัง (ค่าเป็น % ของพลัง) · สูตรขั้น 6–9 · แยกชิ้นส่วน · บอกว่าของไปไหน =====================
const FW_P=[.03,.06,.10,.15,.22];
