 h+=`<h4>🌟 ของหายาก (ชาติละครั้ง) ${g<2?'<span style="opacity:.7;font-size:.85em">🔒 ปลดล็อกที่ระดับสูง</span>':''}</h4>`+(g<2?'':ONCE.map(it=>{const c=sgPrice(it.c),own=(s.ob||[]).includes(it.id);return row(it.n,it.d,own?'ซื้อแล้ว':c+' SP',`onceBuy('${it.id}')`,own||s.sp<c||!it.ok(),'#ffd070')}).join(''));
