grTrack=function(st){const g=S.gr||(S.gr={pow:0,fame:0,kills:0,money:0,p0:total(),f0:S.fame,k0:S.kills,m0:S.money});const y=Math.max(1,Math.min(st||1,50)),a=.25;
 const d={pow:(total()-g.p0)/y,fame:(S.fame-g.f0)/y,kills:(S.kills-g.k0)/y,money:(S.money-g.m0)/y};
 for(const k in d){let v=Math.max(0,d[k]);if(g[k]>0)v=Math.min(v,g[k]*3);g[k]=g[k]?g[k]*(1-a)+v*a:v}g.p0=total();g.f0=S.fame;g.k0=S.kills;g.m0=S.money};
QG3[0][1]=.8;QG3[1][1]=1;QG3[2][1]=1.3;
