{const _qf=QMK.fame;QMK.fame=function(){const r=_qf.apply(this,arguments);try{const base=30+Math.max(0,realmIdx())*15,cap=Math.max(base,Math.round((S.fame||0)*.1)+base);if(r[1]>cap){const o=fmt(r[1]);r[1]=cap;r[0]=r[0].replace(o,fmt(cap))}}catch(e){}return r}}
