 box.querySelectorAll('.slotrow').forEach(e=>e.remove());const old=box.querySelector('.svWrap');if(old)old.remove();
 const used=all.length,lb=svLbl(),fresh=all.filter(x=>(x.d.S.age|0)<1),live=all.filter(x=>(x.d.S.age|0)>=1).sort((a,b)=>(b.d.t||0)-(a.d.t||0));
