 fresh.forEach(x=>{h+=`<div class="svf" data-n="${x.n}"><span>🍼 ช่อง ${x.n} · ยังไม่เริ่ม <span class="tag2">(${esc(x.d.S.name)})</span></span><button class="svPlay" data-p="${x.n}">▶</button><button class="svX" data-x="${x.n}" aria-label="ล้างช่อง ${x.n}">✕</button></div>`});
