 document.addEventListener('pointerdown',e=>{const c=e.target.closest&&e.target.closest('#contBox .svc');if(!c||e.target.closest('.svM'))return;fired=0;st={x:e.clientX,y:e.clientY,c};clearTimeout(t);c.classList.add('press');t=setTimeout(()=>{fired=1;c.classList.remove('press');open(c,+c.dataset.n)},430)},{passive:true});
