function maGhost(sn,cls,ms,inMask){if(!sn)return null;const g0=sn.c;g0.classList.add('maGhost',cls);Object.assign(g0.style,{position:'fixed',left:sn.r.left+'px',top:sn.r.top+'px',width:sn.r.width+'px',height:sn.r.height+'px',maxHeight:'none',margin:'0',pointerEvents:'none',overflow:'hidden'});
 (inMask?$('mask'):document.body).appendChild(g0);try{g0.scrollTop=sn.sc}catch(e){}setTimeout(()=>{try{g0.remove()}catch(e){}},ms);return g0}
function maKind(k,M){if(MA_LOCK(k))return'sheet';if(MA_ALERT.test(k||''))return'alert';const big=M.querySelector('.tabs,.mgrid,.tmgrid,.sysbox,#chatBox,.gdc,.item');if(!big&&(M.textContent||'').length<420&&M.querySelector('.brow'))return'alert';
 const t=MA.tap;if(t&&!t.inM&&Date.now()-t.t<600&&t.y<innerHeight*.58)return'zoom';return'sheet'}
function maStagger(M){let i=0;[...M.children].forEach(ch=>{if(ch.classList.contains('xbtn')||ch.classList.contains('maGrab')||ch.classList.contains('maGhost'))return;ch.style.setProperty('--i',Math.min(i++,14))})}
function maGrab(M,k){if(M.querySelector(':scope>.maGrab'))return;M.insertAdjacentHTML('afterbegin',`<div class="maGrab${MA_LOCK(k)?' lock':''}"><i></i></div>`)}
function maRun(M,cls){M.classList.remove('maSheet','maZoom','maAlert','maPush','maPop','maIn','maLite','maDone');void M.offsetWidth;cls.split(' ').forEach(c=>c&&M.classList.add(c));clearTimeout(M._maT);M._maT=setTimeout(()=>{M.classList.add('maDone');M.classList.remove('maSheet','maZoom','maAlert','maPush','maPop','maLite');M.style.transformOrigin=''},700)}
{const _mdA=modal;modal=function(html,k){const M=$('modal'),on=maOn();let wasOpen=modalOpen&&$('mask').classList.contains('on'),prevK=M.dataset.k||'',sn=null;
 const cl=MA.closed;if(!wasOpen&&cl&&Date.now()-cl.t<120){wasOpen=true;prevK=cl.k;sn=cl.sn;try{cl.g&&cl.g.remove();cl.bd&&cl.bd.remove()}catch(e){}MA.closed=null}
 else if(wasOpen&&on&&(k||'')!==prevK)sn=maSnap();
 const f0=M.firstChild;const r=_mdA.apply(this,arguments);
 try{if(M.firstChild===f0||!on)return r;k=k||'';const shown=$('mask').classList.contains('on');
  if(on===1){if(!wasOpen&&shown)maRun(M,'maLite');return r}
  if(!wasOpen){MA.stack=[k];const kind=maKind(k,M);MA.mode=kind;if(kind!=='alert')maGrab(M,k);maStagger(M);
   if(kind==='zoom'){const rc=M.getBoundingClientRect(),t=MA.tap;M.style.transformOrigin=`${Math.round(t.x-rc.left)}px ${Math.round(t.y-rc.top)}px`}
   if(shown)maRun(M,'ma'+kind[0].toUpperCase()+kind.slice(1)+(kind==='alert'?'':' maIn'))}
  else if(k===prevK){M.classList.remove('maIn');if(MA.mode!=='alert')maGrab(M,k)}
  else{const st=MA.stack,pop=st.length>=2&&st[st.length-2]===k;if(pop)st.pop();else{st.push(k);if(st.length>8)st.shift()}
   if(MA.mode!=='alert'&&!MA_ALERT.test(k))maGrab(M,k);maStagger(M);maGhost(sn,pop?'maPopOut':'maPushOut',360,true);maRun(M,(pop?'maPop':'maPush')+' maIn')}}catch(e){console.error(e)}return r}}
{const _cmA=closeM;closeM=function(){const M=$('modal'),on=maOn()===2,was=$('mask').classList.contains('on')&&modalOpen,k=M.dataset.k||'';const sn=on&&was?maSnap():null;const r=_cmA.apply(this,arguments);
 try{if(sn){const mode=MA.mode||'sheet',bd=document.createElement('div');bd.className='maBdOut';document.body.appendChild(bd);setTimeout(()=>{try{bd.remove()}catch(e){}},300);
  const cls=mode==='zoom'?'maZoomOut':mode==='alert'?'maAlertOut':'maSheetOut';if(mode==='zoom')sn.c.style.transformOrigin=M.style.transformOrigin||'50% 50%';const g=maGhost(sn,cls,300,false);MA.closed={t:Date.now(),k,sn:maSnap0(sn),g,bd};MA.stack=[]}}catch(e){}return r}}
