function fdSpec(btn,id){const lb=btn.textContent.replace(/\s+/g,' ').trim();const m=lb.match(/^(\S+)\s+(.*)$/);const ic=m?m[1]:'🎯',t=(m?m[2]:lb).replace(/\+.*$/,'').trim();
 const d=FDESC[id]?FDESC[id]():['เลือกเป็นสิ่งที่ทำทั้งปี'];let gh='';try{gh=(window.GH||GH||{})[id]||''}catch(e){}
 const rows=d.map(x=>({info:x}));const on=S&&S.focus===id,ok=!btn.disabled;rows.push({sep:1});
 rows.push(on?{info:'✅ กำลังทำอยู่'}:ok?{ic:'🎯',t:'เลือกอันนี้',r:'›',f:()=>{setFocus(id);try{qmClose()}catch(e){}}}:{info:'🔒 ยังเลือกไม่ได้ตอนนี้'});
 return{ic,t,sub:gh,rows}}
(()=>{let tm=0,st=null,fired=0;const sel='#focus .fc';
 const idOf=b=>{const m=(b.getAttribute('onclick')||'').match(/setFocus\('(\w+)'\)/);return m&&m[1]};
 const open=b=>{const id=idOf(b);if(!id)return;fired=1;try{navigator.vibrate&&navigator.vibrate(12)}catch(e){}
  if(typeof qmOpen==='function')qmOpen(b,()=>fdSpec(b,id));else{const s=fdSpec(b,id);toast(s.t+': '+s.rows[0].info)}};
 document.addEventListener('pointerdown',e=>{const b=e.target.closest&&e.target.closest(sel);if(!b||e.button>0||!idOf(b))return;fired=0;st={x:e.clientX,y:e.clientY,b};clearTimeout(tm);tm=setTimeout(()=>{if(st)open(st.b)},420)},true);
 document.addEventListener('pointermove',e=>{if(st&&Math.hypot(e.clientX-st.x,e.clientY-st.y)>10){clearTimeout(tm);st=null}},true);
 ['pointerup','pointercancel'].forEach(ev=>document.addEventListener(ev,()=>{clearTimeout(tm);st=null},true));
 document.addEventListener('click',e=>{if(fired&&e.target.closest&&e.target.closest(sel)){e.preventDefault();e.stopPropagation();fired=0}},true);
 document.addEventListener('contextmenu',e=>{const b=e.target.closest&&e.target.closest(sel);if(b&&idOf(b)){e.preventDefault();if(!fired&&!(typeof QM!=='undefined'&&QM.el))open(b)}},true);
 const css=document.createElement('style');css.textContent=`#focus .fc{-webkit-touch-callout:none;-webkit-user-select:none;user-select:none}`;document.head.appendChild(css);
 {const _sf=setFocus;setFocus=function(){const r=_sf.apply(this,arguments);try{if(!LS.get('murim_fchint',0)){LS.set('murim_fchint',1);toast('💡 กดค้างที่ปุ่มเพื่อดูว่าแต่ละอย่างได้อะไร')}}catch(e){}return r}}
})();


// ===================== ชิปข้างชื่อไม่ล้นไปทับปุ่มออนไลน์ =====================
function islFit(d){try{d=d||$('islDock');if(!d||!d.isConnected)return;const info=d.parentElement,W=info.clientWidth;if(!W)return;
 d.classList.remove('tight','flow');const L0=parseFloat(d.style.left)||0;
 const fit=()=>L0+d.offsetWidth<=W-2;
 if(!fit())d.classList.add('tight');
 if(!fit()){d.classList.add('flow');const nm=$('gName');if(nm&&nm.nextSibling!==d)nm.after(d)}
}catch(e){}}
{const _idE=islDockEl;islDockEl=function(){const d=_idE.apply(this,arguments);if(d){islFit(d);requestAnimationFrame(()=>islFit(d))}return d}}
{const _icF=islChip;islChip=function(){const c=_icF.apply(this,arguments);try{requestAnimationFrame(()=>islFit())}catch(e){}return c}}
window.addEventListener('resize',()=>{try{if($('islDock'))islDockEl()}catch(e){}});
try{new ResizeObserver(()=>{const d=$('islDock');if(d)islFit(d)}).observe(document.body)}catch(e){}
(()=>{const st=document.createElement('style');st.textContent=`#islDock{flex-wrap:nowrap;white-space:nowrap}
#islDock.tight{gap:2px}#islDock.tight .islChip{padding:0 4px 0 3px;gap:2px}#islDock.tight .islChip>span,#islDock.tight .islChip small{display:none}
#islDock.flow{position:static!important;display:flex;flex-wrap:wrap;margin:2px 0 3px;left:auto!important;top:auto!important}`;document.head.appendChild(st)})();


