QQ.muse={
w:['ฤดูใบไม้ร่วงทุกปีเหมือนกันหมด ข้าต่างหากที่เปลี่ยน','ยุทธภพไม่มีคนดีกับคนเลว มีแต่คนที่ยังไม่ถูกบีบให้เลือก','ดาบที่คมที่สุดคือดาบที่ไม่ต้องชัก','m|อย่าถามว่ายุทธภพให้อะไรเจ้า ถามว่าเจ้าทิ้งอะไรไว้ให้ยุทธภพ','หิมะแรกของปี ทำให้ทั้งเมืองเงียบ แม้แต่คนที่อยากฆ่ากัน','s|ข้าดื่มเหล้าเพื่อลืม แต่จำได้ทุกครั้งว่าลืมอะไร','ข้าศึกษาวิชามาครึ่งชีวิต เพิ่งรู้ว่าวิชาที่ยากที่สุดคือการให้อภัย','คนที่ตะโกนดังที่สุดในโรงเตี๊ยม ไม่เคยเป็นคนที่เก่งที่สุดในห้อง','m|ทุกกระบวนท่ามีช่องโหว่ ทุกคนก็เช่นกัน','จันทร์เต็มดวงคืนนี้ ส่องทั้งคนดีและโจรเท่ากัน','สิ่งที่ข้าเรียนรู้จากยุทธภพ คือทุกคนกลัวอะไรบางอย่าง','s|ฟ้าจะครึ้ม แต่ข้าวยังต้องหุง','ข้าเขียนจดหมายถึงตัวเองเมื่อสิบปีก่อน แล้วเผามันทิ้ง บางเรื่องไม่ต้องรู้ล่วงหน้า','ใบไม้ไม่เคยถามว่าทำไมต้องร่วง มันแค่ร่วงอย่างสวยงาม','m|คนฉลาดเรียนจากความผิดของตัวเอง คนฉลาดกว่าเรียนจากความผิดของคนอื่น'],
x:['ร้อยปีเหมือนชั่วฝันเดียว แต่ฝันนั้นยาวพอจะลืมว่าเคยตื่น','m|เต๋าไม่ได้อยู่ข้างหน้า มันอยู่ใต้ฝ่าเท้าทุกก้าว','ข้ามองดอกไม้ที่บานแค่คืนเดียว แล้วอิจฉามันนิดหน่อย','s|เซียนก็ยังต้องกินข้าว ไม่อย่างนั้นจะไปเอาแรงที่ไหนมาเท่','ทะเลเมฆเปลี่ยนรูปทุกวินาที ไม่มีใครเห็นมันซ้ำสองครั้ง เหมือนชีวิต','m|การบำเพ็ญคือการลอกเปลือกทีละชั้น จนเหลือแต่สิ่งที่เป็นจริง','ข้าได้ยินเสียงหัวใจของภูเขา มันเต้นช้ากว่าข้าหมื่นเท่า','s|โลกเซียนกว้างใหญ่ แต่ข่าวลือก็ยังวิ่งเร็วกว่ากระบี่บิน','ทุกขั้นที่ขึ้นไป ข้าเห็นว่าข้างล่างเล็กลง แต่ไม่ได้สำคัญน้อยลง','m|อย่ายึดติดกับความไม่ยึดติด มันก็เป็นการยึดติดแบบหนึ่ง','ดาวที่ข้าเห็นตอนเด็กยังอยู่ที่เดิม ข้าย้ายไปไกลแค่ไหนก็ยังเห็น','ความจริงของฟ้าอยู่ในหยดน้ำ ในเม็ดทราย ในลมหายใจ ไม่ใช่ในคัมภีร์'],
g:['กาลเวลาเป็นแม่น้ำ ข้ายืนอยู่บนฝั่ง แต่บางวันข้ายังเปียก','m|การเป็นเทพไม่ได้ทำให้คำถามน้อยลง มันทำให้คำถามใหญ่ขึ้น','ข้าเห็นจุดเริ่มต้นของจักรวาลในความฝัน มันเริ่มจากความเงียบเหมือนกัน','s|ท่านคิดว่าเหนือแดนเทพยังมีอะไรอีกไหม ... ข้าหวังว่ามี','ทุกกฎของฟ้าที่ข้าเข้าใจ เปิดประตูให้กฎที่ข้าไม่เข้าใจอีกสิบข้อ','m|ความรู้ไร้ขอบเขต แต่ความเข้าใจต้องเริ่มจากหัวใจ','ข้ามองโลกล่างหมุน เด็กคนหนึ่งกำลังมองฟ้า ข้าโบกมือ เขาไม่เห็น','สิ่งที่เทพกับมนุษย์มีเหมือนกัน คือความสงสัยว่าทำไมต้องมีชีวิต','s|แม้แต่แสงดาวยังต้องเดินทางนาน กว่าจะไปถึงใครสักคน','นิรันดร์ไม่ได้แปลว่าไม่มีจุดจบ แปลว่าจุดจบไกลจนลืมว่ามันมี'],
a:['ทุกวันที่ยังหายใจ คือวันที่ยังเปลี่ยนแปลงได้','ข้าไม่รู้ว่าเส้นทางนี้ถูกไหม แต่มันเป็นของข้า','f|คิดมากไปแล้ว มากินข้าวเถอะ','ฟ้าไม่เคยสัญญาอะไรกับใคร','ชีวิตเหมือนชาร้อน ถ้ารอนานเกินไปมันจะเย็น','ทุกคนที่ข้าพบสอนอะไรข้าสักอย่าง แม้แต่คนที่ข้าเกลียด','ความเงียบตอนเช้าตรู่ เป็นเวลาเดียวที่ข้าได้ยินตัวเองชัด']};

// ===================== คำคม: ระบบ =====================
const QQ_SIT={win:'หลังชนะศึก',lose:'หลังพ่ายแพ้',kill:'หลังสังหาร',alone:'ยามอยู่ลำพัง',city:'ในเมือง',road:'ระหว่างทาง',brk:'หลังทะลวงขั้น',brkF:'ยามติดคอขวด',grief:'ยามสูญเสีย',love:'ยามมีคนรัก',child:'ยามมีลูก',old:'ยามชรา',rich:'ยามร่ำรวย',poor:'ยามยากจน',fame:'ยามมีชื่อเสียง',sect:'ในสำนัก',sick:'ยามเจ็บป่วย',rest:'ยามพักผ่อน',dark:'ยามเดินทางมืด',good:'ยามทำความดี',youth:'ยามเยาว์วัย',muse:'ยามใคร่ครวญ',mw:'ในยุคปัจจุบัน'};
const QQ_ALL=(()=>{const L=[];for(const s in QQ)for(const w in QQ[s])QQ[s][w].forEach((t,i)=>L.push([s+'.'+w+'.'+i,t]));return L})();
function qqWorld(){try{if(typeof mwOn==='function'&&mwOn())return'mw'}catch(e){}return S.xt?'g':S.xian?'x':'w'}
function qqSpk(code,sit,W){const M={w:'ผู้อาวุโสคนหนึ่ง',x:'ผู้บำเพ็ญชรา',g:'เทพชราองค์หนึ่ง',mw:'ชายชราข้างทาง'};
 if(code==='m')return M[W]||M.w;if(code==='e')return sit==='kill'?'ศัตรูก่อนสิ้นลม':'ศัตรู';if(code==='s')return W==='mw'?'คนแปลกหน้า':'คนแปลกหน้า';
 if(code==='f'){if((sit==='love'||sit==='child')&&S.spouse)return typeof S.spouse==='string'?S.spouse:(S.spouse.n||'คนรัก');return'คนที่บ้าน'}return''}
function qqSeen(){try{return LS.get('murim_qqseen',{})||{}}catch(e){return{}}}
function qqPick(sit){const W=qqWorld();let pool=[];
 if(W==='mw'){if(S.mw&&S.mw.native)return null;QQ.mw.a.forEach((t,i)=>pool.push(['mw.a.'+i,t]))}
 else{const Q=QQ[sit]||QQ.muse;(Q[W]||[]).forEach((t,i)=>pool.push([sit+'.'+W+'.'+i,t]));(Q.a||[]).forEach((t,i)=>pool.push([sit+'.a.'+i,t]))}
 if(!pool.length)return null;const seen=qqSeen(),mine=(S.qqL||[]);
 let fresh=pool.filter(p=>!seen[p[0]]&&!mine.includes(p[0]));if(!fresh.length)fresh=pool.filter(p=>!mine.includes(p[0]));if(!fresh.length)fresh=pool;
 const p=ch(fresh);return{id:p[0],t:p[1],W,sit:W==='mw'?'mw':sit}}
function qqShow(sit){if(!S||!S.alive)return false;const q=qqPick(sit);if(!q)return false;
 const m=q.t.match(/^([mesf])\|(.*)$/);const who=m?qqSpk(m[1],q.sit,q.W):'',txt=m?m[2]:q.t;
 S.qqL=S.qqL||[];S.qqL.push(q.id);if(S.qqL.length>40)S.qqL.shift();
 try{const s=qqSeen();s[q.id]=1;LS.set('murim_qqseen',s)}catch(e){}try{cdxAdd('qq',q.id)}catch(e){}
 log(`<div class="qqBox"><span class="qqQ">「${txt}」</span><span class="qqW">${who?'— '+esc(who):'— ความคิดในใจ'} · <i>${QQ_SIT[q.sit]||''}</i></span></div>`,'qq');return true}
function qqSnap(){const kidsA=(S.children||[]).filter(c=>c.alive).length,parA=(S.parents||[]).filter(p=>p.alive).length;
 return{ri:realmIdx(),k:S.kills||0,hp:S.maxHp?S.hp/S.maxHp:1,m:S.money||0,kn:(S.children||[]).length,kA:kidsA,pA:parA,sp:!!S.spouse,fa:!!S.faction,fm:S.fame||0,ka:S.karma||0,ch:!!S.chronic,age:S.age}}
function qqTick(b){if(!S||!S.alive||!b)return;if(S.beastMode&&!S.beastMode.human)return;if(S.age<10)return;
 const a=qqSnap(),C={},add=(k,w)=>{C[k]=(C[k]||0)+w};let big=0;
 S._qqN=(S._qqN||0)+1;if(S._qqRi==null||a.ri!==S._qqRi){S._qqRi=a.ri;S._qqRiY=S._qqN}
 if(a.ri>b.ri){add('brk',6);big=1}
 if(a.pA<b.pA||a.kA<b.kA||(b.sp&&!a.sp)){add('grief',8);big=1}
 if(!b.sp&&a.sp){add('love',6);big=1}
 if(a.kn>b.kn){add('child',6);big=1}
 const dk=a.k-b.k;if(dk>0){add('win',2);if(dk>=3||[10,50,100,300].some(n=>b.k<n&&a.k>=n))add('kill',2.5)}
 if(a.hp<.35&&b.hp>=.35)add('lose',3.5);
 if(a.ch&&!b.ch)add('sick',4);else if(a.ch)add('sick',.6);
 const mx=S._qqMx||0;if(a.m>Math.max(mx*2.5,5000)){S._qqMx=a.m;if(mx)add('rich',2.5)}if(mx>20000&&a.m<mx*.05){add('poor',3);S._qqMx=Math.max(a.m,1000)}else if(a.m<200&&S.age>=18)add('poor',.6);
 if(a.fm>b.fm*1.3&&a.fm>500)add('fame',2);
 if(!b.fa&&a.fa){add('sect',3)}
 if(a.ka<=-30&&a.ka<b.ka)add('dark',2.5);if(a.ka-b.ka>=5)add('good',1.8);else if(a.ka>=50)add('good',.4);
 try{if(S.age>lifeMax()*.8)add('old',2)}catch(e){}
 if(S.age>=12&&S.age<=20)add('youth',1.5);
 if(S._qqN-(S._qqRiY||0)>=20&&a.ri<7)add('brkF',1.4);
 const F={train:'alone',qi:'alone',work:'city',adv:'road',rest:'rest',mission:'sect',hhunt:'kill',study:'muse',craft:'alone'}[S.focus];if(F)add(F,1.6);
 if(S.focus==='love')add(S.children&&S.children.length?'child':'love',1.2);
 add('muse',.7);
 const gap=S._qqN-(S._qqLast||-99),need=S._qqGap||(S._qqGap=R(9,16));
 if(!(gap>=need||(big&&gap>=4&&Math.random()<.6)))return;
 if(!big&&Math.random()<.35)return;
 const tot=Object.values(C).reduce((x,y)=>x+y,0);let r=Math.random()*tot,sit='muse';for(const k in C){if((r-=C[k])<=0){sit=k;break}}
 if(qqShow(sit)){S._qqLast=S._qqN;S._qqGap=R(9,16)}}
{const _pyQQ=passYear;passYear=function(){let b=null;try{if(S&&S.alive)b=qqSnap()}catch(e){}const r=_pyQQ.apply(this,arguments);try{qqTick(b)}catch(e){console.error(e)}return r}}
// สารานุกรม
{const _ccQ=cxCats;cxCats=function(){const L=_ccQ.apply(this,arguments);try{L.push({g:'other',ic:'💬',t:'คำที่จำได้',te:'Remembered words',cat:'qq',L:QQ_ALL.map(([id,t])=>[id,t.replace(/^[mesf]\|/,''),false])})}catch(e){}return L}}
