islFly=function(fromEl,toEl,done){try{if(islLite()||!fromEl||!toEl||!fromEl.getBoundingClientRect().width){done();return}
 const a=fromEl.getBoundingClientRect(),b=toEl.getBoundingClientRect();const g=document.createElement('div');g.className='islGhost '+(document.getElementById('isl').className||'');
 g.innerHTML=`<span>${(toEl.querySelector('i')||{}).innerHTML||''}</span>`;Object.assign(g.style,{left:'0px',top:'0px',width:a.width+'px',height:a.height+'px',transform:'none'});document.body.appendChild(g);
 const P0=[a.left+a.width/2,a.top+a.height/2],P2=[b.left+b.width/2,b.top+b.height/2],P1=[P0[0]+(P2[0]-P0[0])*.85,P0[1]+(P2[1]-P0[1])*.05-14];
 const ez=t=>t<.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2,F=[],N=16;
 for(let i=0;i<=N;i++){const t=ez(i/N),u=1-t,x=u*u*P0[0]+2*u*t*P1[0]+t*t*P2[0],y=u*u*P0[1]+2*u*t*P1[1]+t*t*P2[1],k=Math.pow(t,.75),w=a.width+(b.width-a.width)*k,h=a.height+(b.height-a.height)*k;
  F.push({left:(x-w/2)+'px',top:(y-h/2)+'px',width:w+'px',height:h+'px',borderRadius:Math.min(h/2,22)+'px',opacity:i===N?.92:1,offset:i/N})}
 const an=g.animate(F,{duration:720,easing:'linear',fill:'forwards'});const sp=g.querySelector('span');if(sp)sp.animate([{transform:'scale(1)'},{transform:'scale(1.25)',offset:.4},{transform:'scale(1)'}],{duration:720});
 an.onfinish=()=>{g.remove();done()}}catch(e){try{done()}catch(x){}}};
