{const _lsS=liveSnap;liveSnap=function(){const o=_lsS.apply(this,arguments);try{o.xt=S.xt?1:0;o.mw=(typeof mwOn==='function'&&mwOn())?1:0;if(typeof gsOn==='function'&&gsOn())o.gk=gsKind(sceneType())}catch(e){}return o}}
