function grudgeTick(){const L=grudges();L.forEach(g=>{if(!g.done){if(S.age-g.y>=25)g.pw=Math.max(10,Math.round(g.pw*.94));else g.pw=Math.round(g.pw*(1.02+Math.random()*.03))}});
 const live=L.filter(x=>!x.done);if(live.length&&Math.random()<.04&&wxFree()){const g=ch(live);const w=fight(g.n,g.pw);
  if(w){g.done=1;S.fame+=Math.round(60+g.pw/Math.max(1,total())*80);log(`🗡️ <b>${esc(g.n)}</b> ตามมาถึงหน้าบ้านเพื่อปิดบัญชีเก่า แต่คนที่ล้มลงคือเขา · ขีดฆ่าชื่อออกจากบัญชีแค้น`,'epic',true);keyAdd('ชำระแค้นกับ'+g.n)}
  else{S.hp=Math.max(1,Math.round(S.hp-S.maxHp*.35));log(`🩸 <b>${esc(g.n)}</b> บุกมาหาเรื่องถึงที่ และคุณยังสู้ไม่ได้ แค้นนี้ยังไม่จบ`,'bad')}}}
function grudgePlan(i){const g=grudges()[i];if(!g||g.done)return;const W=W15s(),gap=Math.round(g.pw/Math.max(1,total())),cp=Math.round(R(200,400)*W),ct=Math.round(R(120,250)*W);
 const allies=(S.allies||[]).length+peers.filter(p=>p.alive&&p.rel==='friend').length+(S.faction?1:0),gun=S.items.find(x=>x.id==='gun'&&x.left>0),plasma=has('plasma');
 const done=(how,tx,fame,kar)=>{g.done=1;S.fame+=fame;if(kar)S.karma+=kar;joy(10);log(`🕯️ ${tx} — ขีดชื่อ <b>${esc(g.n)}</b> ออกจากบัญชีแค้นโดยไม่ต้องสู้ซึ่งหน้า`,'epic',true);keyAdd('ชำระแค้นกับ'+g.n+' ('+how+')');render();checkDeath()};
 const fail=(tx,extra)=>{S.hp=Math.max(1,Math.round(S.hp-S.maxHp*.3));joy(-6);g.pw=Math.round(g.pw*1.1);log(`💢 ${tx} — <b>${esc(g.n)}</b> รู้ตัวและระวังหนักขึ้น${extra||''}`,'bad');render();checkDeath()};
 const O=[];
 if(gun)O.push({t:'🔫 ใช้ปืนที่ซ่อนไว้',s:`โอกาส ~75% · ใช้กระสุน 1 นัด (เหลือ ${gun.left}) · ไม่ต้องแรงเท่าเขา`,f(){gun.left--;S.flags.gun=1;if(Math.random()<.75)done('ปืน','เสียงปืนนัดเดียวดังก้องลานกว้าง ไม่มีใครเตรียมรับสิ่งนี้ได้',70,-3);else fail('กระสุนพลาดเป้า')}});
 else if(plasma)O.push({t:'⚡ ใช้อาวุธพลาสมาจากต่างโลก',s:'โอกาส ~60% · ความรู้ที่ยุทธภพไม่เคยเห็น',f(){if(Math.random()<.6)done('พลาสมา','แสงสว่างวาบเดียวจบเรื่องที่ค้างมาหลายปี',70,-3);else fail('อาวุธค้างกลางทาง')}});
 O.push({t:'☠️ วางยาในเหล้าหรืออาหาร',s:`ต้นทุน ${fmt(cp)} · โอกาส ${Math.round(Math.max(10,Math.min(50,12+S.int/5)))}% · กรรมติดลบ`,f(){if((S.money||0)<cp)return toast('เงินไม่พอซื้อยา');S.money-=cp;const p=Math.max(.1,Math.min(.5,.12+S.int/500));if(Math.random()<p)done('วางยา','ยาที่คุณผสมถูกเสิร์ฟบนโต๊ะเขาโดยไม่มีใครสงสัย',50,-8);else fail('ยาถูกตรวจพบก่อนถึงปาก')}});
 O.push({t:'🪤 ซุ่มวางกับดักบนเส้นทางที่เขาต้องผ่าน',s:`ต้นทุน ${fmt(ct)} · โอกาส ${Math.round(Math.max(12,Math.min(35,15+S.int/8)))}%`,f(){if((S.money||0)<ct)return toast('เงินไม่พอ');S.money-=ct;const p=Math.max(.12,Math.min(.35,.15+S.int/800));if(Math.random()<p)done('กับดัก','เส้นทางที่เขาเดินประจำพาตัวเขาลงหลุมที่คุณขุดไว้',60,-4);else fail('เขาเห็นร่องรอยกับดักแล้วเดินอ้อม')}});
 if(allies>0)O.push({t:'🤝 ขอพันธมิตรให้ช่วยจัดการ',s:`ผู้ช่วย ${allies} · โอกาส ~${Math.round(Math.min(70,20+allies*12))}% · ถ้าพลาดอาจเสียพันธมิตร`,f(){if(Math.random()<Math.min(.7,.2+allies*.12))done('พันธมิตร','คนที่เคยร่วมสาบานกับคุณพาพวกไปปิดบัญชีให้',40,0);else{if(S.allies&&S.allies.length)S.allies.pop();fail('พันธมิตรถูกตีแตก','')}}});
 O.push({t:'⏳ ฝึกต่อและรอ เขาจะแก่ลงสักวัน',s:`ตอนนี้เขาแรงกว่าคุณ ~${fmt(gap)} เท่า · หลังจดชื่อไป 25 ปี พลังเขาจะเสื่อมถอยลงทุกปี`,f(){toast('ฝึกต่อไป แล้ววันหนึ่งบัญชีนี้จะเอื้อมถึง')}});
 choice('🕯️ แผนล้างแค้นของคนตัวเล็ก',`<b>${esc(g.n)}</b> แกร่งกว่าคุณราว <b>${fmt(gap)} เท่า</b> ดวลซึ่งหน้ามีแต่ตาย คนอ่อนกว่าต้องใช้หัวแทนกำลัง<br><span class="tag2">${esc(g.why)}</span>`,O)}
function grudgeGo(i){const g=grudges()[i];if(!g||g.done)return;if(choice._cur)return toast('ตัดสินใจเรื่องที่ค้างก่อน');closeM();if(g.pw>total()*4)return grudgePlan(i);
 duel(g.n,g.pw,w=>{if(w){g.done=1;const f=Math.round(80+g.pw/Math.max(1,total())*120);S.fame+=f;joy(12);log(`⚔️ ชำระแค้นกับ <b>${esc(g.n)}</b> สำเร็จ — ${esc(g.why)} ... บัดนี้หมดหนี้กันแล้ว · ชื่อเสียง +${fmt(f)}`,'epic',true);keyAdd('ชำระแค้นกับ'+g.n);try{qqShow&&Math.random()<.5&&qqShow('kill')}catch(e){}}
  else{S.hp=Math.max(1,Math.round(S.hp-S.maxHp*.3));joy(-6);log(`💢 ไปทวงแค้น <b>${esc(g.n)}</b> แต่พ่ายกลับมา เขายิ้มเยาะว่า "กลับไปฝึกอีกสิบปี"`,'bad')}render();checkDeath()})}
// ---------- 1) ถอนหมั้น ----------
function betroOffer(){if(S.flags.betro||S.age<15||S.age>19||S.spouse||!wxFree()||Math.random()>.1)return;S.flags.betro=1;const sur=wxSur(),nm=sur+' '+anyName(wxGen()).split(' ').pop(),fam='ตระกูล'+sur,elder='ผู้อาวุโส'+anyName('ชาย').split(' ').pop();
 WX.b={nm,fam};
 choice('📜 หนังสือหมั้นถูกโยนกลางโถง',`${elder}แห่ง<b>${fam}</b>เดินเข้าบ้านคุณพร้อมคนติดตามเต็มลาน ไม่นั่ง ไม่ดื่มชา วางหนังสือหมั้นที่ปู่ของสองตระกูลเคยเซ็นไว้ลงบนโต๊ะ แล้วพูดเสียงดังพอให้เพื่อนบ้านได้ยิน<br><br>"<b>${esc(nm)}</b>เป็นอัจฉริยะของตระกูลเรา ส่วนคน<b>${esc(S.family.n)}</b>... ไม่คู่ควร วันนี้เรามาถอนหมั้น"<br><span class="tag2">${esc(nm)}ยืนอยู่ข้างหลัง ไม่สบตาคุณ</span>`,[
  {t:'📅 "อีกสามปี ข้าจะไปหาเจ้าที่ประตูตระกูล"',s:'สาบานต่อหน้าทุกคน · ถ้าแข็งแกร่งพอตอนครบกำหนด จะได้พลิกกลับ',f(){const tr=Math.max(total()*2.6,(REALMS[Math.min(REALMS.length-1,realmIdx()+1)]||{p:total()*3}).p);S.vow={nm,fam,by:S.age+3,tp:Math.round(tr)};joy(-8);keyAdd(`ถูก${fam}ถอนหมั้น — สาบานนัดสามปี`);log(`📅 คุณฉีกหนังสือหมั้นด้วยมือตัวเอง "สามปีจากนี้ ข้าจะไปยืนที่ประตู${fam} แล้วค่อยดูว่าใครไม่คู่ควร" · ต้องมีพลังราว <b>${fmt(S.vow.tp)}</b> ภายในอายุ ${S.vow.by}`,'epic',true);grudgeAdd(nm,`ถอนหมั้นกลางโถงบ้าน นัดกันไว้อีกสามปี`,S.vow.tp*.8,'betro')}},
  {t:'🍵 รับไว้เงียบๆ',s:'ไม่มีเรื่อง · แต่คนในเมืองนินทาไปอีกนาน',f(){joy(-12);S.int+=4;S.fame=Math.max(0,S.fame-20);log(`🍵 คุณรินชาให้${elder}ทั้งที่มือสั่น แล้วคืนหนังสือหมั้นให้ไปโดยไม่พูดอะไร คืนนั้นคุณนั่งอยู่ลานฝึกจนเช้า`,'bad')}},
  {t:'🔥 "ถอนหมั้นหรือ ข้าเป็นฝ่ายถอนเอง"',s:'ชิงฉีกก่อน · ได้หน้าคืนวันนี้ แต่ได้ศัตรูทั้งตระกูล',f(){S.fame+=40;joy(4);log(`🔥 คุณหยิบพู่กันเขียนทับหนังสือหมั้นว่า "<b>เลิก</b>" แล้วยื่นคืน "ฝากบอกคนของตระกูลด้วยว่า คน${esc(S.family.n)}เป็นฝ่ายไม่เอาเอง" · เสียงหัวเราะดังทั่วลาน`,'epic');grudgeAdd(elder+' แห่ง'+fam,'อับอายต่อหน้าคนทั้งเมืองเพราะคุณ',total()*1.6,'betro')}}])}
function vowTick(){const v=S.vow;if(!v||v.done||S.age<v.by||!wxFree())return;v.done=1;const ok=total()>=v.tp;
 if(!ok){S.fame=Math.max(0,Math.round(S.fame*.7));joy(-18);log(`🥀 ครบสามปีแล้ว คุณยังไม่แข็งแกร่งพอจะไปยืนที่ประตู${esc(v.fam)} ข่าวลือว่า "คนที่ถูกถอนหมั้นไม่กล้าไป" แพร่ไปทั่ว`,'bad',true);return}
 setScene('fight');choice(`⛩️ ประตู${v.fam} — ครบสามปี`,`คุณมาถึงตรงเวลาตามที่สาบาน ลานหน้าประตูมีคนมุงแน่น ทั้งคนที่มาดูคุณแพ้และคนที่มาดูคุณชนะ<br><b>${esc(v.nm)}</b>ก้าวออกมา สายตาไม่เหมือนสามปีก่อน`,[
  {t:'⚔️ ประลองต่อหน้าทุกคน',s:'ตามสัญญา',f(){duel(v.nm,Math.round(total()*.78),w=>{if(w){S.fame+=Math.round(300+S.fame*.15);joy(25);keyAdd(`กลับไปชนะ${v.nm}ที่ประตู${v.fam}ตามนัดสามปี`);const g=grudges().find(x=>x.n===v.nm);if(g)g.done=1;
     choice('🙇 หลังศึก',`${esc(v.nm)}คุกเข่าข้างหนึ่ง ลมหายใจหอบ ผู้อาวุโสของ${esc(v.fam)}ที่เคยโยนหนังสือหมั้นยืนหน้าซีดอยู่บนบันได`,[
      {t:'🤝 ยื่นมือดึงขึ้น',s:'จบกันด้วยดี',f(){S.karma+=15;log(`🤝 "สามปีก่อนเจ้าไม่ได้เลือกเอง ข้ารู้" คุณดึง${esc(v.nm)}ขึ้นยืน คนทั้งลานเงียบ แล้วเสียงปรบมือก็ดังขึ้นทีละคน`,'epic',true);if(!S.spouse&&Math.random()<.35){log(`💌 หลายเดือนต่อมา มีจดหมายจาก${esc(v.nm)}มาถึง ลายมือเรียบร้อยกว่าที่คิด`,'')}}},
      {t:'🗣️ หันไปมองผู้อาวุโส',s:'คืนสิ่งที่ได้รับมา',f(){S.fame+=120;S.karma-=5;log(`🗣️ คุณเงยหน้ามองบันได "คนไม่คู่ควรเมื่อสามปีก่อน วันนี้ขอลาไปก่อนนะขอรับ" ผู้อาวุโสของ${esc(v.fam)}ไม่กล้าออกจากจวนไปหลายเดือน`,'epic',true)}}])}
    else{S.fame=Math.max(0,Math.round(S.fame*.8));joy(-15);log(`💢 สามปีของคุณยังสั้นกว่าสามปีของ${esc(v.nm)} คุณพ่ายกลางลาน แต่อย่างน้อยก็มาตามนัด`,'bad',true)}render();checkDeath()})}}])}
// ---------- 3) ซ่อนพลัง ----------
function hideOn(){return !!(S&&S.hidePw)}
function hideTog(){S.hidePw=S.hidePw?0:1;toast(S.hidePw?'🫥 ซ่อนพลังแล้ว คนอื่นจะเห็นคุณเป็นแค่คนธรรมดา':'💪 เลิกซ่อนพลัง');openWuxia()}
const YM_N=['คุณชาย','คุณหนู','ศิษย์สายตรง','ทายาทเจ้าเมือง','บุตรผู้อาวุโส'];
function hideTick(f0){if(!hideOn()||!wxOk())return;const d=S.fame-f0;if(d>0)S.fame=f0+Math.round(d*.6);
 if(S.age<14||Math.random()>.09||!wxFree())return;const who=ch(YM_N)+anyName(ch(['ชาย','หญิง'])).split(' ').pop(),ep=Math.round(total()*(.55+Math.random()*.3));
 const sc=ch([`<b>${who}</b>ปัดชามบะหมี่คุณตกพื้น "คนไร้ฝีมืออย่างเจ้า นั่งโต๊ะเดียวกับข้าไม่ได้"`,`<b>${who}</b>ขวางทางคุณกลางตลาด แล้วสั่งให้คุณคุกเข่าขอทาง คนรอบข้างหัวเราะ`,`<b>${who}</b>เหยียบเท้าคุณแล้วยิ้ม "ขอโทษ ไม่เห็น คนไม่มีปราณ มองไม่ค่อยเห็นจริงๆ"`,`<b>${who}</b>แย่งสมุนไพรที่คุณเก็บมาทั้งวัน "ของดีแบบนี้ คนแบบเจ้าใช้ไม่เป็นหรอก"`]);
 choice('🫥 ไม่มีใครรู้ว่าคุณเป็นใคร',sc+`<br><span class="tag2">${esc(who)}เห็นพลังคุณแค่ระดับคนธรรมดา</span>`,[
  {t:'😶 ก้มหน้าเดินผ่านไป',s:'ยังซ่อนต่อ · ใจไม่สงบนิดหน่อย',f(){joy(-3);S.int+=1;log('😶 คุณก้มหน้าเดินจากไป มือที่กำแน่นค่อยๆ คลาย ยังไม่ถึงเวลา')}},
  {t:'⚡ ปล่อยปราณเพียงหนึ่งส่วน',s:'ตบหน้ากลางที่สาธารณะ · ชื่อเสียงพุ่ง',f(){const w=fight(who,ep);if(w){const g=Math.round(120+S.fame*.08);S.fame+=g;joy(8);log(ch([`⚡ แค่คุณเงยหน้า ลมปราณแผ่ออกเพียงเสี้ยว ${esc(who)}ทรุดลงคุกเข่าต่อหน้าคนทั้งตลาดโดยที่คุณยังไม่ได้ขยับนิ้ว · ชื่อเสียง +${fmt(g)}`,`⚡ คุณใช้ตะเกียบคู่เดียวปัดกระบี่ของ${esc(who)}หลุดมือ ปักลงพื้นข้างเท้าเขาพอดี "บะหมี่ชามนั้น ราคาสามอีแปะ" · ชื่อเสียง +${fmt(g)}`,`⚡ ${esc(who)}พุ่งเข้ามาเต็มแรง แล้วกระเด็นออกไปไกลกว่าที่วิ่งเข้ามา ร้านน้ำชาทั้งร้านเงียบกริบ · ชื่อเสียง +${fmt(g)}`]),'epic',true);if(Math.random()<.4)grudgeAdd(who.replace(/^(คุณชาย|คุณหนู)/,'')+' (และผู้อยู่เบื้องหลัง)','ถูกคุณทำให้อับอายกลางเมือง',total()*1.3,'hide')}
   else{S.hp=Math.max(1,S.hp-Math.round(S.maxHp*.25));joy(-8);log(`💢 ${esc(who)}แข็งแกร่งกว่าที่คิด การเปิดเผยพลังครั้งแรกจบลงอย่างน่าอาย`,'bad')}}}])}
// ---------- 4) ตัวตนลับ ----------
const ALIAS_T={alch:{ic:'🎭',n:'ปรมาจารย์ปรุงยาสวมหน้ากาก',d:'ขายยาในตลาดใต้ดิน ได้เงินตามฝีมือปรุงยา · เสี่ยงถูกจับได้น้อย'},sw:{ic:'🗡️',n:'นักดาบไร้นาม',d:'รับงานปราบโจรและท้าประลอง ได้ชื่อเสียงลับและเงิน'},kill:{ic:'🌑',n:'มือสังหารเงา',d:'รับงานลอบสังหาร ได้เงินมาก แต่กรรมลด · ถ้าถูกเปิดโปงหนัก'}};
function aliasMake(t){const nm=(($('alNm')||{}).value||'').replace(/[<>&"'`\\]/g,'').trim().slice(0,20);if(!nm)return toast('ตั้งฉายาก่อน');if(t==='alch'&&!(S.cr&&S.cr.lv&&S.cr.lv.alch>=3))return toast('ฝีมือปรุงยาต้องขั้น 3 ขึ้นไป');
 S.alias={t,n:nm,f:0,y:S.age,risk:0};log(`${ALIAS_T[t].ic} ใต้หน้ากาก คุณคือ <b>${esc(nm)}</b> — ${ALIAS_T[t].n} ไม่มีใครรู้ว่าเป็นคนเดียวกับ${esc(S.name)}`,'epic');keyAdd('สร้างตัวตนลับ '+nm);openWuxia()}
