 try{peopleAll().forEach(x=>{if(!has(x.n))return;out.push(`<b>${esc(x.n)}</b> — ${esc(ciTx(x.role))}<br><span class="tag2">${x.alive?'':'🪦 ล่วงลับ · '}${x.age!=null?'อายุ '+x.age+' · ':''}${x.rel!=null?'ความสัมพันธ์ '+Math.round(x.rel):''}</span>`)})}catch(e){}
