function jBook(){const J=jInit(),c=Math.round(600*W15());if(S.money<c)return toast('เงินไม่พอ');const un=JD.map((d,i)=>i).filter(i=>!J.kn[i]);if(!un.length)return toast('รู้จักโรคครบทุกโรคแล้ว');S.money-=c;const L=un.sort(()=>Math.random()-.5).slice(0,3);L.forEach(i=>J.kn[i]=1);log(`📖 อ่านตำราแพทย์ รู้จัก ${L.map(i=>JD[i].n).join(', ')}`,'good');render();openJob()}
