function jDocUI(i){const J=jInit(),c=J.q[i],D=JD[c.d],P=JD_P.find(p=>p.k===c.p),show=S.int>=150?3:c.show,sy=D.s.slice(0,show);
 const known=JD.map((d,k)=>[d,k]).filter(([d,k])=>J.kn[k]&&sy.every(s=>d.s.includes(s)));
 const btn=m=>{const [ic,n]=JD_M[m],cost=m==='tea'?{herb:1}:m==='poison'?(bagN('cure')?{cure:1}:{herb:2}):null,ok=!cost||Object.keys(cost).every(k=>bagN(k)>=cost[k]),out=c.elim.includes(m);
  return`<button class="opt" onclick="jTreat(${i},'${m}')" ${ok&&!out?'':'disabled style="opacity:.4"'}>${ic} ${n}<small>${out?'❌ ตรวจแล้วว่าไม่ใช่':cost?'ใช้ '+Object.keys(cost).map(k=>BAGIT[k].ic+BAGIT[k].n+' ×'+cost[k]).join(' ')+(ok?'':' ไม่มี (ซื้อที่ย่านช่าง)'):'ไม่ต้องใช้ของ'}</small></button>`};
 modal(`<button class="xbtn" onclick="openJob()">←</button><h3>${P.ic} ${P.n}ป่วย</h3><p class="tag2">${{vil:'จ่ายน้อยแต่ได้กรรมดี',mer:'จ่ายปานกลาง',nob:'จ่ายมาก แต่ถ้ารักษาพลาดโดนปรับ',sec:'จ่ายน้อย แต่ได้ชื่อเสียง',mys:'ไม่มีเงินจ่าย ไม่รู้ว่าเป็นใคร อาจตอบแทนหรือพาเรื่องมาหา'}[c.p]}${P.pay?' · ค่ารักษาราว '+ftMf(jbPay(J,P.pay)):''}</p>
 <div class="item"><b>🔍 อาการ</b><ul style="margin:4px 0;padding-left:18px">${sy.map(s=>`<li>${s}</li>`).join('')}${show<3?'<li class="tag2">… ยังมีอาการที่ต้องตรวจละเอียด</li>':''}</ul>
 ${known.length?`<p style="margin:4px 0;color:#5fb85f">📖 อาการเข้ากับโรคที่คุณรู้จัก: ${known.map(([d])=>`<b>${d.n}</b> → ${JD_M[d.m].join(' ')}`).join(' · ')}${known.length>1?' (เข้าได้หลายโรค ลองตรวจละเอียด)':''}</p>`:'<p class="tag2" style="margin:4px 0">💡 ยังไม่รู้จักโรคนี้ ดูอาการแล้วเดา: ไข้/แผล → ต้มยา · พิษ → ถอนพิษ · ลมปราณ/ชีพจร → ฝังเข็ม · กระดูก/อ่อนแรง/ใจ → พักฟื้น · รักษาครั้งเดียวจะจำโรคได้</p>'}</div>
 <button class="gbtn" style="width:100%;margin:4px 0;${c.ck<jChecks(J)?'':'opacity:.45'}" onclick="jCheck(${i})" ${c.ck<jChecks(J)?'':'disabled'}>🩺 จับชีพจรตรวจละเอียด (เหลือ ${jChecks(J)-c.ck} ครั้ง)<small style="display:block">เผยอาการที่ซ่อนอยู่ หรือตัดวิธีที่ผิดออก 1 วิธี</small></button>
 <div class="mgrid">${Object.keys(JD_M).map(btn).join('')}</div>
 <button class="opt" style="width:100%;margin-top:6px" onclick="jRefer(${i})">↪️ ส่งต่อให้หมอคนอื่น<small>ปลอดภัย ไม่ได้เงิน ไม่เสียอะไร</small></button>`,'job')}
function jCheck(i){const J=jInit(),c=J.q[i];if(!c||c.ck>=jChecks(J))return;c.ck++;const D=JD[c.d];if(c.show<3&&S.int<150){c.show++;toast('พบอาการเพิ่ม')}else{const wr=Object.keys(JD_M).filter(m=>m!==D.m&&!c.elim.includes(m));if(wr.length){c.elim.push(ch(wr));toast('ตัดวิธีที่ไม่ใช่ออก 1 วิธี')}}sfx('click');jDocUI(i)}
function jRefer(i){const J=jInit();J.q.splice(i,1);log('↪️ คุณส่งคนไข้ไปหาหมอที่เชี่ยวชาญกว่า');render();openJob()}
function jTreat(i,m){const J=jInit(),c=J.q[i];if(!c)return;const D=JD[c.d],P=JD_P.find(p=>p.k===c.p);
 if(m==='tea'&&!bagTake('herb',1))return toast('ไม่มีสมุนไพร');if(m==='poison'){if(bagN('cure'))bagTake('cure',1);else if(!bagTake('herb',2))return toast('ต้องมียาถอนพิษ หรือสมุนไพร 2 ต้น')}
 J.q.splice(i,1);const ok=m===D.m;let t='',cls='good';J.kn[c.d]=1;
 if(ok){J.st.ok++;J.rep=Math.min(100,(J.rep==null?50:J.rep)+4);jXp(J,c.p==='nob'?2:1);const g=P.pay?jbPay(J,P.pay):0;S.money+=g;J.st.earn+=g;try{ctRepAdd(6,'รักษาคนไข้')}catch(e){}
  t=`${JD_M[m][1]}ได้ผล! ${P.n}หายจาก<b>${D.n}</b>${g?` — ค่ารักษา ${ftMf(g)}`:''}`;
  if(c.p==='vil'){S.karma+=3;t+=' · กรรมดี +3'}if(c.p==='sec'){S.fame+=10;t+=' · สำนักของเขาติดหนี้บุญคุณ (ชื่อเสียง +10)'}
  if(c.p==='mys'){if(Math.random()<.5){const v=jbPay(J,2500);S.money+=v;J.st.earn+=v;t+=` · หลายเดือนต่อมามีคนนำหีบเงิน ${ftMf(v)} มาส่ง "นายท่านไม่ลืมบุญคุณ"`;cls='epic'}else{t+=' · แต่คนที่ตามล่าเขาตามมาถึงโรงหมอ!';setTimeout(()=>{try{duel('มือสังหารที่ตามล่าคนไข้',Math.round(total()*.9),w=>{if(w){S.fame+=25;log('⚔️ คุณไล่มือสังหารออกไปได้ ชื่อเสียง +25','epic')}else{S.hp-=Math.round(S.maxHp*.2);log('⚔️ มือสังหารทำร้ายคุณก่อนหนีไป พลังชีวิต −20%','bad')}render()})}catch(e){}},600)}}}
 else{J.st.bad++;J.rep=Math.max(0,(J.rep==null?50:J.rep)-6);const die=Math.random()<P.die;t=`${JD_M[m][1]}ไม่ได้ผล ที่จริงเป็น<b>${D.n}</b> (ต้อง${JD_M[D.m][1]}) · คุณจำโรคนี้ไว้แล้ว`;cls='bad';
  if(die){S.karma-=3;t+=` · ${P.n}เสียชีวิต กรรม −3`}else t+=' · ครอบครัวพาไปหาหมออื่นทัน';if(c.p==='nob'){const f=jbPay(J,600);S.money=Math.max(0,S.money-f);t+=` · ขุนนางสั่งปรับ ${ftMf(f)}`}}
 log(`🩺 ${t}`,cls);jResult(t,ok)}
function jPsnUI(i){const J=jInit(),g=jbPay(J,1500);modal(`<button class="xbtn" onclick="openJob()">←</button><h3>🧑‍💼 ชายแปลกหน้า</h3><p>ชายคนหนึ่งปิดหน้าครึ่งซีก วางถุงเงินหนักอึ้งบนโต๊ะ "ข้าต้องการยาที่ทำให้คนหลับแล้วไม่ตื่นอีก… ไม่มีใครรู้หรอก"</p>
 <div class="mgrid"><button class="opt" onclick="jPsn(${i},1)">💰 รับงาน<small>ได้ ${ftMf(g)} · กรรม −15 · 30% ถูกสืบเจอ: ปรับและลดขั้น</small></button><button class="opt" onclick="jPsn(${i},0)">🙅 ปฏิเสธ<small>กรรมดี +3</small></button><button class="opt" onclick="jPsn(${i},2)">⚖️ จับส่งทางการ<small>ต้องสู้ · ชนะได้ชื่อเสียง</small></button></div>`,'job')}
function jPsn(i,a){const J=jInit();J.q.splice(i,1);let t;
 if(a===1){const g=jbPay(J,1500);S.money+=g;J.st.earn+=g;S.karma-=15;t=`คุณปรุงยาพิษให้เขา ได้ ${ftMf(g)} · กรรม −15`;if(Math.random()<.3){J.lv=Math.max(0,J.lv-1);J.xp=JOB_XP[J.lv];J.rep=Math.max(0,(J.rep==null?50:J.rep)-30);const f=Math.round(g*.6);S.money=Math.max(0,S.money-f);t+=` แต่ทางการสืบมาถึงคุณ! โดนปรับ ${ftMf(f)} และลดขั้น`}log('🧪 '+t,'bad');return jResult(t,false)}
 if(a===0){S.karma+=3;t='คุณผลักถุงเงินคืน "ข้าเป็นหมอ ไม่ใช่เพชฌฆาต" · กรรมดี +3';log('🩺 '+t,'good');return jResult(t,true)}
 if(choice._cur){J.q.splice(i,0,{k:'psn',y:S.age,p:'mer'});return toast('ตัดสินใจเรื่องที่ค้างอยู่ก่อน')}
 closeM();duel('ชายปิดหน้า',Math.round(total()*.8),w=>{if(w){S.fame+=20;S.karma+=5;J.rep=Math.min(100,(J.rep==null?50:J.rep)+8);log('⚖️ คุณจับชายปิดหน้าส่งทางการ เขาคือมือสังหารที่ถูกตามล่ามานาน · ชื่อเสียง +20','epic')}else{S.hp-=Math.round(S.maxHp*.15);log('⚖️ ชายปิดหน้าหนีไปได้หลังทำร้ายคุณ','bad')}render()})}
// ---------- หน้าสืบคดี ----------
function jCopUI(i){const J=jInit(),c=J.q[i],ev=c.dims.slice(0,c.show).map((d,k)=>JC_DIM[d][c.cul[k]][1]);
 modal(`<button class="xbtn" onclick="openJob()">←</button><h3>📂 ${JC_CR[c.cr]}</h3><p class="tag2">อ่านหลักฐาน แล้วหาคนที่ลักษณะตรงกับหลักฐาน<b>ทุกข้อ</b> · ชี้ผิดคนบริสุทธิ์จะติดคุกแทน</p>
 <div class="item"><b>🧾 หลักฐาน</b><ol style="margin:4px 0;padding-left:20px">${ev.map(e=>`<li>${e}</li>`).join('')}${c.show<3?'<li class="tag2">??? ต้องสอบปากคำพยาน</li>':''}</ol></div>
 <div style="display:flex;gap:6px;margin:4px 0"><button class="gbtn" style="flex:1;${c.show<3?'':'opacity:.45'}" onclick="jAsk(${i})" ${c.show<3?'':'disabled'}>🗣️ สอบปากคำพยาน<small style="display:block">เผยหลักฐานข้อ 3</small></button>${J.lv>=2?`<button class="gbtn" style="flex:1;${c.elim.length?'opacity:.45':''}" onclick="jSpy(${i})" ${c.elim.length?'disabled':''}>🕵️ แฝงตัวสืบ<small style="display:block">ตัดคนบริสุทธิ์ 1 คน</small></button>`:''}</div>
 <b>👥 ผู้ต้องสงสัย</b>${c.sus.map((s,k)=>{const out=c.elim.includes(k);return`<div class="item" style="${out?'opacity:.45':''}"><div class="h"><b>${esc(s.n)}</b><button class="pbtn" style="padding:6px 14px" onclick="jAccuse(${i},${k})" ${out?'disabled':''}>ชี้ตัว</button></div><p class="tag2">${c.dims.map((d,j)=>JC_DIM[d][s.a[j]][0]).join(' · ')}${out?' · ✅ บริสุทธิ์':''}</p></div>`}).join('')}`,'job')}
function jAsk(i){const c=jInit().q[i];if(!c||c.show>=3)return;c.show=3;sfx('click');jCopUI(i)}
function jSpy(i){const c=jInit().q[i];if(!c||c.elim.length)return;c.elim.push(ch(c.sus.map((s,j)=>j).filter(j=>!c.sus[j].g)));sfx('click');jCopUI(i)}
function jAccuse(i,k){const J=jInit(),c=J.q[i];if(!c)return;const s=c.sus[k],serious=c.cr>=1&&c.cr<=3,b=jbPay(J,serious?900:500);
 modal(`<button class="xbtn" onclick="jCopUI(${i})">←</button><h3>⛓️ จับกุม ${esc(s.n)}?</h3><p>${esc(s.n)}ถูกคุมตัวมาที่ศาล ก่อนประกาศผล ญาติของเขาแอบยื่นถุงเงินให้คุณใต้โต๊ะ…</p>
 <div class="mgrid"><button class="opt" onclick="jArrest(${i},${k},0)">⚖️ ตัดสินตามหลักฐาน<small>ถ้าถูกตัว: ค่าปิดคดี ${ftMf(b)}${serious?' · คดีใหญ่ คนร้ายอาจสู้':''}</small></button><button class="opt" onclick="jArrest(${i},${k},1)">💰 รับสินบนปล่อยตัว<small>ได้ ${ftMf(b*2)} · กรรม −8 · 25% เรื่องแดง ลดขั้น</small></button></div>`,'job')}
function jArrest(i,k,bribe){const J=jInit(),c=J.q[i];if(!c)return;const s=c.sus[k],right=!!s.g,serious=c.cr>=1&&c.cr<=3,b=jbPay(J,serious?900:500),cul=c.sus.find(x=>x.g);let t;
 const busy=!!(choice._cur||(typeof DU!=='undefined'&&DU&&DU.me>0&&DU.en>0&&$('duStage')));J.q.splice(i,1);
 if(bribe){S.money+=b*2;J.st.earn+=b*2;S.karma-=8;t=`คุณรับเงิน ${ftMf(b*2)} แล้วปล่อย${esc(s.n)}ไป · กรรม −8`;if(Math.random()<.25){J.lv=Math.max(0,J.lv-1);J.xp=JOB_XP[J.lv];J.rep=Math.max(0,(J.rep==null?50:J.rep)-25);t+=' เรื่องรั่วถึงเจ้าเมือง! ถูกลดขั้น';try{ctRepAdd(-40)}catch(e){}}log('💰 '+t,'bad');return jResult(t,false)}
 const done=()=>{J.st.ok++;J.rep=Math.min(100,(J.rep==null?50:J.rep)+4);jXp(J,serious?2:1);S.money+=b;J.st.earn+=b;S.fame+=(serious?12:6)*(J.lv>=3?2:1);S.karma+=2;try{ctRepAdd(8,'ปิดคดี')}catch(e){}t=`ปิดคดีสำเร็จ — <b>${esc(s.n)}</b>คือคนร้ายจริง · ค่าปิดคดี ${ftMf(b)}`;log('⚖️ '+t,'epic');jResult(t,true)};
 if(!right){J.st.bad++;J.rep=Math.max(0,(J.rep==null?50:J.rep)-8);S.karma-=5;t=`ชี้ผิดคน! ${esc(s.n)}บริสุทธิ์แต่ต้องติดคุก · คนร้ายตัวจริงคือ <b>${esc(cul.n)}</b> (${c.dims.map((d,j)=>JC_DIM[d][cul.a[j]][0]).join(' · ')}) ที่หนีไปแล้ว · กรรม −5`;log('⚖️ '+t,'bad');return jResult(t,false)}
 if(serious&&!busy&&Math.random()<.5){closeM();log(`⚖️ ${esc(s.n)}คือคนร้ายจริง แต่เขาชักอาวุธขัดขืนการจับกุม!`,'');duel(s.n,Math.round(total()*(.75+J.lv*.12)*(.9+Math.random()*.2)),w=>{if(w)done();else{J.st.bad++;S.hp-=Math.round(S.maxHp*.2);log(`⚖️ ${esc(s.n)}หนีไปได้หลังทำร้ายคุณ`,'bad');render()}});return}
 done()}
function jResult(t,ok){render();modal(`<h3>${ok?'✅ สำเร็จ':'❌ ผิดพลาด'}</h3><p>${t}</p><button class="pbtn" style="width:100%" onclick="openJob()">กลับหน้าอาชีพ</button>`,'job')}
