{const _cpJ=ctPage;ctPage=function(p,B){const h=_cpJ.apply(this,arguments);try{if(p==='folk'&&S){const J=jInit();return h.replace('<div class="mgrid">',`<div class="mgrid">${ctBtn('openJob()','📜 อาชีพ',J?`${jRk(J)}${J.q.length?' · มีงานรอ '+J.q.length:''}`:'หมอ · มือปราบ สมัครที่นี่',!!(J&&J.q.length))}`)}}catch(e){}return h}}
{const _omJ=openMenu;openMenu=function(){const r=_omJ.apply(this,arguments);try{if(S&&S.alive&&!(S.beastMode&&!S.beastMode.human)&&!(typeof mwOn==='function'&&mwOn())){const g=$('modal').querySelector('.mgrid');if(g&&!g.querySelector('.jobB')){const J=jInit();g.insertAdjacentHTML('afterbegin',`<button class="opt jobB" onclick="openJob()"${J&&J.q.length?' style="background:var(--tb4)"':''}>📜 อาชีพ<small>${J?jRk(J)+(J.q.length?' · มีงานรอ '+J.q.length:''):'ยังไม่มีงาน'}</small></button>`)}}}catch(e){}return r}}
