{const _ihJ=inherit;inherit=function(ci){const P=S,j=P&&P.job&&JOB[P.job.t]?{t:P.job.t,lv:P.job.lv,kn:Object.assign({},P.job.kn||{})}:null;const r=_ihJ.apply(this,arguments);try{if(j&&S!==P&&!S.job){const lv=Math.max(0,j.lv-1);S.job={t:j.t,lv,xp:JOB_XP[lv],rep:50,q:[],kn:j.kn,st:{ok:0,bad:0,earn:0}};setTimeout(()=>{try{log(`${JOB[j.t].ic} สืบทอดอาชีพตระกูลเป็น<b>${jRk(S.job)}</b>`,'epic')}catch(e){}},800)}}catch(e){}return r}}
