// ===================== v17.8b อาชีพชุดสอง: พ่อค้า · เจ้าโรงฝึก · บัณฑิต =====================
const jStars=n=>`<span style="color:#e8a020">${'★'.repeat(n)}</span><span style="opacity:.35">${'★'.repeat(Math.max(0,5-n))}</span>`;
// ---------- 🐫 พ่อค้า ----------
const GDS=[{n:'ผ้าไหม',ic:'🧵',b:100},{n:'ใบชา',ic:'🍵',b:60},{n:'เกลือ',ic:'🧂',b:40},{n:'สมุนไพร',ic:'🌿',b:80},{n:'เครื่องเคลือบ',ic:'🏺',b:150},{n:'หยกดิบ',ic:'💠',b:300}];
const MER_U=[10,30,80,200];
function jMerTowns(){const w=ECO_W(),L=w==='g'?TOWN_G.map(x=>'นครเทพ'+x):w==='x'?TOWN_X.map(x=>'เมืองเซียน'+x):TOWN_A.map(x=>'เมือง'+x),tn=townName();return L.filter(x=>x!==tn&&!tn.includes(x.replace(/^(เมือง|นครเทพ|เมืองเซียน)/,'')))}
function jMkMer(J){J.q=J.q.filter(c=>c.k!=='mer');const T=jMerTowns().sort(()=>Math.random()-.5),g=[...GDS.keys()].sort(()=>Math.random()-.5).slice(0,3);
 return{k:'mer',y:S.age,gs:g.map(i=>{const buy=Math.round(GDS[i].b*(.85+Math.random()*.3));return{i,buy,ds:T.slice(0,2).map(n=>({n,real:Math.round(buy*(.85+Math.random()*.85)),dg:Math.round(5+Math.random()*35)}))}}),sg:0,sd:0,su:0,gd:1,intel:0}}
function jMerDg(J,d,gd){return Math.round(d.dg*(1-J.lv*.15)*(gd===1?.3:1))}
function jMerUI(i){const J=jInit(),c=J.q[i],W=W15(),G=c.gs[c.sg],D=G.ds[c.sd],gi=GDS[G.i],maxU=J.lv,u=MER_U[Math.min(c.su,maxU)],cost=Math.round(u*G.buy*W),gc=c.gd===1?Math.round(cost*.12):0,lo=Math.round(D.real*(c.intel?1:.8)),hi=Math.round(D.real*(c.intel?1:1.2)),dg=jMerDg(J,D,c.gd);
 const pr=v=>Math.round((u*(v-G.buy)*W)-gc);
 modal(`<button class="xbtn" onclick="openJob()">←</button><h3>🐫 เดินทางค้าขาย</h3><p class="tag2">ซื้อสินค้าที่${esc(townName())} แล้วขนไปขายเมืองอื่น · เลือก 4 อย่างด้านล่างแล้วกดออกเดินทาง · ปีละ 1 เที่ยว</p>
 <b>1) สินค้า</b> <span class="tag2">(ราคาซื้อต่อหน่วย)</span><div class="tabs" style="flex-wrap:wrap">${c.gs.map((g,k)=>`<button class="tabb ${k===c.sg?'on':''}" onclick="jMerSet(${i},'sg',${k})">${GDS[g.i].ic} ${GDS[g.i].n} ${ftMf(Math.round(g.buy*W))}</button>`).join('')}</div>
 <b>2) ปลายทาง</b> <span class="tag2">(ราคาขายที่ได้ยินมา · อันตรายบนเส้นทาง)</span><div class="tabs" style="flex-wrap:wrap">${G.ds.map((d,k)=>`<button class="tabb ${k===c.sd?'on':''}" onclick="jMerSet(${i},'sd',${k})">${esc(d.n)} · ${c.intel?ftMf(Math.round(d.real*W)):ftMf(Math.round(d.real*.8*W))+' ถึง '+ftMf(Math.round(d.real*1.2*W))} · ⚠️${jMerDg(J,d,c.gd)}%</button>`).join('')}</div>
 <b>3) ขนาดกองสินค้า</b><div class="tabs" style="flex-wrap:wrap">${MER_U.map((n,k)=>`<button class="tabb ${k===c.su?'on':''}" onclick="jMerSet(${i},'su',${k})" ${k>maxU?'disabled style="opacity:.4"':''}>${n} หน่วย${k>maxU?' 🔒 ขั้น '+(k+1):''}</button>`).join('')}</div>
 <b>4) การคุ้มกัน</b><div class="tabs" style="flex-wrap:wrap">${[['ไม่จ้าง','เสี่ยงเต็ม · ถ้าโดนปล้นเสียของ 70%'],['จ้างสำนักคุ้มภัย','จ่าย 12% · อันตรายเหลือ 30%'],['คุมเอง','ถ้าเจอโจรต้องสู้ · ชนะไม่เสียอะไร']].map(([n,d],k)=>`<button class="tabb ${k===c.gd?'on':''}" onclick="jMerSet(${i},'gd',${k})">${n}</button>`).join('')}</div><p class="tag2" style="margin:2px 0 6px">${[['เสี่ยงเต็ม · ถ้าโดนปล้นเสียของ 70%'],['จ่ายค่าคุ้มกัน 12% · อันตรายเหลือ 30%'],['ถ้าเจอโจรต้องดวลเอง · ชนะไม่เสียอะไร แพ้เสียของ 50%']][c.gd]}</p>
 <div class="item" style="border-left:4px solid #e8c86a"><b>สรุป: ${gi.ic} ${gi.n} ${u} หน่วย → ${esc(D.n)}</b><p class="tag2">ทุน ${ftMf(cost)}${gc?' + ค่าคุ้มกัน '+ftMf(gc):''} · กำไรคาดไว้ ${pr(lo)>=0?'+':''}${fmtM(pr(lo))} ถึง ${pr(hi)>=0?'+':''}${fmtM(pr(hi))} · โอกาสเจอโจร ${dg}%${c.intel?' · ✅ รู้ราคาจริงแล้ว':''}</p></div>
 <div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:6px"><button class="gbtn" style="flex:1;${c.intel?'opacity:.45':''}" onclick="jMerIntel(${i})" ${c.intel?'disabled':''}>🕵️ ซื้อข่าววงใน ${ftMf(Math.round(150*W*(1+J.lv)))}<small style="display:block">รู้ราคาขายจริงทุกเมือง</small></button><button class="pbtn" style="flex:1" onclick="jMerGo(${i})" ${S.money>=cost+gc?'':'disabled style="opacity:.45;flex:1"'}>🐫 ออกเดินทาง</button></div>
 <button class="opt" style="width:100%;margin-top:6px" onclick="jSkip(${i})">ปีนี้ไม่ค้าขาย<small>เก็บทุนไว้ก่อน</small></button>`,'job')}
function jMerSet(i,k,v){const c=jInit().q[i];if(!c)return;c[k]=v;if(k==='sg')c.sd=0;jMerUI(i)}
function jMerIntel(i){const J=jInit(),c=J.q[i],p=Math.round(150*W15()*(1+J.lv));if(!c||c.intel)return;if(S.money<p)return toast('เงินไม่พอ');S.money-=p;c.intel=1;sfx('click');jMerUI(i)}
function jSkip(i){const J=jInit();J.q.splice(i,1);render();openJob()}
function jMerGo(i){const J=jInit(),c=J.q[i];if(!c)return;const W=W15(),G=c.gs[c.sg],D=G.ds[c.sd],gi=GDS[G.i],u=MER_U[Math.min(c.su,J.lv)],cost=Math.round(u*G.buy*W),gc=c.gd===1?Math.round(cost*.12):0;if(S.money<cost+gc)return toast('ทุนไม่พอ');
 if(c.gd===2&&choice._cur)return toast('ตัดสินใจเรื่องที่ค้างอยู่ก่อน');J.q.splice(i,1);S.money-=cost+gc;
 const sell=Math.round(D.real*(.9+Math.random()*.2)),hit=Math.random()*100<jMerDg(J,D,c.gd);
 const fin=(lost,note)=>{const left=u*(1-lost),rev=Math.round(left*sell*W),profit=rev-cost-gc;S.money+=rev;J.st.earn+=Math.max(0,profit);let t=`ขาย${gi.n} ${Math.round(left)} หน่วยที่${esc(D.n)} ได้ ${ftMf(rev)} · ${profit>=0?'กำไร':'ขาดทุน'} ${ftMf(Math.abs(profit))}${note?' · '+note:''}`;
  if(profit>0){J.st.ok++;J.rep=Math.min(100,(J.rep==null?50:J.rep)+3);jXp(J,profit>(cost+gc)*.4?2:1);try{ctRepAdd(4,'การค้า')}catch(e){}}else{J.st.bad++}log('🐫 '+t,profit>0?'good':'bad');jResult(t,profit>0)};
 if(!hit)return fin(0,sell>D.real?'ราคาปลายทางดีกว่าที่คาด':'');
 if(c.gd===0)return fin(.7,'💢 โจรปล้นกลางทาง เสียสินค้า 70%');
 if(c.gd===1)return Math.random()<.8?fin(0,'🛡️ โจรดักปล้น แต่สำนักคุ้มภัยไล่ไปได้'):fin(.4,'🛡️ โจรมากเกินไป คุ้มภัยรักษาไว้ได้แค่ส่วนหนึ่ง (เสีย 40%)');
 closeM();log(`🏴 โจรดักปล้นกองสินค้าคุณกลางทางไป${esc(D.n)}!`,'');duel('หัวหน้าโจรดักทาง',Math.round(total()*(.6+D.dg/100)*(.9+Math.random()*.2)),w=>{if(w){S.fame+=8;fin(0,'⚔️ คุณไล่โจรไปเอง (ชื่อเสียง +8)')}else fin(.5,'⚔️ สู้โจรไม่ไหว เสียสินค้า 50%')})}
// ---------- 🥋 เจ้าโรงฝึก ----------
const DJ_TR={hard:['💪 ขยัน',1.3,0],lazy:['😴 ขี้เกียจ',.6,0],stub:['😤 หัวรั้น',1,-4],geni:['🌟 อัจฉริยะ',1.6,0],sly:['🦊 เจ้าเล่ห์',1,0],kind:['😊 ใจดี',1,3]};
const DJ_CAP=[3,5,8,12],DJ_STY={h:['🔥 เข้มงวด','ฝีมือขึ้นเร็ว · ความสุขศิษย์ลด',9,-8],m:['⚖️ สมดุล','ปกติ',6,-1],e:['🌸 ผ่อนคลาย','ศิษย์มีความสุข · ฝีมือขึ้นช้า',4,5]};
function djInit(J){J.stu=J.stu||[];J.sty=J.sty||'m';J.grad=J.grad|0;J.grudge=J.grudge||[];return J}
function djName(){return anyName(ch(['ชาย','หญิง']))}
function jMkDojo(J){djInit(J);if(J.grudge.length&&Math.random()<.25)return{k:'djr',y:S.age,n:J.grudge.shift()};
 if(J.stu.length<DJ_CAP[J.lv]&&Math.random()<.6){const tal=pickW([1,2,3,4,5].map(v=>({v,w:[30,30,22,12,6][v-1]}))).v.v,tr=ch(Object.keys(DJ_TR));return{k:'dja',y:S.age,n:djName(),tal,tr,test:0,fee:Math.round((40+tal*25)*W15())}}
 if(!J.stu.length)return null;return{k:'dje',y:S.age,e:ch(['duel','fight','steal']),a:R(0,J.stu.length-1),b:R(0,J.stu.length-1)}}
function djTick(J,st){djInit(J);const y=Math.min(st,5),[,,g,md]=DJ_STY[J.sty];let inc=0;
 for(let t=0;t<y;t++){J.stu.forEach(s=>{const T=DJ_TR[s.tr];s.sk=Math.min(100,s.sk+g*s.tal*.5*T[1]*(.7+Math.random()*.6));s.mood=clamp(s.mood+md+T[2]+(J.sty==='h'&&s.tr==='stub'?-4:0),0,100);inc+=(30+s.tal*20)*(J.lv>=2?1.5:1)});
  J.stu=J.stu.filter(s=>{if(s.mood<15){log(`🥋 ศิษย์<b>${esc(s.n)}</b>ทนไม่ไหว เก็บของออกจากโรงฝึกไป`,'bad');if(Math.random()<.3)J.grudge.push(s.n);J.rep=Math.max(0,(J.rep==null?50:J.rep)-5);return false}
   if(s.sk>=100){J.grad++;S.fame+=10*s.tal;jXp(J,s.tal>=4?3:s.tal>=2?2:1);J.rep=Math.min(100,(J.rep==null?50:J.rep)+5);try{ctRepAdd(10,'ศิษย์จบการฝึก')}catch(e){}log(`🎓 ศิษย์<b>${esc(s.n)}</b> ${jStars(s.tal)} สำเร็จการฝึก ออกไปสร้างชื่อให้โรงฝึกคุณ (ชื่อเสียง +${10*s.tal})`,'epic');return false}return true})}
 if(J.lv>=3&&J.grad)inc+=J.grad*25;const m=Math.round(inc*W15());if(m){S.money+=m;J.st.earn+=m}}
function djExtra(J){djInit(J);return`<h4 style="margin:10px 0 4px">🥋 ศิษย์ในโรงฝึก (${J.stu.length}/${DJ_CAP[J.lv]}) · จบไปแล้ว ${J.grad} คน</h4>
 ${J.stu.length?J.stu.map(s=>`<div class="item"><b>${esc(s.n)}</b> <span class="tag2">${jStars(s.tal)} · ${DJ_TR[s.tr][0]}</span><div class="hpbar" style="height:6px;margin:4px 0"><i style="width:${s.sk}%;background:#e8c86a"></i></div><p class="tag2" style="margin:0">ฝีมือ ${Math.round(s.sk)}/100 (ถึง 100 = จบการฝึก) · ความสุข <span style="color:${s.mood<30?'#ff6b6b':'inherit'}">${Math.round(s.mood)}</span>${s.mood<30?' ⚠️ ใกล้ลาออก':''}</p></div>`).join(''):'<p class="tag2">ยังไม่มีศิษย์ รอคนมาสมัคร</p>'}
 <b>วิธีสอน</b> <span class="tag2">(มีผลทุกปี)</span><div class="tabs" style="flex-wrap:wrap">${Object.entries(DJ_STY).map(([k,v])=>`<button class="tabb ${J.sty===k?'on':''}" onclick="jDjSty('${k}')">${v[0]}</button>`).join('')}</div><p class="tag2">${DJ_STY[J.sty][1]} · ค่าเรียนต่อปีราว ${ftMf(Math.round(J.stu.reduce((a,s)=>a+(30+s.tal*20),0)*(J.lv>=2?1.5:1)*W15()))}</p>`}
