function schP(J,lvl,bonus){return clamp(.15+Math.min(.45,S.int/(160*lvl))+(J.sp||0)*.035-lvl*.06+(bonus||0),.05,.92)}
function jMkSch(J){if(J.ban&&S.age<J.ban)return{k:'scs',y:S.age};if(J.lv<3&&S.age%3===0){const q=[...QB.keys()].sort(()=>Math.random()-.5).slice(0,3);return{k:'sce',y:S.age,lvl:J.lv+1,q,ans:[],cheat:0,ord:q.map(()=>[0,1,2].sort(()=>Math.random()-.5))}}return{k:'scs',y:S.age}}
