 if(n%10===0||n===100)d=[{k:'boss'}];else{const W=(h.frc>0)?[['fight',70],['elite',30]]:[['fight',45],['elite',15],['altar',12],['event',15],['well',13]],pick=()=>{let t=r()*100;for(const [k,w] of W){if((t-=w)<=0)return k}return'fight'};d=[];for(let i=0;i<20&&d.length<3;i++){const k=pick();if(!d.some(x=>x.k===k))d.push({k})}if(!d.some(x=>x.k==='fight'||x.k==='elite'))d[0]={k:'fight'}}
