function hlFuseUI(){const h=hl2();if(!h)return;const C=h.cur||[],cnt={};C.forEach(k=>cnt[k]=(cnt[k]||0)+1);const sets=Object.keys(cnt).filter(k=>cnt[k]>=3);
 modal(`<button class="xbtn" onclick="${h.lv>=18?'openHell2()':'hellShop()'}">←</button><h3>⚗️ หลอมคำสาป</h3><p class="tag2">แก่นนรก ${h.ess} · คำสาปที่ติดตัว ${C.length}</p>
 <div class="item"><b>🔥 หลอม 2 เป็น 1</b><p class="tag2">ลบคำสาป 2 ข้อล่าสุด แลกกับคำสาปสุ่มใหม่ 1 ข้อ + พรด้านมืด (พลังยุทธ์ +8% หรือ ไฟกรรม −20) · ใช้ 3 แก่น</p><button class="sysb" onclick="hlFuse()" ${C.length>=2&&h.ess>=3?'':'disabled style="opacity:.45"'}>หลอม</button></div>
 <div class="item"><b>☯️ พลิกชุดคำสาป</b><p class="tag2">มีคำสาปเดียวกันครบ 3 ข้อ → ลบทั้งชุด แลกพลังยุทธ์ +25% และแก่นนรก +5 (ไม่ต้องจ่าย) · ตั้งใจเลือกคำสาปซ้ำเพื่อพลิกได้</p>${sets.length?sets.map(k=>`<button class="sysb" onclick="hlFlipSet('${k}')">${_HL.CUR[k][0]} ×3</button>`).join(' '):'<span class="tag2">ยังไม่มีชุดครบ 3</span>'}</div>
 <p class="tag2">คำสาปตอนนี้: ${C.map(k=>_HL.CUR[k][0]).join(' · ')||'ไม่มี'}</p>`,'hell2')}
function hlFuse(){const h=hl2();if(!h||(h.cur||[]).length<2||h.ess<3)return;h.ess-=3;const a=h.cur[h.cur.length-1],b=h.cur[h.cur.length-2];hlRmCurse(h,a);hlRmCurse(h,b);const ks=Object.keys(_HL.CUR).filter(k=>_HL.ncur(k)<3&&k!==a&&k!==b);if(ks.length)_HL.addCurse(ch(ks));
 if(Math.random()<.5){const g=pctPow(.08);S.power+=g;log(`⚗️ หลอมคำสาปสำเร็จ พรด้านมืด: พลังยุทธ์ +${fmt(g)}`,'epic')}else{h.heat=Math.max(0,(h.heat||0)-20);log('⚗️ หลอมคำสาปสำเร็จ พรด้านมืด: ไฟกรรม −20','epic')}render();hlFuseUI()}
function hlFlipSet(k){const h=hl2();if(!h||_HL.ncur(k)<3)return;for(let i=0;i<3;i++)hlRmCurse(h,k);const g=pctPow(.25);S.power+=g;h.ess+=5;log(`☯️ ชุดคำสาป ${_HL.CUR[k][0]} พลิกกลายเป็นพลัง พลังยุทธ์ +${fmt(g)} · แก่นนรก +5`,'myth',true);render();hlFuseUI()}
