function rdReunion(D){if(D.done)return;const can=!S.spouse&&!(typeof loveOpt==='function'&&loveOpt()==='off');
 rdAsk('🧵 ด้ายแดงสองชาติ',`${esc(D.n2)}หยุดเดิน มือที่ถืออยู่สั่นเทา "${D.place}… ${D.gift}… ข้าจำได้แล้ว" น้ำตาไหลลงมา "ข้าเคยเป็นของเจ้า ในชาติที่แล้ว"<br><span class="tag2">${D.src} · ${D.n2} วิญญาณดวงเดียวกัน</span>`,[
  ...(can?[{t:'💍 แต่งงานกันอีกครั้ง',s:'ด้ายแดงต่อไปอีกชาติ · ความสุขเต็ม',f(){D.done='wed';D.end='กลับมาคู่กันอีกครั้ง';marry(D.n2,'แต่งงานอีกครั้งข้ามชาติกับ');try{syncFamily();if(S.sp){S.sp.aff=100;S.sp.wy=S.age-10}}catch(e){}S.rd={bind:1,n:D.n2};joy(50);try{keyAdd(`ได้แต่งงานกับ${D.src}อีกครั้งในชาติใหม่`)}catch(e){};rdWin()}}]:[]),
  {t:'🤝 อยู่เคียงข้างแบบเพื่อนวิญญาณ',s:can?'ไม่แต่งงาน แต่ผูกพันกันตลอดไป':'คุณมีคู่ หรือตั้งใจครองโสดอยู่แล้ว',f(){D.done='soul';D.end='กลับมาพบกันในฐานะเพื่อนวิญญาณ';joy(30);S.karma+=5;log(`🤝 คุณกับ${esc(D.n2)}สัญญาว่าจะอยู่เคียงข้างกันแบบนี้ตลอดไป`,'myth',true);rdClose(D)}}])}
function rdWin(){const R0=rdLS()||{};const w=(R0.win||0)+1;log(`🧵 <b>ด้ายแดงสองชาติ</b> วิญญาณสองดวงหาเจอกันอีกครั้ง${w>=2?` (ครั้งที่ ${w+1})`:''}`,'myth',true);if(w>=2){S.flags.rd3=1;log('🏅 ได้ฉายา <b>ด้ายแดงสามชาติ</b>','myth',true)}}
try{TTL_SP.unshift(['rd3',()=>!!(S.flags&&S.flags.rd3),'ด้ายแดงสามชาติ'])}catch(e){}
