async function openGraves(){modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>🪦 สุสานจอมยุทธ์</h3><p class="tag2">ป้ายหลุมศพของผู้เล่นจริงที่จบชีวิตไปแล้ว พร้อมคำอำลาสุดท้าย · ไหว้ได้ปีละ 3 ป้าย จะได้กรรมดี ความสุข และบางครั้งได้แรงบันดาลใจจากยอดฝีมือ</p><div id="gvList" class="tag2">${onlineOK?'กำลังโหลด…':'ต้องออนไลน์ก่อน'}</div><button class="gbtn" style="width:100%;margin-top:6px" onclick="gvLoad(1).then(openGraves)">🔄 ดูป้ายอื่น</button>`,'graves');
 const L=await gvLoad();const el=$('gvList');if(!el)return;el.className='';el.innerHTML=(L&&L.length)?L.map(gvCard).join(''):'<p class="tag2">ยังไม่มีป้ายหลุมศพ</p>'}
async function gvPray(k,btn){const g=GV_C&&GV_C[k];if(!g||!S||!S.alive)return;if(S.gpY!==S.age){S.gpY=S.age;S.gpN=0}if(S.gpN>=3)return toast('ปีนี้ไหว้ครบแล้ว');S.gpN++;if(btn)btn.disabled=true;
 S.karma+=1;joy(2);let ex='';if((g.ri||0)>=6&&Math.random()<.35){const v=pctPow(.01);ex=` · ได้แรงบันดาลใจจากยอดฝีมือ พลัง +${fmt(v||0)}`}
 log(`🙏 คุณจุดธูปหน้าป้ายของ <b>${esc(g.n)}</b>${g.y?` — “${esc(g.y)}”`:''}${ex}`,'good');try{const j=await api('gpray',{g:g.i});g.p=j.n;if(btn)btn.textContent='🙏 ไหว้แล้ว '+(j.n||'')}catch(e){}render()}
{const _egG=endGame;endGame=function(){try{const by=(($('byeIn')||{}).value||'').trim();if(onlineOK&&S&&!S.mw&&!S.cu&&S.age>=10&&!endGame._busy){const best=(S.arts||[]).slice().sort((a,b)=>b.b-a.b)[0];api('grave',{n:S.name,e:(typeof epithet==='function'?epithet():''),a:S.age,r:REALMS[realmIdx()].n,c:S.cause||S.deathCause||'',y:by,w:wpW(),ar:best?best.n:'',ri:realmIdx(),hl:S.ch==='hell'&&S.hell?S.hell.lv|0:0}).catch(()=>{})}}catch(e){}return _egG.apply(this,arguments)}}
