function hvOk(){return !!(S&&S.alive&&S.xt&&!S.beastMode)}
function openHeaven(){if(!hvOk())return toast('ต้องอยู่ในโลกเทพก่อน');const H=S.hv;
 if(!H)return modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>🏛️ ดูแลแคว้นเบื้องล่าง</h3><p>เทวสภาสวรรค์มอบหมายให้คุณเลือกแคว้นหนึ่งในยุทธภพเบื้องล่างไปดูแล ผู้คนที่ศรัทธาจะกลายเป็น<b>ผู้ศรัทธาในแดนเทพ</b>ของคุณ ดูแลดีได้ผลงานเลื่อนตำแหน่งในเทวสภา แต่ถ้าแคว้นล่มสลาย คุณจะถูกปลด</p>${HV_REG.map((n,i)=>`<button class="opt" style="width:100%;margin:3px 0" onclick="hvPick(${i})">🗺️ ${n}</button>`).join('')}`,'heaven');
 const R=hvRank(),G=gdInit(),a=H.ay===S.age?H.ac||{}:{};const b=(k,ic,t,s)=>`<button class="opt" style="width:100%;text-align:left;margin:3px 0" ${a[k]?'disabled':''} onclick="hvAct('${k}')">${ic} ${t}<small>${a[k]?'ทำไปแล้วปีนี้':s}</small></button>`;
 modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>🏛️ ${esc(R.n)}</h3><p class="tag2">ตำแหน่งในเทวสภา: <b>${GD_RK[G.rk]}</b> · ผู้ศรัทธาในแดนเทพ ${fmt(G.bel)} · ดูแลมาแล้ว ${H.yr||0} ปี</p>
 <p style="margin:6px 0 0">🌾 ความรุ่งเรือง ${Math.round(H.pr)}</p>${wpBar(H.pr,100,'#5cb85c')}<p style="margin:6px 0 0">🙏 ความศรัทธา ${Math.round(H.fa)}</p>${wpBar(H.fa,100,'#e0a030')}<p style="margin:6px 0 0">🔥 ความวุ่นวาย ${Math.round(H.un)}</p>${wpBar(H.un,100,'#e04050')}
 <p class="tag2">ศรัทธา×รุ่งเรืองสูง = ได้ผู้ศรัทธาเข้าแดนเทพทุกปี · ดูแลดีครบทุก 10 ปีได้ผลงานเทวสภา · รุ่งเรืองต่ำทำให้วุ่นวายขึ้น · วุ่นวายถึง 80 จะเกิดกบฏ · ศรัทธาต่ำกว่า 10 นาน 3 ปี จะถูกปลด</p>
 ${b('bless','🌧️','ประทานพร',`ส่งฝนและความอุดมสมบูรณ์ · พลังชีวิต −10% · รุ่งเรือง +10 ศรัทธา +3`)}${b('smite','⚡','ลงทัณฑ์ผู้ก่อการร้าย',`วุ่นวาย −18 · ศรัทธา +4 (กลัว) · รุ่งเรือง −3 · กรรม −2`)}${b('dream','👁️','ส่งนิมิตถึงนักพรต',`ศรัทธา +7`)}
 <button class="gbtn" style="width:100%;margin-top:8px" onclick="if(confirm('วางมือจากแคว้นนี้? ค่าต่างๆ ของแคว้นจะหายหมด'))hvQuit()">วางมือจากแคว้นนี้</button>`,'heaven')}
function hvPick(i){if(!hvOk())return;S.hv={reg:i,pr:50,fa:30,un:25,yr:0,good:0,low:0,ay:-1,ac:{}};log(`🏛️ เทวสภามอบหมายให้คุณดูแล<b>${HV_REG[i]}</b> ผู้คนเบื้องล่างเริ่มตั้งศาลบูชา`,'myth',true);openHeaven()}
function hvQuit(){S.hv=null;log('🏛️ คุณวางตำแหน่งสวรรค์ลง กลับไปบำเพ็ญเพียรเงียบๆ','epic');closeM()}
function hvAct(k){const H=S.hv;if(!H||!hvOk())return;if(H.ay!==S.age){H.ay=S.age;H.ac={}}if(H.ac[k])return;H.ac[k]=1;const cl=v=>clamp(v,0,100);
 if(k==='bless'){S.hp=Math.max(1,S.hp-Math.round(S.maxHp*.1));H.pr=cl(H.pr+10);H.fa=cl(H.fa+3);log(`🌧️ ฝนทิพย์โปรยลงทั่ว${HV_REG[H.reg]} ข้าวออกรวงเต็มทุ่ง`,'good')}
 if(k==='smite'){H.un=cl(H.un-18);H.fa=cl(H.fa+4);H.pr=cl(H.pr-3);S.karma-=2;log(`⚡ สายฟ้าฟาดลงกลางรังโจรใน${HV_REG[H.reg]} ผู้คนกราบกรานด้วยความหวาดกลัว`,'epic')}
 if(k==='dream'){H.fa=cl(H.fa+7);log(`👁️ นักพรตใน${HV_REG[H.reg]}ฝันเห็นคุณ แล้วป่าวประกาศไปทั่ว`,'good')}
 render();openHeaven()}
function hvTick(){const H=S.hv;if(!H||!hvOk())return;const cl=v=>clamp(v,0,100);H.yr=(H.yr||0)+1;
 H.pr=cl(H.pr+(H.fa-50)/25+R(-3,3)-(H.un>60?3:0));H.un=cl(H.un+(50-H.pr)/18+R(-2,3));H.fa=cl(H.fa-1-H.un/60+(H.pr>70?1:0));
 try{gdBel(Math.round(H.fa*H.pr*25));if(H.fa>=40)pctPow(.002*H.fa/50);H.good=H.fa>=50&&H.pr>=50?(H.good||0)+1:0;if(H.good>=10){H.good=0;gdMerit(4,`${HV_REG[H.reg]}รุ่งเรืองสงบสุขมาสิบปี`)}}catch(e){}
 if(H.un>=80){H.pr=cl(H.pr-15);H.fa=cl(H.fa-10);H.un=cl(H.un-25);log(`🔥 กบฏลุกฮือทั่ว${HV_REG[H.reg]} ศาลบูชาถูกเผา`,'bad',true)}
 H.low=H.fa<10?(H.low||0)+1:0;if(H.low>=3){S.fame=Math.max(0,S.fame-150);try{gdMerit(-8)}catch(e){};log(`🏛️ เทวสภาสวรรค์ปลดคุณจากตำแหน่ง ไม่มีใครใน${HV_REG[H.reg]}บูชาคุณอีกแล้ว`,'bad',true);S.hv=null;return}
 if(Math.random()<.3&&!choice._cur&&!modalOpen)hvPetition()}
