function bkTxt(b){return b[1].replace('{r3}',REALMS[3].n).replace('{r5}',REALMS[5].n).replace('{m}',wpMf(20000*W15()))}
function bkInit(){if(S.bk)return S.bk;const d=new Date(Date.now()+7*3600e3).toISOString().slice(0,10);const R0=pxRng(hshStr('bk'+d));const P=BK.slice().sort(()=>R0()-.5);const out=[];for(const b of P){if(out.length>=5)break;if((b[0]==='saint'&&out.includes('devil'))||(b[0]==='devil'&&out.includes('saint')))continue;out.push(b[0])}return S.bk={d,g:out,done:{}}}
