const LNK_RX=/(https?:\/\/[^\s<>"']+|www\.[^\s<>"']+|\b[a-z0-9][a-z0-9-]*(?:\.[a-z0-9-]+)*\.(?:com|net|org|io|gg|me|th|co|ly|app|dev|link|xyz|tv|info|site|shop)(?:\/[^\s<>"']*)?)/gi;
function lnkify(root){if(!root)return;const W=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>{const p=n.parentNode;if(!p||/^(A|TEXTAREA|INPUT|SCRIPT|STYLE|BUTTON)$/.test(p.nodeName)||p.closest('a,textarea,button'))return NodeFilter.FILTER_REJECT;LNK_RX.lastIndex=0;return LNK_RX.test(n.nodeValue)?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT}});const L=[];while(W.nextNode())L.push(W.currentNode);
 L.forEach(n=>{const s=n.nodeValue,f=document.createDocumentFragment();let last=0;LNK_RX.lastIndex=0;let m;while((m=LNK_RX.exec(s))){let u=m[0].replace(/[).,!?:;]+$/,'');if(!u)continue;f.appendChild(document.createTextNode(s.slice(last,m.index)));const href=/^https?:\/\//i.test(u)?u:'https://'+u;let ok=false;try{const U=new URL(href);ok=U.protocol==='https:'||U.protocol==='http:'}catch(e){}
  if(ok){const a=document.createElement('a');a.href=href;a.target='_blank';a.rel='noopener noreferrer nofollow';a.textContent=u;a.className='admLnk';a.addEventListener('click',ev=>ev.stopPropagation());f.appendChild(a)}else f.appendChild(document.createTextNode(u));last=m.index+u.length;LNK_RX.lastIndex=last}f.appendChild(document.createTextNode(s.slice(last)));n.parentNode.replaceChild(f,n)})}
(()=>{const st=document.createElement('style');st.textContent='a.admLnk{color:#4aa8ff;text-decoration:underline;word-break:break-all;font-weight:bold}a.admLnk::after{content:" ↗";font-size:.8em}';document.head.appendChild(st)})();
