// ============ กันเซฟหายบน Safari ============
// Safari ลบ localStorage ทิ้งเมื่อใช้ Safari ครบ 7 วันโดยไม่ได้เข้าเว็บนี้ · พื้นที่เก็บของ Safari ก็เล็กกว่าเบราว์เซอร์อื่น
// (1) กู้อัตโนมัติ: เซิร์ฟเวอร์ฝาก cookie (HttpOnly) ไว้ตอนเซฟคลาวด์ → เครื่องว่างเปล่าเมื่อไหร่ ถาม ?a=cme แล้วคืนตัวตนเดิมให้ แล้วเปิดหน้ากู้เซฟ
(function(){
 const hasLocal=()=>{try{return SLOTS.some(n=>!!readSave(n))||arcList().length>0}catch(e){return true}};
 const ask=()=>{try{if(!LS.get('murim_cmeAsk',0))return;LS.del('murim_cmeAsk');if(S||hasLocal())return;openCloudRestore();toast('☁️ พบเซฟเก่าของเครื่องนี้บนเซิร์ฟเวอร์ เลือกชีวิตที่จะกู้คืนได้เลย')}catch(e){}};
 const check=async()=>{try{if(!_freshDev)return;let j=null;try{const r=await fetch(API+'?a=cme',{cache:'no-store',credentials:'same-origin'});if(!r.ok)return;j=await r.json()}catch(e){return}
  if(!j||!j.p||!j.tk||!Array.isArray(j.l)||!j.l.length)return;if(j.p===pid)return;if(S||hasLocal())return;
  LS.set('murim_pid',j.p);LS.set('murim_ctok',j.tk);LS.set('murim_cmeAsk',1);location.reload()}catch(e){}};
 const go=()=>{setTimeout(ask,1200);setTimeout(check,800)};
 if(document.readyState==='complete')go();else window.addEventListener('load',go);
})();
// (2) ขอให้เบราว์เซอร์เก็บข้อมูลแบบถาวร (Safari 17+/Chrome ไม่มีหน้าต่างถาม · ข้าม Firefox เดสก์ท็อปที่จะเด้งถาม)
(function(){if(!(navigator.storage&&navigator.storage.persist)||/Firefox\//.test(navigator.userAgent||''))return;
 const once=()=>{removeEventListener('pointerdown',once,true);try{navigator.storage.persisted().then(p=>p||navigator.storage.persist()).catch(()=>{})}catch(e){}};
 addEventListener('pointerdown',once,true)})();
// (3) ย่อภาพอัลบั้ม PNG เก่าในเซฟ (จากรุ่นก่อนที่ Safari บันทึกเป็น PNG) → JPEG ถ้าเล็กกว่า
function albumShrink(){try{const a=S&&S.album;if(!Array.isArray(a))return;a.forEach(it=>{if(!it||typeof it.u!=='string'||it.u.indexOf('data:image/png')!==0||it.u.length<6000)return;
 const im=new Image();im.onload=()=>{try{const c=document.createElement('canvas');c.width=im.width;c.height=im.height;const x=c.getContext('2d');if(!x)return;x.fillStyle='#000';x.fillRect(0,0,c.width,c.height);x.drawImage(im,0,0);const j=c.toDataURL('image/jpeg',.72);if(j&&j.indexOf('image/jpeg')>=0&&j.length<it.u.length*.8)it.u=j}catch(e){}};im.src=it.u})}catch(e){}}
{const _lgA=loadGame;loadGame=function(){const r=_lgA.apply(this,arguments);try{setTimeout(albumShrink,500)}catch(e){}return r}}
// (4) เซฟไม่สำเร็จ → แถบเตือนค้างไว้จนกว่าจะเซฟได้ (เดิมเตือนครั้งเดียว ผู้เล่นไม่รู้ว่าเกมไม่ได้บันทึก)
function saveFailBar(on){let e=document.getElementById('saveFailBar');if(!on){if(e)e.remove();return}if(e)return;e=document.createElement('div');e.id='saveFailBar';
 e.style.cssText='position:fixed;left:0;right:0;top:0;z-index:2147482000;background:#7a1f1f;color:#fff;font:14px/1.45 system-ui,sans-serif;padding:8px 12px;text-align:center;box-shadow:0 2px 10px rgba(0,0,0,.5)';
 e.innerHTML='⚠️ <b>เกมยังไม่ได้บันทึก</b> พื้นที่เก็บข้อมูลในเบราว์เซอร์เต็ม ลบช่องเซฟเก่า หรือย้ายเซฟไปเก็บที่ 🗂️ คลังสำรอง แล้วเกมจะบันทึกต่อเอง';document.body.appendChild(e)}
{const _sgF=saveGame;saveGame=function(){const r=_sgF.apply(this,arguments);try{saveFailBar(!!saveGame._warn)}catch(e){}return r}}
{const _ttF=toTitle;toTitle=function(){try{saveFailBar(false)}catch(e){}return _ttF.apply(this,arguments)}}

// ============ v17.9.2 ป้ายบอกเงื่อนไข: ถึงขั้นสูงสุดแล้วแต่ยังขึ้นโลกถัดไปไม่ได้ ============
// เดิมต้องเปิด ☰ เมนู → ⚡ ฝ่าทัณฑ์สวรรค์ ถึงจะรู้ว่าติดอะไร ผู้เล่นหลายคนเลยไม่รู้ว่าต้องเล่นต่อ → แสดงสรุปเงื่อนไขที่ยังขาดไว้บนหน้าเล่นเลย แตะดูรายละเอียดได้
function ascHintUpd(){try{let b=$('ascHint');const row=document.querySelector('#game .onrow');
 if(!b&&row){row.insertAdjacentHTML('beforebegin','<button id="ascHint" onclick="ascForce()" style="display:none"></button>');b=$('ascHint')}if(!b)return;
 let show=false,t='';
 if(S&&S.alive&&ascCan()&&!ascEligible()){const q=ascReq(),g=q.g||{};
  if(g.ok===false||q.w>0){const need=S.xian?9:(((typeof MN_X!=='undefined'&&MN_X.p)||0)+1),parts=[];
   if(g.pOK===false)parts.push('ชั้นเหนือขั้นสูงสุด ★'+(g.pl<0?0:(g.pl%9)+1)+'/'+need);
   if(g.tOK===false)parts.push('อีก '+fmt(g.left||0)+' ปี');
   if(q.w>0)parts.push('รออีก '+fmt(q.w)+' ปี');
   if(parts.length){show=true;t='🔒 ขึ้น'+(S.xian?'โลกเทพ':'โลกเซียน')+'ยังไม่ได้ — '+parts.join(' · ')+'  (แตะดูเงื่อนไข)'}}}
 b.style.display=show?'':'none';if(show&&b.textContent!==t)b.textContent=t}catch(e){}}
setInterval(ascHintUpd,1500);{const _rdH=render;render=function(){const r=_rdH.apply(this,arguments);ascHintUpd();return r}}
(function(){const st=document.createElement('style');st.textContent='#ascHint{display:block;width:100%;margin:0 0 5px;padding:4px 10px;border:1px dashed #b89cff;border-radius:12px;background:#3a2470;color:#fff;font:inherit;font-size:.8em;line-height:1.35;text-align:center;cursor:pointer}#ascHint:active{transform:translateY(1px)}';document.head.appendChild(st)})();

// ============ แก้บั๊กถ้ำบ่มเพาะหาย ============
// ถ้ำเช่าในเมือง (v17.8) เคยใช้ตัวแปร S.cave ร่วมกับถ้ำบ่มเพาะส่วนตัว → ทุกปีโค้ดถ้ำเช่าเห็นว่า "ไม่ใช่ของโลกนี้" แล้วลบทิ้ง
// ตอนนี้ถ้ำเช่าย้ายไป S.rcave แล้ว · เซฟเก่า: ย้ายถ้ำเช่าที่ค้างอยู่ใน S.cave ออก แล้วคืนถ้ำบ่มเพาะให้คนที่เคยได้ (เคยอัปจนสุด = คืนระดับสูงสุด)
function caveFix(){try{if(!S||!S.alive||S._caveFix)return;S._caveFix=1;
 const c=S.cave;if(c&&c.u!=null){if(!S.rcave&&c.u>S.age&&c.w===ECO_W())S.rcave=c;S.cave=null}
 if(!S.cave&&S.xian){const had=(S.flags&&S.flags.caveGot)||(S.key||[]).some(k=>String(k).indexOf('ได้ถ้ำบ่มเพาะส่วนตัว')>=0);
  if(had){S.cave={lv:S.flags&&S.flags.cave4?4:0};log(`🏔️ <b>ถ้ำบ่มเพาะคุณกลับมาแล้ว</b>${S.cave.lv?' (ระดับสูงสุด)':''} ขออภัย ก่อนหน้านี้ถ้ำหายเพราะบั๊ก`,'epic')}}}catch(e){}}
{const _lgCF=loadGame;loadGame=function(){const r=_lgCF.apply(this,arguments);try{caveFix()}catch(e){}return r}}
{const _pyCF=passYear;passYear=function(){try{caveFix()}catch(e){}return _pyCF.apply(this,arguments)}}

// ============ เมนู ☰ หาของง่ายขึ้น ============
// 1) ปุ่มที่ระบบใหม่ๆ เติมเข้ามาทีหลังเคยไปกองรวมในหมวด "⭐ ใช้บ่อย" (26 ปุ่ม) → จัดเข้าหมวดที่ถูกต้อง
// 2) หมวดที่ถูกพับไว้ (แตะหัวข้อโดยไม่ตั้งใจตอนเลื่อนจอ แล้วจำค่าไว้ตลอด) ทำให้ปุ่มหายจนต้องพิมพ์ค้นหา → กางทุกหมวดให้ใหม่ 1 ครั้ง และหัวข้อที่พับอยู่บอกชัดว่าซ่อนกี่รายการ
const MENU_MORE={'⭐ ใช้บ่อย':['ascForce','openCal','openTerr','openB2Evo','openPack','openWBoss','openHib','openNest'],
 '🧘 ตัวละครและการฝึก':['openJob','openWuxia','openTalent','openRealm','openMoveBook','openInvest','glwSet','openTtlMine','openRoadmap','openAdvice'],
 '👪 ครอบครัวและผู้คน':['openLove','openKeep'],
 '📚 บันทึกและสะสม':['openArcBook','openLore','openMyCard','openGraves']};
{const _omR=openMenu;openMenu=function(){const r=_omR.apply(this,arguments);try{const m=$('modal'),H=[...m.querySelectorAll('.mcat15>.mch15')];if(H.length<2)return r;
 const grid={};H.forEach(h=>{const g=h.nextElementSibling;if(g&&g.classList.contains('mgrid'))grid[h.textContent.trim()]=g});
 const first=grid[MENU_CAT[0][0]];if(!first)return r;const fnOf=b=>((b.getAttribute('onclick')||'').match(/^\s*([A-Za-z0-9_]+)\(/)||[])[1]||'';
 const keep=new Set([...MENU_CAT[0][1],...MENU_MORE[MENU_CAT[0][0]]]);const home=f=>{for(const [cn,fs] of MENU_CAT.slice(1))if(fs.includes(f)&&grid[cn])return grid[cn];for(const cn in MENU_MORE)if(cn!==MENU_CAT[0][0]&&MENU_MORE[cn].includes(f)&&grid[cn])return grid[cn];return grid['🧘 ตัวละครและการฝึก']||null};
 [...first.children].forEach(b=>{const f=fnOf(b);if(keep.has(f))return;const g=home(f);if(g&&g!==first)g.appendChild(b)})}catch(e){console.error(e)}return r}}
try{if((LS.get('murim_mncolV',0)|0)<3){LS.del('murim_mncol');LS.set('murim_mncolV',3)}}catch(e){}
