{const _paL=playAs;playAs=function(kind){const P=S,heir=kind==='disc'&&P&&P.lead&&P.lead.heir&&P.flags&&P.flags.disciple===P.lead.heir?P.lead:null,wasF=P&&P.faction&&P.rank>=4,os=P&&P.ownSect&&!P.faction?P.ownSect:null;
 const r=_paL.apply(this,arguments);try{if(heir&&S&&S!==P){if(wasF){S.faction=P.faction;S.rank=4;S.merit=MERIT[4]||S.merit}else if(os){S.ownSect={n:os.n,dis:Math.round(os.dis*.8),lv:os.lv};S.path='founder'}
  const b={};for(const k in heir.b)b[k]=Math.max(0,heir.b[k]-1);S.lead=Object.assign({},heir,{tr:Math.round(heir.tr*.5),b,loy:60,wy:-99,ws:0,ly:S.age,evY:S.age,heir:null,cand:[],coup:0});
  log(`👑 คุณขึ้นรับตำแหน่งเจ้า<b>${esc(heir.n)}</b>ต่อจากอาจารย์ คลังสำนัก ${fmtM(S.lead.tr)} ตำลึง`,'myth',true);keyAdd('สืบทอดตำแหน่งเจ้า'+heir.n);render()}}catch(e){console.error(e)}return r}}
