// ---- การ์ดในฟองคำพูด: แสดงทันที ไม่พิมพ์ทีละตัว ----
{const _ctL=coType;coType=function(el,html){const L=LESSON[CO.id],s=L&&L.s[CO.i];if(s&&s.card){clearInterval(CO.tw);el.innerHTML=s.card+(html?`<div style="margin-top:6px">${html}</div>`:'');const b=el.closest('.cbub'),bx=el.closest('.cbox');if(b)b.classList.add('cbCard');if(bx&&!s.sel){bx.style.bottom='';bx.style.top=Math.max(8,Math.round(innerHeight*.06))+'px'}return}const b=el.closest&&el.closest('.cbub');if(b)b.classList.remove('cbCard');return _ctL.apply(this,arguments)}}
// ---- ตัวกระตุ้น ----
const MODE_K=()=>!S?null:S.beastMode&&!S.beastMode.human?'beast':S.rg?'regress':(S.ch&&S.ch!=='normal'?S.ch:'normal');
function mtGet(){return LS.get('murim_mtried',{})||{}}
function lsnTry(id,delay){if(coSeen(id)||!coCan()||modalOpen||choice._cur||CO.id)return false;setTimeout(()=>{if(!coSeen(id)&&coCan()&&!modalOpen&&!choice._cur&&!CO.id)coStart(id)},delay||300);return true}
{const _pyL=passYear;passYear=function(){const r=_pyL.apply(this,arguments);try{if(S&&S.alive){const k=MODE_K(),T=mtGet();if(k&&!T[k]){T[k]=1;LS.set('murim_mtried',T)}
 if(k&&k!=='normal'&&lsnTry('m_'+k,500))return r;if(S.sys&&lsnTry('sys',600))return r;if(S.sarc&&lsnTry('arc',700))return r}}catch(e){}return r}}
{const _crL=choiceRun;choiceRun=function(){const r=_crL.apply(this,arguments);try{if(S&&S.alive&&S.sarc&&!coSeen('arc'))setTimeout(()=>lsnTry('arc',0),900)}catch(e){}return r}}
{const _opL=openPAuc;openPAuc=function(){const r=_opL.apply(this,arguments);try{if(!coSeen('pauc'))setTimeout(()=>{if(!CO.id)coStart('pauc')},700)}catch(e){}return r}}
{const _osL=openSectBiz;openSectBiz=function(){const r=_osL.apply(this,arguments);try{if(!coSeen('sect'))setTimeout(()=>{if(!CO.id)coStart('sect')},500)}catch(e){}return r}}
{const _oscL=openSysCult;openSysCult=function(){const r=_oscL.apply(this,arguments);try{if(!coSeen('scult'))setTimeout(()=>{if(!CO.id)coStart('scult')},500)}catch(e){}return r}}
// ---- หน้าบทเรียนแบบแบ่งหมวด + อ่านได้ทันที ----
const LSN_G=[['🌱','พื้นฐาน',[['start','🧭','หน้าจอและปุ่มหลัก'],['choice','🔀','ตัวเลือก ℹ️ ข้อมูล · 🔒 ล็อก · ▾ ย่อ'],['town','🏘️','4 ย่าน · ชื่อเสียงในเมือง'],['job0','💼','อาชีพ ทำทีละ 1 อย่าง'],['job1','📨','งานของอาชีพ'],['family','👪','ใช้เวลากับคู่และลูก'],['bag','🎒','ยา วัตถุดิบ การขาย'],['cloud','🔐','เชื่อม Google กันเซฟหาย']]],
 ['🌏','โลก',[['xian','☁️','หินวิญญาณ · อาคารใหม่ในเมือง'],['god','🌟','หยกดาราเทพ · ศรัทธา · สภาเทพ']]],
 ['🎯','โหมดท้าทาย',[['m_hell','🔥','นรก 100 ชั้น · ผู้คุม · คำสาป · ประตู'],['m_short','⏳','สิ่งที่ต้องทำก่อนตาย · พินัยกรรม'],['m_junk','🗑️','บัญชีแค้น · ของที่คนทิ้ง'],['m_regress','🔁','ตายแล้วย้อนไปอายุ 15'],['m_beast','🐾','ลูกสัตว์ → อสูร → ราชา']]],
 ['⚙️','ระบบ',[['sys','🟦','เควส · แต้ม · อันดับ F→EX'],['arc','📖','ภาคเรื่องราวและตอนจบ'],['pauc','🏛️','ประมูลกับผู้เล่นจริง'],['sect','🏯','คลัง · อาคาร · ผู้สืบทอด'],['scult','🧘','บำเพ็ญเพื่อเรียกระบบ']]]];
function openLessons(){const T=mtGet(),seen=LSN_G.reduce((a,g)=>a+g[2].filter(x=>coSeen(x[0])).length,0),tot=LSN_G.reduce((a,g)=>a+g[2].length,0);
 modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>🎓 บทเรียน</h3><div class="lsnTop"><b>${seen}/${tot}</b> บท<div class="hpbar"><i style="width:${Math.round(seen/tot*100)}%;background:#e8b830"></i></div></div><p class="tag2">ครูผู้เฒ่าจะมาสอนเองเมื่อเจอครั้งแรก · บทที่ยังไม่เจอ กด <b>อ่าน</b> ได้เลย</p>
 ${LSN_G.map(([gi,gn,L])=>`<h4 class="lsnH">${gi} ${gn}</h4><div class="lsnG">${L.filter(x=>LESSON[x[0]]).map(([id,ic,sub])=>{const sn=coSeen(id),md=id.startsWith('m_')?id.slice(2):null;return`<div class="lsnI${sn?' ok':''}"><div class="li1">${ic}</div><div class="li2"><b>${sn?'✅ ':''}${LESSON[id].t}</b>${!sn?' <span class="lsnNew">ใหม่</span>':''}${md&&!T[md]?' <span class="lsnNew" style="background:#7a5ad8">ยังไม่เคยเล่น</span>':''}<small>${sub}</small></div><button class="sysb" onclick="openLessonRead('${id}')">อ่าน</button></div>`}).join('')}</div>`).join('')}
 <button class="gbtn" style="width:100%;margin-top:10px" onclick="closeM();coFull()">🧭 ทัวร์ปุ่มทั้งหมด (ฉบับเต็ม)</button>`,'lessons')}
function openLessonRead(id){const L=LESSON[id];if(!L)return;const md=id.startsWith('m_')?id.slice(2):null;
 modal(`<button class="xbtn" onclick="openLessons()">←</button><h3>🎓 ${L.t}</h3>${L.s.map(s=>`${s.card||`<div class="item"><b>${s.t}</b></div>`}${s.d?`<div class="tag2" style="margin:2px 2px 10px">${s.d}</div>`:''}`).join('')}
 <div class="brow">${md&&MODE_I[md]?`<button class="pbtn" onclick="mtGo('${md}')">▶ ลองโหมดนี้ชีวิตหน้า</button>`:''}<button class="gbtn" onclick="coReplay('${id}')">👴 ให้ครูสอน</button></div>`,'lessonread');try{coMark(id)}catch(e){}}
// ---- แนะนำโหมดที่ยังไม่เคยลอง ----
const MODE_I={hell:{ic:'🔥',n:'นรก',c:'#c8323a',chm:1,p:'ลงนรก 100 ชั้น สู้ผู้คุม รับคำสาป เลือกประตูเอง และขึ้นทำเนียบนรก'},short:{ic:'⏳',n:'ชีวิตสั้น',c:'#d88a20',chm:2,p:'ชีวิตสั้นนิดเดียว ทำ 5 อย่างก่อนตาย แล้วส่งพินัยกรรมให้ตัวถัดไป'},junk:{ic:'🗑️',n:'รากขยะ',c:'#7a8a5a',chm:3,p:'เกิดมาพรสวรรค์ต่ำสุด จดชื่อคนที่ดูถูก แล้วกลับไปตบหน้าเขา'},regress:{ic:'🔁',n:'ผู้ย้อนกาล',c:'#5a7ae0',chm:4,p:'ตายแล้วย้อนไปอายุ 15 ใช้ความรู้จากรอบก่อนช่วยเพื่อนร่วมชะตา'},beast:{ic:'🐾',n:'เกิดเป็นสัตว์',c:'#3a9a5a',beast:1,p:'เกิดเป็นลูกสัตว์ในป่า บำเพ็ญจนเป็นอสูร แล้วเลือกแปลงกายหรือครองป่า'}};
function mtPick(){const T=mtGet(),no=LS.get('murim_mtno',{})||{},ok=k=>!T[k]&&!no[k];const pref=[];try{const old=/แก่|อายุขัย/.test(S.cause||'')||S.age>=(lifeMax()-2);if(realmIdx()>=6||S.xian)pref.push('hell');if(old)pref.push('short');if((S.talent&&S.talent.m<1)||(S.kills||0)<5)pref.push('junk');if((S.arcDone||[]).length)pref.push('regress');if(S.beast)pref.push('beast')}catch(e){}
 const k=pref.find(ok)||Object.keys(MODE_I).find(ok);if(!k)return null;const why={hell:'คุณแกร่งเกินกว่ายุทธภพจะท้าทายได้แล้ว',short:'ชีวิตนี้ยาวจนแก่ตาย ลองดูว่าถ้าเหลือเวลาน้อยนิดจะทำอะไร',junk:'อยากรู้ไหมว่าถ้าเริ่มจากศูนย์จริงๆ จะไปได้ไกลแค่ไหน',regress:'ชอบเนื้อเรื่อง? โหมดนี้มีเรื่องราวที่วนซ้ำให้ไขปริศนา',beast:'คุณเลี้ยงสัตว์คู่ใจมาแล้ว ลองเป็นฝ่ายสัตว์ดูบ้าง'}[k]||'';return{k,why}}
function mtGo(k){const M=MODE_I[k];if(!M)return;closeM();if(S&&S.alive){if(M.beast)return toast('🐾 ชีวิตหน้าเลือก "เกิดเป็นสัตว์" ตอนกดเกิดได้เลย');CFG.chm=M.chm;document.querySelectorAll('.seg[data-k="chm"] button').forEach(b=>b.classList.toggle('on',+b.dataset.v===M.chm));return toast(`${M.ic} ตั้งโหมด${M.n}ไว้แล้ว จะใช้ตอนเริ่มชีวิตใหม่`)}try{toTitle()}catch(e){}
 if(M.beast)return setTimeout(()=>{try{goBeastLife()}catch(e){}},300);CFG.chm=M.chm;document.querySelectorAll('.seg[data-k="chm"] button').forEach(b=>b.classList.toggle('on',+b.dataset.v===M.chm));try{updateHints()}catch(e){}toast(`${M.ic} ตั้งโหมด${M.n}แล้ว เปลี่ยนกลับได้ที่ตัวเลือกการเกิด`);setTimeout(()=>{try{goBirth()}catch(e){}},300)}
function mtNo(k,all){if(all)LS.set('murim_mtoff',1);else{const n=LS.get('murim_mtno',{})||{};n[k]=1;LS.set('murim_mtno',n)}const c=document.getElementById('mtCard');if(c)c.remove()}
{const _egL=endGame;endGame=function(){const busy=endGame._busy;const r=_egL.apply(this,arguments);try{if(busy||!S||S._mtC)return r;S._mtC=1;const n=(+LS.get('murim_lifeN',0)||0)+1;LS.set('murim_lifeN',n);if(n<3||LS.get('murim_mtoff',0)||S.custom)return r;
 const p=mtPick();if(!p)return r;const M=MODE_I[p.k],end=$('end'),brs=end.querySelectorAll(':scope>.brow'),anchor=brs[brs.length-1];
 const h=`<div id="mtCard" class="lc" style="--c:${M.c};margin-top:14px"><div class="lh"><i>${M.ic}</i><div><b>ชีวิตหน้า ลองโหมด${M.n}ไหม?</b><small>${p.why}</small></div></div><ul><li><span>✨</span><span>${M.p}</span></li></ul><div class="brow" style="padding:0 10px 10px"><button class="pbtn" onclick="mtGo('${p.k}')">▶ ลองชีวิตหน้า</button><button class="gbtn" onclick="openLessonRead('m_${p.k}')">📖 อ่านก่อน</button></div><div style="text-align:center;padding:0 0 8px;font-size:11px"><a href="#" onclick="mtNo('${p.k}');return false" style="color:inherit;opacity:.6">ไม่สนใจโหมดนี้</a> · <a href="#" onclick="mtNo('',1);return false" style="color:inherit;opacity:.6">ไม่ต้องแนะนำอีก</a></div></div>`;
 if(anchor)anchor.insertAdjacentHTML('beforebegin',h);else end.insertAdjacentHTML('beforeend',h)}catch(e){console.error(e)}return r}}
