// ===================== v17.10 🌟 หนึ่งเดียวในนวนิยาย =====================
// สุ่มตอนเริ่มชีวิตแบบสุ่ม (ไม่ใช่สร้างเอง · ชะตาประจำวัน · สัตว์) โอกาส 0.0001% = 1 ใน 1,000,000 ชีวิต · สุ่มตอนกดเริ่ม จึงกดสุ่มใหม่เพื่อตามหาไม่ได้
// ได้: พรสวรรค์สูงสุด + ของเทพ 1 ชิ้นจาก 4 แบบ · พลังเสริมเยอะตอนต้น แล้วลดลงตามขั้น (กันพังทำเนียบ) · ประกาศแชทโลก · ป้าย 🌟 ในทำเนียบ
const ONE_P=1e-6;
const ONE_SET=[
 {id:'sword',ic:'🗡️',n:'กระบี่ลิขิตฟ้า',d:'พลังยุทธ์เติบโตเพิ่มทุกปี แรงมากตอนเริ่ม แล้วค่อยๆ ลดลงเมื่อขั้นสูงขึ้น'},
 {id:'pearl',ic:'📿',n:'ลูกปัดอายุวัฒนะ',d:'อายุขัย +30% ทันที · ลมปราณเพิ่มทุกปี'},
 {id:'book',ic:'📕',n:'คัมภีร์ไร้นาม',d:'ได้วิชาระดับสูงตั้งแต่เกิด และเรียนรู้วิชาใหม่เองทุก ~12 ปี'},
 {id:'seal',ic:'👑',n:'ตราผู้ถูกเลือก',d:'ชื่อเสียง เสน่ห์ และโชคชะตาเกื้อหนุน · พรสวรรค์ ×1.1'}];
function oneDecay(){const ri=realmIdx();let d=ri<=3?1:ri<=5?.6:.35;if(S.xian)d*=.6;if(S.xt)d*=.6;return d}
function oneApply(force){const it=force?ONE_SET.find(x=>x.id===force)||ONE_SET[0]:ch(ONE_SET);S.flags.one=1;S.one={id:it.id,y:S.age};
 const best=TALENT.slice().sort((a,b)=>b.m-a.m)[0];S.talent=Object.assign({},best);try{if(S.xian)S.root=rootOf(S.talent)}catch(e){}
 if(it.id==='pearl')lsAdd(Math.round(lifeMax()*.3));if(it.id==='book'){try{S.arts.push(newArt(3))}catch(e){}}if(it.id==='seal'){S.talent.m=+(S.talent.m*1.1).toFixed(2);S.fame+=300;S.cha=(S.cha||0)+20;S.karma+=10}
 S.items.push({id:'one_'+it.id,n:it.n,d:it.d,passive:1,one:1});keyAdd(`ถือกำเนิดเป็นหนึ่งเดียวในนวนิยาย พร้อม${it.n}`);
 log(`🌟 <b>ฟ้าดินสั่นสะเทือน คุณคือ「หนึ่งเดียวในนวนิยาย」</b> โอกาส 1 ใน 1,000,000 ชีวิต · เกิดมาพร้อม <b>${it.ic} ${it.n}</b> — ${it.d}`,'myth',true);
 try{pxPlay({mode:'arrive',type:'peak',w:S.xt?'g':S.xian?'x':'m',seed:77,fx:'ember',title:'🌟 หนึ่งเดียวในนวนิยาย',sub:`${esc(S.name)} · ${it.ic} ${it.n}`,sub0:'โอกาส 1 ใน 1,000,000 ชีวิต'})}catch(e){}
 try{if(!force&&typeof onlineOK!=='undefined'&&onlineOK)api('oneborn',{n:pname(),it:it.n,w:S.xt?'g':S.xian?'x':'m'}).then(j=>{if(j&&j.ok&&j.cnt)log(`📢 ฟ้าประกาศชื่อคุณไปทั่วแผ่นดิน คุณคือคนที่ <b>${fmt(j.cnt)}</b> ของเซิร์ฟเวอร์`,'epic')}).catch(()=>{})}catch(e){}}
window.oneForce=k=>{if(typeof ADM!=='undefined'&&ADM.ok&&S&&S.alive&&!S.flags.one)oneApply(k||1)};
{const _slO=startLife;startLife=function(){const r0=roll;const out=_slO.apply(this,arguments);try{if(S&&r0&&!r0.custom&&!r0.daily&&!(r0.f&&r0.f.v&&r0.f.v.beast)&&!S.mw)oneRoll()}catch(e){}return out}}
async function oneRoll(){try{if(typeof onlineOK==='undefined'||!onlineOK)return;const L=S;const j=await api('oneroll',{});if(j&&j.win)setTimeout(()=>{try{if(S===L&&S&&S.alive&&!S.flags.one)oneApply()}catch(e){console.error(e)}},1200)}catch(e){}}
{const _pyO=passYear;passYear=function(){const a0=S?S.age:0;const r=_pyO.apply(this,arguments);try{if(S&&S.alive&&S.one){const dy=Math.min(10,Math.max(1,S.age-a0)),d=oneDecay(),k=S.one.id;
 if(k==='sword')S.power+=pctPow(.012*d*dy);if(k==='pearl')S.qi=+(S.qi+.4*d*dy).toFixed(2);if(k==='book'&&S.age-(S.one.ly||S.one.y)>=12){S.one.ly=S.age;try{const a=newArt(2);S.arts.push(a);log(`📕 คัมภีร์ไร้นามเปิดหน้าใหม่ด้วยตัวเอง ${artHtml(a)}`,'epic')}catch(e){}}if(k==='seal'&&Math.random()<.1*dy)S.fame+=Math.round(40*d*dy)}}catch(e){}return r}}
