function bodyB(){return !!(S&&S.beastMode&&!S.beastMode.human)}
function bodyTab(beast){return beast?BODY_CB:BODY_C}
function bodyGen(beast,kind){
 const LK=beast?BODY_LKB:BODY_LK,C=bodyTab(beast);let a=Math.random(),lk=2;for(let i=0;i<LK.length;i++){if(a<LK[i].p){lk=i;break}a-=LK[i].p}
 const pool=Object.keys(C).filter(k=>{const c=C[k];return c.p>0&&(!c.only||c.only===kind)&&!(c.notFor&&c.notFor.includes(kind))});
 const tot=pool.reduce((s,k)=>s+C[k].p,0);let b=Math.random(),cs=[],cp=1-tot;for(const k of pool){if(b<C[k].p){cs=[k];cp=C[k].p;break}b-=C[k].p}
 return{lk,lkP:LK[lk].p,cs,cP:cp,bt:beast?1:0,cured:[],acq:0}}
function bodyLk(b){return(b&&b.bt?BODY_LKB:BODY_LK)[b?b.lk:2]}
function bodyCs(b){const C=bodyTab(b&&b.bt);return(b&&b.cs||[]).map(k=>Object.assign({id:k},C[k])).filter(c=>c.n)}
function bodyHas(k){return !!(S&&S.body&&(S.body.cs||[]).includes(k))}
function bodyRows(b,T,beast){const L=bodyLk(b),cs=bodyCs(b);
 T.push([beast?'🐾 รูปลักษณ์':'🪞 รูปลักษณ์',L.ic+' '+L.n,L.d,b.lkP]);
 if(cs.length)cs.forEach(c=>T.push([c.good?'💎 ร่างกาย':'🩹 ร่างกาย',c.ic+' '+c.n,c.d,b.cP]));
 else T.push(['🩺 ร่างกาย','ครบสามสิบสองประการ','ร่างกายปกติ ไม่มีอะไรขาดไม่มีอะไรเกิน',b.cP])}
// ---------- ความหายาก ----------
const RARE_CUT=.1,RARE_TOP=[1,.7,.45,.25,.12,.05,.02,.007,.0025,.0008,.0002,.00005,.00001];
const RARE_DIST={};
function rareN(ps){let n=1;ps.forEach(p=>{if(p>0&&p<RARE_CUT)n/=p});return n}
function rareHumanPs(){const era=pickW(ERAS),r=genRoll(Math.min(.6,era.v.ow*(CFG.xian?2.5:1))),tw=TRAITS.reduce((a,x)=>a+x.w,0),b=bodyGen(false);
 const ps=[era.p,r.g.p,r.f.p,r.t.p,r.op,b.lkP,b.cP];const L=r.trs.list.map(trOf).filter(Boolean);if(!L.length)ps.push(.45);else L.forEach(t=>ps.push(t.w/tw*.55));
 if(r.w){ps.push(r.w.p,r.it.p)}if(r.os)ps.push(r.os.p);return ps}
function rareBeastPs(){const r=_brGenRaw(),k=(BL_SP[r.sp]||[])[1],b=bodyGen(true,k);return[r.spP,r.elP,r.blP,r.tP,r.gP,r.parP||1,b.lkP,b.cP]}
function rareDist(key){if(RARE_DIST[key])return RARE_DIST[key];const A=[],beast=key[0]==='b';
 for(let i=0;i<3000;i++){try{A.push(Math.log10(rareN(beast?rareBeastPs():rareHumanPs())))}catch(e){A.push(0)}}
 A.sort((a,b)=>a-b);return RARE_DIST[key]=A}
function rareFrac(N,key){const A=rareDist(key),x=Math.log10(N),n=A.length;
 // สัดส่วนชีวิตที่หายาก "เท่ากับหรือมากกว่า" ชีวิตนี้
 let lo=0,hi=n;while(lo<hi){const m=(lo+hi)>>1;if(A[m]<x-1e-9)lo=m+1;else hi=m}const ge=(n-lo)/n;
 const q=A[Math.floor(n*.99)];if(ge<.01&&x>q)return Math.min(.01,.01*Math.pow(10,q-x));return Math.max(ge,1/n/4)}
function rareTier(fr){let f=0;RARE_TOP.forEach((t,i)=>{if(fr<=t)f=i});return f}
function rareCalc(T,key){const R0=T.filter(c=>c[3]>0&&c[3]<RARE_CUT),N=rareN(T.map(c=>c[3])),fr=rareFrac(N,key),f=rareTier(fr);
 const top=R0.slice().sort((a,b)=>a[3]-b[3])[0];return{N,fr,f,k:R0.length,top:top?[String(top[0]).replace(/^[^\wก-๙]+\s*/,''),String(top[1]).replace(/<[^>]+>/g,''),1/top[3]]:null}}
function rareFrTxt(fr){return fr>=.01?(fr*100).toFixed(fr>=.1?0:1)+'%':'1 ใน '+fmt(Math.round(1/fr))+' ชีวิต'}
function rareSub(r){if(!r)return'';if(!r.k)return'ไม่มีอะไรหายากเลย ชีวิตธรรมดาแบบคนส่วนใหญ่';
 return`อยู่กลุ่มบนสุด <b>${rareFrTxt(r.fr)}</b> ของทุกชีวิต · นับเฉพาะ ${r.k} อย่างที่หายาก${r.top?`<br>ชิ้นที่หายากที่สุด: <b>${esc(r.top[1])}</b> (1 ใน ${fmt(Math.round(r.top[2]))})`:''}`}
function oddsShowR(r){const n=$('oddsN');if(!n)return;const R0=r&&r.rare;
 if(!R0){n.textContent='1 ใน '+fmt(1/(r.p*r.era.p));return}
 n.textContent=R0.k?'1 ใน '+fmt(Math.round(R0.N)):'ธรรมดา';
 let d=$('oddsR');if(!d){n.insertAdjacentHTML('afterend','<div class="od" id="oddsR" style="margin-top:2px"></div>');d=$('oddsR')}d.innerHTML=rareSub(R0)}
