const _brGenRaw=brGen;
brGen=function(){const r=_brGenRaw.apply(this,arguments);try{const k=(BL_SP[r.sp]||[])[1];r.body=bodyGen(true,k);const T=[];
 const s=BL_SP[r.sp],b=BBLOOD[r.bl];T.push(['เผ่าพันธุ์',s[0],'',r.spP],['ธาตุ',BEL[r.el][0],'',r.elP],['สายเลือด',b.n,'',r.blP],['รากปราณ',BTAL_N[r.t]||TALENT[r.t].n,'',r.tP],['เพศ','','',r.gP],['ครอบครัว','','',r.parP||1]);
 bodyRows(r.body,T,true);r.rare=rareCalc(T,'b'+(CFG.xian?1:0))}catch(e){console.error(e)}return r};
function bodyBRows(r,row){if(!r.body)return[];const T=[];bodyRows(r.body,T,true);return T.map(c=>row(c[0],c[1],c[2],c[3]))}
{const _bb2=beastBirth2;beastBirth2=function(r){window._bbR=r;try{return _bb2.apply(this,arguments)}finally{window._bbR=null;try{if(S&&r&&r.body&&!S.body){S.body=JSON.parse(JSON.stringify(r.body));bodyStart();if(r.rare){S.rareN=r.rare.N;S.rareF=r.rare.f;S.rareFr=r.rare.fr}render()}}catch(e){console.error(e)}}}}
// ---------- เริ่มชีวิต ----------
function bodyStart(){const b=S.body;if(!b||b._st)return;b._st=1;const L=bodyLk(b);S.cha=Math.max(0,(S.cha||0)+L.cha);
 if(bodyHas('hetero'))S.cha+=10;if(bodyHas('mute'))S.cha=Math.max(0,S.cha-10);if(bodyHas('whole')){S.hp+=30}
 if(bodyHas('albino'))S.cha+=5}
