const AC_HK=['lv','ess','rev','fail','heat','cs','frc'],AC_HSYM=Symbol('h');
function acTrapH(o){if(!o||typeof o!=='object'||o[AC_HSYM])return;try{Object.defineProperty(o,AC_HSYM,{value:1});
 AC_HK.forEach(k=>{const d=Object.getOwnPropertyDescriptor(o,k);if(d&&(!('value' in d)||!d.configurable))return;let v=d?d.value:undefined;
  Object.defineProperty(o,k,{enumerable:true,configurable:false,get(){return v},set:function __acS(n){try{if(n!==v&&!acCaller()){if(acConsole()){acFlag('console-hell-'+k);acSus('hlc-'+k)}else acSus('hsm-'+k)}}catch(e){}v=n}})})}catch(e){}}
setInterval(()=>{try{if(S&&S.alive&&!S.custom&&S.hell)acTrapH(S.hell)}catch(e){}},400);
