let AC_HL=null;setInterval(()=>{try{if(!S||!S.alive||S.custom||!S.hell)return;const lv=+S.hell.lv||0;if(AC_HL&&AC_HL.o===S){const d=lv-AC_HL.lv;if(d>1&&!(S.hell.cs&&lv===S.hell.cs&&AC_HL.lv===0)){acSus('jump-hell')}}AC_HL={o:S,lv}}catch(e){}},500);

