function heFire(w){if(!S||!S.alive||choice._cur||modalOpen)return false;const h=heH();
 let P=HE.filter(T=>(T.w===w||T.w==='b')&&(!T.ok||T.ok()));if(!P.length)return false;
 const fresh=P.filter(T=>!h.seen.includes(T.id));if(fresh.length)P=fresh;
 const T=ch(P);let v,key;
 for(let i=0;i<6;i++){v={};for(const k in T.v){const L=typeof T.v[k]==='function'?T.v[k]():T.v[k];v[k]=ch(L)}key=T.id+':'+Object.values(v).join('|');if(!h.vs.includes(key))break}
 h.seen.push(T.id);if(h.seen.length>10)h.seen.shift();h.vs.push(key);if(h.vs.length>400)h.vs.shift();
 const opts=T.o(v).filter(o=>!o.r||o.r===kRl()).map(o=>({_x:1,t:o.t,s:o.s||'',f(){let r='';try{r=o.f(v)||''}catch(e){console.error(e)}heH().ev++;if(r)log(`${T.ic} ${r}`,'epic');try{render()}catch(e){}}}));
 choice(`${T.ic} ${T.t(v)}`,T.d(v),opts);return true}
function heCount(){return HE.reduce((a,T)=>{let n=1;for(const k in T.v){const L=typeof T.v[k]==='function'?T.v[k]():T.v[k];n*=L.length}return a+n},0)}
