function heG(){try{if(S&&S.alive&&hiG()&&!hiK())heFire('g')}catch(e){console.error(e)}}
function heKf(){try{if(S&&S.alive&&hiK()&&!(S.kalpa&&S.kalpa.pend))heFire('k')}catch(e){console.error(e)}}
{const _pyHE=passYear;passYear=function(){
 try{if(S&&S.alive&&S.hePend&&!choice._cur&&!modalOpen){const w=S.hePend;S.hePend=0;if((w==='k'?hiK():hiG()&&!hiK())&&heFire(w)){try{render()}catch(e){}return}}}catch(e){console.error(e)}
 const r=_pyHE.apply(this,arguments);
 try{if(S&&S.alive&&!S.mw&&!(S.kalpa&&S.kalpa.pend)){const w=hiK()?(Pr(.2)?'k':0):(hiG()&&!(S.beastMode&&!S.beastMode.human)&&Pr(.15)?'g':0);if(w){if(choice._cur||modalOpen)S.hePend=w;else heFire(w)}}}catch(e){console.error(e)}return r}}
