const HQ_DROP=['join','rank','house','gear','money','cha','marry','kid','pill','arena','tqd','est','bank','gov','found'];
const HQN={power:()=>`บ่มเพาะร่างเทพจนพลัง +{g}`,qi:()=>`กลั่นปราณ${hiK()?'จักรวาล':'สวรรค์'} +{g} ปี`,fame:()=>`ให้นามคุณดังทั่ว${hiK()?'จักรวาลใหม่':'แดนเทพ'} +{g}`,win:()=>'ชนะศึกระดับเทพ {g} ครั้ง',
 art:()=>'หยั่งรู้วิชาใหม่ 1 วิชา',int:()=>'ทำความเข้าใจกฎฟ้าดิน ปัญญา +{g}',karma:()=>'สะสมบุญในภพสูง กรรมดี +{g}',karmaDown:()=>'ก่อกรรมมาร กรรมดิ่งลง {g}',joy:()=>'หาความสุขให้ใจที่อยู่มานาน +{g}'};
