Object.assign(QOK,{h_faith:()=>hiOut(),h_deed:()=>hiOut(),h_relic:()=>hiK(),h_civ:()=>hiK()&&kRl()==='make',h_save:()=>hiK()&&kRl()==='guard',h_eat:()=>hiK()&&kRl()==='demon'});
try{Object.assign(QAGE,{h_faith:0,h_deed:0,h_relic:0,h_civ:0,h_save:0,h_eat:0})}catch(e){}
try{Object.assign(SQWHY,{h_faith:'ศรัทธาจากเบื้องล่างคือรากของเทพ',h_deed:'ผู้อยู่เหนือโลกต้องเลือก ไม่ใช่แค่มอง',h_relic:'ซากของจักรวาลเก่าบอกได้ว่ากัลป์นี้จะจบอย่างไร',h_civ:'สิ่งที่ผู้สร้างทิ้งไว้คือตัวตนของผู้สร้าง',h_save:'ผู้พิทักษ์ที่ไม่ได้พิทักษ์ก็เป็นแค่ชื่อ',h_eat:'มารสิ้นกัลป์ต้องกินเพื่ออยู่'})}catch(e){}
{const _qkH=qKeys;qKeys=function(){let k=_qkH.apply(this,arguments);try{if(hiOut()&&!bsB()){const s=S.sys;k=k.filter(x=>!HQ_DROP.includes(x));['h_faith','h_deed','h_relic','h_civ','h_save','h_eat'].forEach(x=>{if(QOK[x]()&&!k.includes(x)&&!s.quests.some(q=>q.k===x))k.push(x)})}}catch(e){console.error(e)}return k}}
// ภารกิจเก่าที่ค้างจากโลกล่างและไม่มีความหมายแล้ว: ปลดออกโดยไม่ลงโทษ
function hqClean(){try{if(!hiOut())return;const s=S.sys;if(s&&Array.isArray(s.quests)){const bad=s.quests.filter(q=>q&&HQ_DROP.includes(q.k));if(bad.length){s.quests=s.quests.filter(q=>!bad.includes(q));sysLog(`ภารกิจของโลกล่าง ${bad.length} รายการถูกปลดออก ไม่มีความหมายในที่ที่คุณอยู่แล้ว`)}}
 if(Array.isArray(S.nq)&&S.nq.length){const n0=S.nq.length;S.nq=S.nq.filter(q=>q&&!HQ_DROP.includes(q.k));if(S.nq.length<n0)log('📜 คำขอจากคนในโลกล่างที่ทำไม่ได้แล้วถูกปลดออก (ไม่เสียอะไร)')}}catch(e){console.error(e)}}
