function hqLists(){const L=[];if(S&&S.sys&&Array.isArray(S.sys.quests))L.push(...S.sys.quests);if(S&&Array.isArray(S.nq))L.push(...S.nq);return L.filter(q=>q&&!q.pz)}
{const _pyHT=passYear;passYear=function(){let on=false;try{on=xFast();if(on){hqClean();for(const q of hqLists()){if(q.hiT==null)q.hiT=Math.max(2,(q.dl|0)-S.age);q.dl=q.hiT<=0?-1:S.age+1e15}}}catch(e){console.error(e)}
 const r=_pyHT.apply(this,arguments);
 try{if(S&&on){for(const q of hqLists()){if(q.hiT==null)continue;if(q.dl>0)q.hiT--;q.dl=S.age+Math.max(0,q.hiT)}}else if(S)for(const q of hqLists())if(q.hiT!=null){q.dl=S.age+Math.max(1,q.hiT);delete q.hiT}}catch(e){console.error(e)}return r}}
{const _mkT=mkQuest;mkQuest=function(k){const q=_mkT.apply(this,arguments);try{if(q&&hiOut()&&HQN[k]&&!bsB())q.n=HQN[k]().replace('{g}',fmt(+q.g));if(q&&xFast())q.hiT=Math.max(2,q.dl-S.age)}catch(e){}return q}}
{const _pqT=pushQuest;pushQuest=function(q){if(!(S&&xFast()))return _pqT.apply(this,arguments);const o=sysLog;sysLog=function(t){return o.call(this,String(t).replace(/ภายใน (\d+) ปี/,'ภายใน $1 รอบเวลา'))};try{return _pqT.apply(this,arguments)}finally{sysLog=o}}}
{const _qlT=questList;questList=function(){const L=_qlT.apply(this,arguments);try{if(S&&xFast())L.forEach(x=>{if(x&&/^(sq|nq)\d/.test(x.k)&&typeof x.p==='string')x.p=x.p.replace(/เหลือ (\d+) ปี/,'เหลือ $1 รอบเวลา')})}catch(e){}return L}}

