// ===================== 🐾 สัตว์คู่ใจ 2.0 — แตกสายวิวัฒนาการ · เลี้ยงได้ 3 ตัว · ความผูกพัน · ส่งต่อทายาท =====================
// S.beast = ตัวที่ติดตัว (ผลเต็ม) · S.bTeam = ตัวที่อยู่บ้าน (ผล 1/3)
const BP={f:['⚔️','ดุร้าย','#ff5a3a','ช่วยตีในศึกแรงขึ้น','สังหารพันศึก'],g:['🛡️','พิทักษ์','#4aa0ff','รับการโจมตีถึงตายแทน 1 ครั้งต่อ 10 ปี','พิทักษ์ประตูสวรรค์'],l:['🍀','โชคลาภ','#3fbf6a','คาบของหายากกลับมาให้','นำโชคพันลี้'],s:['🌀','วิญญาณ','#b07aff','ลมปราณเพิ่มทุกปี','กลืนแสงจันทรา']};
const BP_FOC={train:'f',mission:'f',adv:'l',work:'l',rest:'g',love:'g',qi:'s',study:'s',tech:'s',hunt:'f',hide:'g',roam:'l',moon:'s',human:'g'};
const BSET=[['f','g','🛡️⚔️ โล่หน้าดาบหลัง','พลังในศึก +3%'],['l','s','🍀🌀 ฟ้าประทานพร','ของหายากและลมปราณจากสัตว์คู่ใจ ×1.5'],['f','s','⚔️🌀 ดาบวิญญาณ','พลังในศึก +2% · ลมปราณจากสัตว์คู่ใจ ×1.3'],['g','l','🛡️🍀 บ้านอบอุ่น','ความสุข +2 และพลังชีวิตฟื้นเพิ่มทุกปี'],['f','l','⚔️🍀 นักล่าโชคดี','ชนะศึกแล้วมีโอกาสได้ของ'],['g','s','🛡️🌀 ผู้เฝ้าสมาธิ','ทะลวงขั้นปลอดภัยขึ้น · ลมปราณ ×1.2']];
function bTeam(){if(!S)return[];if(!Array.isArray(S.bTeam))S.bTeam=[];return S.bTeam}
function bSlots(){if(!S)return 1;return 1+((realmIdx()>=3||S.xian)?1:0)+((realmIdx()>=5||S.xt||(S.flags&&S.flags.bPact))?1:0)}
function bAll(){return(S&&S.beast?[S.beast]:[]).concat(bTeam())}
function bSlotFree(){return bSlots()-bAll().length}
function bTeamKeep(B){if(!B||bSlotFree()<=0)return false;bTeam().push(B);return true}
function bPaths(){const s=new Set();bAll().forEach(B=>{if(B.path)s.add(B.path)});return s}
function bSets(){const P=bPaths();return BSET.filter(x=>P.has(x[0])&&P.has(x[1]))}
function bHas(set){return bSets().some(x=>x[2]===set)}
function bBaseM(B){try{const b=beasts()[B.i];return .04+.03*B.st+Math.min(.12,B.lv*.004)+b.t*.006}catch(e){return 0}}
function bStageName(B){const b=beasts()[B.i];if(!b)return'?';if(B.st===0)return b.n;if(B.st===1)return b.n+'ตื่นรู้';return B.path?(['เทพ','ราชา','จักรพรรดิ'][b.t%3])+b.sp+BP[B.path][4]:(['เทพ','ราชา','จักรพรรดิ'][b.t%3])+b.sp+'สวรรค์'}
{const _bsn=beastStageN;beastStageN=function(){try{if(S&&S.beast&&S.beast.path)return bStageName(S.beast)}catch(e){}return _bsn.apply(this,arguments)}}
// พลังในศึก: ตัวติดตัวเต็ม + สาย ⚔️ · ตัวที่อยู่บ้าน 1/3 · โบนัสชุด
{const _bmM=beastM;beastM=function(){let m=_bmM.apply(this,arguments);try{if(!S)return m;const A=S.beast;if(A&&A.path==='f')m+=.02*(A.st+1);
 for(const B of bTeam()){m+=bBaseM(B)/3;if(B.path==='f')m+=.02*(B.st+1)/3}if(bHas(BSET[0][2]))m+=.03;if(bHas(BSET[2][2]))m+=.02}catch(e){}return m}}
function bPathPick(B,why){const L=B.ln||{f:0,g:0,l:0,s:0};let best=null,v=-1;for(const k of ['f','g','l','s']){const x=(L[k]||0)+Math.random()*.5;if(x>v){v=x;best=k}}B.path=best;const P=BP[best];
 log(`${P[0]} ${esc(B.nick)} ตื่นรู้เป็น<b>สาย${P[1]}</b>${why?' — '+why:''} · ${P[3]}`,'epic',true)}
function bGrow(B,home){const b=beasts()[B.i];if(!b)return;B.xp+=home?1:0;while(B.xp>=B.lv*2&&B.lv<60){B.xp-=B.lv*2;B.lv++}
 if(home){if(B.st===0&&B.lv>=10){B.st=1;if(!B.path)bPathPick(B,'ระหว่างอยู่บ้าน')}else if(B.st===1&&B.lv>=25&&b.t>=3){B.st=2;log(`🌟 ${esc(B.nick)} (อยู่บ้าน) วิวัฒนาการสูงสุดเป็น <b>${bStageName(B)}</b>`,'myth')}B.bond=Math.min(100,(B.bond||0)+.5)}}
{const _bct=beastCompTick;beastCompTick=function(){const A=S&&S.beast,st0=A?A.st:0;try{if(A&&A.st===0){A.ln=A.ln||{f:0,g:0,l:0,s:0};const k=BP_FOC[S.focus];if(k)A.ln[k]+=2}}catch(e){}
 const r=_bct.apply(this,arguments);try{if(A&&S.beast===A&&A.st>=1&&!A.path&&st0===0)bPathPick(A,'ตามวิธีที่คุณเลี้ยงมา');
  for(const B of bTeam())bGrow(B,1);
  // ผลประจำปีตามสาย
  const k=x=>x===S.beast?1:1/3,luckM=bHas(BSET[1][2])?1.5:1,qiM=bHas(BSET[1][2])?1.5:bHas(BSET[2][2])?1.3:bHas(BSET[5][2])?1.2:1;
  for(const B of bAll()){if(B.path==='l'&&Math.random()<.3*k(B)*luckM)bagGive(2,Math.min(6,3+B.st),`🍀 ${B.nick}คาบของกลับมา`);if(B.path==='s'){const g=+(Math.max(.5,(S.qi||0)*.004*(B.st+1))*k(B)*qiM).toFixed(1);S.qi=+((S.qi||0)+g).toFixed(1)}}
  if(bHas(BSET[3][2])){joy(2);S.hp=Math.min(S.maxHp,S.hp+Math.round(S.maxHp*.05))}
  bBondEv()}catch(e){console.error(e)}return r}}
// สาย 🛡️ (ตัวติดตัว) รับการโจมตีถึงตายแทน · ความผูกพันสูงสุดช่วยได้ 1 ครั้งต่อตัว
{const _cdB=checkDeath;checkDeath=function(){try{if(S&&S.alive&&!S.deathCause&&S.hp<=0&&S.beast){const A=S.beast;let why='';
  if(A.path==='g'&&A.st>=1&&S.age-(A.gAt==null?-99:A.gAt)>=10){A.gAt=S.age;why='พุ่งเข้ารับการโจมตีถึงตายแทนคุณ'}else if((A.bond||0)>=95&&!A.saved){A.saved=1;why='ไม่ยอมทิ้งคุณ ลากร่างคุณออกจากความตาย'}
  if(why){S.hp=Math.max(1,Math.round(S.maxHp*.3));A.bond=Math.min(100,(A.bond||0)+5);log(`${A.path==='g'?'🛡️':'💗'} <b>${esc(A.nick)}</b>${why}!`,'myth',true)}}}catch(e){}return _cdB.apply(this,arguments)}}
// ความผูกพันสูง: หายไปแล้วกลับมาพร้อมลูก
function bBondEv(){const A=S.beast;if(!A||(A.bond||0)<90||A.lv<15||A.kid||choice._cur||modalOpen||Math.random()>.08)return;A.kid=1;const b=beasts()[A.i];
 choice(`🐾 ${A.nick} หายไปสามปี`,`${esc(A.nick)}หายไปจากบ้านสามปีเต็ม คุณตามหาจนเกือบถอดใจ แล้ววันหนึ่งมันก็เดินกลับมา ข้างหลังมี<b>ลูก${b.sp}ตัวเล็ก</b>เดินตามมาต้อยๆ`,[
  {t:'🏡 รับลูกมาเลี้ยงด้วย',s:bSlotFree()>0?'ได้สัตว์คู่ใจตัวใหม่ (ไปอยู่บ้าน)':'ช่องเต็ม ฝากลูกไว้กับฝูงของมัน',_x:1,f(){if(bSlotFree()>0){const nk=ch(['เสี่ยว','อา','ต้า'])+ch(['ไป๋','เฮย','หง','จิน','หลาน','ฮวา','เล่ย','อวิ๋น','ซิง','เหมย']);bTeam().push({i:A.i,lv:1,xp:0,st:0,bond:70,nick:nk,hum:0,ln:{f:0,g:0,l:0,s:0}});log(`🐣 ลูกของ${esc(A.nick)}ชื่อ <b>${nk}</b> เข้ามาอยู่ในบ้าน`,'epic',true)}else{A.bond=100;log(`🐾 ลูกของ${esc(A.nick)}กลับไปอยู่กับฝูง แต่จะแวะมาหาทุกฤดูใบไม้ผลิ`,'good')}joy(10)}},
  {t:'🤗 กอดทั้งสองตัว',s:'ความสุข +',_x:1,f(){joy(15);A.bond=100;log(`🐾 ${esc(A.nick)}ซุกหน้าลงที่ตักคุณเหมือนวันแรก`,'good')}}])}
// สยบตัวใหม่: ช่องว่าง → ตัวเก่าไปอยู่บ้าน (ไม่ปล่อยทิ้ง)
function bTameNote(){return bSlotFree()>0?'ตัวเดิมจะไปอยู่บ้าน':'ช่องเต็ม ถ้าสำเร็จจะปล่อยตัวเก่า'}
// ฝึกด้วยกัน (ปีละครั้ง) — ดันสายตอนยังไม่ตื่นรู้
function bTrain(k){const A=S.beast;if(!A)return;if(S.bTrY===S.age)return toast('ปีนี้ฝึกด้วยกันแล้ว');S.bTrY=S.age;A.ln=A.ln||{f:0,g:0,l:0,s:0};A.ln[k]+=4;A.xp+=2;A.bond=Math.min(100,(A.bond||0)+2);
 const T={f:'พาออกล่าในป่าลึก',g:'นอนเฝ้าบ้านด้วยกันทั้งคืน',l:'พาเดินทางไปเมืองข้างเคียง',s:'นั่งสมาธิใต้แสงจันทร์ด้วยกัน'};log(`${BP[k][0]} ${T[k]}กับ${esc(A.nick)} — เอียงไปทางสาย${BP[k][1]}`);try{render()}catch(e){}openBeastComp()}
function bChoosePath(k){const A=S.beast;if(!A||A.path||A.st<1)return;A.path=k;log(`${BP[k][0]} ${esc(A.nick)} เลือกเดิน<b>สาย${BP[k][1]}</b> · ${BP[k][3]}`,'epic');openBeastComp()}
function bSwap(i){const T=bTeam(),B=T[i];if(!B)return;if(S.bSwY===S.age)return toast('สลับตัวติดตัวได้ปีละครั้ง');S.bSwY=S.age;T.splice(i,1);if(S.beast)T.push(S.beast);S.beast=B;log(`🔄 ${esc(B.nick)} ออกมาติดตัวแทน`);try{render()}catch(e){}openBeastComp()}
