// ===================== 🏝️ Dynamic Island: เสถียรขึ้น =====================
// 1) ป้ายที่ถูกรวม/อัปเดตซ้ำ ต่อเวลาได้ไม่เกิน 4 วิ นับจากที่ขึ้นครั้งแรก (เดิมรวมกันไม่หยุด → ค้างจอและแจ้งเตือนอื่นในคิวไม่ได้ขึ้น)
// 2) แจ้งเตือนสำคัญแทรก → ป้ายที่ถูกแทรกกลับเข้าคิวต่อ ไม่หายไปเฉยๆ
// 3) ตัวเฝ้า: ป้ายค้างนานเกิน · มีคิวแต่ไม่มีอะไรขึ้น · เกาะโชว์ค้างทั้งที่ไม่มีอะไร · กลับมาจากแท็บอื่น → จัดการให้
{const _irS=islRender;islRender=function(n,m){try{if(n&&!n._at)n._at=Date.now()}catch(e){}return _irS.apply(this,arguments)}}
{const _ntS=islNext;islNext=function(user){try{const c=ISL.cur,q0=ISL.q[0];if(!user&&c&&!c.live&&!c.sticky&&q0&&q0.pri&&!c.pri&&c._at&&Date.now()-c._at<(c.ms||2000)*.6&&!c._rq){c._rq=1;c._at=0;ISL.q.splice(1,0,c)}}catch(e){}return _ntS.apply(this,arguments)}}
{const _isS=island;island=function(n){try{const c=ISL.cur;if(n&&c&&c._at&&!c.live&&!c.sticky&&Date.now()-c._at>4000&&(n.upd&&c.key===n.key||(n.key||(n.ic||'')+n.t)===c.key||(!n.big&&!n.pri&&n.ic&&n.ic===c.ic&&(n.kind||'info')===(c.kind||'info')))){
   // หมดโควต้าต่อเวลา → ต่อคิวเป็นป้ายใหม่แทน
   if(n.upd)return;const q=ISL.q.find(x=>!x.big&&x.ic===n.ic&&(x.kind||'info')===(n.kind||'info'));if(q){q.t=n.t;q.n=(q.n||1)+1;return}ISL.q.push(Object.assign({},n,{key:(n.key||(n.ic||'')+n.t)+'~'+Date.now(),n:1,ms:n.ms||(n.big?3800:2000)}));return}}catch(e){}return _isS.apply(this,arguments)}}
// 4) ของที่รอคิวไอคอนเดียวกัน → รวมเป็นป้ายเดียว (×N) · คิวเต็ม → ทิ้งป้ายซ้ำ/ทั่วไปก่อน เก็บคำเตือนไว้
{const _isQ=island;island=function(n){try{if(n&&n.t&&!n.big&&!n.pri&&!n.sticky&&!n.upd&&n.ic){const q=ISL.q.find(x=>!x.big&&!x.sticky&&x.ic===n.ic&&(x.kind||'info')===(n.kind||'info'));if(q){q.t=n.t;q.n=(q.n||1)+1;return}}}catch(e){}
 const r=_isQ.apply(this,arguments);try{while(ISL.q.length>6){let i=ISL.q.findIndex((x,j)=>!x.pri&&ISL.q.some((y,k)=>k>j&&y.ic===x.ic));if(i<0)i=ISL.q.findIndex(x=>!x.pri&&(x.kind||'info')!=='bad');if(i<0)i=0;ISL.q.splice(i,1)}}catch(e){}return r}}
