function lvKeys(d){return(d.key||[]).map(k=>{const m=/^(\d+) ปี — ([\s\S]*)$/.exec(k);return m?{a:+m[1],x:m[2]}:{a:null,x:String(k)}})}
function lvMiles(d){const K=lvKeys(d),out=[];if(K.length)out.push({ic:'🐣',a:0,i:0});
 const pick=(ic,re,last)=>{let idx=-1;K.forEach((k,i)=>{if(re.test(k.x)&&(last||idx<0))idx=i});if(idx>0&&!out.some(o=>o.i===idx))out.push({ic,a:K[idx].a,i:idx})};
 pick('🏯',/เข้าสำนัก|รับเป็นศิษย์|เข้าร่วม|ศิษย์สำนัก/);pick('💍',/แต่งงาน|💍/);pick('👶',/ลูกคนแรก|ให้กำเนิด|👶/);pick('⚡',/ทะลวง|บรรลุ/,1);pick('☁️',/ขึ้นสู่โลก|เซียน|☁️/);pick('🌟',/ฉายา|ตำนาน|จอหงวน|🏆/);
 out.sort((a,b)=>(a.a||0)-(b.a||0)||a.i-b.i);const r=out.slice(0,6);r.push({ic:'🪦',a:d.age,i:-1});return r}
function lvJump(i){LV.hl=i;LV.f='all';lvDraw('tl')}
async function lvOpen(lid,tab){if(LV.lid!==lid||$('modal').dataset.k!=='lifeview'){lvBackSet();LV.f='all';LV.hl=-1}LV.lid=lid;tab=tab||'sum';
 let c=LVC[lid];if(!c||Date.now()-c.t>60e3){try{const j=await api('lifeview&l='+encodeURIComponent(lid));c=LVC[lid]={j,t:Date.now()}}catch(e){LV.lid=null;
   modal(`<button class="xbtn" onclick="lvBack()">✕</button><h3>${e.message==='private'?'🔒 ชีวิตนี้เป็นส่วนตัว':'ไม่พบข้อมูล'}</h3><p class="tag2">${e.message==='private'?'เจ้าของตั้งไม่ให้คนอื่นดูรายละเอียด':'ข้อมูลอาจหมดอายุแล้ว (เก็บไว้ 40 วัน)'}</p><button class="gbtn" style="width:100%" onclick="lvBack()">← กลับ</button>`,'lifeview');return}}
 if(LV.lid!==lid)return;lvDraw(tab)}
function lvBody(tab,j){const d=j.d,st=d.st||{};const list=(a,emp)=>a&&a.length?'<ul class="speclist">'+a.map(x=>`<li>${esc(x)}</li>`).join('')+'</ul>':`<p class="tag2">${emp}</p>`;
 if(tab==='sum'){const M=lvMiles(d);return`<div class="lvLine">${M.map(m=>`<button class="lvDot" onclick="lvJump(${m.i})"><i>${m.ic}</i><b>${m.a==null?'':m.a+' ปี'}</b></button>`).join('')}</div>
  <div class="specgrid"><div>⚔️ พลังรวม <b>${fmt(st.pow||0)}</b></div><div>📖 ปัญญา <b>${specN(st.int)}</b></div><div>🌸 เสน่ห์ <b>${specN(st.cha)}</b></div><div>💰 เงิน <b>${specMoney(d,st.money||0)}</b></div><div>⭐ ชื่อเสียง <b>${fmt(st.fame||0)}</b></div><div>☯️ กรรม <b>${specN(st.karma)}</b></div><div>⚔️ ชนะศึก <b>${fmt(st.kills||0)}</b></div><div>😊 สุขเฉลี่ย <b>${st.joy==null?'-':st.joy}</b></div></div>
  <ul class="speclist"><li>${esc(d.fam)} · ${esc(d.tal)}${d.gen>1?' · รุ่นที่ '+d.gen:''}</li><li>${esc(d.f)}</li>${d.traits&&d.traits.length?`<li>พรสวรรค์: ${esc(d.traits.join(' · '))}</li>`:''}${d.ow?`<li>🌌 ${esc(d.ow)}</li>`:''}${d.goal?`<li>🎯 ปณิธาน: ${esc(d.goal)}</li>`:''}${d.sys?`<li>🟦 ${esc(d.sys)}</li>`:''}${d.sect?`<li>🏯 ${esc(d.sect)}</li>`:''}${d.kl?`<li>🌀 ${esc(d.kl)}</li>`:''}</ul>${d.bye?`<p style="font-style:italic;text-align:center">"${esc(d.bye)}"</p>`:''}${lvSoc(j)}`}
 if(tab==='cmp')return lvCmp(d);
 if(tab==='birth'){let h=typeof birthHtml==='function'?birthHtml(d.birth):list([d.fam,d.tal],'');const p=lvCopyOk(d);if(p)h+=`<button class="gbtn" style="width:100%;margin-top:8px" onclick="lvCopy()">🎲 เกิดแบบนี้บ้าง<small style="display:block;font-size:11px;opacity:.85">เปิดหน้าสร้างเองด้วย${esc(p)} · ชีวิตสร้างเองไม่ติดทำเนียบ</small></button>`;return h}
 if(tab==='tl'){const K=lvKeys(d),F=LV.f,re=LV_FI[F];const rows=K.map((k,i)=>re&&!re.test(k.x)?'':`<div data-i="${i}" class="${i===LV.hl?'hl':''}">${k.a!=null?`<b class="px">${k.a}</b> `:''}${esc(k.x)}</div>`).join('');
  return`<div class="lvF">${[['all','ทั้งหมด'],['fight','⚔️ ต่อสู้'],['love','💞 ความรัก'],['turn','⭐ จุดเปลี่ยน']].map(([k,l])=>`<button class="${F===k?'on':''}" onclick="LV.f='${k}';LV.hl=-1;lvDraw('tl')">${l}</button>`).join('')}</div><div class="lvTl">${rows||'<p class="tag2">ไม่มีเหตุการณ์ในหมวดนี้</p>'}<div class="sfh" data-i="-1" ${LV.hl===-1&&F==='all'?'':''}>🪦 ${esc(d.cause)} · อายุ ${d.age}</div></div>`}
 if(tab==='rel')return'<h4 style="margin:4px 0">💞 ความสัมพันธ์</h4>'+(d.rel&&d.rel.length?list(d.rel,''):`<ul class="speclist">${d.spouse?`<li>💍 คู่ครอง ${esc(d.spouse)}</li>`:''}${d.kids&&d.kids.length?`<li>👶 ลูก ${d.kids.length} คน: ${esc(d.kids.join(', '))}</li>`:''}</ul>${!d.spouse&&!(d.kids||[]).length?'<p class="tag2">ใช้ชีวิตตัวคนเดียว</p>':''}`)+(d.org&&d.org.length?'<h4 style="margin:8px 0 4px">🏯 สังกัด</h4>'+list(d.org,''):'');
 if(tab==='item'){const A=Array.isArray(d.at)&&d.at.length?`<div class="lvArts">${d.at.map(a=>{const t=Math.max(0,Math.min(4,a[1]|0));return`<div class="lvArt" style="--c:${LV_AC[t]}"><small>${esc((ART_TIER[t]||{}).n||'')}${a[2]&&typeof AMN!=='undefined'&&AMN[a[2]]?' · '+esc(AMN[a[2]]):''}</small>《${esc(a[0])}》</div>`}).join('')}</div>`:list(d.arts,'ไม่มีวิชา');
  return'<h4 style="margin:4px 0">🛡️ สวมใส่</h4>'+list(d.eq,'ไม่มี')+'<h4 style="margin:8px 0 4px">📜 วิชา</h4>'+A}
 if(tab==='ach')return list(d.ach,'ไม่ได้ปลดล็อกอะไรในชีวิตนี้');
 if(tab==='story')return typeof storyHtml==='function'?storyHtml(d.sa,0):'';return''}
function lvDraw(tab){const c=LVC[LV.lid];if(!c)return;LV.tab=tab;const j=c.j,d=j.d,lid=LV.lid;const T=LV_T.filter(t=>t[0]!=='story'||d.sa);
 const ch=[];if(d.tt)ch.push(`<span class="lvChip ttl">🏷️ ${esc(d.tt)}</span>`);(d.bc||[]).forEach(k=>{const b=BODY_C[k];if(!b)return;ch.push(`<span class="lvChip ${k==='bowleg'?'bow':k==='rush'?'rush':''}" ${k==='bowleg'?'onclick="try{bowFx()}catch(e){}"':k==='rush'?'onclick="try{rushFx()}catch(e){}"':''}>${b.ic||'💪'} ${esc(b.n)}</span>`)});if(j.kn)ch.push(`<span class="lvChip">🙏 ${fmt(j.kn)}</span>`);
 let av='<canvas id="specCv" width="140" height="154"></canvas>';try{if(d.fr&&typeof frWrap==='function'&&frOf(d.fr))av=frWrap(av,d.fr)}catch(e){}
 const sc=$('modal').dataset.k==='lifeview'?($('modal').querySelector('.lvT')||{}).scrollLeft||0:0;
 modal(`<button class="xbtn" onclick="lvBack()">✕</button><div class="lvH">${av}<div style="min-width:0">${d.ep?`<div class="tag2" style="color:var(--pinkd)">「${esc(d.ep)}」</div>`:''}<h3 style="margin:0">${j.pu?`<span class="pfav" data-pu="${j.pu}"></span>`:''}${esc(d.n)}</h3><div class="tag2">${d.x?'☁️ โลกเทพเซียน':'⚔️ ยุทธภพ'} · อายุ ${d.age} ปี · ${esc(d.r)}${d.cu?' · ✍️':''}</div><div class="tag2">🪦 ${esc(d.cause)}</div><div class="tag2">คะแนนตำนาน <b class="px">${fmt(d.s||0)}</b>${j.mine?` · ${j.pub?'🌐 เปิดให้ดู':'🔒 ส่วนตัว'} (ของคุณ)`:''}</div>${ch.length?`<div class="lvChips">${ch.join('')}</div>`:''}</div></div>
  <div class="lvT">${T.map(t=>`<button class="lvTb ${t[0]===tab?'on':''}" onclick="lvDraw('${t[0]}')">${t[1]}</button>`).join('')}</div><div class="lvB">${lvBody(tab,j)}</div><button class="gbtn" style="width:100%;margin-top:8px" onclick="lvBack()">← กลับ</button>`,'lifeview');
 try{specDrawAva(d.look||{})}catch(e){}
 try{const t=$('modal').querySelector('.lvT');if(t){t.scrollLeft=sc;const on=t.querySelector('.on');if(on&&(on.offsetLeft<t.scrollLeft||on.offsetLeft+on.offsetWidth>t.scrollLeft+t.clientWidth))on.scrollIntoView({inline:'center',block:'nearest'})}}catch(e){}
 if(tab==='tl'&&LV.hl!==-1)setTimeout(()=>{try{const e=$('modal').querySelector(`.lvTl [data-i="${LV.hl}"]`);if(e){const box=e.parentNode;box.scrollTop=e.offsetTop-box.offsetTop-60}}catch(x){}},30);
 if(tab==='tl'&&LV.hl===-1&&LV.f==='all'&&lvJump._end){lvJump._end=0}}
// แตะ 🪦 ในเส้นชีวิต → ไปท้ายไทม์ไลน์
{const _j=lvJump;lvJump=function(i){if(i===-1){LV.hl=-2;LV.f='all';lvDraw('tl');setTimeout(()=>{try{const b=$('modal').querySelector('.lvTl');if(b)b.scrollTop=b.scrollHeight}catch(e){}},30);return}return _j(i)}}

// ---- เทียบกับฉัน ----
function lvMine(){if(S&&S.alive){let p=0;try{p=total()}catch(e){p=S.power||0}return{n:S.name,age:S.age,live:1,st:{pow:p,int:S.int,cha:S.cha,fame:S.fame,money:S.money,kills:S.kills,karma:S.karma}}}const m=LS.get('murim_mylast',null);return m&&m.st?m:null}
function lvCmp(d){const me=lvMine();if(!me)return'<p class="tag2">ยังไม่มีชีวิตคุณให้เทียบ เล่นสักชีวิตก่อนนะ</p>';const a=d.st||{},b=me.st||{};
 const R=[['⚔️ พลังรวม','pow'],['📖 ปัญญา','int'],['🌸 เสน่ห์','cha'],['⭐ ชื่อเสียง','fame'],['💰 เงิน','money'],['⚔️ ชนะศึก','kills'],['⏳ อายุ',null,d.age,me.age]];if(!me.live&&me.s)R.push(['🏆 คะแนนตำนาน',null,d.s||0,me.s]);
 let win=0,lose=0;const rows=R.map(([l,k,x0,y0])=>{const x=Math.max(0,+(k?a[k]:x0)||0),y=Math.max(0,+(k?b[k]:y0)||0),mx=Math.max(x,y,1),w=v=>v<=0?0:Math.max(3,Math.log10(v+1)/Math.log10(mx+1)*100);if(y>x)win++;else if(x>y)lose++;
  return`<div class="r"><div><span>${l}</span><span><b style="color:#ff9a6a">${fmt(x)}</b> · <b style="color:#6ac8ff">${fmt(y)}</b>${x>0&&y>0&&x!==y?` <small class="tag2">${y>x?'คุณ ×'+(y/x).toFixed(y/x<10?1:0):'เขา ×'+(x/y).toFixed(x/y<10?1:0)}</small>`:''}</span></div><div class="bar"><i style="width:${w(x)}%;background:#ff9a6a"></i></div><div class="bar"><i style="width:${w(y)}%;background:#6ac8ff"></i></div></div>`}).join('');
 return`<p class="tag2" style="margin:2px 0 6px"><b style="color:#ff9a6a">■ ${esc(d.n)}</b> vs <b style="color:#6ac8ff">■ ${esc(me.n||'คุณ')}${me.live?' (ชีวิตที่เล่นอยู่)':' (ชีวิตล่าสุด)'}</b></p><div class="lvCmp">${rows}</div><p style="text-align:center;margin:10px 0 0;font-weight:700">${win>lose?`🔥 คุณชนะ ${win}/${R.length} ด้าน`:win<lose?`💀 เขานำ ${lose}/${R.length} ด้าน ยังต้องฝึกอีกเยอะ`:'⚖️ สูสีกันมาก'}</p>`}

// ---- คารวะ · คำไว้อาลัย ----
function lvSoc(j){const mine=j.mine,pub=j.pub;if(!pub&&!mine)return'';const E=j.eu||[];
 return`<div class="lvSoc">${mine?`<div style="text-align:center;font-weight:700">🙏 มีคนคารวะชีวิตนี้ ${fmt(j.kn||0)} ครั้ง</div>`:`<button class="lvKn" ${j.kd?'disabled':''} onclick="lvKneel(this)">🙏 คารวะ${j.kn?' · '+fmt(j.kn):''}${j.kd?' (วันนี้คารวะแล้ว)':''}</button>`}
  <div class="lvEu">${E.length?E.map(e=>`<div><b>${esc(e.n)}</b><span>${esc(e.x)}</span>${e.me||mine?'':`<button title="รายงาน" onclick="lvRep('${e.i}',this)">🚩</button>`}</div>`).join(''):'<p class="tag2" style="margin:0;text-align:center">ยังไม่มีคำไว้อาลัย</p>'}</div>
  ${!mine&&!j.em?`<div class="lvEin"><input id="lvEx" maxlength="60" placeholder="เขียนคำไว้อาลัย 1 บรรทัด (ได้ครั้งเดียว)"><button onclick="lvEu()">ส่ง</button></div>`:''}</div>`}
openLifeView=lvOpen;
async function lvKneel(btn){const lid=LV.lid,c=LVC[lid];if(!c||!onlineOK)return toast('ต้องออนไลน์ก่อน');btn.disabled=true;try{const r=await api('lvkneel',{lid});c.j.kn=r.kn||c.j.kn;c.j.kd=1;if(r.ok){sfx('good');toast('🙏 คารวะแล้ว');btn.classList.add('pop')}else toast('วันนี้คารวะไปแล้ว');btn.textContent=`🙏 คารวะ · ${fmt(c.j.kn)} (วันนี้คารวะแล้ว)`}catch(e){btn.disabled=false;toast(e.message==='self'?'คารวะชีวิตตัวเองไม่ได้':'คารวะไม่สำเร็จ')}}
async function lvEu(){const lid=LV.lid,c=LVC[lid],i=$('lvEx');if(!c||!i)return;const x=i.value.trim();if(!x)return toast('พิมพ์ก่อน');if(!onlineOK)return toast('ต้องออนไลน์ก่อน');i.disabled=true;
 try{const r=await api('lveu',{lid,x,n:pname()});c.j.em=1;if(r.ok&&r.e){c.j.eu=[r.e].concat(c.j.eu||[]).slice(0,20);toast('ส่งคำไว้อาลัยแล้ว')}else toast('คุณเขียนให้ชีวิตนี้ไปแล้ว');if(LV.lid===lid&&LV.tab==='sum')lvDraw('sum')}catch(e){i.disabled=false;toast(e.message==='muted'?'บัญชีนี้ถูกปิดการพิมพ์':'ส่งไม่สำเร็จ')}}
async function lvRep(mid,b){try{await api('report',{mid});b.textContent='✓';b.disabled=true;toast('รายงานแล้ว ขอบคุณครับ')}catch(e){toast('รายงานไม่สำเร็จ')}}

// ---- เกิดแบบนี้บ้าง ----
function lvCopyPlan(d){const B=d.birth;if(!B||B.cu||typeof FAMILY==='undefined')return null;const fi=FAMILY.findIndex(f=>f.n===B.fam);if(fi<0||fi>=CR_FAM.length)return null;let ti=TALENT.findIndex(t=>t.n===B.tal||(typeof rootOf==='function'&&rootOf(t)===B.tal));if(ti>=CR_TAL.length)ti=-1;
 const trs=[];(B.traits||[]).forEach(n=>{const nm=String(n).replace(/^⚠️\s*/,'');const t=(typeof TRAITS!=='undefined'?TRAITS:[]).find(x=>x.n===nm);if(t&&trs.length<3&&!(typeof TR_CONF!=='undefined'&&TR_CONF.some(([a,b])=>(a===t.id&&trs.includes(b))||(b===t.id&&trs.includes(a)))))trs.push(t.id)});
 return{fi,ti,trs,g:GENDER.findIndex(x=>x.n===B.g)}}
function lvCopyOk(d){const p=lvCopyPlan(d);if(!p)return'';return FAMILY[p.fi].n+(p.ti>=0?' · '+TALENT[p.ti].n:'')+(p.trs.length?` · พรสวรรค์ ${p.trs.length} ใบ`:'')}
