function jCrtF(a){const J=jInit(),W=CT_W();if(!J)return closeM();if(a===0||Math.random()<.5){if(a===0){J.lv=2;J.xp=JOB_XP[2];J.ct={f:40,side:''};J.ban=S.age+6;const t=`คุณหนีออกจากเมืองหลวงกลางดึก ถูกปลดเหลือ${jRk(J)} และห้ามกลับ${W[0]} 6 ปี`;log('🏛️ '+t,'bad',true);return jResult(t,false)}J.ct.f=60;J.ct.side='';S.karma+=10;const t=`ศาลไต่สวนแล้วไม่พบหลักฐาน คุณได้ล้างมลทิน ความโปรดปรานกลับมา 60 · กรรม +10`;log('🏛️ '+t,'epic',true);return jResult(t,true)}
 closeM();S.deathCause=`ถูกประหารใน${W[0]}ด้วยข้อหากบฏ`;S.hp=0;try{checkDeath()}catch(e){}}
JOB.sch.extra=(()=>{const _e=JOB.sch.extra;return function(J){let h=_e.apply(this,arguments);if(J.lv>=3){const W=CT_W(),T=J.ct||{f:50};h+=`<div class="item"><b>🏛️ ${W[0]}</b><p class="tag2">ความโปรดปราน ${Math.round(T.f)}/100${T.side?' · อยู่'+(T.side==='a'?W[1]:W[2]):''}${T.top?' · 👑 '+W[4]:''}</p></div>`}return h}})();
{const _sl=JOB.sch.sal;JOB.sch.tick=(()=>{const _t=JOB.sch.tick;return function(J,st){try{if(_t)_t.apply(this,arguments)}catch(e){}if(J.ct&&J.ct.top){const s=Math.round(((_sl||[])[J.lv]||0)*W15()*st);if(s){S.money+=s;J.st.earn+=s}}}})()}

// ---------- 🗡️ มือสังหาร (ยุทธภพ) ----------
const ASN_R=['พ่อค้าเกลือหน้าเลือด','ขุนนางฉ้อราษฎร์','เจ้าสำนักเล็กที่ขัดขวางคนใหญ่','หัวหน้าโจรภูเขา','ผู้อาวุโสพรรคมาร','ทายาทตระกูลใหญ่','หมอที่รู้ความลับของคนผิด','นักพรตที่ไม่ยอมขายที่ดิน'];
Object.assign(JOB,{asn:{ic:'🗡️',w:'m',n:{m:'มือสังหาร',x:'มือสังหารเงา',g:'เพชฌฆาตสวรรค์'},rk:{m:['มือสังหารไร้นาม','มือสังหารเงาดำ','มือสังหารค่าตัวพันตำลึง','ราชันมือสังหาร'],x:['มือสังหารไร้นาม','มือสังหารเงาดำ','มือสังหารค่าตัวหมื่นหิน','ราชันมือสังหาร'],g:['เพชฌฆาตฝึกหัด','เพชฌฆาตเงา','เพชฌฆาตเลื่องชื่อ','ราชันเพชฌฆาต']},
 d:'รับสัญญาสังหาร สืบประวัติเป้าหมาย แล้วเลือกวิธี: วางยา ลอบฆ่ายามวิกาล หรือท้าดวลซึ่งหน้า · ได้เงินมากแต่กรรมลด · ยิ่งดังยิ่งถูกตามล่า',req:'ยุทธภพเท่านั้น · อายุ 18+ · ขั้นสองขึ้นไป',ok:()=>ECO_W()==='m'&&S.age>=18&&realmIdx()>=2,
 qh:'📜 สัญญาที่รออยู่',ex:'ผู้ว่าจ้างรอไม่ไหว ไปจ้างคนอื่นแล้ว',nt:n=>`มีผู้ว่าจ้างส่งสัญญามา ${n} ฉบับ`,mk:jMkAsn,tick:asnTick,extra:asnExtra,
 perks:['ขั้น 2: สืบประวัติเป้าหมายฟรี','ขั้น 3: ค่าจ้าง ×1.5','ขั้น 4: ปีละครั้ง "ลบรอย" ล้างความแค้นที่ตามล่าครึ่งหนึ่ง']}});
function jMkAsn(J){J.heat=J.heat|0;if(J.heat>=60&&Math.random()<.4&&!J.q.some(c=>c.k==='ahn'))return{k:'ahn',y:S.age};const evil=Math.random()<.55,lie=!evil&&Math.random()<.5;return{k:'asn',y:S.age,tg:anyName(ch(['ชาย','หญิง'])),role:ASN_R[evil?R(0,4):R(5,7)],evil,lie,gd:ch(['none','guard','guard','master']),pw:+(0.6+Math.random()*.5+J.lv*.08).toFixed(2),scout:J.lv>=1?1:0}}
function asnTick(J,st){J.heat=Math.max(0,(J.heat|0)-4*st)}
function asnExtra(J){return`<div class="item" style="margin-top:8px"><b>🔥 ความแค้นที่ตามล่า ${Math.round(J.heat|0)}/100</b><div class="hpbar" style="height:6px;margin:4px 0"><i style="width:${Math.min(100,J.heat|0)}%;background:#c83a3a"></i></div><p class="tag2">ทุกงานเพิ่มความแค้น · เกิน 60 จะมีคนมาตามล่า · ลดลงเองปีละ 4${J.lv>=3?` <button class="sysb" onclick="jAsnClean()" ${J.clY===S.age?'disabled':''}>🧹 ลบรอย</button>`:''}</p></div>`}
function jAsnClean(){const J=jInit();if(!J||J.lv<3||J.clY===S.age)return;J.clY=S.age;J.heat=Math.round((J.heat|0)/2);toast('🧹 ลบร่องรอยแล้ว ความแค้นลดครึ่ง');openJob()}
function jAsnPay(J){return jbPay(J,1400)*(J.lv>=2?1.5:1)|0}
function jAsnUI(id){const J=jInit(),c=jcGet(id);if(!c)return openJob();const ep=Math.round(total()*c.pw),g=jAsnPay(J),pc=jAsnP(J,c);const GD={none:'อยู่ตัวคนเดียว',guard:'มีองครักษ์ 5–6 คน',master:'มียอดฝีมือคุ้มกัน'}[c.gd];
 modal(`${jBk}<h3>🗡️ สัญญาสังหาร: ${esc(c.tg)}</h3><p>ชายสวมงอบวางถุงเงินบนโต๊ะในมุมมืดของโรงเตี๊ยม "${esc(c.tg)} — <b>${c.role}</b> · ค่าจ้าง ${ftMf(g)}"</p>
 <div class="item"><b>🔍 ข้อมูลเป้าหมาย</b><p class="tag2">${c.scout?`${GD} · แรงราว ${Math.round(c.pw*100)}% ของคุณ<br>${c.lie?'⚠️ <b>สืบแล้วพบว่าเป้าหมายเป็นคนดี</b> ผู้ว่าจ้างโกหก':c.evil?'✅ เป้าหมายทำชั่วมามากจริง':'❔ เป็นคนธรรมดา ไม่ได้ชั่วร้าย'}`:'ยังไม่รู้อะไรเลย'}</p>${c.scout?'':`<button class="gbtn" style="width:100%" onclick="jAsnScout('${id}')">🕵️ สืบประวัติ ${ftMf(jbPay(J,200))}</button>`}</div>
 <div class="mgrid"><button class="opt" onclick="jAsn('${id}','poi')">☠️ วางยา<small>ใช้สมุนไพร 2 · โอกาส ${Math.round(pc.poi*100)}% · เงียบที่สุด</small></button><button class="opt" onclick="jAsn('${id}','sne')">🌑 ลอบฆ่ายามวิกาล<small>โอกาส ${Math.round(pc.sne*100)}% · พลาด = ต้องสู้</small></button><button class="opt" onclick="jAsn('${id}','duel')">⚔️ ท้าดวลซึ่งหน้า<small>ดวล (แรงเขา ${fmt(ep)}) · ได้ชื่อเสียง · ความแค้นน้อย</small></button><button class="opt" onclick="jAsn('${id}','no')">✋ ฉีกสัญญา<small>กรรม +2${c.lie?' · เตือนเป้าหมายได้กรรม +8':''}</small></button></div>`,'job')}
function jAsnP(J,c){const gd={none:0,guard:.12,master:.25}[c.gd];return{poi:clamp(.3+S.int/500+J.lv*.08-gd*.5,.1,.9),sne:clamp(.25+.35/c.pw+J.lv*.07-gd,.08,.9)}}
function jAsnScout(id){const J=jInit(),c=jcGet(id),p=jbPay(J,200);if(!c)return;if(S.money<p)return toast('เงินไม่พอ');S.money-=p;c.scout=1;sfx('click');jAsnUI(id)}
function jAsn(id,m){const J=jInit(),c=jcGet(id);if(!c)return;const g=jAsnPay(J),pc=jAsnP(J,c),kk=c.lie?-25:c.evil?-2:-12;
 const ok=(how)=>{S.money+=g;J.st.earn+=g;J.st.ok++;S.karma+=kk;J.heat=Math.min(100,(J.heat|0)+(how==='duel'?6:how==='poi'?10:16));jXp(J,c.gd==='master'?2:1);if(how==='duel')S.fame+=25;const t=`${esc(c.tg)}${how==='poi'?'สิ้นใจในงานเลี้ยงอย่างเงียบเชียบ':how==='sne'?'ถูกพบเป็นศพในห้องนอนตอนเช้า':'ล้มลงต่อหน้าผู้คนหลังการดวล'} · ได้ ${ftMf(g)} · กรรม ${kk}${c.lie?' (ฆ่าคนบริสุทธิ์)':''}`;log('🗡️ '+t,c.lie?'bad':'good');jResult(t,true)};
 const fail=(t)=>{J.st.bad++;J.heat=Math.min(100,(J.heat|0)+20);jRp(J,-6);log('🗡️ '+t,'bad');jResult(t,false)};
 if(m==='no'){jcDel(id);S.karma+=c.lie&&c.scout?8:2;const t=c.lie&&c.scout?`คุณฉีกสัญญาแล้วแอบส่งจดหมายเตือน${esc(c.tg)} · กรรม +8`:'คุณดันถุงเงินคืน "งานนี้ข้าไม่รับ" · กรรม +2';log('🗡️ '+t,'good');return jResult(t,true)}
 if(m==='poi'){if(!bagTake('herb',2))return toast('ต้องใช้สมุนไพร 2 ต้น');jcDel(id);return Math.random()<pc.poi?ok('poi'):fail(`ยาพิษถูกตรวจพบก่อนถึงปาก${esc(c.tg)} มีคนเริ่มตามหาคนปรุงยา (ความแค้น +20)`)}
 if(choice._cur)return toast('ตัดสินใจเรื่องที่ค้างอยู่ก่อน');jcDel(id);
 if(m==='sne'&&Math.random()<pc.sne)return ok('sne');
 closeM();if(m==='sne')log(`🗡️ ${esc(c.tg)}สะดุ้งตื่นกลางดึก ต้องสู้กันซึ่งหน้า!`,'');duel(c.tg,Math.round(total()*c.pw*(m==='sne'?1.1:1)),w=>{if(w)ok(m==='sne'?'sne':'duel');else{S.hp-=Math.round(S.maxHp*.35);fail(`คุณพลาดท่า${esc(c.tg)} ต้องหนีออกมาพร้อมบาดแผล (พลังชีวิต −35%)`)}})}
function jAhnUI(id){const J=jInit(),c=jcGet(id);if(!c)return openJob();const g=jbPay(J,1500);
 modal(`${jBk}<h3>🩸 มีคนตามล่าคุณ</h3><p>ญาติและศิษย์ของคนที่คุณสังหาร รวมตัวกันจ้างนักล่าค่าหัวมาตามหาคุณ ตอนนี้พวกมันล้อมโรงเตี๊ยมไว้แล้ว</p>
 <div class="mgrid"><button class="opt" onclick="jAhn('${id}',0)">⚔️ ฝ่าวงล้อม<small>ดวลกับนักล่าค่าหัว · ชนะความแค้น −40</small></button><button class="opt" onclick="jAhn('${id}',1)">💰 จ่ายค่าไถ่ชีวิต<small>${ftMf(g)} · ความแค้น −30</small></button></div>`,'job')}
function jAhn(id,a){const J=jInit(),c=jcGet(id);if(!c)return;if(a===1){const g=jbPay(J,1500);if(S.money<g)return toast('เงินไม่พอ');jcDel(id);S.money-=g;J.heat=Math.max(0,(J.heat|0)-30);const t=`จ่ายเงินให้นักล่าค่าหัวถอนตัว ${ftMf(g)} · ความแค้น −30`;log('🩸 '+t,'');return jResult(t,true)}
 if(choice._cur)return toast('ตัดสินใจเรื่องที่ค้างอยู่ก่อน');jcDel(id);closeM();duel('นักล่าค่าหัว',Math.round(total()*(1+J.heat/250)),w=>{if(w){J.heat=Math.max(0,(J.heat|0)-40);S.fame+=15;log('🩸 คุณฝ่าวงล้อมออกมาได้ ศพนักล่าค่าหัวกองอยู่หน้าโรงเตี๊ยม · ความแค้น −40','epic')}else{S.hp-=Math.round(S.maxHp*.5);J.heat=Math.max(0,(J.heat|0)-15);log('🩸 คุณหนีรอดมาได้อย่างหวุดหวิด พลังชีวิต −50%','bad')}try{render()}catch(e){}})}

// ---------- 📰 สำนักรู้ร้อยเรื่อง (ยุทธภพ) — จัดอันดับยอดฝีมือจากทำเนียบจริง ----------
Object.assign(JOB,{nws:{ic:'📰',w:'m',n:{m:'สำนักรู้ร้อยเรื่อง',x:'หอบันทึกเซียน',g:'หอบันทึกสวรรค์'},rk:{m:['ผู้จดบันทึก','นักข่าวโรงเตี๊ยม','บัณฑิตรู้ร้อยเรื่อง','ไป่เสี่ยวเซิงแห่งยุคสมัย'],x:['ผู้จดบันทึก','นักบันทึกหอเซียน','ผู้รู้แห่งหอเซียน','ปราชญ์ร้อยเรื่องแดนเซียน'],g:['ผู้จดบันทึก','นักบันทึกสวรรค์','ผู้รู้แห่งสวรรค์','ปราชญ์ร้อยเรื่องสวรรค์']},
 d:'จัดอันดับยอดฝีมือจาก<b>ชีวิตของผู้เล่นจริงในทำเนียบ</b> ดูประวัติแล้วเรียงว่าใครเป็นตำนานยิ่งกว่า · ทายถูกได้ชื่อเสียงและเงิน · ขายข่าวลือได้ปีละครั้ง',req:'ยุทธภพเท่านั้น · อายุ 16+ · ปัญญา 60+',ok:()=>ECO_W()==='m'&&S.age>=16&&S.int>=60,
 qh:'📰 งานจัดอันดับ',ex:'ทำเนียบรอบนี้ออกไปโดยไม่มีชื่อคุณ',nt:()=>'ถึงเวลาออกทำเนียบยอดฝีมือรอบใหม่',one:1,mk:J=>J.q.some(c=>c.k==='nws')?null:{k:'nws',y:S.age},extra:nwsExtra,
 perks:['ขั้น 2: เห็นอายุขัยและสาเหตุการตาย','ขั้น 3: ขายข่าวได้เงินมากขึ้น','ขั้น 4: ชื่อสำนักขึ้นหัวทำเนียบ ชื่อเสียงทุกปี']}});
async function nwsPool(){const c=nwsPool._c;if(c&&Date.now()-c.t<300e3)return c.l;let l=[];if(onlineOK){try{const j=await api('board',{p:'w'});l=[].concat(j.top||[],j.ctop||[]).filter(e=>e&&e.n&&+e.s>0&&e.n!=='ผู้ไม่ประสงค์ออกนาม');const seen={};l=l.filter(e=>{const k=e.n+'|'+e.s;if(seen[k])return false;seen[k]=1;return true})}catch(e){}}nwsPool._c={t:Date.now(),l};return l}
async function jNwsUI(id){const J=jInit(),c=jcGet(id);if(!c)return openJob();if(!c.set){modal(`${jBk}<h3>📰 กำลังรวบรวมข่าว…</h3>`,'job');const L=await nwsPool();if(!jcGet(id))return;
  if(L.length>=3){const P=L.slice().sort(()=>Math.random()-.5).slice(0,3);c.set=P.map(e=>({n:e.n,s:+e.s,age:e.age,r:e.r,f:e.f,c:e.c,x:e.x}));c.real=1}
  else{c.set=[0,1,2].map(()=>{const a=R(30,400),r=R(0,6);return{n:anyName(ch(['ชาย','หญิง'])),s:Math.round((r+1)*a*(5+Math.random()*10)),age:a,r:REALMS[r].n,f:ch(FACTIONS).n,c:'จากไปอย่างสงบ',x:0}});c.real=0}c.pick=[]}
 const P=c.set;modal(`${jBk}<h3>📰 ทำเนียบยอดฝีมือรอบใหม่</h3><p class="tag2">${c.real?'🌐 ข้อมูลจากชีวิตผู้เล่นจริงในทำเนียบสัปดาห์นี้':'ออฟไลน์ ใช้ข่าวลือในโรงเตี๊ยมแทน'} · แตะเรียงจาก<b>คะแนนตำนานสูงสุด</b>ไปต่ำสุด</p>
 <div class="jpick">${P.map((e,k)=>{const at=c.pick.indexOf(k);return`<div class="jsel ${at>=0?'on':''}" onclick="jNwsP('${id}',${k})"><span class="jbig"><b>${esc(e.n)}</b><br><span class="tag2">${e.x?'☁️':'⚔️'} ${esc(e.r||'')} · ${esc(e.f||'')}${J.lv>=1?` · อายุ ${e.age} · ${esc(String(e.c||'').slice(0,40))}`:''}</span></span><b style="font-size:20px">${at>=0?['🥇','🥈','🥉'][at]:''}</b></div>`}).join('')}</div>
 <div class="brow" style="margin-top:6px"><button class="gbtn" style="flex:1" onclick="jcGet('${id}').pick=[];jNwsUI('${id}')">↺ เริ่มเรียงใหม่</button><button class="pbtn" style="flex:2" onclick="jNwsGo('${id}')" ${c.pick.length===3?'':'disabled style="opacity:.5"'}>📜 ประกาศทำเนียบ</button></div>`,'job')}
function jNwsP(id,k){const c=jcGet(id);if(!c)return;if(c.pick.includes(k))return;c.pick.push(k);if(c.pick.length===2)c.pick.push([0,1,2].find(x=>!c.pick.includes(x)));jNwsUI(id)}
function jNwsGo(id){const J=jInit(),c=jcGet(id);if(!c||c.pick.length<3)return;jcDel(id);const P=c.set,ans=[0,1,2].sort((a,b)=>P[b].s-P[a].s);let hit=0;c.pick.forEach((k,i)=>{if(ans[i]===k)hit++});
 const g=hit===3?jbPay(J,900):hit===1?jbPay(J,200):0;S.money+=g;J.st.earn+=g;const f=hit===3?25:hit?5:0;S.fame+=f;if(hit===3){J.st.ok++;jXp(J,2);jRp(J,5)}else{J.st.bad++;jRp(J,-4)}
 J.hist=(J.hist||[]).concat([ans.map(k=>P[k].n)]).slice(-3);
 const t=`${hit===3?'ทำเนียบคุณแม่นยำทุกอันดับ! ชาวยุทธภพแห่ซื้อกันจนหมดแผง':hit?'ทำเนียบถูกบ้างผิดบ้าง มีคนมาโวยที่โรงเตี๊ยม':'ทำเนียบผิดทั้งหมด ถูกหัวเราะเยาะทั้งเมือง'}${g?' · ได้ '+ftMf(g):''}${f?' · ชื่อเสียง +'+f:''}<br><span class="tag2">อันดับจริง: ${ans.map((k,i)=>`${['🥇','🥈','🥉'][i]} ${esc(P[k].n)} (${fmt(P[k].s)})`).join(' · ')}</span>`;log('📰 '+t.replace(/<br>[\s\S]*/,''),hit===3?'epic':hit?'':'bad');jResult(t,hit===3)}
function nwsExtra(J){return`<div class="item" style="margin-top:8px"><div class="h"><b>🗞️ ขายข่าวลือ</b><button class="sysb" onclick="jNwsSell()" ${J.slY===S.age?'disabled style="opacity:.45"':''}>${J.slY===S.age?'ปีนี้ขายแล้ว':'ขาย'}</button></div><p class="tag2">ปีละครั้ง · ได้เงินตามความน่าเชื่อถือ${J.lv>=2?' (ขั้น 3 ได้เพิ่ม)':''}</p></div>${(J.hist||[]).length?`<div class="item"><b>📜 ทำเนียบที่คุณออกล่าสุด</b><ul class="jrank tag2" style="margin:4px 0;padding-left:18px">${J.hist.slice().reverse().map(h=>`<li>${h.map((n,i)=>['🥇','🥈','🥉'][i]+' '+esc(n)).join(' · ')}</li>`).join('')}</ul></div>`:''}`}
