function ymRule(d){const k=+(d.st&&d.st.karma)||0,kl=+(d.st&&d.st.kills)||0;return k<=-80?0:k>=150?3:kl>=40&&k<0?2:1}
async function jYmaUI(id){const J=jInit(),c=jcGet(id);if(!c)return openJob();if(!c.d){modal(`${jBk}<h3>👻 วิญญาณกำลังเดินมาตามสะพาน…</h3>`,'job');let d=null,lid='';
  try{const L=(await nwsPool()).filter(e=>e.lid&&e.pub&&!(J.done||[]).includes(e.lid));for(const e of L.sort(()=>Math.random()-.5).slice(0,4)){try{const j=await api('lifeview&l='+encodeURIComponent(e.lid));if(j&&j.d){d=j.d;lid=e.lid;break}}catch(x){}}}catch(e){}
  const cc=jcGet(id);if(!cc)return;if(!d){const k=R(-200,300);d={n:anyName(ch(['ชาย','หญิง'])),age:R(20,90),cause:ch(['ป่วยตายในฤดูหนาว','ถูกลอบฆ่า','จากไปอย่างสงบ']),r:ch(REALMS).n,st:{karma:k,kills:R(0,80),fame:R(0,900)},key:['ลืมตาดูโลกในหมู่บ้านเล็ก',k>0?'ช่วยเหลือชาวบ้านจากโจร':'ปล้นคาราวานเกลือ','แต่งงานและมีลูกสามคน']}}cc.d={n:d.n,age:d.age,cause:d.cause,r:d.r,st:d.st||{},key:(d.key||[]).slice(),ach:(d.ach||[]).length};cc.lid=lid;}
 const C=jcGet(id);if(!C)return;const d=C.d,K=d.key.length>8?[d.key[0]].concat(d.key.slice(1,-1).sort(()=>Math.random()-.5).slice(0,J.lv>=1?7:4)).concat([d.key[d.key.length-1]]):d.key;
 modal(`${jBk}<h3>👻 วิญญาณของ ${esc(d.n)}</h3><p class="tag2">${C.lid?'🌐 ชีวิตจริงของผู้เล่นคนหนึ่ง':'วิญญาณนิรนาม'} · อายุ ${d.age} ปี · ${esc(d.r||'')} · 🪦 ${esc(d.cause||'')}</p>
 <div class="specgrid"><div>☯️ กรรม <b>${specN(d.st.karma)}</b></div><div>⚔️ ฆ่า/ชนะศึก <b>${fmt(d.st.kills||0)}</b></div><div>⭐ ชื่อเสียง <b>${fmt(d.st.fame||0)}</b></div><div>🏆 ความสำเร็จ <b>${d.ach||0}</b></div></div>
 <div class="item tag2" style="max-height:170px;overflow:auto;margin-top:6px">${K.map(x=>`<div>• ${esc(x)}</div>`).join('')}</div>
 <div class="mgrid" style="margin-top:6px">${YM_V.map((v,k)=>`<button class="opt" onclick="jYma('${id}',${k})">${v[0]} ${v[1]}</button>`).join('')}</div>`,'job')}
async function jYma(id,v){const J=jInit(),c=jcGet(id);if(!c||!c.d||jYma._b)return;jYma._b=1;let prev=null;try{if(c.lid&&onlineOK){const r=await api('yvote',{lid:c.lid,v});if(r&&r.ok)prev=r.prev}}catch(e){}jYma._b=0;if(!jcGet(id))return;jcDel(id);J.done=(J.done||[]).concat(c.lid?[c.lid]:[]).slice(-60);
 const tot=prev?prev.reduce((a,b)=>a+b,0):0;let right,how;if(tot>=3){const mx=Math.max(...prev);right=prev[v]===mx;how=`ยมบาลคนอื่นตัดสินไว้: ${YM_V.map((x,k)=>x[0]+' '+prev[k]).join(' · ')}`}else{const r=ymRule(c.d);right=r===v;how=`ตามบัญชีกรรม วิญญาณนี้ควร${YM_V[r][1]}`}
 const g=right?Math.round(jbPay(J,700)*(J.lv>=2?1.5:1)):0;if(right){S.money+=g;J.st.earn+=g;J.st.ok++;jXp(J,1);jRp(J,4);S.karma+=2}else{J.st.bad++;jRp(J,-5)}
 const t=`คุณตัดสินให้ ${esc(c.d.n)} ${YM_V[v][0]} ${YM_V[v][1]} — ${right?`ตรงกับความเห็นส่วนใหญ่ ได้ ${ftMf(g)} · กรรม +2`:'ไม่ตรงกับความเห็นส่วนใหญ่ หอพิพากษาตั้งคำถามกับคุณ'}<br><span class="tag2">${how}</span>`;log('⚖️ '+t.replace(/<br>[\s\S]*/,''),right?'good':'bad');jResult(t,right)}

