{const _oj=jOpen;jOpen=function(i){const J=jInit(),c=J&&J.q[i];if(c){if(!c.id)c.id=jId();const f={pla:jPlaUI,rev:jRevUI,rgb:jRgbUI,crt:jCrtUI,asn:jAsnUI,ahn:jAhnUI,nws:jNwsUI,rlc:jRlcUI,brd:jBrdUI,yma:jYmaUI,fat:jFatUI}[c.k];if(f){jOpen._c=c;return f(c.id)}}return _oj.apply(this,arguments)}}
