// ===================== v17.14 🩸 มารข้ามภพ: บารมีมาร · ทัณฑ์โลหิต · ศึกธรรม-มาร · นิกายของตัวเอง · เทพนอกรีต & แดนอสูร · กลืนกัลป์ · ทำเนียบมาร =====================
const DM_T=[[0,'',''],[100,'ผู้ฝึกสายมาร','#b06a6a'],[300,'มารร้าย','#d84a4a'],[800,'จอมมาร','#ff3a3a'],[2000,'มารสวรรค์','#ff2a6a'],[5000,'มารบรรพกาล','#c02aff']];
const mpOf=()=>S&&S.mp?S.mp:0;
function dmTi(v){v=v==null?mpOf():v;let i=0;DM_T.forEach((t,k)=>{if(v>=t[0])i=k});return i}
const dmIs=n=>mpOf()>=(n||300);
function mpAdd(v,why){if(!S||!v)return;const a=dmTi();S.mp=Math.max(0,Math.round((S.mp||0)+v));const b=dmTi();if(b>a){log(`🩸 <b>บารมีมารพุ่งถึงขั้น「${DM_T[b][1]}」</b>${why?' — '+why:''} · ผู้คนเริ่มกระซิบชื่อคุณด้วยความหวาดกลัว`,'myth',true);try{keyAdd('บารมีมารถึงขั้น'+DM_T[b][1])}catch(e){}S.fame+=50*b}}
(()=>{const st=document.createElement('style');st.textContent=`.dmb{cursor:pointer;background:#2a0a10;color:#ff8a9a;border:1px solid #c83a4a;border-radius:8px;padding:0 6px;font-size:.85em;font-weight:700;margin-left:4px}.dmb.hi{animation:dmP 1.6s ease-in-out infinite;background:linear-gradient(90deg,#3a0610,#6a0a2a,#3a0610);background-size:200% 100%}@keyframes dmP{0%,100%{box-shadow:0 0 0 #ff2a5a00;background-position:0 0}50%{box-shadow:0 0 10px #ff2a5aaa;background-position:100% 0}}
.dmbox{background:radial-gradient(circle at 50% 0,#4a0a1a,#1a0408 70%);color:#ffd8de;border-radius:14px;padding:12px;margin:-4px -4px 8px;border:1px solid #8a1a2a}.dmbox h3{color:#ff6a7a;margin:0 0 2px}.dmbar{height:9px;border-radius:5px;background:#ffffff14;overflow:hidden;margin:6px 0 2px}.dmbar i{display:block;height:100%;background:linear-gradient(90deg,#8a0a1a,#ff2a4a,#ff9aa8)}
.dmsec{border:1px solid #6a1a2a;border-radius:10px;padding:8px 10px;margin:6px 0;background:#24070d;color:#ffdce1}.dmsec b{color:#ff9aa8}.dmsec .tag2,.dmsec li{color:#f0c0c8!important;opacity:1}.dmsec .pbtn{font-size:13px;padding:8px 6px;line-height:1.3}.dmsec .sysb{flex:0 0 auto}.dmrk li{margin:2px 0}.dmland{display:grid;grid-template-columns:repeat(3,1fr);gap:4px;margin:6px 0}.dmland span{border-radius:7px;padding:5px 2px;text-align:center;font-size:11px;border:1px solid #6a4a7a;background:#1a1028;color:#d8c8f0}.dmland span.on{background:linear-gradient(180deg,#6a0a2a,#2a0410);border-color:#ff4a6a;color:#ffd0d8}`;document.head.appendChild(st)})();

// ---------- สะสมบารมีมารรายปี ----------
{const _pyDm=passYear;passYear=function(){const a0=S?S.age:0,k0=S?S.kills||0:0;const r=_pyDm.apply(this,arguments);try{if(!S||!S.alive)return r;const dy=Math.max(1,Math.min(10,S.age-a0));let g=0;
 if(S.faction&&S.faction.t==='มาร')g+=3*dy*(1+(S.rank||0)*.2);if((S.karma||0)<0)g+=Math.min(10,-S.karma/150)*dy;g+=Math.min(50,Math.max(0,(S.kills||0)-k0)*.3);if(S.dsect)g+=S.dsect.lv*dy;
 if(S.wWar&&S.age<S.wWar.until&&S.wWar.w==='d'&&dmIs())g+=2*dy;if(g>0)mpAdd(g);
 if(S.dsect)dmSectYear(dy);dmYearEv();if(S.age-(S._dmPost||0)>=10&&mpOf()>=100){S._dmPost=S.age;dmPost()}}catch(e){console.error(e)}return r}}
function dmYearEv(){if(choice._cur)return;const X=S.xian&&!S.xt,G=S.xt;
 if(X&&dmIs(300)&&!(S.faction&&S.faction.t==='มาร')&&!S.dsect&&S.age-(S.dmInv||-999)>=60&&Math.random()<.25){S.dmInv=S.age;return wpWait(dmInvite)}
 if(X&&S.age-(S.dmW==null?S.age-150:S.dmW)>=300&&realmIdx()>=2&&Math.random()<.2){S.dmW=S.age;return wpWait(dmWar)}
 if(S.dmW==null&&X)S.dmW=S.age-150;
 if(S.wWar&&S.age<S.wWar.until&&S.wWar.w==='r'&&dmIs()&&Math.random()<.1)return wpWait(()=>dmHunt('นักล่ามารจากสำนักธรรมะที่ชนะศึก'));
 if(G&&S.asr&&S.asr.lands>0&&Math.random()<.05*S.asr.lands)return wpWait(dmHeaven);}
{const _rdDm=render;render=function(){const r=_rdDm.apply(this,arguments);try{const g=$('gRealm');if(g&&S&&mpOf()>=100&&!g.querySelector('.dmb')){const i=dmTi();g.insertAdjacentHTML('beforeend',`<span class="dmb ${i>=3?'hi':''}" onclick="event.stopPropagation();openDm()">🩸 ${DM_T[i][1]}</span>`)}}catch(e){}return r}}
{const _omDm=openMenu;openMenu=function(){const r=_omDm.apply(this,arguments);try{if(S&&mpOf()>=100){const g=$('modal').querySelector('.mgrid');if(g&&!g.querySelector('.dmMB'))g.insertAdjacentHTML('afterbegin',`<button class="opt dmMB" onclick="openDm()">🩸 วิถีมาร<small>${DM_T[dmTi()][1]} · บารมี ${fmt(mpOf())}</small></button>`)}}catch(e){}return r}}

// ---------- 1) ทัณฑ์โลหิต: สายมารขึ้นสวรรค์ต้องเจอเงาของคนที่ตัวเองฆ่า ----------
{const _awDm=ascendWave;ascendWave=function(n){if(n===1&&S&&dmIs(300)&&!S.xt&&S._bt!==S.age){S._bt=S.age;const self=this,args=arguments,ep=Math.round(total()*(1.1+dmTi()*.05));
  return choice('🩸 ทัณฑ์โลหิต',`เมฆทัณฑ์เปลี่ยนเป็นสีเลือด แทนที่อัสนีจะผ่าลงมา <b>เงาของทุกคนที่คุณเคยฆ่า</b>ก้าวออกจากเมฆ รวมร่างเป็นยักษ์โลหิตตนเดียว<br><span class="tag2">ฟ้าไม่ยอมให้มารผ่านง่ายๆ · บารมีมาร ${fmt(mpOf())}</span>`,[
   {t:'⚔️ บดขยี้เงาโลหิต',s:`ดวล (แรง ${fmt(ep)}) · ชนะ = ได้แก่นมาร พลังยุทธ์ +8% แล้วฝ่าทัณฑ์ต่อ`,f(){setTimeout(()=>duel('ยักษ์โลหิตแห่งกรรม',ep,w=>{if(w){S.mpk=(S.mpk|0)+1;S.power+=pctPow(.08);mpAdd(80,'กลืนเงาโลหิตของตัวเอง');log('🩸 คุณขย้ำเงาโลหิตจนแหลก แล้วดูดมันเข้าไปเป็น<b>แก่นมาร</b> พลังยุทธ์ +8%','myth',true)}else{S.hp=Math.max(1,Math.round(S.hp-S.maxHp*.5));log('🩸 เงาโลหิตฉีกร่างคุณจนเลือดท่วม พลังชีวิต −50% แต่ทัณฑ์ยังต้องดำเนินต่อ','bad',true)}setTimeout(()=>_awDm.apply(self,args),400)}),300)}},
   {t:'🙏 สารภาพบาปต่อฟ้า',s:'บารมีมาร −40% · กรรม +30 · ทัณฑ์กลับเป็นแบบปกติ',f(){S.mp=Math.round(mpOf()*.6);S.karma+=30;log('🙏 คุณคุกเข่ากลางเมฆโลหิต เมฆค่อยๆ กลับเป็นสีเทา','epic');setTimeout(()=>_awDm.apply(self,args),300)}}])}
 return _awDm.apply(this,arguments)}}

// ---------- 2) โลกเซียน: คำเชิญจากนิกายมาร · ตั้งนิกายเอง ----------
function dmFacs(){return(FACTIONS||[]).filter(f=>f.t==='มาร'&&f.tier!=='เล็ก')}
function dmInvite(){const F=dmFacs();const f=F.length?ch(F):null;choice('🩸 ทูตจากนิกายมาร',`ชายสวมหน้ากากกระดูกยื่นป้ายหยกสีดำให้ "กลิ่นเลือดของท่านหอมไปถึงวังของเรา ${f?esc(xT?xT(f.n):f.n):'นิกายของเรา'}ยินดีต้อนรับ สำนักธรรมะไม่มีวันยอมรับคนอย่างท่านหรอก"`,[
 ...(f?[{t:`🏯 เข้า${xT?xT(f.n):f.n}`,s:`${f.d||''} · บารมีมารเพิ่มทุกปี`,f(){S.faction=f;S.rank=0;mpAdd(30);log(`🩸 คุณสวมป้ายหยกดำ เป็นศิษย์${xT?xT(f.n):f.n}แล้ว`,'epic',true)}}]:[]),
 ...(mpOf()>=800?[{t:'👑 ข้าจะตั้งนิกายของข้าเอง',s:'เปิดนิกายมารของตัวเอง รับสาวก ขยายอาณาเขต',f(){dmSectFound()}}]:[]),
 {t:'✋ ไม่สนใจ',s:'ทูตหัวเราะแล้วหายไปในหมอก',skip:true,f(){log('ทูตนิกายมารหัวเราะเยาะ "สักวันท่านจะกลับมาหาเรา"')}}])}
const DS_N1=['โลหิต','อเวจี','กระดูก','เงาจันทร์','หมื่นวิญญาณ','เก้าอเวจี','ดอกบัวดำ','พันพิษ'],DS_LV=['ถ้ำมาร','นิกายมาร','วังมาร','อาณาจักรมาร','ดินแดนมารสวรรค์'];
function dmSectFound(){S.dsect={n:'นิกาย'+ch(DS_N1),lv:0,mem:20,y:S.age};S.faction=null;mpAdd(100,'ตั้งนิกายของตัวเอง');try{keyAdd('ก่อตั้ง'+S.dsect.n)}catch(e){}log(`👑 คุณปักธงดำบนยอดเขา <b>${S.dsect.n}</b> ถือกำเนิด สาวกกลุ่มแรก 20 คน`,'myth',true);render()}
function dmSectYear(dy){const D=S.dsect;D.mem=Math.round(D.mem*(1+.04*dy)+mpOf()/400*dy);const nl=D.mem>=20000?4:D.mem>=4000?3:D.mem>=800?2:D.mem>=150?1:0;if(nl>D.lv){D.lv=nl;log(`👑 ${D.n}เติบโตเป็น<b>${DS_LV[nl]}</b> — สาวก ${fmt(D.mem)} คน`,'myth',true);S.power+=pctPow(.03*nl)}
 const g=Math.round(D.mem*2*W15()*dy/10);if(g){S.money+=g}S.fame+=D.lv*2*dy}

// ---------- ศึกธรรมะ-มาร (โลกเซียน ทุก ~300 ปี) ----------
const WAR_B=[['🗡️ ยุทธการเชิงเขาหมื่นกระบี่','ทัพสองฝ่ายปะทะกันกลางหุบเขา'],['🌊 ศึกริมทะเลสาบหยก','ยอดฝีมือของอีกฝ่ายยืนขวางทางข้ามทะเลสาบ'],['🔥 ล้อมวังของอีกฝ่าย','ศึกตัดสินชี้ชะตาโลกเซียนไปอีกสองร้อยปี']];
function dmWar(){const d=dmIs(300);choice('⚔️ ศึกธรรมะ-มารครั้งใหญ่',`ห้าร้อยสำนักธรรมะกับนิกายมารทั้งหมดประกาศสงคราม ฝ่ายที่ชนะจะกำหนดหน้าตาของโลกเซียนไปอีก 200 ปี<br><span class="tag2">ถ้ามารชนะ: โลกมืดลง ผู้คุมกฎลงมาบ่อย สายมารรุ่งเรือง · ถ้าธรรมะชนะ: สายมารถูกไล่ล่า</span>`,[
 {t:'☯️ ร่วมรบฝ่ายธรรมะ',s:d?'บารมีมารคุณสูง ฝ่ายธรรมะไม่ไว้ใจ (เสี่ยงถูกหักหลัง)':'กรรมดี · ชื่อเสียงถ้าชนะ',f(){dmWarRound('r',0,0)}},
 {t:'🩸 ร่วมรบฝ่ายมาร',s:'บารมีมาร +' + (d?'มาก':'') + ' · กรรมลด',f(){dmWarRound('d',0,0)}},
 {t:'🌫️ วางตัวเป็นกลาง',s:'ปลอดภัย ไม่มีส่วนในผลลัพธ์',skip:true,f(){const w=Math.random()<.5?'d':'r';S.wWar={w,until:S.age+200,me:''};log(`⚔️ ศึกจบลงโดยไม่มีคุณ ฝ่าย${w==='d'?'มาร':'ธรรมะ'}ชนะ`,'')}}])}
function dmWarRound(side,k,ok){const B=WAR_B[k],ep=Math.round(total()*(1.0+k*.15)*(.9+Math.random()*.2)),p1=clamp(.45+Math.min(.2,(S.int||0)/3000)+(side==='d'?Math.min(.15,mpOf()/20000):Math.min(.15,Math.max(0,S.karma)/2000)),.15,.85);
 const next=(win)=>{const o=ok+(win?1:0);if(k<2)return setTimeout(()=>dmWarRound(side,k+1,o),300);dmWarEnd(side,o>=2)};
 setTimeout(()=>choice(`${B[0]} · ${k+1}/3`,`${B[1]}<br><span class="tag2">ชนะแล้ว ${ok}/${k} · ชนะ 2 ใน 3 ฝ่ายคุณชนะสงคราม</span>`,[
  {t:'⚔️ ดวลแม่ทัพฝ่ายตรงข้าม',s:`ดวลจริง (แรง ${fmt(ep)})`,f(){setTimeout(()=>duel(side==='d'?'แม่ทัพสำนักธรรมะ':'แม่ทัพนิกายมาร',ep,w=>{if(w)S.fame+=60;else S.hp=Math.max(1,Math.round(S.hp-S.maxHp*.3));next(w)}),300)}},
  {t:'📜 วางกลยุทธ์ซุ่มโจมตี',s:`~${Math.round(p1*100)}% · ปัญญาและบารมีฝ่ายช่วย`,f(){const w=Math.random()<p1;log(`${B[0]} — ซุ่มโจมตี${w?'สำเร็จ ทัพศัตรูแตกพ่าย':'ถูกจับได้ ทัพคุณเสียหายหนัก'}`,w?'epic':'bad');if(!w)S.hp=Math.max(1,Math.round(S.hp-S.maxHp*.2));next(w)}},
  ...(side==='d'&&dmIs(800)?[{t:'🩸 ปลดปล่อยมหาวิชามาร',s:'~75% · กรรม −40 · กลืนศพทหารเพิ่มบารมี',f(){const w=Math.random()<.75;S.karma-=40;if(w)mpAdd(60);log(`${B[0]} — คลื่นโลหิตกวาดสนามรบ${w?' ทัพธรรมะล้มเป็นใบไม้ร่วง':' แต่ยอดฝีมือฝ่ายธรรมะผนึกไว้ได้'}`,w?'myth':'bad');next(w)}}]:[])]),200)}
function dmWarEnd(side,win){const w=win?side:side==='d'?'r':'d';S.wWar={w,until:S.age+200,me:side};
 if(side==='r'&&dmIs(300)&&Math.random()<.4){S.wWar.w='d';log('🗡️ <b>คุณถูกหักหลัง!</b> แม่ทัพฝ่ายธรรมะสั่งยิงธนูใส่หลังคุณกลางสนามรบ "คนมีกลิ่นมารอย่างเจ้าไว้ใจไม่ได้" ทัพธรรมะแตกพ่าย','bad',true);S.hp=Math.max(1,Math.round(S.hp-S.maxHp*.4));mpAdd(150,'ความแค้นจากการถูกหักหลัง');return}
 if(win){S.fame+=500;S.power+=pctPow(.05);if(side==='d'){mpAdd(400,'นำทัพมารพิชิตโลกเซียน');S.karma-=60}else{S.karma+=80}try{keyAdd(side==='d'?'นำทัพมารชนะศึกธรรมะ-มาร':'ปกป้องโลกเซียนในศึกธรรมะ-มาร')}catch(e){}
  log(`⚔️ <b>ฝ่าย${side==='d'?'มาร':'ธรรมะ'}ชนะสงคราม!</b> ${side==='d'?'ท้องฟ้าโลกเซียนกลายเป็นสีหม่น 200 ปีต่อจากนี้คือยุคของมาร':'แสงทองกลับมาส่องโลกเซียน นิกายมารแตกกระสานซ่านเซ็น'} · ชื่อเสียง +500 · พลังยุทธ์ +5%`,'myth',true)}
 else{log(`⚔️ ฝ่ายคุณแพ้สงคราม ${w==='d'?'ยุคมืดของมารเริ่มขึ้น':'สายมารถูกไล่ล่าไปทั่วโลกเซียน'} 200 ปี`,'bad',true)}}
function dmHunt(who){const ep=Math.round(total()*(1+dmTi()*.06));choice('🗡️ นักล่ามาร',`${who}ล้อมคุณไว้ "มารร้ายอย่างเจ้า วันนี้ต้องตาย"`,[{t:'⚔️ สู้',s:`ดวล (แรง ${fmt(ep)})`,f(){setTimeout(()=>duel(who,ep,w=>{if(w){mpAdd(40);S.fame+=30;log('🩸 คุณสังหารนักล่ามารทั้งกลุ่ม หัวของพวกมันถูกแขวนหน้าเมือง','epic')}else{S.hp=Math.max(1,Math.round(S.hp-S.maxHp*.45));log('🗡️ นักล่ามารฟันคุณสาหัส คุณหนีรอดมาได้หวุดหวิด','bad')}}),300)}},{t:'🌫️ หนี',s:'บารมีมาร −5% · ปลอดภัย',skip:true,f(){S.mp=Math.round(mpOf()*.95);log('🌫️ คุณสลายร่างเป็นหมอกเลือดหนีไป')}}])}

// ---------- วิชาเฉพาะสายมาร: ยาโลหิต · ดูดพลังศิษย์ · กลืนผู้บังคับใช้กฎ ----------
{const _dlDm=duel;duel=function(name,ep,cb){return _dlDm.call(this,name,ep,function(w){try{if(w&&S&&dmIs(300)&&!/ยักษ์โลหิต/.test(name)&&Math.random()<.3){S.bp=Math.min(20,(S.bp|0)+1);log(`🩸 คุณกรีดเลือดของ${esc(name)}เก็บไว้หลอม ได้<b>ยาโลหิต</b> 1 เม็ด (มี ${S.bp})`,'')}}catch(e){}return cb&&cb.apply(this,arguments)})}}
function dmPill(){if(!(S.bp>0))return;S.bp--;const g=pctPow(.02);S.power+=g;S.karma-=5;mpAdd(10);log(`🩸 กลืนยาโลหิต พลังยุทธ์ +${fmt(g)} · กรรม −5`,'epic');openDm()}
function dmDrain(k){const J=S.job;if(!J||J.t!=='dojo'||!(J.stu||[])[k])return;const s=J.stu[k];modal(`<h3>🧛 ดูดพลังศิษย์?</h3><p><b>${esc(s.n)}</b> ${jStars(s.tal)} มองคุณด้วยความเชื่อใจ ไม่รู้ว่าอาจารย์กำลังคิดอะไร</p><div class="brow"><button class="pbtn" style="flex:1;background:#8a1a2a" onclick="dmDrainGo(${k})">🩸 ดูด</button><button class="gbtn" style="flex:1" onclick="openDm()">ไม่ทำ</button></div>`,'dm')}
function dmDrainGo(k){const J=S.job,s=J&&(J.stu||[])[k];if(!s)return openDm();J.stu.splice(k,1);const g=pctPow(.02*s.tal);S.power+=g;S.karma-=20;mpAdd(50,'ดูดพลังศิษย์ตัวเอง');J.rep=Math.max(0,(J.rep==null?50:J.rep)-30);(J.stu||[]).forEach(x=>x.mood=Math.max(0,x.mood-25));log(`🧛 ร่างของ<b>${esc(s.n)}</b>เหี่ยวแห้งเหลือแต่หนังหุ้มกระดูก พลังยุทธ์ +${fmt(g)} · กรรม −20 · ศิษย์คนอื่นเริ่มหวาดกลัว (ความน่าเชื่อถือ −30)`,'bad',true);openDm()}
{const _tkDm=wpTick;wpTick=function(st){const v0=S&&S.wp?S.wp.v:null;const r=_tkDm.apply(this,arguments);try{if(S&&S.wp&&v0!=null&&dmIs(300)&&S.wp.v>v0&&!S.wp.seal)S.wp.v=Math.min(100,S.wp.v+(S.wp.v-v0)*.5);if(S&&S.wp&&S.wWar&&S.age<S.wWar.until&&S.wWar.w==='d'&&S.wp.v>(v0||0))S.wp.v=Math.min(100,S.wp.v+.05*(st||1))}catch(e){}return r}}
{const _weDm=wpEnforcer;wpEnforcer=function(){const r=_weDm.apply(this,arguments);try{if(dmIs(300)&&choice._cur&&/ผู้บังคับใช้กฎ/.test(choice._cur.title)){const P=S.wp,ep=Math.round(total()*1.4);choice._cur.opts.splice(1,0,{t:'👹 กลืนกินผู้บังคับใช้กฎ',s:`ดวลหนักกว่าเดิม (แรง ${fmt(ep)}) · ชนะ = พลังยุทธ์ +10% บารมีมารพุ่ง แต่แรงกดดันไม่ลด`,_x:1,noFate:1,f(){setTimeout(()=>duel('ผู้บังคับใช้กฎ',ep,w=>{if(w){const g=pctPow(.1);S.power+=g;mpAdd(200,'กลืนผู้บังคับใช้กฎทั้งตัว');P.v=Math.min(100,P.v+5);S.flags.dmEatE=1;log(`👹 คุณกลืนผู้บังคับใช้กฎทั้งร่าง แสงศักดิ์สิทธิ์ของมันกลายเป็นพลังมาร พลังยุทธ์ +${fmt(g)} · แต่ฟ้าโกรธจัด แรงกดดัน +5%`,'myth',true)}else{P.fail=(P.fail||0)+1;S.hp=Math.max(1,Math.round(S.hp-S.maxHp*.6));log(`⚖️ ผู้บังคับใช้กฎรอดจากเขี้ยวมารคุณ แพ้แล้ว ${P.fail}/3`,'bad',true);if(P.fail>=3){S.deathCause='ถูกผู้บังคับใช้กฎลบออกจากโลกขณะพยายามกลืนกินมัน';S.hp=0;try{checkDeath()}catch(e){}}}try{render()}catch(e){}}),300)}});choiceShow()}}catch(e){console.error(e)}return r}}

// ---------- 3) แดนเทพ: เทพนอกรีต · แดนอสูร ----------
const ASR_L=['แคว้นเมฆาใต้','ทุ่งดาวตก','ป้อมประตูทิศตะวันตก','ทะเลสาบสวรรค์','หุบเขาฟีนิกซ์','เมืองหลวงชั้นนอก','หอดาราจักร','ประตูสวรรค์ชั้นใน','บัลลังก์จักรพรรดิสวรรค์'];
{const _agDm=ascendGod;ascendGod=function(){const r=_agDm.apply(this,arguments);try{if(dmIs(800)){S.flags.heretic=1;S.asr={army:Math.round(mpOf()/10),lands:0,y:-1};log('🩸 <b>สวรรค์ประทับตราคุณเป็น「เทพนอกรีต」</b> ราชสำนักสวรรค์ปิดประตูใส่ แต่ไกลออกไปทางทิศเหนือ มีเทพตกสวรรค์นับหมื่นรอคนนำทัพอยู่ใน<b>แดนอสูร</b>','myth',true)}}catch(e){}return r}}
