function dmRecruit(){const A=S.asr;if(!A||A.ry===S.age)return;const c=Math.round(800*W15());if(S.money<c)return toast('เงินไม่พอ');S.money-=c;A.ry=S.age;const g=Math.round(30+mpOf()/40+S.fame/3000);A.army+=g;log(`📯 เทพตกสวรรค์ ${fmt(g)} ตนมาสวามิภักดิ์ ทัพอสูร ${fmt(A.army)}`,'epic');openDm()}
function dmDef(i){return Math.round(120*Math.pow(1.75,i))}
function dmConquer(){const A=S.asr;if(!A||A.lands>=9||A.cy===S.age)return;if(choice._cur)return toast('ตัดสินใจเรื่องที่ค้างอยู่ก่อน');A.cy=S.age;const df=dmDef(A.lands),p=clamp(A.army/(A.army+df)+(S.int||0)/40000,.08,.92),nm=ASR_L[A.lands];closeM();
 choice(`👹 บุก${nm}`,`ทัพอสูร ${fmt(A.army)} ตน vs ทัพสวรรค์ ${fmt(df)} ตน<br><span class="tag2">ยึดได้ = พลังยุทธ์ +4% และบรรณาการทุกปี · แพ้ = ทัพเสีย 40%</span>`,[
  {t:'⚔️ นำทัพบุกเอง',s:`ดวลแม่ทัพเฝ้า${nm} แล้วทัพตามเข้าไป`,f(){setTimeout(()=>duel('แม่ทัพสวรรค์แห่ง'+nm,Math.round(total()*(.9+A.lands*.06)),w=>dmConqEnd(w&&Math.random()<Math.min(.95,p+.25))),300)}},
  {t:'🐺 ปล่อยทัพบุก',s:`~${Math.round(p*100)}%`,f(){dmConqEnd(Math.random()<p)}}])}
function dmConqEnd(w){const A=S.asr,nm=ASR_L[A.lands];if(w){A.lands++;const g=pctPow(.04);S.power+=g;mpAdd(150*A.lands,'ยึด'+nm);S.fame+=400;log(`👹 <b>ธงดำปักบน${nm}แล้ว!</b> (${A.lands}/9) · พลังยุทธ์ +${fmt(g)}`,'myth',true);
  if(A.lands>=9){try{keyAdd('ยึดบัลลังก์จักรพรรดิสวรรค์ จักรพรรดิแดนอสูร')}catch(e){}S.flags.asrKing=1;log('👑 <b>คุณนั่งลงบนบัลลังก์จักรพรรดิสวรรค์</b> ตั้งแต่วันนี้สวรรค์ทั้งเก้าชั้นขึ้นกับ「จักรพรรดิแดนอสูร」','myth',true)}}
 else{A.army=Math.round(A.army*.6);log(`👹 ทัพอสูรแตกพ่ายที่${nm} — เหลือ ${fmt(A.army)} ตน`,'bad',true)}render()}
function dmHeaven(){const A=S.asr;if(!A||!A.lands)return;const ep=Math.round(total()*(1+A.lands*.08));choice('☁️ ทัพปราบมารจากสวรรค์',`จักรพรรดิสวรรค์ส่งทัพเทพนับแสนมายึด${ASR_L[A.lands-1]}คืน`,[{t:'⚔️ ปะทะแม่ทัพสวรรค์',s:`ดวล (แรง ${fmt(ep)}) · แพ้ = เสียแคว้น`,f(){setTimeout(()=>duel('แม่ทัพปราบมาร',ep,w=>{if(w){mpAdd(80);S.fame+=200;log('☁️ ทัพปราบมารถอยกลับขึ้นฟ้า แคว้นคุณปลอดภัย','epic')}else{A.lands--;S.hp=Math.max(1,Math.round(S.hp-S.maxHp*.4));log(`☁️ สวรรค์ยึด${ASR_L[A.lands]}คืนไปได้ (${A.lands}/9)`,'bad',true)}}),300)}},{t:'🏳️ ยอมถอยออกจากแคว้น',s:'เสียแคว้นล่าสุด · ทัพไม่เสีย',skip:true,f(){A.lands--;log(`🏳️ คุณถอนทัพออกจาก${ASR_L[A.lands]}`,'bad')}}])}
{const _pyAs=passYear;passYear=function(){const a0=S?S.age:0;const r=_pyAs.apply(this,arguments);try{if(S&&S.alive&&S.asr&&S.asr.lands){const g=Math.round(S.asr.lands*300*W15()*Math.min(10,Math.max(1,S.age-a0)));S.money+=g}}catch(e){}return r}}

