{const _slDm=startLife;startLife=function(){const out=_slDm.apply(this,arguments);try{const L=LS.get('murim_kdev',null);if(S&&L&&L.n&&!S.beastMode){LS.set('murim_kdev',null);S.mp=Math.max(S.mp||0,500);S.talent=Object.assign({},S.talent,{m:+(S.talent.m*1.15).toFixed(2)});S.flags.kHeir=1;
 setTimeout(()=>{try{const a=newArt(3);a.n='คัมภีร์มารบรรพกาล';S.arts.push(a);log(`👁️‍🗨️ <b>ทารกคนนี้ลืมตาด้วยดวงตาสีม่วงเข้ม</b> ในฝันมีเสียงของ<b>${esc(L.n)}</b>ผู้กลืนกัลป์กระซิบอยู่ไม่หยุด · ได้ ${artHtml(a)} · พรสวรรค์ ×1.15 · บารมีมาร 500 ติดตัวตั้งแต่เกิด`,'myth',true);keyAdd('เกิดใหม่พร้อมเศษความทรงจำของมารบรรพกาล '+L.n)}catch(e){}},1600)}}catch(e){console.error(e)}return out}}

