const rdy=()=>{try{const h=typeof hl2==='function'?hl2():null;return !!(h&&S&&S.alive&&S.ch==='hell'&&h.lv<(h.ab?1000:100)&&(h.ab||h.lv>=18)&&S.age>=h.cd)}catch(e){return false}};
setInterval(()=>{try{const r=rdy();document.querySelectorAll('.hlb').forEach(b=>b.classList.toggle('rdy',r));
 if(!r)return;const h=hl2();if(h.autoCd===h.cd)return;if(h.ab&&S.flags&&S.flags.abAuto)return;if(choice._cur||modalOpen||(document.querySelector('.ov.show')||($('birth')&&$('birth').classList.contains('on'))))return;
 if(!S.age||S.age<16)return;h.autoCd=h.cd;(h.ab?openAbyss:openHell2)()}catch(e){}},1500);
