try{(()=>{
const NMS=new Set();let ownT=0;
const hit=s=>{for(const d of XDICT)if(s.includes(d[0]))return true;return false};
function add(s){if(typeof s!=='string'||s.length<2||s.length>40||NMS.has(s))return;if(hit(s)){if(NMS.size>300)NMS.clear();NMS.add(s)}}
function walk(o,d){if(!o||d>5)return;if(Array.isArray(o)){for(let i=0;i<o.length&&i<400;i++)walk(o[i],d+1);return}
 if(typeof o==='object')for(const k in o){const v=o[k];if(typeof v==='string'){if(k==='n'||k==='name'||k==='pn')add(v)}else if(v&&typeof v==='object')walk(v,d+1)}}
function own(){const t=Date.now();if(t-ownT<3000)return;ownT=t;try{add(LS.get('murim_pname',''));if(S&&S.name)add(S.name)}catch(e){}}
{const _x=xT;xT=function(t){if(typeof t!=='string')return _x(t);own();if(!NMS.size)return _x(t);
 const L=[...NMS].filter(n=>t.includes(n)).sort((a,b)=>b.length-a.length);if(!L.length)return _x(t);
 L.forEach((n,i)=>{t=t.split(n).join('\uE000'+i+'\uE001')});t=_x(t);L.forEach((n,i)=>{t=t.split('\uE000'+i+'\uE001').join(n)});return t}}
{const _j=Response.prototype.json;Response.prototype.json=function(){return _j.apply(this,arguments).then(j=>{try{walk(j,0)}catch(e){}return j})}}
})()}catch(e){console.error(e)}

