function card(k){const n=PK[k][1],t=T(),v=vget(),have=t===n,low=t===3&&n<3;
 const L={1:[F('dice','สุ่มเกิดได้ <b>30 ครั้ง</b>ต่อชีวิต'),F('dice','🔒 ตั๋วล็อกชะตา <b>2 ใบ</b> ทุกรอบ 30 วัน'),F('dice','🔒 ล็อกคำตอบ <b>5 ช่อง</b> ให้ชะตาเลือกคำตอบเดิมให้'),F('stamp','ตราประทับชาด <b>เส้นเดี่ยว</b>'),F('frame','กรอบอวตารเส้นเดี่ยวสีชาด'),F('lantern','ป้ายโคมหน้าชื่อในแชท'),F('tag','ฉายา เลือกจากชุดสำเร็จรูป 6 ชื่อ')],
  2:[F('dice','สุ่มเกิดได้ <b>60 ครั้ง</b>ต่อชีวิต'),F('dice','🔒 ตั๋วล็อกชะตา <b>6 ใบ</b> ทุกรอบ 30 วัน'),F('dice','🔒 ล็อกคำตอบ <b>10 ช่อง</b> ให้ชะตาเลือกคำตอบเดิมให้'),F('stamp','ตราประทับชาด <b>เส้นคู่</b>'),F('frame','กรอบอวตารเส้นคู่'),F('yin','แลกกรรมสุ่มได้วันละ <b>8 ครั้ง</b> (ปกติ 5)'),F('bolt','ปุ่ม <b>สุ่มรัว</b> ตั้งเงื่อนไขแล้วระบบสุ่มให้เอง'),F('tag','ฉายาเลือกจากชุดสำเร็จรูป')],
  3:[F('dice','สุ่มเกิดได้ <b>100 ครั้ง</b>ต่อชีวิต ตลอดไป'),F('dice','🔒 ตั๋วล็อกชะตา <b>10 ใบ</b>ทันที + <b>เดือนละ 5</b> ตลอดไป'),F('dice','🔒 ล็อกคำตอบ <b>20 ช่อง</b> ให้ชะตาเลือกคำตอบเดิมให้'),F('stamp','ตราทองแกะลาย พร้อม <b>เลขลำดับ</b> ซื้อซ้ำไม่ได้'),F('frame','กรอบขอบทองเส้นคู่ ประดับมุม'),F('plaque','ป้ายชื่อในหอผู้ก่อตั้ง · คำจารึก · จุดธูป'),F('tag','ฉายา <b>ตั้งเองได้</b> (20 ตัวอักษร)'),F('bolt','ทุกอย่างของผู้อาวุโส ตลอดไป')]}[n];
 const price=n===3?'ครั้งเดียว ตลอดไป':'/ 30 วัน',lbl=have&&n<3?`ต่ออายุ ${PK[k][0]} บาท · 30 วัน`:n===3?`ซื้อตลอดไป ${PK[k][0]} บาท`:`สมัคร ${PK[k][0]} บาท · 30 วัน`;
 const cmp=n===3?`<div class="vx-cmp"><div><span>30 วัน 99 × 6</span><i style="width:99%"></i><b>594</b></div><div><span>ตลอดไป</span><i style="width:100%" class="g"></i><b>599</b></div><p>จ่ายครั้งเดียว คุ้มตั้งแต่เดือนที่ 7 · ไม่ต้องต่ออายุอีก</p></div>`:'';
 const dis=(n===3&&t===3)||low;
 return`<div class="vx-card vk${n}${have?' on':''}${low?' dim':''}">${n===3?'<span class="vx-rib g">คุ้มสุด · ตลอดไป</span>':''}${have?'<span class="vx-rib o">ใช้อยู่</span>':''}
 <div class="vx-hd">${seal(n,'')}<div><div class="vx-nm">${NM[n]}</div><div class="vx-pr">${PK[k][0]} <small>บาท ${price}</small></div></div></div>
 <ul>${L.join('')}</ul>${cmp}<button class="vx-buy vk${n}" ${dis?'disabled':''} onclick="vipBuy('${k}')">${n===3&&t===3?'เป็นผู้ก่อตั้งแล้ว':low?'มีสิทธิ์ถาวรอยู่แล้ว':lbl}</button></div>`}
function ttHtml(){const t=T();if(!t)return'';const cur=TT.tt||'';
 const body=t===3?`<div class="vx-ttin"><input id="vipT" maxlength="20" placeholder="ตั้งฉายาคุณ (ไม่เกิน 20 ตัวอักษร)" value="${esc(cur)}"><button class="gbtn" onclick="vipTtl(document.getElementById('vipT').value)">บันทึก</button></div>`
  :`<div class="vx-tt">${(TT.ttl||[]).map(n=>`<button class="${n===cur?'on':''}" data-w="${esc(n)}" onclick="vipTtl(this.dataset.w)">${esc(n)}</button>`).join('')||'<small class="tag2">กำลังโหลด…</small>'}</div>`;
 return`<div class="vx-sec"><h4 class="vx-h4">ฉายาคุณ</h4><p class="tag2" style="margin:0 0 6px">${cur?'ตอนนี้: <b>'+esc(cur)+'</b> · ':''}แสดงข้างชื่อในแชท${t<3?' · กดซ้ำที่ชื่อเดิมเพื่อถอด':''}</p>${body}</div>`}
window.vipTtl=async function(w){w=String(w||'').trim();if(w&&w===TT.tt&&T()<3)w='';try{const j=await api('vipttl',{w});TT.tt=j.tt||'';try{LS.set('murim_vipt',TT)}catch(e){}toast(TT.tt?'ตั้งฉายาแล้ว':'ถอดฉายาแล้ว');if(inVip())vipMenu()}catch(e){toast(e.message==='preset'?'เลือกจากชุดที่มีให้':'บันทึกไม่สำเร็จ ลองใหม่อีกครั้ง')}};
window.vipMenu=function(){const t=T(),v=vget(),near=t&&t<3&&(endOf(v,t)-Date.now())<3*864e5,P=pend();
 const stat=t?`<div class="vx-stat">${seal(t,near?' fade':'')}<div><b>${NM[t]}</b><small>${t===3?(v.ul?`ลำดับที่ ${v.ul.o} · เข้าร่วม ${dTxt(v.ul.t)}`:'ตลอดไป'):`ถึง ${dTxt(endOf(v,t))} · อีก ${daysLeft(v,t)} วัน${near?' · ใกล้หมดอายุ':''}`}</small></div></div>`:'';
 const ins=t===3&&v.ul?`<div class="vx-sec"><h4 class="vx-h4">คำจารึกบนป้าย</h4><div class="vx-ttin"><input id="vipW" maxlength="40" placeholder="ข้อความสั้นๆ (ไม่เกิน 40 ตัวอักษร)" value="${esc(v.ul.w||'')}"><button class="gbtn" onclick="vipSay(this)">จารึก</button></div></div>`:'';
 modal(`<button class="xbtn" onclick="rrMenu()">✕</button><h3 class="vx-vip">ผู้สนับสนุน</h3>
 <div class="vx-free"><b>เล่นฟรีก็เล่นได้เหมือนกัน ไม่ต้องน้อยใจ</b><details><summary>อ่านรายละเอียด</summary><p>ผู้สนับสนุนไม่ได้พลัง เงิน หรือโบนัสในเกม ได้แค่สุ่มเกิดมากขึ้น กับตราประทับ กรอบ และฉายา ชีวิตทุกคนต้องเล่นเองทั้งชีวิตและแข่งทำเนียบด้วยกติกาเดียวกัน · สายฟรีสุ่มเกิดได้ 5 ครั้งต่อชีวิต และแลกกรรมเพิ่มได้ทุกวัน</p></details></div>
 ${stat}${P?tlHtml(P):''}${ins}${ttHtml()}
 ${card('v1')}${card('v2')}${card('v3')}
 <button class="vx-wallb" onclick="vipWall()">${ico('plaque')}<span>เข้าหอผู้ก่อตั้ง<small>ป้ายผู้ก่อตั้ง · อันดับผู้สนับสนุน (อยู่ในหน้าเดียวกัน)</small></span><span class="go">${ico('chev')}</span></button>
 <details class="vfp"><summary>เงื่อนไขการซื้อ</summary><p class="tag2">ไม่ต่ออายุเอง ไม่มีการตัดเงินอัตโนมัติ · ซื้อซ้ำก่อนหมดอายุจะต่อวันให้ · สิทธิ์ผูกกับบัญชี (ล็อกอิน Google ไว้จะไม่หายเวลาเปลี่ยนเครื่อง) · แนบสลิปแล้วระบบตรวจอัตโนมัติ สิทธิ์เข้าทันที (ถ้าตรวจอัตโนมัติไม่ได้ ผู้พัฒนาตรวจให้ ปกติไม่เกิน 1 วัน) · ถ้าเกิน 48 ชม. ยังไม่ได้ แจ้งบั๊กเพื่อขอคืนเงินได้ · สิทธิ์สุ่มที่ซื้อเป็นแพ็กไม่หายเมื่อ VIP หมดอายุ</p></details>`);
 if(!vipMenu._ld){vipMenu._ld=1;const a=JSON.stringify([vget(),TT]);vxFetch(false).catch(()=>{}).then(()=>{vipMenu._ld=0;if(inVip()&&a!==JSON.stringify([vget(),TT]))vipMenu()})}};

