const steps=()=>`<ol class="vx-st"><li><i>1</i>สแกนโอน</li><li><i>2</i>แนบสลิป</li><li><i>3</i>สิทธิ์เข้า</li></ol>`;
for(const f of ['vipBuy','rrBuy']){const o=window[f];if(typeof o!=='function')continue;window[f]=function(){const r=o.apply(this,arguments);try{const h=$('modal').querySelector('h3');if(h&&!$('modal').querySelector('.vx-st'))h.insertAdjacentHTML('afterend',steps())}catch(e){}return r}}
{const o=window.vipPaid;if(typeof o==='function')window.vipPaid=async function(btn,k){const r=await o.apply(this,arguments);try{if(/ส่งแล้ว/.test(btn.textContent))setPend({t:Date.now(),k})}catch(e){}return r}}
{const o=window.rrPaid;if(typeof o==='function')window.rrPaid=async function(btn,k){const r=await o.apply(this,arguments);try{if(/ส่งแล้ว/.test(btn.textContent)){const RR=window._RR||{};setPend({t:Date.now(),k:'',pk:k,n:(RR.pk&&RR.pk[k]&&RR.pk[k][1])||0,c0:RR.c||0})}}catch(e){}return r}}

// ---------- หน้าจอ "ได้รับแล้ว" ----------
window.vipCele=function(kind,n){const t=kind==='rr'?0:kind,v=vget();
 const conf=Array.from({length:22},(_,i)=>`<i style="--x:${Math.round(Math.random()*100)}%;--d:${(Math.random()*.8).toFixed(2)}s;--r:${Math.round(Math.random()*360)}deg;--c:${['#c9a24a','#f0dc9a','#b8372a','#fff'][i%4]}"></i>`).join('');
 const head=kind==='rr'?`สิทธิ์สุ่มเข้าแล้ว <b>+${n}</b> ครั้ง`:`ยินดีต้อนรับ <b>${NM[t]}</b>`;
 const det=kind==='rr'?'<li>สิทธิ์ไม่มีวันหมดอายุ เก็บไว้ใช้ได้ทุกชีวิต</li><li>ไปที่ 🎲 สุ่มเกิดเพิ่ม แล้วกด "ใช้ 1 ครั้ง"</li>'
  :t===3?`<li>เลขลำดับคุณ <b>${v&&v.ul?'№ '+v.ul.o:'ในหอผู้ก่อตั้ง'}</b> ซื้อซ้ำไม่ได้</li><li>สุ่มเกิด 100 ครั้งต่อชีวิต ตลอดไป</li><li>กรอบบรรพชนอยู่ในโปรไฟล์ · ตั้งฉายาและคำจารึกได้แล้ว</li>`
  :`<li>สุ่มเกิด ${t===2?60:30} ครั้งต่อชีวิต${v&&endOf(v,t)?' · ถึง '+dTxt(endOf(v,t)):''}</li><li>ตราประทับและกรอบ${t===2?'เส้นคู่':'เส้นเดี่ยว'}อยู่ในโปรไฟล์</li><li>เลือกฉายาได้ที่หน้านี้</li>`;
 modal(`<button class="xbtn" onclick="closeM()">✕</button><div class="vx-cele cc${t}"><div class="vx-conf">${conf}</div><div class="vx-rays"></div>
 <div class="vx-stamp">${kind==='rr'?`<span class="vx-dice">${ico('dice')}</span>`:seal(t,' big')}</div><p class="vx-th">ได้รับแล้ว ขอบคุณมากครับ</p><h3>${head}</h3><ul>${det}</ul>
 <button class="pbtn" style="width:100%" onclick="${kind==='rr'?'rrMenu()':'vipMenu()'}">${kind==='rr'?'ไปสุ่มเกิด':'ดูสิทธิ์ของฉัน'}</button></div>`);try{sfx('realm')}catch(e){}};
{const o=window.vipSet;if(typeof o==='function')window.vipSet=function(v){const old=T(),P=pend();const r=o.apply(this,arguments);try{if(P){const RR=window._RR||{},nw=T();
  if(P.k&&nw>=PK[P.k][1]&&old<PK[P.k][1]){setPend(null);setTimeout(()=>{if(!choice._cur)vipCele(PK[P.k][1])},400)}
  else if(!P.k&&RR.c!=null&&RR.c>(P.c0||0)){const n=RR.c-(P.c0||0);setPend(null);setTimeout(()=>{if(!choice._cur)vipCele('rr',n)},400)}}}catch(e){console.error(e)}return r}}
setTimeout(()=>{try{if(pend())vxFetch(false).catch(()=>{})}catch(e){}},4500);

