{const _dk=dkLeft;dkLeft=function(){let h=_dk.apply(this,arguments);try{const n=String(S&&S.age||0).length;if(n>=6)h=h.replace('<div class="dk-age px">',`<div class="dk-age px ${n>=9?'dkA3':n>=7?'dkA2':'dkA1'}">`)}catch(e){}return h}}
