const hsh=s=>{s=String(s||'');let h=7;for(let i=0;i<s.length;i++)h=(h*31+s.charCodeAt(i))>>>0;return h};
const CACHE={};
function pxiURL(kind,r,tint,seed){r=Math.max(0,Math.min(7,r|0));const ai=hsh(seed)%6,key=kind+'|'+r+'|'+(tint||'')+'|'+(tint?0:ai);if(CACHE[key])return CACHE[key];
 const A=ART[kind]||ART.box,cv=document.createElement('canvas');cv.width=cv.height=16;const ctx=cv.getContext('2d');const ramp=tint&&TINT[tint]?TINT[tint]:RAMP[r];
 const pal=Object.assign({},FIX,{m:ramp[0],l:ramp[1],d:ramp[2],a:tint&&TINT[tint]?ramp[0]:ACC[ai][0],A:tint&&TINT[tint]?ramp[2]:ACC[ai][1]});
 const grid=[];for(let y=0;y<16;y++){grid.push(new Array(16).fill(null))}
 A.forEach((row,y)=>{for(let x=0;x<14;x++){const ch=row[x];if(ch&&ch!=='.'&&pal[ch])grid[y+1][x+1]=pal[ch]}});
 const out='#1a1420';for(let y=0;y<16;y++)for(let x=0;x<16;x++){if(grid[y][x])continue;const n=[[0,1],[1,0],[0,-1],[-1,0]].some(([dx,dy])=>{const v=(grid[y+dy]||[])[x+dx];return v&&v!==out});if(n)grid[y][x]=out}
 for(let y=0;y<16;y++)for(let x=0;x<16;x++)if(grid[y][x]){ctx.fillStyle=grid[y][x];ctx.fillRect(x,y,1,1)}
 if(r>=4){ctx.fillStyle='#ffffff';ctx.fillRect(13,1,1,1);ctx.fillStyle='rgba(255,255,255,.6)';ctx.fillRect(12,1,1,1);ctx.fillRect(14,1,1,1);ctx.fillRect(13,0,1,1);ctx.fillRect(13,2,1,1)}
 return CACHE[key]=cv.toDataURL()}
window.pxi=function(kind,r,tint,seed,big){return`<span class="pxf r${r|0}${big?' big':''}"><img src="${pxiURL(kind,r,tint,seed)}" alt=""></span>`};
