const byKw=(n,d)=>{for(const [k,v] of KW)if(n.includes(k))return v;return d};
const CATD={w:'sword',a:'chestplate',p:'pill',k:'book',c:'pendant',t:'talisman',b:'pagoda',x:'box',f:'food',g:'box',e:'house',m:'ore',s:'horse'};
