function ecoIcon(it){let k;if(it.c==='m'&&MATK[it.mat])k=MATK[it.mat];else if(it.c==='b')k='pagoda';else if(it.c==='s')k=byKw(it.n,'horse');else if(it.c==='e')k='house';else k=byKw(it.n,CATD[it.c]||'box');
 if(it.c==='x')k=byKw(it.n,'box');if(it.c==='f'&&!['jug','bottle','drop','peach'].includes(k))k='food';if(it.c==='s'&&!['horse','donkey'].includes(k))k='horse';
 const tint=(it.c==='p'&&FXT[it.fx])?FXT[it.fx]:null;return[k,it.r|0,tint,it.n]}
const SHI={pill:['pill','orange'],heal:['vial','green'],qi:['pill','blue'],art:['chest'],life:['peach'],break:['pill','red'],revive:['card'],ticket:['ticket'],furnace:['cauldron'],body:['bottle','orange'],mask:['mask'],soulp:['pill','purple'],
 perfume:['vial','pink'],redline:['redline'],yinyang:['yinyang'],recruit:['sign'],deed:['scroll'],hammer:['hammer'],lure:['lure'],sand:['hourglass']};
let NM=null,NMw='';
function nameMap(){const w=typeof ECO_W==='function'&&S?ECO_W():'m';if(NM&&NMw===w)return NM;NMw=w;const M={};
 try{(ecoCat(w)||[]).forEach(it=>{M[it.n]=ecoIcon(it)})}catch(e){}
 try{Object.entries(BAGIT).forEach(([k,v])=>{const e=EMK[v.ic]||['box'];M[v.n]=[e[0],typeof bRar==='function'?bRar(k):1,e[1]||null,k]})}catch(e){}
 try{Object.entries(EQI).forEach(([k,v])=>{const e=EMK[v.ic]||[byKw(v.n,'ring')];let kk=e[0],tn=e[1]||null;if(v.s==='fit'){kk='robe'}if(v.s==='fw')kk=byKw(v.n,'sword');M[v.n]=[kk,Math.max(0,Math.min(7,(v.t|0)||(v.s==='fw'?2:1))),tn,k]})}catch(e){}
 try{Object.entries(GEAR).forEach(([slot,L])=>L.forEach((it,i)=>{const r=[0,1,2,4][i]|0;const kk=slot==='weapon'?byKw(it.n,'sword'):slot==='armor'?'chestplate':slot==='mount'?(it.n.startsWith('ลา')?'donkey':'horse'):'house';M[it.n]=[kk,r,slot==='armor'?['brown','gold','white'][i]:null,it.id]}))}catch(e){}
 try{SHOP.forEach(it=>{const e=SHI[it.id]||[byKw(it.n,'box')];M[it.n]=[e[0],it.c<30?1:it.c<60?2:it.c<100?3:4,e[1]||null,it.id]})}catch(e){}
 NM=M;NM._k=Object.keys(M).filter(k=>k.length>=3).sort((a,b)=>b.length-a.length);return NM}
const EMRE=new RegExp('^\\s*('+Object.keys(EMK).map(e=>e.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')\\uFE0F?\\s*');
function deco(root){if(!root)return;const M=nameMap();const els=[];root.querySelectorAll('.item .h').forEach(h=>{const x=h.querySelector('b');if(x)els.push(x)});root.querySelectorAll('.sysq b, .eqs > b').forEach(x=>els.push(x));els.forEach(el=>{if(el.dataset.px||el.querySelector('.pxf'))return;el.dataset.px=1;const t=el.textContent.trim();if(!t||t.startsWith('—'))return;
  let hit=null;for(const k of M._k){if(t.includes(k)){hit=M[k];break}}
  const em=t.match(EMRE);if(!hit&&em&&EMK[em[1]]){const e=EMK[em[1]];hit=[e[0],1,e[1]||null,t]}if(!hit){const rt=el.querySelector('.rtag')||(el.parentNode&&el.parentNode.querySelector('.rtag'));const mm=rt&&String(rt.className).match(/rar(\d)/);if(mm){const k=byKw(t,null);if(k)hit=[k,+mm[1],null,t]}}if(!hit)return;
  const ic=pxi(hit[0],hit[1],hit[2],hit[3]);const ps=el.previousSibling;if(ps&&ps.nodeType===3&&EMRE.test(ps.textContent.trim()+' ')){ps.textContent=ps.textContent.replace(EMRE,'');el.insertAdjacentHTML('beforebegin',ic)}else{const h=el.innerHTML,m2=h.match(EMRE);el.innerHTML=m2?ic+h.slice(m2[0].length):ic+h;el.classList.add('pxrow')}})}
window.pxDeco=deco;
