try{const m=$('modal');if(m)new MutationObserver(()=>{if(!pxQ){pxQ=1;requestAnimationFrame(pxRun)}}).observe(m,{childList:true,subtree:true})}catch(e){}
const _md=modal;modal=function(){const r=_md.apply(this,arguments);pxRun();return r};
