EV.a2=()=>{const s=sect(),el=nm(),A=AH();choice('📜 คดีที่คุณไม่ได้ทำ',`${s}ประกาศทั่วยุทธภพว่าคุณสังหารคาราวานพ่อค้าสามสิบชีวิต แต่คุณรู้ว่าผู้อาวุโส <b>${esc(el)}</b> ของ${s}เป็นคนทำเอง`,[
 {t:'🔍 สืบหาหลักฐาน',s:A.ally?`${esc(A.ally.n)}จะช่วยคุณ`:'ขึ้นกับปัญญา',f(){const ok=A.ally||Math.random()<clamp(.3+(S.int||0)/600,.3,.85);if(ok){K(15);ahPt(20,'เปิดโปงผู้อาวุโสจอมปลอม');S.fame+=200;log(`🔍 ${A.ally?esc(A.ally.n)+'นำพยานมาให้ ':''}หลักฐานถูกวางกลางที่ประชุมยุทธภพ ${esc(el)}หน้าซีดเผือด · ${RP({pp:10,sect:-5,court:8})}`,'myth',true);later(R(8,14),'a2x',{el,s})}else{S.fame=Math.round(S.fame*.8);RP({sect:-12,pp:-5});log('🔍 พยานทุกคนหายตัวไปก่อนคุณจะถึง… ชื่อเสียงคุณดิ่งลง','bad');later(R(2,4),'hunt',{s})}}},
 {t:'⚔️ บุกกลางพิธีแล้วฉีกหน้ากากด้วยกำลัง',s:'วิธีมาร · ดวลผู้อาวุโส',f(){fightThen(`ผู้อาวุโส${el}`,1.2,w=>{if(w){mpAdd(130,'ทุบผู้อาวุโสกลางพิธี');K(5);ahPt(15,'');log(`⚔️ ${esc(el)}คุกเข่าสารภาพต่อหน้าทุกคน เพราะกลัวคุณ ไม่ใช่เพราะสำนึก · ${RP({pp:8,sect:-20,dem:5})}`,'epic');later(R(3,5),'hunt',{s})}else{S.hp=Math.max(1,Math.round(S.hp*.4));S.fame=Math.round(S.fame*.7);log('🩸 คุณแพ้ในพิธี ข้อกล่าวหาจึงยิ่งดูจริง','bad')}})}},
 {t:'🌫️ ยอมให้ชื่อเสีย แล้วหายตัวไป',s:'ชื่อเสียง −40% · ความจริงอาจกลับมาเอง',f(){S.fame=Math.round(S.fame*.6);K(10);joy(-12);log('🌫️ คุณปล่อยให้ทั้งยุทธภพสาปแช่ง แล้วหายไปในขุนเขา','bad');later(R(6,12),'a2t',{el,s})}}])};
EV.a2t=d=>{S.fame+=400;K(20);ahPt(25,'ความจริงเปิดเผยเอง');log(`📜 ศิษย์ของ${esc(d.el)}ทนความผิดไม่ไหว สารภาพกลางเมืองว่าอาจารย์ของตนคือฆาตกรคาราวาน ผู้คนตามหาคุณเพื่อขอโทษ · ${RP({pp:15,sect:-10})}`,'myth',true)};
EV.a2x=d=>{choice('🎭 คนเดิมในหน้ากากใหม่',`หลังถูกขับจาก${d.s} <b>${esc(d.el)}</b> ฝึกวิชามารจนกลายเป็นปีศาจ และประกาศว่า "ข้ากลายเป็นสิ่งที่พวกเจ้ากล่าวหาเขา ทีนี้มาดูว่าใครคือมารตัวจริง"`,[
 {t:'⚔️ ปิดบัญชี',s:'ศึกหนัก',f(){fightThen(`มาร${d.el}`,1.3,w=>{if(w){mpAdd(150,'สังหารมารที่เคยใส่ร้ายคุณ');K(15);ahPt(20,'');log('⚔️ มารปลอมตายด้วยมือมารจริง คนทั้งยุทธภพเห็นความต่าง','myth',true)}else{S.hp=Math.max(1,Math.round(S.hp*.3));log('🩸 คุณรอดมาได้หวุดหวิด','bad')}})}},
 {t:'🤝 ชวนเขาร่วมมือล้าง'+d.s,s:'กรรมชั่ว · บารมีมารมหาศาล',f(){mpAdd(250,'ร่วมมือมารล้างสำนัก');K(-60);whAdd(20);log(`🩸 คุณกับ${esc(d.el)}เดินเข้า${d.s}ด้วยกัน ไม่มีใครเดินออกมา · ${RP({sect:-40,dem:20,pp:-10})}`,'epic',true)}}])};
