EV.a3=()=>{const A=AH(),D=A.dis;if(!D)return false;choice('🩸 ศิษย์ถามคำถามเดียว',`<b>${esc(D.n)}</b> ${D.grudge?'มองคุณด้วยแววตาเย็นชา':'ถาม'} "อาจารย์มีพลังมารเหนือคนทั้งแคว้น ทำไมเราต้องอดมื้อกินมื้อ ทำไมไม่ปล้นเหมือนนิกายอื่น"`,[
 {t:'📜 "เพราะเราไม่ใช่พวกมัน"',s:'ขึ้นกับเสน่ห์และกรรม',f(){const p=clamp(.35+(S.cha||0)/300+(S.karma||0)/600-(D.grudge?.15:0),.15,.9);if(Math.random()<p){D.ok=1;ahPt(15,'สอนศิษย์ด้วยหลักของตน');log(`📜 ${esc(D.n)}เงียบไปนาน แล้วพยักหน้า คืนนั้นเขาแบ่งข้าวให้ขอทานหน้าถ้ำ`,'good');later(R(6,10),'a3g',{})}else{log(`📜 ${esc(D.n)}ฟังแล้วไม่พูดอะไร… สามวันต่อมาเขาหายไปพร้อมคัมภีร์คุณ`,'bad');later(R(5,9),'a3x',{n:D.n});A.dis=null}}},
 {t:'🗡️ "อยากปล้นก็ไปเถิด แต่อย่ากลับมา"',s:'ปล่อยเขาไป',f(){log(`🗡️ ${esc(D.n)}กราบลาแล้วเดินลงเขา`);later(R(5,9),'a3x',{n:D.n,free:1});A.dis=null}},
 {t:'🩸 ลงโทษจนไม่กล้าถามอีก',s:'บารมีมาร+ · เสียงมารดังขึ้น',f(){mpAdd(40,'');whAdd(12);D.fear=1;log(`🩸 ${esc(D.n)}ไม่เคยถามอีกเลย และไม่เคยมองตาคุณอีกเลย`,'bad');later(R(8,12),'a3f',{})}}])};
EV.a3g=()=>{const D=AH().dis;if(!D)return false;ahPt(20,'ศิษย์เดินตามทาง');S.fame+=250;log(`🌗 <b>${esc(D.n)}</b> ศิษย์คุณตั้ง "สำนักมารไร้นาม" ที่รับแต่คนที่สำนักธรรมะทอดทิ้ง ทั้งยุทธภพเริ่มเรียกพวกเขาว่าสายมารผู้ถือสัจจะ · ${RP({pp:10,dem:-5})}`,'myth',true);AH().ally=AH().ally||{n:D.n,y:S.age}};
EV.a3f=()=>{const D=AH().dis;if(!D)return false;choice('🗡️ มีดในความมืด',`คืนหนึ่ง <b>${esc(D.n)}</b> ยืนอยู่ข้างเตียงคุณพร้อมมีด "ท่านสอนข้าว่าคนแข็งแกร่งทำอะไรก็ได้"`,[
 {t:'⚔️ สู้',s:'ดวลศิษย์',f(){fightThen(D.n,.85,w=>{AH().dis=null;if(w){K(-5);mpAdd(30,'');log(`🩸 ศิษย์ที่คุณสร้างมา ตายด้วยบทเรียนที่คุณสอน`,'bad')}else{S.hp=1;log(`🩸 ${esc(D.n)}แทงคุณแล้วหนีไป คุณรอดเพราะโชคช่วย`,'bad')}})}},
 {t:'🙇 "ข้าสอนเจ้าผิดไป"',s:'เสี่ยง',f(){if(Math.random()<.45+(S.karma||0)/500){AH().dis.ok=1;AH().dis.fear=0;K(15);whAdd(-15);ahPt(15,'');log(`🙇 มีดในมือ${esc(D.n)}ร่วงลงพื้น`,'myth',true)}else{S.hp=Math.max(1,Math.round(S.hp*.2));AH().dis=null;log(`🩸 คำขอโทษมาช้าไปหนึ่งปี`,'bad')}}}])};
EV.a3x=d=>{choice('👹 ศิษย์ที่จากไปกลายเป็นจอมมาร',`<b>${esc(d.n)}</b> ${d.free?'ที่คุณปล่อยไป':'ที่ขโมยคัมภีร์ของคุณ'} ตั้งนิกายปล้นสะดมเจ็ดเมือง ชาวบ้านเรียกเขาว่า "ศิษย์ของมารผู้ถือสัจจะ" ชื่อคุณเปื้อนเลือดที่คุณไม่ได้หลั่ง`,[
 {t:'⚔️ ไปปิดทางเอง',s:'ดวล',f(){fightThen(`จอมมาร${d.n}`,1.15,w=>{if(w){choice('⚔️ ศิษย์เก่าล้มลงแล้ว','',[{t:'🩸 ฆ่า',s:'ล้างมลทิน',f(){mpAdd(80,'');ahPt(15,'ล้างมลทินด้วยมือตัวเอง');log(`🩸 คุณลบความผิดพลาดของตัวเองทิ้ง ด้วยราคาที่แพงที่สุด`,'epic')}},{t:'🤲 พากลับมา',s:'เสี่ยงอีกครั้ง',f(){AH().dis={n:d.n,y:S.age,ok:Math.random()<.55?1:0};K(10);log(`🤲 คุณแบก${esc(d.n)}กลับถ้ำ ครั้งนี้คุณจะสอนให้ถูก`,'good');later(R(5,8),AH().dis.ok?'a3g':'a3f',{})}}])}else{S.hp=Math.max(1,Math.round(S.hp*.3));S.fame=Math.round(S.fame*.8);log('🩸 ศิษย์เก่าเหนือกว่าคุณไปแล้ว','bad')}})}},
 {t:'🩸 เข้าร่วมกับเขา',s:'กลายเป็นจอมมาร · กรรมดิ่ง',f(){mpAdd(300,'ร่วมนิกายศิษย์เก่า');K(-90);whAdd(25);log(`🩸 อาจารย์กับศิษย์ปล้นเมืองที่แปดด้วยกัน คุณไม่ใช่มารผู้ถือสัจจะอีกต่อไป · ${RP({pp:-25,dem:20})}`,'bad',true);try{keyAdd('ทิ้งสัจจะ ร่วมปล้นกับศิษย์เก่า')}catch(e){}}},
 {t:'🚶 ปล่อยให้คนอื่นจัดการ',s:'ชื่อเสียง −',f(){S.fame=Math.round(S.fame*.75);ahPt(-20,'');log('🚶 ฉายาคุณเปื้อนไปตลอดกาล','bad')}}])};
