EV.a4=()=>{const h=nm(),s=sect(),A=AH();choice('⚖️ วีรบุรุษคนสุดท้ายที่ยังเชื่อในธรรมะ',`<b>${esc(h)}</b> วีรบุรุษหนุ่มแห่ง${s} ยืนขวางทาง "ข้าไม่สนว่าเจ้าช่วยใคร มารก็คือมาร"`,[
 {t:'⚔️ สู้',s:'ดวล · ชนะแล้วเลือกต่อ',f(){fightThen(h,1.05,w=>{if(!w){S.hp=Math.max(1,Math.round(S.hp*.35));if(Math.random()<.5){log(`🩸 ${esc(h)}ชนะ แต่ไม่ฟันซ้ำ "ทำไมเจ้าไม่ใช้วิชามารเต็มกำลัง"`,'bad');later(R(3,6),'a4b',{h,s,spared:1})}else log(`🩸 ${esc(h)}ทิ้งคุณไว้ให้ตายข้างทาง คุณคลานกลับมาได้`,'bad');return}
   choice(`⚖️ ${h}ล้มอยู่ตรงหน้า`,'"ฆ่าข้าสิ ให้ทุกคนรู้ว่ามารเป็นอย่างไร"',[
    {t:'🩸 ฆ่า',s:'เขาไม่ใช่คนชั่ว · กรรมชั่ว',f(){K(-35);whAdd(15);mpAdd(100,'สังหารวีรบุรุษ');log(`🩸 วีรบุรุษตายในวันที่เขาคิดถูกเรื่องคุณ · ${RP({sect:-15,pp:-5,dem:10})}`,'bad',true)}},
    {t:'🕊️ ไว้ชีวิต ไม่พูดอะไร',s:'',f(){K(10);log(`🕊️ คุณเดินผ่าน${esc(h)}ไปเฉยๆ`);later(R(4,8),'a4b',{h,s,spared:1})}},
    {t:'📜 บอกความจริงทั้งหมดของ'+s,s:'ขึ้นกับปัญญา',f(){if(Math.random()<clamp(.35+(S.int||0)/500,.35,.85)){K(15);ahPt(20,'ทำให้วีรบุรุษเห็นความจริง');A.ally={n:h,y:S.age};log(`📜 ${esc(h)}ฟังจนจบ แล้วหักป้ายศิษย์${s}ทิ้งต่อหน้าคุณ คุณได้พันธมิตรที่ไม่มีใครคาดคิด · ${RP({sect:-8,pp:5})}`,'myth',true)}else{log(`📜 "โกหก!" ${esc(h)}ไม่เชื่อสักคำ`);later(R(4,8),'a4b',{h,s})}}}])})}},
 {t:'🌫️ ไม่สู้ ถอยไป',s:'ชื่อเสียงลด',f(){S.fame=Math.round(S.fame*.9);log(`🌫️ คุณหันหลังให้${esc(h)} เขาตะโกนตามหลังว่า "มารขี้ขลาด!"`);later(R(4,8),'a4b',{h,s})}}])};
