// A5 คืนที่เสียงมารดังที่สุด
EV.a5=()=>{const L=loved();if(!L)return false;const A=AH();choice('🌑 คืนที่เสียงมารดังที่สุด',`<b>${esc(L.n)}</b> ป่วยหนักด้วยพิษเย็นที่ไม่มียาแก้ หมอบอกว่าเหลือไม่เกินเจ็ดวัน<br>เสียงในหัวกระซิบ: <i>"คัมภีร์มารหน้าสุดท้าย… ชีวิตแลกชีวิต คนแปลกหน้าคนไหนก็ได้"</i>`,[
 {t:'🩸 สังเวยคนแปลกหน้า',s:`${esc(L.n)}รอดแน่ · กรรมดิ่งหนัก`,f(){K(-70);whAdd(30);mpAdd(80,'');joy(10);log(`🩸 คนเร่ร่อนคนหนึ่งหายไปจากสะพานหน้าเมือง ${esc(L.n)}ลืมตาตอนรุ่งสาง และคุณรู้ว่าตัวเองจะไม่มีวันลืมคืนนั้น`,'bad',true);try{keyAdd('สังเวยคนแปลกหน้าเพื่อ'+L.n)}catch(e){}later(R(8,12),'a5r',{n:L.n})}},
 {t:'🔥 สังเวยพลังของตัวเองแทน',s:'พลังยุทธ์ −15% · อายุขัย −',f(){S.power=Math.round(S.power*.85);try{if(!S.xt)S.lifespan=Math.max(S.age+5,S.lifespan-Math.round((S.lifespan-S.age)*.15))}catch(e){}K(25);whAdd(-25);ahPt(25,'สังเวยพลังตัวเองแทนชีวิตคนอื่น');joy(5);log(`🔥 คุณถ่ายพลังมารเข้าร่าง${esc(L.n)}จนตัวเองกระอักเลือด พิษเย็นละลายไป`,'myth',true)}},
 {t:'🙏 ออกตามหายาแบบทางธรรม',s:'ขึ้นกับปัญญาและเงิน',f(){const p=clamp(.25+(S.int||0)/800+Math.min(.25,S.money/(sxBiz()*20)),.15,.75);if(Math.random()<p){K(10);ahPt(10,'');log(`🙏 เจ็ดวันเจ็ดคืน คุณได้ดอกบัวหิมะมาทันเวลา ${esc(L.n)}รอด`,'good')}else lose(L)}},
 {t:'🌫️ ทำใจ',s:'',f(){lose(L);whAdd(5)}}])};
EV.a5r=d=>{const c=nm();choice('🕯️ ลูกของคนเร่ร่อน',`ชายหนุ่มชื่อ <b>${esc(c)}</b> ตามรอยมาสิบปี "พ่อข้าหายไปจากสะพานคืนนั้น ศพเขามีรอยวิชามารของท่าน"`,[
 {t:'🙇 ยอมรับ ให้เขาตัดสิน',s:'พลังชีวิต −60% · กรรมดี+',f(){S.hp=Math.max(1,Math.round(S.hp*.4));K(40);whAdd(-20);log(`🙇 เขาแทงคุณหนึ่งแผล แล้วทิ้งมีดไว้ "เท่านี้ก็พอ ข้าไม่อยากเป็นแบบท่าน"`,'myth',true)}},
 {t:'⚔️ สู้',s:'ถ้าฆ่า กรรมชั่วซ้ำ',f(){fightThen(c,.95,w=>{if(w){K(-30);whAdd(10);log(`🩸 คุณฆ่าพ่อแล้วฆ่าลูก เสียงมารหัวเราะเบาๆ`,'bad',true)}else{S.hp=1;log(`🩸 ${esc(c)}ชนะ แต่ไม่ฆ่า "ท่านยังต้องอยู่ชดใช้"`,'bad')}})}},
 {t:'🤲 รับเขาเป็นศิษย์ ชดใช้ด้วยชีวิตที่เหลือ',s:'',f(){AH().dis={n:c,y:S.age,grudge:1};K(20);log(`🤲 ${esc(c)}รับคำ แต่บอกว่า "วันที่ข้าชนะท่านได้ ข้าจะเลือกใหม่"`,'good');later(R(4,7),'a3',{})}}])};
// W เสียงมารกระซิบ
const LURE=[['เด็กอัจฉริยะในหมู่บ้านข้างล่าง มีรากปราณบริสุทธิ์ กลืนเขาแล้วทะลวงขั้นได้ทันที',.18],['พยานคนสุดท้ายของคดีเก่า ถ้าเขาตาย ไม่มีใครรู้อีกว่าเจ้าเคยทำอะไร',.1],['เลือดชาวบ้านสามร้อยคนเปิดค่ายกลโลหิตได้ เจ้าจะไร้เทียมทานไปสิบปี',.25],['ภรรยาของศัตรูกำลังตั้งครรภ์ ฆ่าทั้งสองแล้วสายเลือดมันจะสิ้น',.12]];
EV.w=()=>{const A=AH(),[t,g]=pick(LURE),p=resist();choice('🌑 เสียงมารกระซิบ',`<i>"${t}"</i><br><span class="tag2">เสียงมาร ${Math.round(A.wh)}/100 · โอกาสต้านไหว ~${Math.round(p*100)}%</span>`,[
 {t:'🩸 ยอมตามเสียงนั้น',s:`พลังยุทธ์พุ่ง · กรรมดิ่ง`,f(){const gg=pw(g);K(-60);whAdd(18);A.yd++;mpAdd(120,'ยอมตามเสียงมาร');log(`🩸 คุณทำตามเสียงนั้น พลังยุทธ์ +${fmt(gg)} · เสียงในหัวดังขึ้นอีก`,'bad',true);if(A.yd>=3&&!A.done.wf)later(1,'wf',{})}},
 {t:'🧘 ข่มใจต้านไว้',s:`~${Math.round(p*100)}%`,f(){if(Math.random()<p){whAdd(-12);A.rs++;K(8);ahPt(8,'ต้านเสียงมาร');log('🧘 คุณนั่งสมาธิจนรุ่งเช้า เสียงนั้นเงียบไป ครั้งนี้','good');if(A.rs>=4&&!A.done.wr){A.done.wr=1;const gg=pw(.12);log(`🌗 <b>จิตเหนือมาร</b> ต้านเสียงมารมาสี่ครั้ง วิชามารไม่อาจครอบงำคุณได้อีก · พลังยุทธ์ +${fmt(gg)}`,'myth',true);whAdd(-30)}}else{S.hp=Math.max(1,Math.round(S.hp*.7));whAdd(6);log('🌑 คุณต้านได้แต่ร่างกายแลกด้วยเลือด เสียงมารยังไม่ยอมเงียบ','bad')}}},
 {t:'✂️ ตัดพลังมารทิ้งส่วนหนึ่ง',s:'บารมีมาร −25% · เสียงเงียบลงมาก',f(){S.mp=Math.round(mpOf()*.75);whAdd(-35);K(5);log('✂️ คุณสลายพลังมารหนึ่งในสี่ทิ้ง เสียงในหัวเหลือแค่กระซิบไกลๆ','good')}}])};
EV.wf=()=>{const A=AH();A.done.wf=1;choice('👁️ มารในใจตื่นขึ้น',`เสียงที่เคยกระซิบ ตอนนี้พูดด้วยเสียงคุณเอง <i>"เจ้ายอมข้ามาสามครั้งแล้ว เลิกแกล้งทำเป็นคนดีเสียที"</i>`,[
 {t:'😈 ยอมรับว่าข้าคือมาร',s:'กลายเป็นจอมมารเต็มตัว',f(){mpAdd(400,'ยอมรับมารในใจ');K(-80);const gg=pw(.3);log(`😈 คุณหัวเราะพร้อมกับเสียงนั้น พลังยุทธ์ +${fmt(gg)} · มารผู้ถือสัจจะตายไปแล้ว`,'myth',true);try{keyAdd('ยอมรับมารในใจ')}catch(e){}}},
 {t:'🔥 สลายพลังมารทิ้งครึ่งหนึ่ง',s:'เจ็บหนัก · เริ่มใหม่',f(){S.mp=Math.round(mpOf()*.5);S.power=Math.round(S.power*.8);A.wh=0;A.yd=0;K(30);log('🔥 คุณเผาพลังมารครึ่งหนึ่งทิ้งด้วยไฟในใจ ร่างพังแต่เสียงนั้นเงียบสนิท','myth',true)}},
 {t:'🗡️ ดวลกับมารในใจ',s:'ดวลกับตัวเอง',f(){fightThen('มารในใจของคุณ',1.1,w=>{if(w){A.wh=0;A.yd=0;K(20);ahPt(30,'ชนะมารในใจ');const gg=pw(.15);log(`🗡️ คุณชนะตัวเอง พลังมารยังอยู่ แต่ตอนนี้มันเป็นของคุณ · พลังยุทธ์ +${fmt(gg)}`,'myth',true)}else{mpAdd(200,'');K(-50);whAdd(30);log('🩸 คุณแพ้ตัวเอง เสียงนั้นยึดครองร่างอยู่ครู่หนึ่ง… และมีคนตายระหว่างนั้น','bad',true)}})}}])};
// M หน้ากากธรรม
EV.m1=()=>{const w=nm(),A=AH();choice('🎭 พยานที่เห็นมากเกินไป',`คนรับใช้ชื่อ <b>${esc(w)}</b> เห็นคุณขนของต้องห้ามออกจากหอคัมภีร์ตอนดึก<br><span class="tag2">ความลับเสี่ยงรั่ว ${Math.round(A.sec)}/100</span>`,[
 {t:'🩸 ปิดปากถาวร',s:'กรรมชั่ว · ความลับปลอดภัย',f(){K(-30);A.sec=Math.max(0,A.sec-25);log(`🩸 ${esc(w)}พลัดตกบ่อน้ำ ทุกคนเสียใจ คุณเป็นคนกล่าวไว้อาลัยเอง`,'bad');later(R(5,9),'m1g',{w})}},
 {t:'💰 ติดสินบนให้เงียบ',s:`${Mf(Math.round(sxBiz()*.4))}`,f(){S.money=Math.max(0,S.money-Math.round(sxBiz()*.4));A.sec=Math.max(0,A.sec-10);log(`💰 ${esc(w)}รับเงินแล้วยิ้ม รอยยิ้มแบบคนที่รู้ว่าจะได้อีก`);later(R(2,4),'m1b',{w})}},
 {t:'🙏 สารภาพกับเขา และเลิกทำ',s:'กรรมดี+ · ทางกลับตัว',f(){K(40);A.sec=Math.max(0,A.sec-40);log(`🙏 คุณเผาของต้องห้ามต่อหน้า${esc(w)} "ช่วยข้าเป็นคนอย่างที่คนอื่นคิดว่าข้าเป็น"`,'myth',true)}}])};
EV.m1g=d=>{AH().sec+=20;log(`👻 ลูกสาวของ${esc(d.w)}เข้าสำนักมาเป็นศิษย์ เธอถามทุกคนว่าคืนนั้นพ่อของเธอไปทำอะไรที่หอคัมภีร์`,'bad')};
EV.m1b=d=>{const A=AH();choice('💰 คนที่รู้ความลับกลับมา',`<b>${esc(d.w)}</b> ขอเป็นห้าเท่า "หรือจะให้ข้าเล่าเรื่องสนุกให้เจ้าสำนักฟัง"`,[
 {t:'💰 จ่าย',s:`${Mf(Math.round(sxBiz()*2))}`,f(){const c=Math.round(sxBiz()*2);if(S.money<c){A.sec+=35;log('💸 คุณจ่ายไม่ไหว… เขาเริ่มพูด','bad');return}S.money-=c;later(R(3,5),'m1b',d)}},
 {t:'🩸 จัดการเสีย',s:'กรรมชั่ว',f(){K(-30);A.sec+=8;log(`🩸 ${esc(d.w)}หายไปเฉยๆ แต่เขาบอกเมียไว้ก่อนแล้ว`,'bad')}}])};
EV.m2=()=>{const s=nm(),A=AH();choice('🎭 ศิษย์ที่เริ่มสงสัย',`ศิษย์เอก <b>${esc(s)}</b> เจอบัญชีลับของคุณ "อาจารย์… เงินบริจาคช่วยน้ำท่วมไปอยู่ที่ไหน"`,[
 {t:'😊 อธิบายให้เชื่อ',s:'ขึ้นกับเสน่ห์',f(){if(Math.random()<clamp(.3+(S.cha||0)/250,.3,.85)){log(`😊 ${esc(s)}ก้มหัวขอโทษที่สงสัยอาจารย์`);A.sec=Math.max(0,A.sec-5)}else{A.sec+=25;log(`😶 ${esc(s)}พยักหน้า แต่คุณเห็นว่าเขาไม่เชื่อ`,'bad')}}},
 {t:'📜 ใส่ร้ายให้เขาถูกขับจากสำนัก',s:'กรรมชั่ว · เขาจะกลับมา',f(){K(-25);A.sec=Math.max(0,A.sec-10);log(`📜 ${esc(s)}ถูกประจานว่าขโมยเงินบริจาค ถูกขับลงเขากลางฝน`,'bad');later(R(6,10),'m2x',{s})}},
 {t:'🤝 ชวนเขามาร่วมกิน',s:'ได้พวก หรือโดนแฉ',f(){if(Math.random()<.5){S.money+=Math.round(sxBiz()*.5);K(-10);log(`🤝 ${esc(s)}ยิ้ม "ข้านึกว่าอาจารย์จะไม่ชวนเสียแล้ว"`)}else{A.sec+=45;log(`🙅 ${esc(s)}ถอยหลังสองก้าว แล้ววิ่งไปหาเจ้าสำนัก`,'bad')}}}])};
EV.m2x=d=>{choice('👹 ศิษย์ที่ถูกขับกลับมา',`<b>${esc(d.s)}</b> ที่คุณใส่ร้าย กลับมาพร้อมวิชามาร "ท่านทำให้ข้ากลายเป็นสิ่งที่ท่านเป็นอยู่ข้างใน"`,[
 {t:'⚔️ สู้',s:'ดวล',f(){fightThen(`มาร${d.s}`,1.1,w=>{if(w){S.fame+=150;log(`⚔️ "ข้าปราบมารร้ายได้แล้ว" คุณประกาศ ทุกคนปรบมือ`,'epic');AH().sec+=10}else{AH().sec+=40;S.hp=Math.max(1,Math.round(S.hp*.3));log('🩸 เขาตะโกนความจริงทั้งหมดกลางตลาดก่อนจากไป','bad')}})}},
 {t:'🙇 สารภาพต่อหน้าเขา',s:'',f(){K(30);AH().sec+=30;log(`🙇 ${esc(d.s)}ไม่ฆ่าคุณ "ข้าจะปล่อยให้ทุกคนตัดสินท่านเอง"`,'myth')}}])};
EV.m3=()=>{const A=AH();A.done.m3=S.age;choice('🎭 หน้ากากแตก',`ความลับทั้งหมดถูกอ่านกลางที่ประชุมยุทธภพ บัญชีลับ ของต้องห้าม พยานที่หายไป ทุกสายตาหันมาที่คุณ`,[
 {t:'🙇 สารภาพทั้งหมด และชดใช้',s:'ชื่อเสียงหาย · กรรมดี+ · เริ่มใหม่',f(){S.fame=Math.round(S.fame*.4);K(60);A.sec=0;A.mk++;if(S.faction){S.rank=0}joy(-20);log('🙇 คุณคุกเข่าต่อหน้าทุกคน ยอมสละตำแหน่งทั้งหมด บางคนถุยน้ำลาย บางคนเริ่มเคารพ','myth',true);try{keyAdd('สารภาพความผิดทั้งหมดต่อหน้ายุทธภพ')}catch(e){}}},
 {t:'🩸 ฉีกหน้ากากทิ้ง กลายเป็นมาร',s:'ออกจากสำนัก · บารมีมาร+',f(){S.faction=null;S.rank=0;mpAdd(220,'หน้ากากธรรมแตก');K(-40);A.sec=0;A.mk++;log('🩸 คุณหัวเราะกลางที่ประชุม "ใช่ ข้านี่แหละ" แล้วฝ่าวงล้อมออกไป','myth',true)}},
 {t:'⚔️ ฆ่าคนที่เปิดโปงกลางที่ประชุม',s:'ศึกหนักมาก',f(){fightThen('ยอดฝีมือทั้งที่ประชุม',1.4,w=>{if(w){A.sec=30;A.mk++;K(-50);S.fame+=300;log('⚔️ ไม่มีใครกล้าพูดคำว่า "ความลับ" อีก แต่ทุกคนรู้','epic',true)}else{S.hp=1;S.fame=Math.round(S.fame*.3);S.faction=null;log('🩸 คุณหนีออกมาได้แบบไม่เหลืออะไร','bad',true)}})}}])};
window._ahEV=EV;
// ---- ลูปรายปี ----
let pend=0,pendS=null,pendT=0;const pBusy=()=>!!(pend&&pendS===S&&Date.now()-pendT<90000);const fire=(id,d)=>{if(pBusy())return;pend=1;pendS=S;pendT=Date.now();wpWait(()=>{pend=0;try{if(!S||!S.alive||choice._cur)return;const f=EV[id];if(f&&f(d)!==false)AH().last=S.age}catch(e){console.error(e)}})};
{const _py=passYear;passYear=function(){const a0=S?S.age:0,k0=S?S.karma||0:0;const r=_py.apply(this,arguments);try{if(!S||!S.alive||S.beastMode||S.age<16)return r;const A=AH(),dy=Math.max(1,Math.min(10,S.age-a0)),q=q4();
  if(q==='anti')A.ay+=dy;if(q==='mask'){A.my+=dy;const dk=(S.karma||0)-k0;if(dk<0)A.sec=clamp(A.sec+Math.min(15,-dk/6),0,100);A.sec=clamp(A.sec+.5*dy,0,100)}
  if(q==='anti'&&Math.random()<.5)RP({sect:-1,pp:1});
  if(mpOf()>=150&&A.wh<60)whAdd(Math.min(3,.5+.4*dmTi())*dy);
  if(pBusy())return r;const due=A.q.findIndex(x=>x.at<=S.age);if(due>=0){const x=A.q.splice(due,1)[0];fire(x.id,x.d);return r}
  if(S.age-A.last<3)return r;
  if(mpOf()>=300&&(S.karma||0)>-150&&A.wh>=10&&Math.random()<.05*dy*(1+A.wh/60))return fire('w'),r;
  if(q==='mask'){if(A.sec>=70&&(!A.done.m3||S.age-A.done.m3>30)&&Math.random()<A.sec/350*dy)return fire('m3'),r;if(Math.random()<.07*dy)return fire(pick(['m1','m2'])),r}
  if(q==='anti'&&Math.random()<.08*dy){const L=['a1','a2','a4','a5'].filter(k=>!(A.done[k]&&S.age-A.done[k]<25));if(A.dis&&!A.done.a3)L.push('a3');if(!L.length)return r;const k=pick(L);A.done[k]=S.age;return fire(k),r}
  if(q==='anti'&&Math.random()<.025*dy)return fire('hunt',{}),r;}catch(e){console.error(e)}return r}}
