 const o=[{t:'⚔️ ดวลยึด',s:`ดวล${k.t} (แรง ×${k.m}) · ได้แคว้นไว แต่ลูกน้องจะแค้น`,f(){A.ay=S.age;fightThen(`${k.t} ${k.n}`,k.m,w=>dzDuelEnd(l,w))}}];
