function dzDuelEnd(l,w){const A=AB(),k=l.k;if(!w){S.hp=Math.max(1,Math.round(S.hp*.35));A.arm=Math.round(A.arm*.8);k.mood-=20;log(`🩸 ${k.t} ${k.n}เหยียบคุณจมดิน "กลับมาใหม่เมื่อเจ้าหิวกว่านี้"`,'bad');return}
 choice(`⚔️ ${k.t}ล้มลงแล้ว`,`${esc(k.n)}คุกเข่าบนพื้นเลือดของตัวเอง`,[
  {t:'🩸 กลืนแก่นของเขา',s:'พลังพุ่ง · ความหิวหาย · สติ −',f(){k.alive=0;l.own=1;A.kills++;A.hun=0;const g=pw(.08);satAdd(-8);fx({king:-8});log(`🩸 คุณกลืน${k.t}ทั้งแก่น — พลังยุทธ์ +${fmt(g)} · ${l.n}เป็นของคุณ`,'myth',true);later(R(3,6),'men',{i:l.i,n:k.n});rumor(l.i,'kill');if(Math.random()<.35)seal('ในแก่นของ'+k.n);if(i4(l))dzThrone()}},
  {t:'⚔️ ตัดหัวเฉยๆ',s:'',f(){k.alive=0;l.own=1;A.kills++;fx({king:-5});log(`⚔️ หัวของ${k.t}ถูกเสียบไว้หน้าประตู${l.n}`,'epic');later(R(3,6),'men',{i:l.i,n:k.n});rumor(l.i,'kill');if(Math.random()<.35)seal('ใต้บัลลังก์'+l.n);if(i4(l))dzThrone()}},
  {t:'🕊️ ไว้ชีวิต ให้เป็นเมืองขึ้น',s:'ได้แคว้น · เขาจะจำ (ดีหรือร้ายก็ได้)',f(){l.own=1;k.sp=1;k.mood+=30;satAdd(5);K(5);fx({king:5});log(`🕊️ คุณปล่อย${k.n}ไว้ เขามองคุณเหมือนมองสิ่งที่ไม่เข้าใจ`,'good');later(R(4,8),'spared',{i:l.i});if(i4(l))dzThrone()}}])}
const i4=l=>l.i===4;
function dzThrone(){const A=AB();A.throne=1;S.flags.abKing=1;const g=pw(.2);log(`👑 <b>คุณนั่งลงบนบัลลังก์กลางของแดนอสูร</b> ราชันทุกแคว้นที่เหลือส่งบรรณาการมาภายในเจ็ดวัน · พลังยุทธ์ +${fmt(g)}`,'myth',true);try{keyAdd('จักรพรรดิแดนอสูร')}catch(e){}
 if(!S.asr)S.asr={army:Math.round(A.arm*3+mpOf()/10),lands:0,y:-1};else S.asr.army+=Math.round(A.arm*3);log('☁️ ทัพอสูรทั้งแดนรอคำสั่ง ยกทัพขึ้นสวรรค์ได้ที่หน้าบารมีมาร','epic')}
