      const dust=[58,42,36],lit2=.35+lt*.65,a=cov*.8;col=[lerp(col[0],dust[0]*lit2+10,a),lerp(col[1],dust[1]*lit2+6,a),lerp(col[2],dust[2]*lit2+4,a)];
