const NEB=(()=>{const c=mk(96,54),x=c.getContext('2d'),im=x.createImageData(96,54),d=im.data;for(let y=0;y<54;y++)for(let i=0;i<96;i++){const dx=(i-48)/30,dy=(y-27)/22,r=Math.hypot(dx,dy),n=fbm(i*.09+5,y*.11,1,4),ring=Math.exp(-Math.pow((r-.75)/.32,2))*(.4+n*1.1)+Math.exp(-r*r*4)*.35*n;const k=(y*96+i)*4,c1=mix([255,80,170],[90,140,255],clamp(n*1.3-.2)),c2=mix(c1,[255,190,110],clamp(1-r*1.6));d[k]=c2[0];d[k+1]=c2[1];d[k+2]=c2[2];d[k+3]=clamp(ring)*255}x.putImageData(im,0,0);return c})();
