  if(t>3.2){const k=clamp((t-3.2)/.5);slashCrescent(bx,ci.tip[0]+k*120,ci.tip[1]-10,H*1.6,1,1,DSX.Cr)}
  const fw=1-clamp(Math.abs(t-TCH)/.3);if(fw>0&&t>TCH-.3){bx.fillStyle=rgb(255,255,255,fw);bx.fillRect(0,0,W,H)}
