 // ชิ้นส่วนเสียง
 const swish=(v,w,hi)=>{nz(.22,.13*v,'bandpass',hi?2600:1400,hi?7000:4200,1.4,w,.05);tn(hi?1900:1100,.14,'triangle',.02*v,w,hi?700:420)};
 const boom=(v,w,len)=>{len=len||.8;tn(78,len,'sine',.16*v,w,30,.006);tn(52,len*1.2,'sine',.12*v,w,24,.01);nz(len,.14*v,'lowpass',900,70,.7,w,.006);nz(.09,.12*v,'highpass',900,0,.7,w)};
 const rumble=(d,v,w)=>{nz(d,.1*v,'lowpass',180,50,1,w,Math.min(.5,d*.3));tn(41,d,'sine',.06*v,w,33,Math.min(.4,d*.3))};
 const charge=(d,v,w)=>{nz(d,.08*v,'bandpass',180,2600,2.2,w,d*.9);tn(70,d,'sawtooth',.025*v,w,260,d*.9);tn(140,d,'triangle',.02*v,w,520,d*.9)};
 const zap=(v,w)=>{for(let i=0;i<5;i++)nz(.04+Math.random()*.04,.12*v,'highpass',1800+Math.random()*2000,0,.8,(w||0)+i*.045+Math.random()*.02)};
 const shimmer=(v,w,n)=>{const P=[1047,1319,1568,2093,2637,3136];for(let i=0;i<(n||6);i++)tn(P[i%6],.5,'sine',.03*v,(w||0)+i*.06)};
 const gong=(v,w)=>{tn(196,2.2,'sine',.09*v,w,0,.004);tn(196*2.76,1.4,'sine',.035*v,w,0,.004);tn(196*5.4,.9,'sine',.018*v,w,0,.004);tn(98,1.8,'sine',.05*v,w)};
 // ท่าวิชาตามสาย · T = 1..4 (ยิ่งขั้นสูงยิ่งดังและยาว)
 const ART={
  sword:(v,T)=>{swish(v,0,1);if(T>=2)swish(v*.8,.12,1);if(T>=3){tn(2400,.7,'sine',.025*v,.18);tn(3600,.5,'sine',.012*v,.18)}if(T>=4)boom(v*.6,.22,.6)},
  fist:(v,T)=>{nz(.16,.1*v,'bandpass',500,180,1,0,.05);boom(v*.8,.12,.4+.1*T);if(T>=3)nz(.3,.07*v,'highpass',1200,4000,.7,.14)},
  palm:(v,T)=>{nz(.55,.08*v,'bandpass',260,900,.9,0,.3);tn(150,.6,'sine',.07*v,.2,80);if(T>=3)boom(v*.6,.45,.7)},
  fire:(v,T)=>{nz(.9+.2*T,.11*v,'bandpass',350,1700,.6,0,.3);for(let i=0;i<4+T*3;i++)nz(.025,.08*v,'highpass',3000,0,.6,.1+Math.random()*.8);if(T>=3)boom(v*.6,.6,.7)},
  ice:(v,T)=>{[2093,2637,3136,4186].slice(0,2+T).forEach((f,i)=>tn(f,.45,'sine',.04*v,i*.07));nz(.2,.08*v,'highpass',5000,9000,.7,.3);if(T>=3)nz(.5,.07*v,'highpass',3000,800,.6,.35)},
  thunder:(v,T)=>{zap(v,0);if(T>=2)zap(v*.8,.25);boom(v*(.6+.12*T),.3,.6+.15*T)},
  wind:(v,T)=>{nz(.8,.09*v,'bandpass',450,2000,2.2,0,.35);nz(.7,.07*v,'bandpass',1800,400,2.2,.45,.2);if(T>=3)nz(1,.06*v,'bandpass',300,3000,3,.2,.5)},
  demon:(v,T)=>{tn(62,1,'sawtooth',.05*v,0,46,.1);tn(65.5,1,'sawtooth',.04*v,0,48,.1);nz(.9,.05*v,'bandpass',900,300,6,0,.3);tn(311,.7,'sawtooth',.018*v,.25,290);if(T>=3)boom(v*.7,.5,.9)},
  buddha:(v,T)=>{gong(v,0);if(T>=2)tn(220,1.2,'sine',.03*v,.1);if(T>=3){tn(330,1.2,'sine',.025*v,.1);gong(v*.7,.6)}}};
 const art=(st,T)=>{if(!ok())return;const f=ART[st]||ART.palm;T=Math.max(1,Math.min(4,T|0));try{f(.75+.15*T,T)}catch(e){}};
 // ทะลวงขั้น: ชาร์จขึ้น → ฟ้าแตก → ระฆังแก้ว
 const brk=(T,dur)=>{if(!ok())return;T=Math.max(1,Math.min(4,T|0));const v=.8+.15*T,c=Math.max(.6,Math.min(1.6,(dur||1500)/1000*.55));charge(c,v,0);[392,523,659,784,1047,1319].forEach((f,i)=>tn(f,.25,'triangle',.03*v,c*.4+i*.07));boom(v,c,.7+.2*T);shimmer(v,c+.1,4+T);if(T>=3)zap(v*.7,c+.05)};
 // ฉากทำลายล้าง: [เวลา(วินาที), ชนิด, ค่า] ตามจังหวะในฉากจริง
 const DSQ={1:[[.2,'charge',2.1],[2.45,'swish'],[2.88,'boom',.9],[2.95,'rumble',1.6]],
  2:[[.2,'charge',2.4],[2.7,'swish'],[2.85,'swish'],[4.4,'boom',1.1],[4.5,'rumble',2.6]],
  3:[[.2,'charge',2.4],[2.75,'beam',3.4],[6.45,'boom',1.6],[6.5,'zap'],[6.6,'rumble',5],[9,'boom',.8]],
  4:[[.3,'rumble',3],[.4,'charge',3.1],[3.7,'flash'],[4,'beam',4.1],[8.3,'boom',2],[8.35,'zap'],[8.5,'rumble',7]],
  5:[[.3,'hum',3.3],[3.7,'flash'],[4,'charge',4.1],[8.3,'nova'],[8.6,'rumble',5],[9.2,'shimmer']]};
 let Q=[];const clr=()=>{Q.forEach(clearTimeout);Q=[]};
 const ds=k=>{clr();if(!ok())return;const v=1+.08*k;(DSQ[k]||[]).forEach(([t,ty,x])=>Q.push(setTimeout(()=>{try{if(!ok())return;
  if(ty==='charge')charge(x,v,0);else if(ty==='swish')swish(v,0,1);else if(ty==='boom')boom(v*(x||1),0,.8*(x||1));else if(ty==='rumble')rumble(x,v,0);else if(ty==='zap')zap(v,0);
  else if(ty==='beam'){nz(x,.09*v,'bandpass',300,2400,1.5,0,.25);tn(110,x,'sawtooth',.03*v,0,330,.2);tn(220,x,'triangle',.025*v,0,660,.2)}
  else if(ty==='flash'){nz(.5,.12*v,'highpass',600,8000,.7,0,.01);tn(1568,.4,'sine',.04*v);tn(2093,.5,'sine',.03*v,.05)}
  else if(ty==='hum'){tn(55,x,'sine',.06*v,0,58,1);tn(82.4,x,'sine',.04*v,0,85,1);tn(110,x,'triangle',.02*v,0,116,1.2)}
  else if(ty==='nova'){boom(v*1.6,0,2.4);nz(2.5,.12*v,'highpass',200,9000,.6,0,.02);tn(30,3,'sine',.12*v,0,20,.01)}
  else if(ty==='shimmer')shimmer(v,0,8)}catch(e){}},t*1000)))};
 return {art,brk,ds,clr,nz,tn,boom,swish,zap,charge};
