 const tag=x.p?`<span class="tg tm">🪙 ${x.p}฿ · ฉบับเลข ${x.cap} ชิ้น</span>`:`<span class="tg ${x.s==='g'?'tk':'te'}">${x.s==='g'?'☯️':'☠️'} ${f(x.k)} ${x.s==='g'?'กรรมดี':'กรรมชั่ว'}</span>`;
 const lf=x.p?left(r[2]):null,bar=x.p&&lf!=null?`<div class="bar"><i style="width:${Math.round(lf/x.cap*100)}%"></i></div><div class="ds">เหลือ ${lf}/${x.cap}</div>`:'';
