function txt(e){
 const n='<b>'+NM(e.n)+'</b>';
 if(e.k==='vip')return e.ti===3?[n+' เข้าหอผู้ก่อตั้ง','ขอบคุณที่ร่วมสร้างเกมนี้ด้วยกัน']:[n+' เป็นสมาชิก VIP','ขอบคุณที่สนับสนุนเกม'];
 if(e.k==='rr')return [n+' ได้แพ็กสุ่มเกิด','ขอบคุณที่สนับสนุนเกม'];
 let l=e.l;if(!l&&e.it&&e.it[0]){try{const f=FRAMES.find(x=>x.id===e.it[0]);if(f)l=f.n}catch(x){}}
 return [n+' ได้ '+esc(l||'ของตกแต่งใหม่')+(e.sn&&e.cap?` <b>เลขที่ ${e.sn}/${e.cap}</b>`:''),'ขอบคุณที่สนับสนุนเกม'];}
const IC=[['🪙'],['✨'],['👑'],['🏆']],SP=['✨','🌟','💫','✨','🌟'];
function pbnShow(){
 if(busy||!Q.length)return;const m=$('modal'),box=$('chatBox');
 if(!m||!box||m.dataset.k!=='online'||document.hidden)return;
 const e=Q.shift(),t=tier(e.a||0),tx=txt(e),d=document.createElement('div');d.className='pbn t'+t;
 d.innerHTML=`<span class="ic">${t===3?'👑':t===2?'💎':t===1?'🌟':'🪙'}</span><span class="tx">${tx[0]}<small>${tx[1]}</small></span>`+(t>=2?SP.map((x,i)=>`<span class="sp" style="left:${12+i*19}%;top:${40+(i%2)*20}%;animation-delay:${i*.45}s">${x}</span>`).join(''):'');
 m.appendChild(d);busy=1;
 const hold=[5000,7000,10000,15000][t];
 const end=()=>{d.classList.remove('in');d.classList.add('out');setTimeout(()=>{d.remove();busy=0;setTimeout(pbnShow,400)},550)};
 d.onclick=end;requestAnimationFrame(()=>requestAnimationFrame(()=>d.classList.add('in')));setTimeout(end,hold)}
async function poll(){
 try{const m=$('modal');if(!m||m.dataset.k!=='online'||!$('chatBox')||document.hidden)return;
  const j=await api('buyann');const l=(j&&j.l)||[];const now=Date.now();
  const fresh=l.filter(e=>e.t>seen&&now-e.t<15*60000).sort((a,b)=>a.t-b.t);
  if(l.length){const mx=Math.max(...l.map(e=>e.t));if(mx>seen){seen=mx;LS.set('murim_banT',seen)}}
  fresh.slice(-4).forEach(e=>Q.push(e));pbnShow()}catch(e){}}
setInterval(poll,40000);
