window.fetch=function(u,o){try{if(typeof u==='string'&&/\/api\/pay/.test(u)&&o&&typeof o.body==='string'&&LS.get('murim_banoff',0)){const b=JSON.parse(o.body);if(b&&b.pk&&b.pk!=='donate'){b.an=1;o=Object.assign({},o,{body:JSON.stringify(b)})}}}catch(e){}return of.call(this,u,o)};
