window.openProfile=function(){const r=op.apply(this,arguments);try{const m=$('modal');const ac=m&&m.querySelector('.pfpane[data-t="acc"]');if(ac&&!ac.querySelector('.pfban'))ac.insertAdjacentHTML('beforeend',`<div class="pfsec pfban"><h4>📣 ประกาศการซื้อ</h4><label class="tag2" style="display:flex;gap:6px;align-items:center"><input type="checkbox" ${LS.get('murim_banoff',0)?'checked':''} onchange="banOffTog(this)"> ซ่อนชื่อของฉันเวลามีประกาศซื้อของในแชท (ขึ้นเป็น "ผู้สนับสนุนนิรนาม")</label></div>`)}catch(e){}return r};
