 E.pk=Math.max(E.pk,oldPow);E.pkR=Math.max(E.pkR,rawRealm());E.n++;E.ev=0;E.memD=0;E.tomb=0;
 const kp=peers.filter(p=>p&&p.killed).slice(0,3).map(p=>({n:p.name,p:Math.round(Math.max(150,oldPow*.35)),h:0}));
 while(kp.length<2)kp.push({n:ch(['ทายาทแห่งตระกูล','ศิษย์ผู้แค้น','ผู้ถูกทิ้งแห่งสำนัก'])+anyName(S.gender),p:Math.round(Math.max(150,oldPow*.3)),h:0});
 if(mode===3)kp.forEach(f=>{f.p=Math.round(f.p*.5);f.h=1});
 E.foes=(E.foes||[]).concat(kp).slice(-5);
 E.ally=mode===3?null:{n:anyName(S.gender),met:0};E.gone=mode===3?R(30,70):0;
