 try{if(S.arts&&S.arts.length){const A=Array.prototype.slice.call(S.arts).sort((a,b)=>((b&&b.b)||0)-((a&&a.b)||0));const nk=Math.max(1,Math.round(A.length*keep));S.arts.splice(0,S.arts.length);A.slice(0,nk).forEach(a=>Array.prototype.push.call(S.arts,a))}}catch(e){console.error(e)}
 S.power=Math.max(10,Math.round(oldPow*k)-rest);S.qi=+(S.qi*.35).toFixed(1);
