const MSETS=['ms1','ms2','ms3','ms4','ms5','ms6','ws1','ws2','ws3','ws4','ws5','ws6','ws7','ws8','ws9'];
const deal=()=>{const day=Math.floor((Date.now()+7*3600e3)/864e5),h=(day*2654435761)>>>0;let a=(h>>>8)%18,b=(h>>>16)%18;if(b===a)b=(b+1)%18;return{s:MSETS[h%MSETS.length],t:['mn'+(a+1),'mn'+(b+1)],exp:(day+1)*864e5-7*3600e3}};
const rate=pk=>{const d=deal();return d.s===pk?.7:d.t.includes(pk)?.75:1};
const dp=(pk,p)=>Math.round(p*rate(pk));
const priceH=(pk,p)=>{const q=dp(pk,p);return q<p?'<span class="pr"><s style="opacity:.55;margin-right:4px">'+p+'฿</s><b>'+q+'฿</b></span>':'<span class="pr"><b>'+p+'฿</b></span>'};
