window._abQ=0;
{const _o=openHell2;openHell2=function(){if(Date.now()<(window._abQ||0))return;return _o.apply(this,arguments)}}
{const _s=abAutoStep;abAutoStep=function(f){try{if(f||(S&&S.flags&&S.flags.abAuto))window._abQ=Date.now()+1600}catch(e){}return _s.apply(this,arguments)}}
{const _b=window.abBatch;window.abBatch=function(){try{window._abQ=Date.now()+1600}catch(e){}const r=_b.apply(this,arguments);try{window._abQ=Date.now()+1600;if(typeof modalOpen!=='undefined'&&modalOpen){const m=$('modal');if(m&&/hell2|abyss/.test(m.dataset.k||''))closeM()}}catch(e){}return r}}
