const rwMoney=x=>{const g=Math.round(sc0()*(.4+x*1.4));S.money+=g;return`เงิน +${fmt(g)}`};
const rwInt=x=>{const g=Math.max(1,Math.round(5*x));S.int=(S.int||0)+g;return`ปัญญา +${g}`};
const rwHp=x=>{const g=Math.round(S.maxHp*.12*x);S.hp=Math.min(S.maxHp,S.hp+g);return`พลังชีวิต +${fmt(g)}`};
const rwKarma=x=>{const g=Math.round(2+8*x);S.karma+=g;return`กรรม +${g}`};
const rwFame=x=>{const g=Math.round(10+40*x*(1+ri()));S.fame+=g;return`ชื่อเสียง +${fmt(g)}`};
const rwJoy=x=>{try{joy(Math.round(3+9*x))}catch(e){}return`ใจเบิกบาน`};
const rwCha=x=>{const g=Math.max(1,Math.round(4*x));S.cha=(S.cha||0)+g;return`เสน่ห์ +${g}`};
const sh=a=>a.slice().sort(()=>Math.random()-.5);
const btn=(t,st)=>`<button class="pbtn" style="width:100%;font-size:18px;padding:13px;${st||''}">${t}</button>`;
// ---------- เครื่องยนต์ใหม่ ----------
// แตะเป้า (มีเป้าดี/เป้าห้ามแตะ)
function targets(B,api,{good,bad,N,life,bg,badP}){let hit=0,miss=0,sp=0,goodN=0;B.innerHTML=`<div id="m3A" style="position:relative;height:200px;border:2px solid var(--line);border-radius:12px;background:${bg||'#f3e6c8'};overflow:hidden"></div><div id="m3H" style="text-align:center;margin:4px">แตะ ${good}${bad?` · ห้ามแตะ ${bad}`:''}</div>`;const A=B.querySelector('#m3A');
 const nx=()=>{if(!api.live())return;if(sp>=N){api.end();return}sp++;const isB=bad&&Math.random()<(badP||.3);if(!isB)goodN++;const e=document.createElement('button');e.textContent=isB?bad:good;e.style.cssText=`position:absolute;left:${R(3,80)}%;top:${R(3,72)}%;font-size:34px;background:none;border:0;padding:4px`;A.appendChild(e);let t=0;
  e.onpointerdown=ev=>{ev.preventDefault();if(t)return;t=1;if(isB){miss++;e.textContent='✕';try{vib(40)}catch(x){}}else{hit++;e.textContent='✨'}};setTimeout(()=>{e.remove();setTimeout(nx,110)},Math.round((life||800)*api.ez-sp*12))};setTimeout(nx,350);
 return{sc:()=>Math.max(0,hit/Math.max(1,goodN)-miss*.2)}}
// รอจังหวะแล้วแตะ (ห้ามแตะตอนอันตราย)
function waitTap(B,api,{N,wIc,wBg,gIc,gBg,ok,fail,label}){let rd=0,okN=0,st='w',tm;B.innerHTML=`<div id="m3P" style="height:140px;display:flex;align-items:center;justify-content:center;font-size:58px;border:2px solid var(--line);border-radius:12px"></div><div id="m3H" style="text-align:center;margin:4px">รอบ 1/${N}</div>${btn(label)}`;
 const P=B.querySelector('#m3P');const set=s=>{st=s;P.textContent=s==='w'?wIc:gIc;P.style.background=s==='w'?wBg:gBg};
 const nx=()=>{if(!api.live())return;set('w');clearTimeout(tm);tm=setTimeout(()=>{set('g');tm=setTimeout(()=>{if(st==='g'){set('w');tm=setTimeout(nx,R(250,600))}},Math.round(R(520,820)*api.ez))},R(700,1800))};
 B.querySelector('.pbtn').onpointerdown=e=>{e.preventDefault();if(!api.live()||st==='x')return;clearTimeout(tm);if(st==='g'){okN++;P.textContent=ok}else P.textContent=fail;st='x';rd++;B.querySelector('#m3H').textContent=`สำเร็จ ${okN}/${rd}`;if(rd>=N)api.end();else setTimeout(nx,450)};
 set('w');setTimeout(nx,300);return{sc:()=>okN/N,stop:()=>clearTimeout(tm)}}
// ทิศทาง: ลูกศรมา แตะปุ่มทิศให้ทัน
function dirs(B,api,{N,ic,labels}){const D=['⬅️','⬆️','➡️'];let k=0,ok=0,cur=-1,t0=0,tm;B.innerHTML=`<div id="m3D" style="height:120px;display:flex;align-items:center;justify-content:center;font-size:60px;border:2px solid var(--line);border-radius:12px">${ic}</div><div id="m3H" style="text-align:center;margin:4px">0/${N}</div><div style="display:flex;gap:6px">${D.map((d,i)=>`<button class="pbtn m3d" data-i="${i}" style="flex:1;font-size:15px;padding:12px 2px">${(labels||[])[i]||d}</button>`).join('')}</div>`;
 const box=B.querySelector('#m3D');const nx=()=>{if(!api.live())return;if(k>=N){api.end();return}cur=R(0,2);t0=performance.now();box.textContent=D[cur];box.style.background='#ffe7a8';clearTimeout(tm);tm=setTimeout(()=>{if(cur>=0){cur=-1;k++;box.textContent='💢';box.style.background='#f8c0c0';B.querySelector('#m3H').textContent=`${ok}/${N}`;setTimeout(nx,300)}},Math.round(900*api.ez))};
 B.querySelectorAll('.m3d').forEach(b=>b.onpointerdown=e=>{e.preventDefault();if(cur<0||!api.live())return;const i=+b.dataset.i;clearTimeout(tm);k++;if(i===cur){ok++;box.textContent='💥';box.style.background='#c8f0c0';try{sfx('hit')}catch(x){}}else{box.textContent='💢';box.style.background='#f8c0c0'}cur=-1;B.querySelector('#m3H').textContent=`${ok}/${N}`;setTimeout(nx,260)});setTimeout(nx,400);return{sc:()=>ok/N,stop:()=>clearTimeout(tm)}}
// ทรงตัว: ค่าไหลออกนอกกลาง กดซ้าย/ขวาดึงกลับ
function balance(B,api,{ic,lab}){let x=0,v=0,inz=0,tot=0,last=performance.now(),raf;const zw=.18*api.ez;B.innerHTML=`<div style="position:relative;height:90px;border:2px solid var(--line);border-radius:12px;overflow:hidden;background:#0001"><div style="position:absolute;top:0;bottom:0;left:${50-zw*50}%;width:${zw*100}%;background:#e8b83a88"></div><div id="m3B" style="position:absolute;top:18px;font-size:40px;transform:translateX(-50%)">${ic}</div></div><div class="tag2" style="text-align:center;margin:4px">${lab}</div><div style="display:flex;gap:8px"><button class="pbtn" id="m3L" style="flex:1;font-size:24px;padding:12px">◀</button><button class="pbtn" id="m3R" style="flex:1;font-size:24px;padding:12px">▶</button></div>`;
 const b=B.querySelector('#m3B');B.querySelector('#m3L').onpointerdown=e=>{e.preventDefault();v-=.0011};B.querySelector('#m3R').onpointerdown=e=>{e.preventDefault();v+=.0011};
 const lp=t=>{if(!api.live())return;const dt=Math.min(50,t-last);last=t;v+=(Math.random()-.5)*.00012*dt+x*.000012*dt;v*=.992;x=Math.max(-1,Math.min(1,x+v*dt));if(Math.abs(x)>=1)v*=-.3;b.style.left=(50+x*46)+'%';tot+=dt;if(Math.abs(x)<=zw)inz+=dt;b.style.transform=`translateX(-50%) rotate(${x*35}deg)`;raf=requestAnimationFrame(lp)};raf=requestAnimationFrame(lp);
 return{sc:()=>tot?Math.min(1,inz/tot*1.25):0,stop:()=>cancelAnimationFrame(raf)}}
// คำถามหลายรอบ (ตัวเลือก 3 ข้อ)
function quiz(B,api,{N,gen,head}){let rd=0,ok=0;const one=()=>{if(!api.live())return;const q=gen(rd);const ops=sh(q.o.map((t,i)=>({t,c:i===0})));B.innerHTML=`<div class="tag2" style="text-align:center">${head||''} รอบ ${rd+1}/${N}</div><div style="padding:12px;border:2px solid #c9a24a;border-radius:10px;background:#fff7dc;margin:6px 0;font-size:16px;text-align:center">${q.q}</div>${ops.map((o,i)=>`<button class="opt m3q" data-c="${o.c?1:0}" style="width:100%;margin:3px 0;padding:11px;text-align:left">${o.t}</button>`).join('')}`;
  B.querySelectorAll('.m3q').forEach(b=>b.onclick=()=>{if(!api.live())return;const c=b.dataset.c==='1';if(c)ok++;b.style.background=c?'#c8f0c0':'#f8c0c0';rd++;setTimeout(()=>{if(rd>=N)api.end();else one()},320)})};one();return{sc:()=>ok/N}}
// เรียงลำดับ
function order(B,api,{items,head}){let k=0,ok=0;B.innerHTML=`<div class="tag2" style="text-align:center;margin-bottom:6px">${head}</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:6px">${sh(items).map(t=>`<button class="opt m3o" style="padding:11px 4px">${t}</button>`).join('')}</div>`;
 B.querySelectorAll('.m3o').forEach(b=>b.onclick=()=>{if(!api.live()||b.disabled)return;b.disabled=true;const c=b.textContent===items[k];if(c)ok++;b.style.background=c?'#c8f0c0':'#f8c0c0';b.textContent=(k+1)+'. '+b.textContent;k++;if(k>=items.length)api.end()});return{sc:()=>ok/items.length}}
// เสี่ยงดวงกดค้าง: ยิ่งสูงยิ่งดี แต่เกินขีดซ่อน = พัง
function push(B,api,{n,ic,label,boom}){let res=[],v=0,h=0,t0=0,raf,lim=.75+Math.random()*.2;B.innerHTML=`<div style="position:relative;height:150px;width:64px;margin:0 auto;border:2px solid var(--line);border-radius:32px;overflow:hidden;background:#0001"><div id="m3F" style="position:absolute;left:0;right:0;bottom:0;height:0;background:linear-gradient(#ffe9a8,#d98a1a)"></div></div><div id="m3H" style="text-align:center;margin:6px;font-size:18px">${'○ '.repeat(n)}</div><button id="m3Hd" class="pbtn" style="width:100%;font-size:18px;padding:16px;touch-action:none">${ic} ${label}</button><div class="tag2" style="text-align:center">ยิ่งมากยิ่งได้ แต่เกินขีดของร่าง = ${boom}</div>`;
 const up=()=>{if(!h||!api.live())return;h=0;const s=v>lim?0:Math.min(1,Math.pow(v/lim,1.3)*1.15);res.push(s);B.querySelector('#m3H').textContent=res.map(x=>x===0?'💥':Math.round(x*100)+'%').concat(Array(n).fill('○')).slice(0,n).join(' ');v=0;B.querySelector('#m3F').style.height='0';lim=.7+Math.random()*.25;if(res.length>=n)api.end()};
 const lp=()=>{if(!api.live())return;if(h){v=Math.min(1,(performance.now()-t0)/1700);B.querySelector('#m3F').style.height=v*100+'%';if(v>=1)up()}raf=requestAnimationFrame(lp)};raf=requestAnimationFrame(lp);
 const b=B.querySelector('#m3Hd');b.addEventListener('pointerdown',e=>{e.preventDefault();if(res.length<n){h=1;t0=performance.now()}});['pointerup','pointerleave','pointercancel'].forEach(k=>b.addEventListener(k,up));return{sc:()=>res.reduce((a,b)=>a+b,0)/n,stop:()=>cancelAnimationFrame(raf)}}
// ลากตามรอย (วาดยันต์)
function trace(B,api,{col}){const W=300,H=200,pts=[];let x=R(40,80),y=R(40,160);for(let i=0;i<6;i++){pts.push([x,y]);x=Math.max(30,Math.min(270,x+R(30,60)));y=Math.max(25,Math.min(175,y+R(-70,70)))}const P=[];for(let i=0;i<pts.length-1;i++)for(let k=0;k<=12;k++){const a=pts[i],b=pts[i+1];P.push([a[0]+(b[0]-a[0])*k/12,a[1]+(b[1]-a[1])*k/12])}const got=Array(P.length).fill(0);let off=0,on=0,dn=0;const rad=16*api.ez;
 B.innerHTML=`<canvas id="m3C" width="${W}" height="${H}" style="width:100%;border:2px solid var(--line);border-radius:10px;background:#f6ecd0;touch-action:none"></canvas><div class="tag2" style="text-align:center">ลากนิ้วตามรอยยันต์ตั้งแต่จุดแดงไปจนสุดเส้น</div>`;const cv=B.querySelector('#m3C'),c=cv.getContext('2d');
 const draw=()=>{c.clearRect(0,0,W,H);c.lineWidth=14;c.lineCap='round';c.strokeStyle='#c9a24a55';c.beginPath();pts.forEach((p,i)=>i?c.lineTo(p[0],p[1]):c.moveTo(p[0],p[1]));c.stroke();c.fillStyle=col||'#b3261e';P.forEach((p,i)=>{if(got[i]){c.beginPath();c.arc(p[0],p[1],5,0,7);c.fill()}});c.fillStyle='#d9534f';c.beginPath();c.arc(pts[0][0],pts[0][1],8,0,7);c.fill()};draw();
 const pos=e=>{const r=cv.getBoundingClientRect();return[(e.clientX-r.left)*W/r.width,(e.clientY-r.top)*H/r.height]};
 cv.addEventListener('pointerdown',e=>{e.preventDefault();dn=1;cv.setPointerCapture(e.pointerId)});cv.addEventListener('pointerup',()=>{dn=0;if(got.filter(Boolean).length>P.length*.85)api.end()});
 cv.addEventListener('pointermove',e=>{if(!dn||!api.live())return;const [px,py]=pos(e);let near=0;P.forEach((p,i)=>{if(Math.hypot(p[0]-px,p[1]-py)<rad){got[i]=1;near=1}});if(near)on++;else off++;draw()});
 return{sc:()=>Math.max(0,Math.min(1,got.filter(Boolean).length/P.length*1.15)-Math.max(0,off/Math.max(1,on+off)-.1)*.5)}}
