function modeKey(){try{if(!S)return'x';if(S.mw){let w='normal';try{w=window._wld.wOf(S.mw)}catch(e){}return('mw_'+(S.mw.kid?'kid':w)).slice(0,24)}if(S.beastMode&&!S.beastMode.human)return'beast';let ch='';try{ch=CH_KEYS[CFG.chm]||''}catch(e){}if(S.daily||CFG.daily)return'daily';const w=S.xt?'god':S.xian?'xian':'murim';return ch&&ch!=='normal'?(w+'_'+ch).slice(0,24):w}catch(e){return'x'}}
