{const _sv=saveLegacy;saveLegacy=function(){const r=_sv.apply(this,arguments);try{if(cur&&!cur.ended&&cur.me===S){cur.ended=1;send('ed',(S.mw?S.mw.y:(S.age||0)-cur.a0),modeKey())}}catch(e){}return r}}
{const _me=window.mwEnter;if(typeof _me==='function'){const w=function(){const had=S&&S.mw;const r=_me.apply(this,arguments);try{if(S&&S.mw&&!had){cur={m:modeKey(),a0:S.age,me:S,ended:0};send('in',0,cur.m)}}catch(e){}return r};window.mwEnter=w;try{mwEnter=w}catch(e){}}}
window.openModeStats=async function(){const k=typeof admK==='function'?admK():'';if(!k)return toast('เฉพาะแอดมิน');let J=null;try{J=await api('mstget&n=7&key='+encodeURIComponent(k))}catch(e){}if(!J||!J.ok)return toast('โหลดสถิติไม่ได้');
 const agg={};Object.values(J.data).forEach(o=>Object.entries(o).forEach(([k,v])=>{agg[k]=(agg[k]||0)+v}));const modes=[...new Set(Object.keys(agg).map(k=>k.split(':')[0]))].sort((a,b)=>((agg[b+':st']||0)+(agg[b+':in']||0))-((agg[a+':st']||0)+(agg[a+':in']||0)));
 const BK=['0','1-2','3-5','6-14','15-39','40+'];const row=m=>{const st=(agg[m+':st']||0)+(agg[m+':in']||0),ed=agg[m+':ed']||0,ab=agg[m+':ab']||0,early=['0','1-2'].reduce((a,b)=>a+(agg[m+':ab:'+b]||0),0);return`<tr><td><b>${esc(m)}</b></td><td>${J.users[m]||0}</td><td>${st}</td><td>${ed}</td><td>${ab}</td><td style="color:${early>st*.3?'#c33':''}">${early}</td></tr>`};
 modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>📊 สถิติโหมด 7 วัน</h3><p class="tag2">คน = ผู้เล่นไม่ซ้ำ · เริ่ม = ชีวิตที่เริ่ม (รวมเข้ากลางชีวิต) · จบ = ตายครบชีวิต · ทิ้ง = เริ่มชีวิตใหม่ทั้งที่ยังไม่ตาย · ทิ้งเร็ว = ทิ้งภายใน 2 ปีแรก</p><div style="overflow:auto"><table style="width:100%;font-size:12px;border-collapse:collapse"><tr style="text-align:left"><th>โหมด</th><th>คน</th><th>เริ่ม</th><th>จบ</th><th>ทิ้ง</th><th>ทิ้งเร็ว</th></tr>${modes.map(row).join('')}</table></div>
 <div id="hostBox" class="item" style="margin-top:8px"><b>🌐 เข้าเล่นจากที่อยู่เว็บไหน</b><div class="tag2">กำลังโหลด…</div></div><details style="margin-top:8px"><summary class="tag2">ทิ้งกลางทางแยกตามจำนวนปี</summary>${modes.map(m=>`<div class="tag2"><b>${esc(m)}</b>: ${BK.map(b=>`${b}ปี ${agg[m+':ab:'+b]||0}`).join(' · ')}</div>`).join('')}</details>`,'mstat');try{const H=await api('hoststat&key='+encodeURIComponent(k));const bx=$('hostBox');if(bx&&H&&H.hosts)bx.innerHTML=`<b>🌐 เข้าเล่นจากที่อยู่เว็บไหน</b><table style="width:100%;font-size:12px"><tr style="text-align:left"><th>ที่อยู่</th><th>วันนี้</th><th>7 วัน</th><th>ทั้งหมด</th></tr>${H.hosts.map(h=>`<tr><td>${esc(h.o)}</td><td>${h.d1}</td><td>${h.d7}</td><td>${h.all}</td></tr>`).join('')}</table><p class="tag2">นับจากเครื่องที่เคยส่งข้อมูลภาพสด · ที่อยู่ที่ต้องมีใน Google OAuth = ทุกอันที่ยังมีคนเล่นใน 7 วัน</p>`}catch(e){}};
{const _om=openMenu;openMenu=function(){const r=_om.apply(this,arguments);try{if(typeof ADM!=='undefined'&&ADM.ok){const g=$('modal').querySelector('.mgrid');if(g&&!g.querySelector('.mstB'))g.insertAdjacentHTML('beforeend','<button class="opt mstB" onclick="closeM();openModeStats()">📊 สถิติโหมด<small>แอดมิน</small></button>')}}catch(e){}return r}}
