window.mwQuickStart=function(){try{const b=document.querySelector('#title .mwopt');if(b)b.click();else{CFG.mw=1;CFG.xian=0}}catch(e){}try{closeM()}catch(e){}setTimeout(()=>{try{goBirthPick()}catch(e){console.error(e)}},60)};
