  px(X,Y,col,a){X|=0;Y|=0;if(X<0||Y<0||X>=W||Y>=H)return;const q=hx(col),j=(Y*W+X)*4;if(a==null||a>=1){d[j]=q[0];d[j+1]=q[1];d[j+2]=q[2];d[j+3]=255}else if(a>0){d[j]+=(q[0]-d[j])*a;d[j+1]+=(q[1]-d[j+1])*a;d[j+2]+=(q[2]-d[j+2])*a;d[j+3]=255}},
