  disc(cx,cy,r,col,a){const C=B.X(cx),Cy=B.Y(cy),rr=Math.max(1,r*B.sx);for(let y=Math.floor(Cy-rr);y<=Cy+rr;y++)for(let x=Math.floor(C-rr);x<=C+rr;x++){const q=(x-C)**2+(y-Cy)**2;if(q<=rr*rr)B.px(x,y,col,a)}},
