function kfRect(b,x,y){x=x==null?b.x:x;y=y==null?b.y:y;const s=kfS(y),hw=Math.max(KSZ*s/2,b.w/2)+3;return[x-hw,x+hw,y-50*s-4,y+24]}
const kfHit=(A,B,m)=>A[0]<B[1]+(m||0)&&B[0]<A[1]+(m||0)&&A[2]<B[3]&&B[2]<A[3];
function kfInit(B,W){KF.W=W;for(const b of B){const P=KF.pos[b.key];if(P){Object.assign(b,P);continue}
  if(b.nw){b.x=150;b.y=b.ty=300}else{let ok=0;for(let k=0;k<80&&!ok;k++){const x=-40+Math.random()*(W+80),y=KY0+Math.random()*(KY1-KY0),R=kfRect(b,x,y);if(B.every(o=>o===b||o.x==null||!kfHit(R,kfRect(o),8))){b.x=x;b.y=y;ok=1}}
   if(!ok){b.x=-b.w/2-30-Math.random()*260;b.y=KY0+Math.random()*(KY1-KY0)}b.ty=b.y}
  b.vm=.85+Math.random()*.3;b.nt=0}}
function kfStep(dt,t,W){const B=KS.bd;if(!B||!B.length)return;KF.W=W;
 for(const b of B){if(b.x==null)continue;if(!b.wm){const e=kbEl(b);if(e&&e.offsetWidth){b.w=e.offsetWidth;b.wm=1}}
  let v=kfV(b.y)*b.vm;if(t>b.nt){b.nt=t+6+Math.random()*8;b.ty=kfC(b.y+(Math.random()-.5)*80)}
  const Rb=kfRect(b);for(const o of B){if(o===b||o.x==null)continue;const Ro=kfRect(o),dx=o.x-b.x,vo=kfV(o.y)*o.vm;
   // ข้างหน้ามีกระทงช้ากว่า → ชะลอตาม แล้วอ้อมขึ้นหรือลง
   if(dx>0&&v>vo&&kfHit(kfRect(b,b.x+(v-vo)*3+12),Ro,6)){v=kfHit(kfRect(b,b.x+(v-vo)*1.2+4),Ro,4)?vo*.97:Math.max(vo,v*.7);const h=(Rb[3]-Rb[2]+Ro[3]-Ro[2])/2+6,up=o.y-h,dn=o.y+h;b.ty=b.y<=o.y?(up>=KY0?up:dn):(dn<=KY1?dn:up);b.nt=t+5}
   // ซ้อนกันอยู่แล้ว → ดันแยกกันขึ้นลง
   if(kfHit(Rb,Ro,2)){let d=b.y<o.y||(b.y===o.y&&b.i<o.i)?-1:1;if((d<0&&b.y<=KY0+1)||(d>0&&b.y>=KY1-1))d=-d;b.y=kfC(b.y+d*40*dt);b.ty=b.y;if(dx>0)v=Math.min(v,vo*.85);else if(dx<0)v=Math.max(v,vo*1.1)}}
  {const ny=b.y+Math.max(-7*dt,Math.min(7*dt,b.ty-b.y));if(ny!==b.y){const R1=kfRect(b,b.x,ny),R0=kfRect(b);if(B.some(o=>o!==b&&o.x!=null&&kfHit(R1,kfRect(o),4)&&!kfHit(R0,kfRect(o),4))){b.ty=b.y;b.nt=t+1.5}else b.y=ny}}
  // กำลังจะเข้าจอแต่ทางเข้ามีกระทงอยู่ → รอก่อน
  const ent=b.x+b.w/2<0&&b.x+b.w/2+v*dt>=0&&B.some(o=>o!==b&&o.x!=null&&o.x-o.w/2<b.w+20&&kfHit(kfRect(b,b.w/2),kfRect(o),10));if(!ent)b.x+=v*dt;
  if(b.x-b.w/2>W+30){b.x=-b.w/2-30-Math.random()*160;b.y=b.ty=KY0+Math.random()*(KY1-KY0)}
  const s=kfS(b.y);b.sz=KSZ*s;b.top=b.y-50.4*s;KF.pos[b.key]={x:b.x,y:b.y,ty:b.ty,vm:b.vm,nt:b.nt};
  const e=kbEl(b);if(e){e.style.transform=`translate3d(${(b.x-b.w/2).toFixed(1)}px,${(b.y-50.4).toFixed(1)}px,0)`;if(Math.abs((b.ls||0)-s)>.004){b.ls=s;const sc=b.sc||(b.sc=e.querySelector('.kSc'));if(sc)sc.style.transform=`scale(${s.toFixed(3)})`}const z=e.classList.contains('kSelB')?30:10+Math.round(kfZ(b.y)*16);if(b.zi!==z){b.zi=z;e.style.zIndex=z}}}}
function kbPos(b){if(b.x==null)return{x:-999,y:0,tx:0};const s=kfS(b.y);return{x:b.x/2,y:b.y/2,tx:(b.y-50.4*s)/2}}
const kbEl=b=>b.e||(b.e=document.querySelector(`#modal .kBoat[data-i="${b.i}"]`));
const kRiv=()=>document.querySelector('#modal .kRiver');
function kpHeart(g,x,y,c){g.fillStyle=c;g.fillRect(x-2,y-1,2,2);g.fillRect(x+1,y-1,2,2);g.fillRect(x-2,y,5,1);g.fillRect(x-1,y+1,3,1);g.fillRect(x,y+2,1,1)}
