 const E=KS.E||(KS.E={gust:t+18+R()*12,moon:t+9+R()*8,star:t+6+R()*8,fish:t+3+R()*4,turt:t+12+R()*8,col:t+2,pair:{},fishA:[]});
 // 🌬️ ลมพัดแรง: กระทงเอียง เปลวเทียนลู่ โคมลอยปลิว
