 if(e.k==='bigring'){g.strokeStyle='#ffe9b0';for(let i=0;i<3;i++){const kk=k-i*.15;if(kk<0||kk>1)continue;const r=6+kk*70;g.globalAlpha=.75*(1-kk);g.beginPath();g.ellipse(e.x,e.y,r,r*.28,0,0,6.283);g.stroke()}return 1}
